  app.get("/api/infrastructure/:tenantId/topology", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [locResult, assetResult] = await Promise.all([
        poolRead.query(`SELECT * FROM infrastructure_locations WHERE tenant_id = $1 AND is_active = true ORDER BY infra_type, name`, [tenantId]),
        poolRead.query(
          `SELECT hostname, ip_address, operating_system, status, cloud_provider, cloud_region,
                  endpoint_type, enrichment_data, endpoint_group
           FROM assets WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != ''
           ORDER BY ip_address LIMIT 5000`,
          tenantIds
        ),
      ]);

      const locations = locResult.rows;
      const assets = assetResult.rows;

      const ENDPOINT_GROUP_CITY_MAP: Record<string, string> = {
        NRB: "Nairobi, Kenya", KLA: "Kampala, Uganda", DAR: "Dar-Es-Salaam, Tanzania", KGL: "Kigali, Rwanda",
        MSA: "Mombasa, Kenya", NKR: "Nakuru", MLD: "Malindi", NBI: "Nairobi, Kenya",
        LAG: "Lagos, Nigeria", JHB: "Johannesburg, South Africa", CPT: "Cape Town, South Africa", ACC: "Accra, Ghana",
      };

      function locationFromEndpointGroup(group: string | null): string | null {
        if (!group) return null;
        const parts = group.split("-");
        if (parts.length >= 3) {
          const cityCode = parts[2]?.toUpperCase();
          if (ENDPOINT_GROUP_CITY_MAP[cityCode]) return ENDPOINT_GROUP_CITY_MAP[cityCode];
        }
        return null;
      }

      const subnetMap: Record<string, any[]> = {};
      assets.forEach(a => {
        const parts = (a.ip_address || "").split(".");
        if (parts.length >= 3) {
          const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
          if (!subnetMap[subnet]) subnetMap[subnet] = [];
          subnetMap[subnet].push({
            hostname: a.hostname,
            ip: a.ip_address,
            os: a.operating_system,
            status: a.status,
            type: a.endpoint_type,
            endpointGroup: a.endpoint_group,
            cloudRegion: a.cloud_region,
          });
        }
      });

      function isIpInRange(ip: string, cidr: string): boolean {
        try {
          const [rangeIp, bits] = cidr.split("/");
          const mask = bits ? parseInt(bits) : 24;
          const ipParts = ip.split(".").map(Number);
          const rangeParts = rangeIp.split(".").map(Number);
          const ipNum = (ipParts[0] << 24) | (ipParts[1] << 16) | (ipParts[2] << 8) | ipParts[3];
          const rangeNum = (rangeParts[0] << 24) | (rangeParts[1] << 16) | (rangeParts[2] << 8) | rangeParts[3];
          const maskNum = mask === 0 ? 0 : (~0 << (32 - mask));
          return (ipNum & maskNum) === (rangeNum & maskNum);
        } catch { return false; }
      }

      const tree: any[] = [];
      const assignedSubnets = new Set<string>();

      if (locations.length > 0) {
        const byType: Record<string, any[]> = {};
        locations.forEach(loc => {
          const t = loc.infra_type || "on-prem";
          if (!byType[t]) byType[t] = [];
          byType[t].push(loc);
        });

        for (const [infraType, locs] of Object.entries(byType)) {
          const typeNode: any = {
            id: `type-${infraType}`,
            label: infraType === "on-prem" ? "On-Premises" : infraType === "cloud" ? "Cloud" : "Hybrid",
            type: "infraType",
            infraType,
            children: [],
            deviceCount: 0,
          };

          for (const loc of locs) {
            const allRanges = [...(loc.public_ip_ranges || []), ...(loc.private_ip_ranges || [])];
            const locNode: any = {
              id: `loc-${loc.id}`,
              label: loc.name,
              type: "location",
              cloudProvider: loc.cloud_provider,
              regionalDc: loc.regional_dc,
              publicIpRanges: loc.public_ip_ranges || [],
              privateIpRanges: loc.private_ip_ranges || [],
              assetTypes: loc.asset_types || [],
              connectedLocationIds: loc.connected_location_ids || [],
              children: [],
              deviceCount: 0,
            };

            for (const [subnet, devices] of Object.entries(subnetMap)) {
              if (allRanges.length === 0) continue;
              const matchesRange = allRanges.some(range => {
                const sampleIp = subnet.replace("/24", "").replace(".0", ".1");
                return isIpInRange(sampleIp, range);
              });

              if (matchesRange && !assignedSubnets.has(subnet)) {
                assignedSubnets.add(subnet);
                locNode.children.push({
                  id: `subnet-${subnet}`,
                  label: subnet,
                  type: "subnet",
                  isPrivate: subnet.startsWith("10.") || subnet.startsWith("172.") || subnet.startsWith("192.168."),
                  children: devices.map((d: any, i: number) => ({
                    id: `device-${d.hostname}-${i}`,
                    label: d.hostname,
                    type: "device",
                    ip: d.ip,
                    os: d.os,
                    status: d.status,
                    deviceType: d.type,
                  })),
                  deviceCount: devices.length,
                });
                locNode.deviceCount += devices.length;
              }
            }
            typeNode.children.push(locNode);
            typeNode.deviceCount += locNode.deviceCount;
          }
          tree.push(typeNode);
        }
      }

      const unassignedSubnets = Object.entries(subnetMap).filter(([s]) => !assignedSubnets.has(s));
      if (unassignedSubnets.length > 0) {
        const isPrivate = (s: string) => s.startsWith("10.") || s.startsWith("172.") || s.startsWith("192.168.");

        const locationSubnets: Record<string, [string, any[]][]> = {};
        for (const [subnet, devices] of unassignedSubnets) {
          const epLocations = new Map<string, any[]>();
          const noLocDevices: any[] = [];
          const locNames = locations.map((l: any) => ({ name: (l.name || "").toLowerCase(), dc: (l.regional_dc || "").toLowerCase(), label: l.name || l.regional_dc || "Unknown" }));
          for (const d of devices) {
            const loc = locationFromEndpointGroup(d.endpointGroup);
            if (loc) {
              if (!epLocations.has(loc)) epLocations.set(loc, []);
              epLocations.get(loc)!.push(d);
            } else {
              const cr = (d.cloudRegion || "").toLowerCase().trim();
              const regionMatch = cr ? locNames.find((l: any) => l.name.includes(cr) || cr.includes(l.name) || l.name.split(",")[0].trim() === cr.split(",")[0].trim()) : null;
              if (regionMatch) {
                if (!epLocations.has(regionMatch.label)) epLocations.set(regionMatch.label, []);
                epLocations.get(regionMatch.label)!.push(d);
              } else {
                noLocDevices.push(d);
              }
            }
          }

          if (epLocations.size > 0) {
            for (const [loc, locDevices] of epLocations) {
              if (!locationSubnets[loc]) locationSubnets[loc] = [];
              locationSubnets[loc].push([subnet, locDevices]);
            }
            if (noLocDevices.length > 0) {
              const fallback = isPrivate(subnet) ? "Private Network (Auto-detected)" : "Public Network (Auto-detected)";
              if (!locationSubnets[fallback]) locationSubnets[fallback] = [];
              locationSubnets[fallback].push([subnet, noLocDevices]);
            }
          } else {
            const fallback = isPrivate(subnet) ? "Private Network (Auto-detected)" : "Public Network (Auto-detected)";
            if (!locationSubnets[fallback]) locationSubnets[fallback] = [];
            locationSubnets[fallback].push([subnet, devices]);
          }
        }

        for (const [locLabel, subnets] of Object.entries(locationSubnets)) {
          if (subnets.length === 0) continue;
          const isAutoFallback = locLabel.includes("Auto-detected");
          const infraType = locLabel.includes("Public") ? "cloud" : "on-prem";
          let totalDevices = 0;

          const subnetNodes = subnets.map(([subnet, devices]) => {
            totalDevices += devices.length;
            return {
              id: `subnet-${locLabel}-${subnet}`,
              label: subnet,
              type: "subnet",
              isPrivate: isPrivate(subnet),
              children: devices.map((d: any, i: number) => ({
                id: `device-${d.hostname}-${i}`,
                label: d.hostname,
                type: "device",
                ip: d.ip,
                os: d.os,
                status: d.status,
                deviceType: d.type,
              })),
              deviceCount: devices.length,
            };
          });

          const locationNode: any = {
            id: `auto-${locLabel.replace(/[^a-zA-Z0-9]/g, "-")}`,
            label: locLabel,
            type: "location",
            auto: !isAutoFallback ? false : true,
            children: subnetNodes,
            deviceCount: totalDevices,
          };

          let typeNode = tree.find((t: any) => t.infraType === infraType);
          if (!typeNode) {
            typeNode = {
              id: `type-${infraType}`,
              label: infraType === "on-prem" ? "On-Premises" : "Cloud",
              type: "infraType",
              infraType,
              children: [],
              deviceCount: 0,
            };
            tree.push(typeNode);
          }
          typeNode.children.push(locationNode);
          typeNode.deviceCount += totalDevices;
        }
      }

      res.json({
        tree,
        locations: locations.map(loc => ({
          id: loc.id,
          name: loc.name,
          infraType: loc.infra_type,
          connectedLocationIds: loc.connected_location_ids || [],
          publicIpRanges: loc.public_ip_ranges || [],
          privateIpRanges: loc.private_ip_ranges || [],
          assetTypes: loc.asset_types || [],
          cloudProvider: loc.cloud_provider,
          regionalDc: loc.regional_dc,
        })),
        totalLocations: locations.length,
        totalSubnets: Object.keys(subnetMap).length,
        totalDevices: assets.length,
        hasInfraConfig: locations.length > 0,
      });
    } catch (error: any) {
      console.error("Infrastructure topology error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/infrastructure/:tenantId/dc-os-tree", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      if (!tenantIds.length) return res.json({ label: "Organization", type: "org", children: [] });
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [locResult, assetResult, tenantResult] = await Promise.all([
        poolRead.query(`SELECT * FROM infrastructure_locations WHERE tenant_id = $1 AND is_active = true ORDER BY infra_type, name`, [tenantId]),
        poolRead.query(
          `SELECT hostname, ip_address, operating_system, status, cloud_provider, cloud_region, endpoint_type, endpoint_group
           FROM assets WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != ''
           ORDER BY operating_system, hostname LIMIT 5000`,
          tenantIds
        ),
        poolRead.query(`SELECT name FROM tenants WHERE id = $1`, [tenantId]),
      ]);

      const locations = locResult.rows;
      const assets = assetResult.rows;
      const orgName = tenantResult.rows[0]?.name || "Organization";

      const ENDPOINT_GROUP_CITY_MAP: Record<string, string> = {
        NRB: "Nairobi, Kenya", KLA: "Kampala, Uganda", DAR: "Dar-Es-Salaam, Tanzania", KGL: "Kigali, Rwanda",
        MSA: "Mombasa, Kenya", NKR: "Nakuru", MLD: "Malindi", NBI: "Nairobi, Kenya",
        LAG: "Lagos, Nigeria", JHB: "Johannesburg, South Africa", CPT: "Cape Town, South Africa", ACC: "Accra, Ghana",
      };

      function locationFromEndpointGroup(group: string | null): string | null {
        if (!group) return null;
        const parts = group.split("-");
        if (parts.length >= 3) {
          const cityCode = parts[2]?.toUpperCase();
          if (ENDPOINT_GROUP_CITY_MAP[cityCode]) return ENDPOINT_GROUP_CITY_MAP[cityCode];
        }
        return null;
      }

      function normalizeOs(os: string | null): string {
        if (!os) return "Unknown";
        const lower = os.toLowerCase();
        if (lower.includes("windows")) return "Windows";
        if (lower.includes("linux") || lower.includes("ubuntu") || lower.includes("centos") || lower.includes("rhel") || lower.includes("debian") || lower.includes("suse") || lower.includes("fedora") || lower.includes("red hat")) return "Linux";
        if (lower.includes("aix")) return "AIX";
        if (lower.includes("mac") || lower.includes("darwin")) return "macOS";
        if (lower.includes("esxi") || lower.includes("vmware")) return "VMware ESXi";
        if (lower.includes("solaris")) return "Solaris";
        if (lower.includes("freebsd")) return "FreeBSD";
        return os;
      }

      function isTimestampValue(val: string): boolean {
        return /^\d{4}-\d{2}-\d{2}/.test(val);
      }

      function locationFromEnrichment(asset: any): string | null {
        const ed = asset.enrichment_data || asset.enrichmentData;
        if (!ed || typeof ed !== "object") return null;
        if (ed.datacenterName && !isTimestampValue(ed.datacenterName)) return ed.datacenterName;
        if (ed.datacenter && !isTimestampValue(ed.datacenter)) return ed.datacenter;
        if (ed.location && typeof ed.location === "string" && !isTimestampValue(ed.location)) return ed.location;
        return null;
      }

      function locationFromHostname(hostname: string | null): string | null {
        if (!hostname) return null;
        const h = hostname.toUpperCase();
        const fqdn = hostname.toLowerCase();
        if (fqdn.includes(".asia.")) return "Asia Pacific";
        if (fqdn.includes(".emea.") || fqdn.includes(".europe.")) return "EMEA";
        if (fqdn.includes(".americas.") || fqdn.includes(".amer.")) return "Americas";
        if (h.startsWith("HKPD") || h.startsWith("HK")) return "Hong Kong";
        if (h.startsWith("JPTKYO") || h.startsWith("JP") || h.includes("AKASAKA") || h.includes("YOKOHAMA")) return "Japan";
        if (h.startsWith("KRSEL") || h.startsWith("KR")) return "Korea";
        if (h.startsWith("CNSHA") || h.startsWith("CN")) return "China";
        if (h.startsWith("USNCPD") || h.startsWith("USNC") || h.includes("GRNSBR")) return "Greensboro, NC";
        if (h.startsWith("USNYPD") || h.startsWith("USNY")) return "New York, NY";
        if (h.startsWith("INBLR") || h.startsWith("IN") && h.length > 8 && h.startsWith("INBANG")) return "India-Bangalore";
        return null;
      }

      function classifyLocation(asset: any): string {
        const epLoc = locationFromEndpointGroup(asset.endpoint_group);
        if (epLoc) return epLoc;
        const enrichLoc = locationFromEnrichment(asset);
        if (enrichLoc) return enrichLoc;
        if (asset.cloud_provider) {
          const cp = asset.cloud_provider.toLowerCase();
          if (cp.includes("aws") || cp.includes("amazon")) return "AWS";
          if (cp.includes("azure") || cp.includes("microsoft")) return "Azure";
          if (cp.includes("gcp") || cp.includes("google")) return "GCP";
          if (cp === "vmware" || cp === "on-premise") {
            const region = asset.cloud_region;
            if (region && !isTimestampValue(region)) return region;
            const hostLoc = locationFromHostname(asset.hostname);
            if (hostLoc) return hostLoc;
            return "On-Premises";
          }
          return asset.cloud_provider;
        }
        if (asset.cloud_region && !isTimestampValue(asset.cloud_region)) {
          if (asset.cloud_region.startsWith("us-") || asset.cloud_region.startsWith("eu-") || asset.cloud_region.startsWith("ap-")) return "AWS";
          if (asset.cloud_region.includes("east") || asset.cloud_region.includes("west")) return "Azure";
          return asset.cloud_region;
        }
        const hostLoc = locationFromHostname(asset.hostname);
        if (hostLoc) return hostLoc;
        return "On-Premises";
      }

      const dcOsMap: Record<string, Record<string, number>> = {};

      if (locations.length > 0) {
        function isIpInRange(ip: string, cidr: string): boolean {
          try {
            const [rangeIp, bits] = cidr.split("/");
            const mask = bits ? parseInt(bits) : 24;
            const ipParts = ip.split(".").map(Number);
            const rangeParts = rangeIp.split(".").map(Number);
            const ipNum = (ipParts[0] << 24) | (ipParts[1] << 16) | (ipParts[2] << 8) | ipParts[3];
            const rangeNum = (rangeParts[0] << 24) | (rangeParts[1] << 16) | (rangeParts[2] << 8) | rangeParts[3];
            const maskNum = mask === 0 ? 0 : (~0 << (32 - mask));
            return (ipNum & maskNum) === (rangeNum & maskNum);
          } catch { return false; }
        }

        const locNameMap = new Map<string, string>();
        for (const loc of locations) {
          const locName = loc.name || loc.regional_dc || "Unknown DC";
          const lowerName = locName.toLowerCase();
          const lowerDc = (loc.regional_dc || "").toLowerCase();
          locNameMap.set(lowerName, locName);
          if (lowerDc && lowerDc !== lowerName) locNameMap.set(lowerDc, locName);
        }

        function matchLocationByRegion(region: string | null): string | null {
          if (!region) return null;
          const lower = region.toLowerCase().trim();
          if (locNameMap.has(lower)) return locNameMap.get(lower)!;
          for (const [key, val] of locNameMap) {
            if (lower.includes(key) || key.includes(lower)) return val;
          }
          const regionFirst = lower.split(",")[0].trim();
          for (const [key, val] of locNameMap) {
            const keyFirst = key.split(",")[0].trim();
            if (regionFirst === keyFirst || regionFirst.includes(keyFirst) || keyFirst.includes(regionFirst)) return val;
          }
          return null;
        }

        const assignedAssets = new Set<string>();
        for (const loc of locations) {
          const locName = loc.name || loc.regional_dc || "Unknown DC";
          if (!dcOsMap[locName]) dcOsMap[locName] = {};
          const allRanges = [...(loc.public_ip_ranges || []), ...(loc.private_ip_ranges || [])];
          if (allRanges.length === 0) continue;
          for (const asset of assets) {
            if (assignedAssets.has(asset.hostname)) continue;
            const matchesRange = allRanges.some((range: string) => isIpInRange(asset.ip_address, range));
            if (matchesRange) {
              assignedAssets.add(asset.hostname);
              const osKey = normalizeOs(asset.operating_system);
              dcOsMap[locName][osKey] = (dcOsMap[locName][osKey] || 0) + 1;
            }
          }
        }
        for (const asset of assets) {
          if (assignedAssets.has(asset.hostname)) continue;
          const regionMatch = matchLocationByRegion(asset.cloud_region);
          if (regionMatch) {
            assignedAssets.add(asset.hostname);
            if (!dcOsMap[regionMatch]) dcOsMap[regionMatch] = {};
            const osKey = normalizeOs(asset.operating_system);
            dcOsMap[regionMatch][osKey] = (dcOsMap[regionMatch][osKey] || 0) + 1;
          }
        }
        for (const asset of assets) {
          if (!assignedAssets.has(asset.hostname)) {
            const locName = classifyLocation(asset);
            if (!dcOsMap[locName]) dcOsMap[locName] = {};
            const osKey = normalizeOs(asset.operating_system);
            dcOsMap[locName][osKey] = (dcOsMap[locName][osKey] || 0) + 1;
          }
        }
      } else {
        for (const asset of assets) {
          const locName = classifyLocation(asset);
          if (!dcOsMap[locName]) dcOsMap[locName] = {};
          const osKey = normalizeOs(asset.operating_system);
          dcOsMap[locName][osKey] = (dcOsMap[locName][osKey] || 0) + 1;
        }
      }

      const children = Object.entries(dcOsMap).map(([dcName, osGroups]) => {
        const osChildren = Object.entries(osGroups)
          .sort((a, b) => b[1] - a[1])
          .map(([osName, count]) => ({
            id: `os-${dcName}-${osName}`,
            label: osName,
            type: "os" as const,
            deviceCount: count,
          }));
        return {
          id: `dc-${dcName}`,
          label: dcName,
          type: "location" as const,
          deviceCount: osChildren.reduce((s, c) => s + c.deviceCount, 0),
          children: osChildren,
        };
      }).sort((a, b) => b.deviceCount - a.deviceCount);

      const tree = {
        id: "org-root",
        label: orgName,
        type: "org" as const,
        deviceCount: children.reduce((s, c) => s + c.deviceCount, 0),
        children,
      };

      res.json({ tree, totalAssets: assets.length });
    } catch (error: any) {
      console.error("DC-OS tree error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/infrastructure/:tenantId/dc-network-tree", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      if (!tenantIds.length) return res.json({ label: "Organization", type: "org", children: [] });
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [locResult, assetResult, tenantResult] = await Promise.all([
        poolRead.query(`SELECT * FROM infrastructure_locations WHERE tenant_id = $1 AND is_active = true ORDER BY infra_type, name`, [tenantId]),
        poolRead.query(
          `SELECT hostname, ip_address, operating_system, status, cloud_provider, cloud_region, endpoint_type, endpoint_group
           FROM assets WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != ''
           ORDER BY ip_address LIMIT 5000`,
          tenantIds
        ),
        poolRead.query(`SELECT name FROM tenants WHERE id = $1`, [tenantId]),
      ]);

      const locations = locResult.rows;
      const assets = assetResult.rows;
      const orgName = tenantResult.rows[0]?.name || "Organization";

      const ENDPOINT_GROUP_CITY_MAP: Record<string, string> = {
        NRB: "Nairobi, Kenya", KLA: "Kampala, Uganda", DAR: "Dar-Es-Salaam, Tanzania", KGL: "Kigali, Rwanda",
        MSA: "Mombasa, Kenya", NKR: "Nakuru", MLD: "Malindi", NBI: "Nairobi, Kenya",
        LAG: "Lagos, Nigeria", JHB: "Johannesburg, South Africa", CPT: "Cape Town, South Africa", ACC: "Accra, Ghana",
      };

      function locationFromEndpointGroup(group: string | null): string | null {
        if (!group) return null;
        const parts = group.split("-");
        if (parts.length >= 3) {
          const cityCode = parts[2]?.toUpperCase();
          if (ENDPOINT_GROUP_CITY_MAP[cityCode]) return ENDPOINT_GROUP_CITY_MAP[cityCode];
        }
        return null;
      }

      function isTimestampValue2(val: string): boolean {
        return /^\d{4}-\d{2}-\d{2}/.test(val);
      }

      function locationFromEnrichment2(asset: any): string | null {
        const ed = asset.enrichment_data || asset.enrichmentData;
        if (!ed || typeof ed !== "object") return null;
        if (ed.datacenterName && !isTimestampValue2(ed.datacenterName)) return ed.datacenterName;
        if (ed.datacenter && !isTimestampValue2(ed.datacenter)) return ed.datacenter;
        if (ed.location && typeof ed.location === "string" && !isTimestampValue2(ed.location)) return ed.location;
        return null;
      }

      function locationFromHostname2(hostname: string | null): string | null {
        if (!hostname) return null;
        const h = hostname.toUpperCase();
        const fqdn = hostname.toLowerCase();
        if (fqdn.includes(".asia.")) return "Asia Pacific";
        if (fqdn.includes(".emea.") || fqdn.includes(".europe.")) return "EMEA";
        if (fqdn.includes(".americas.") || fqdn.includes(".amer.")) return "Americas";
        if (h.startsWith("HKPD") || h.startsWith("HK")) return "Hong Kong";
        if (h.startsWith("JPTKYO") || h.startsWith("JP") || h.includes("AKASAKA") || h.includes("YOKOHAMA")) return "Japan";
        if (h.startsWith("KRSEL") || h.startsWith("KR")) return "Korea";
        if (h.startsWith("CNSHA") || h.startsWith("CN")) return "China";
        if (h.startsWith("USNCPD") || h.startsWith("USNC") || h.includes("GRNSBR")) return "Greensboro, NC";
        if (h.startsWith("USNYPD") || h.startsWith("USNY")) return "New York, NY";
        if (h.startsWith("INBLR") || h.startsWith("IN") && h.length > 8 && h.startsWith("INBANG")) return "India-Bangalore";
        return null;
      }

      function classifyLocation(asset: any): string {
        const epLoc = locationFromEndpointGroup(asset.endpoint_group);
        if (epLoc) return epLoc;
        const enrichLoc = locationFromEnrichment2(asset);
        if (enrichLoc) return enrichLoc;
        if (asset.cloud_provider) {
          const cp = asset.cloud_provider.toLowerCase();
          if (cp.includes("aws") || cp.includes("amazon")) return "AWS";
          if (cp.includes("azure") || cp.includes("microsoft")) return "Azure";
          if (cp.includes("gcp") || cp.includes("google")) return "GCP";
          if (cp === "vmware" || cp === "on-premise") {
            const region = asset.cloud_region;
            if (region && !isTimestampValue2(region)) return region;
            const hostLoc = locationFromHostname2(asset.hostname);
            if (hostLoc) return hostLoc;
            return "On-Premises";
          }
          return asset.cloud_provider;
        }
        if (asset.cloud_region && !isTimestampValue2(asset.cloud_region)) {
          if (asset.cloud_region.startsWith("us-") || asset.cloud_region.startsWith("eu-") || asset.cloud_region.startsWith("ap-")) return "AWS";
          if (asset.cloud_region.includes("east") || asset.cloud_region.includes("west")) return "Azure";
          return asset.cloud_region;
        }
        const hostLoc = locationFromHostname2(asset.hostname);
        if (hostLoc) return hostLoc;
        return "On-Premises";
      }

      const dcSubnetMap: Record<string, Record<string, number>> = {};

      if (locations.length > 0) {
        function isIpInRange(ip: string, cidr: string): boolean {
          try {
            const [rangeIp, bits] = cidr.split("/");
            const mask = bits ? parseInt(bits) : 24;
            const ipParts = ip.split(".").map(Number);
            const rangeParts = rangeIp.split(".").map(Number);
            const ipNum = (ipParts[0] << 24) | (ipParts[1] << 16) | (ipParts[2] << 8) | ipParts[3];
            const rangeNum = (rangeParts[0] << 24) | (rangeParts[1] << 16) | (rangeParts[2] << 8) | rangeParts[3];
            const maskNum = mask === 0 ? 0 : (~0 << (32 - mask));
            return (ipNum & maskNum) === (rangeNum & maskNum);
          } catch { return false; }
        }

        const locNameMap = new Map<string, string>();
        for (const loc of locations) {
          const locName = loc.name || loc.regional_dc || "Unknown DC";
          const lowerName = locName.toLowerCase();
          const lowerDc = (loc.regional_dc || "").toLowerCase();
          locNameMap.set(lowerName, locName);
          if (lowerDc && lowerDc !== lowerName) locNameMap.set(lowerDc, locName);
        }

        function matchLocationByRegion(region: string | null): string | null {
          if (!region) return null;
          const lower = region.toLowerCase().trim();
          if (locNameMap.has(lower)) return locNameMap.get(lower)!;
          for (const [key, val] of locNameMap) {
            if (lower.includes(key) || key.includes(lower)) return val;
          }
          const regionFirst = lower.split(",")[0].trim();
          for (const [key, val] of locNameMap) {
            const keyFirst = key.split(",")[0].trim();
            if (regionFirst === keyFirst || regionFirst.includes(keyFirst) || keyFirst.includes(regionFirst)) return val;
          }
          return null;
        }

        const assignedAssets = new Set<string>();
        for (const loc of locations) {
          const locName = loc.name || loc.regional_dc || "Unknown DC";
          if (!dcSubnetMap[locName]) dcSubnetMap[locName] = {};
          const allRanges = [...(loc.public_ip_ranges || []), ...(loc.private_ip_ranges || [])];
          if (allRanges.length === 0) continue;
          for (const asset of assets) {
            if (assignedAssets.has(asset.hostname)) continue;
            const matchesRange = allRanges.some((range: string) => isIpInRange(asset.ip_address, range));
            if (matchesRange) {
              assignedAssets.add(asset.hostname);
              const parts = asset.ip_address.split(".");
              if (parts.length >= 3) {
                const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
                dcSubnetMap[locName][subnet] = (dcSubnetMap[locName][subnet] || 0) + 1;
              }
            }
          }
        }
        for (const asset of assets) {
          if (assignedAssets.has(asset.hostname)) continue;
          const regionMatch = matchLocationByRegion(asset.cloud_region);
          if (regionMatch) {
            assignedAssets.add(asset.hostname);
            if (!dcSubnetMap[regionMatch]) dcSubnetMap[regionMatch] = {};
            const parts = (asset.ip_address || "").split(".");
            if (parts.length >= 3) {
              const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
              dcSubnetMap[regionMatch][subnet] = (dcSubnetMap[regionMatch][subnet] || 0) + 1;
            }
          }
        }
        for (const asset of assets) {
          if (!assignedAssets.has(asset.hostname)) {
            const locName = classifyLocation(asset);
            if (!dcSubnetMap[locName]) dcSubnetMap[locName] = {};
            const parts = (asset.ip_address || "").split(".");
            if (parts.length >= 3) {
              const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
              dcSubnetMap[locName][subnet] = (dcSubnetMap[locName][subnet] || 0) + 1;
            }
          }
        }
      } else {
        for (const asset of assets) {
          const locName = classifyLocation(asset);
          if (!dcSubnetMap[locName]) dcSubnetMap[locName] = {};
          const parts = asset.ip_address.split(".");
          if (parts.length >= 3) {
            const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
            dcSubnetMap[locName][subnet] = (dcSubnetMap[locName][subnet] || 0) + 1;
          }
        }
      }

      const children = Object.entries(dcSubnetMap).map(([dcName, subnets]) => {
        const subnetChildren = Object.entries(subnets)
          .sort((a, b) => b[1] - a[1])
          .map(([subnetName, count]) => ({
            id: `subnet-${dcName}-${subnetName}`,
            label: subnetName,
            type: "subnet" as const,
            deviceCount: count,
            isPrivate: subnetName.startsWith("10.") || subnetName.startsWith("172.") || subnetName.startsWith("192.168."),
          }));
        return {
          id: `dc-${dcName}`,
          label: dcName,
          type: "location" as const,
          deviceCount: subnetChildren.reduce((s, c) => s + c.deviceCount, 0),
          children: subnetChildren,
        };
      }).sort((a, b) => b.deviceCount - a.deviceCount);

      const tree = {
        id: "org-root",
        label: orgName,
        type: "org" as const,
        deviceCount: children.reduce((s, c) => s + c.deviceCount, 0),
        children,
      };

      res.json({ tree, totalAssets: assets.length });
    } catch (error: any) {
      console.error("DC-Network tree error:", error);
      res.status(500).json({ message: error.message });
    }
  });

