  app.get("/api/tenants/:tenantId/compliance-dashboard", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      if (!tenantIds.includes(tenantId)) return res.status(403).json({ message: "Forbidden" });

      const toolsResult = await poolRead.query(
        `SELECT * FROM tenant_security_tools WHERE tenant_id = $1 AND deployment_status != 'not_deployed' ORDER BY category`,
        [tenantId]
      );
      const configuredTools = toolsResult.rows;

      const { CATEGORY_NIST_MAPPING, CATEGORY_ISO27001_MAPPING, SECURITY_TOOL_CATEGORY_DEFINITIONS } = await import("@shared/schema");

      const nistFunctions: Record<string, { score: number; maxWeight: number; categories: string[]; tools: string[]; reasons: string[] }> = {};
      ["Govern", "Identify", "Protect", "Detect", "Respond", "Recover"].forEach(fn => {
        nistFunctions[fn] = { score: 0, maxWeight: 0, categories: [], tools: [], reasons: [] };
      });

      const isoControlGroups: Record<string, { score: number; maxWeight: number; controls: string[]; tools: string[]; reasons: string[] }> = {};
      ["Organizational", "People", "Physical", "Technological"].forEach(cg => {
        isoControlGroups[cg] = { score: 0, maxWeight: 0, controls: [], tools: [], reasons: [] };
      });

      const coveredCategories = new Set<string>();
      const categoryToolMap: Record<string, any[]> = {};

      for (const tool of configuredTools) {
        coveredCategories.add(tool.category);
        if (!categoryToolMap[tool.category]) categoryToolMap[tool.category] = [];
        categoryToolMap[tool.category].push(tool);

        const deployFactor = tool.deployment_status === "deployed" ? 1.0
          : tool.deployment_status === "partial" ? 0.6
          : tool.deployment_status === "planned" ? 0.2 : 0;
        const coverageFactor = (tool.coverage_percent || 100) / 100;
        const effectiveFactor = deployFactor * coverageFactor;

        const nistMapping = CATEGORY_NIST_MAPPING[tool.category];
        if (nistMapping) {
          for (const [fn, mapping] of Object.entries(nistMapping.functions)) {
            const eff = nistFunctions[fn];
            if (eff) {
              const adjustedWeight = mapping.weight * effectiveFactor;
              if (adjustedWeight > eff.maxWeight) eff.maxWeight = adjustedWeight;
              eff.score = Math.max(eff.score, adjustedWeight);
              mapping.categories.forEach(c => { if (!eff.categories.includes(c)) eff.categories.push(c); });
              if (!eff.tools.includes(tool.tool_name)) eff.tools.push(tool.tool_name);
              if (!eff.reasons.includes(mapping.reason)) eff.reasons.push(mapping.reason);
            }
          }
        }

        const isoMapping = CATEGORY_ISO27001_MAPPING[tool.category];
        if (isoMapping) {
          for (const [cg, mapping] of Object.entries(isoMapping.controlGroups)) {
            const eff = isoControlGroups[cg];
            if (eff) {
              const adjustedWeight = mapping.weight * effectiveFactor;
              if (adjustedWeight > eff.maxWeight) eff.maxWeight = adjustedWeight;
              eff.score = Math.max(eff.score, adjustedWeight);
              mapping.controls.forEach(c => { if (!eff.controls.includes(c)) eff.controls.push(c); });
              if (!eff.tools.includes(tool.tool_name)) eff.tools.push(tool.tool_name);
              if (!eff.reasons.includes(mapping.reason)) eff.reasons.push(mapping.reason);
            }
          }
        }
      }

      const allCategories = SECURITY_TOOL_CATEGORY_DEFINITIONS.map(c => c.key);
      const gaps = allCategories.filter(c => !coveredCategories.has(c));

      const nistScores = Object.entries(nistFunctions).map(([fn, data]) => ({
        function: fn,
        score: Math.round(data.score),
        categories: data.categories,
        tools: data.tools,
        reasons: data.reasons,
      }));
      const overallNist = nistScores.length > 0
        ? Math.round(nistScores.reduce((s, n) => s + n.score, 0) / nistScores.length)
        : 0;

      const isoScores = Object.entries(isoControlGroups).map(([cg, data]) => ({
        controlGroup: cg,
        score: Math.round(data.score),
        controls: data.controls,
        tools: data.tools,
        reasons: data.reasons,
      }));
      const overallIso = isoScores.length > 0
        ? Math.round(isoScores.reduce((s, n) => s + n.score, 0) / isoScores.length)
        : 0;

      const coverageByCategory = allCategories.map(cat => {
        const catDef = SECURITY_TOOL_CATEGORY_DEFINITIONS.find(c => c.key === cat);
        const tools = categoryToolMap[cat] || [];
        return {
          category: cat,
          name: catDef?.name || cat,
          tools: tools.map(t => ({ name: t.tool_name, vendor: t.vendor, status: t.deployment_status, coverage: t.coverage_percent })),
          status: tools.length === 0 ? "gap" : tools.some(t => t.deployment_status === "deployed") ? "covered" : "partial",
          toolCount: tools.length,
        };
      });

      res.json({
        configuredTools: configuredTools.length,
        coveredCategories: coveredCategories.size,
        totalCategories: allCategories.length,
        gaps,
        nist: { scores: nistScores, overall: overallNist },
        iso: { scores: isoScores, overall: overallIso },
        coverageByCategory,
      });
    } catch (error: any) {
      console.error("Compliance dashboard error:", error);
      res.status(500).json({ message: error.message });
    }
  });

