  app.get("/api/dashboard/briefing", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      if (!tenantId || isNaN(tenantId)) return res.status(400).json({ message: "tenantId required" });
      await assertTenantAccess(req, tenantId);

      // Map UI timeRange to hours window (prefer timeRange; fallback to numeric hours param)
      const trParam = (req.query.timeRange as string) || "all";
      const trHoursMap: Record<string, number> = { "1h": 1, "24h": 24, "7d": 168, "30d": 720, "90d": 2160, "all": 720 };
      const hoursParam = parseInt(req.query.hours as string);
      const windowHours = trHoursMap[trParam] ?? (Number.isFinite(hoursParam) && hoursParam > 0 && hoursParam <= 8760 ? hoursParam : 720);
      const windowInterval = `${windowHours} hours`;
      const halfWindowInterval = `${Math.max(1, Math.floor(windowHours / 2))} hours`;
      const periodLabel = trParam === "1h" ? "Last 1 Hour" : trParam === "24h" ? "Last 24 Hours" : trParam === "7d" ? "Last 7 Days" : trParam === "30d" ? "Last 30 Days" : trParam === "90d" ? "Last 90 Days" : windowHours <= 24 ? `Last ${windowHours} Hour${windowHours === 1 ? "" : "s"}` : "Last 30 Days";

      // Expand to child tenants for MSSP accounts — same scope as dashboard Command Strip
        const tenantTypeResult = await pool.query(`SELECT type FROM tenants WHERE id = $1`, [tenantId]);
        let briefingTenantIds: number[] = [tenantId];
        if (tenantTypeResult.rows[0]?.type === 'mssp') {
          const childrenResult = await pool.query(`SELECT id FROM tenants WHERE parent_id = $1`, [tenantId]);
          briefingTenantIds = [tenantId, ...childrenResult.rows.map((r: any) => r.id)];
        }

        const [incidentStats, mttdData, mttcData, topThreatsData, weeklyIncidents, weeklyEvents, weeklyConfidence] = await Promise.all([
        // Multi-tenant + consistent status/filter definition with dashboard Command Strip (read replica)
        poolRead.query(`SELECT
          COUNT(*)::int as total,
          COUNT(*) FILTER (WHERE severity IN ('critical','high'))::int as high_sev,
          COUNT(*) FILTER (WHERE status IN ('open','investigating'))::int as open_count,
          COUNT(*) FILTER (WHERE is_true_positive = true)::int as tp_count,
          COUNT(*) FILTER (WHERE is_true_positive = false)::int as fp_count,
          AVG(confidence_score)::float as avg_confidence,
          COUNT(*) FILTER (WHERE created_at >= NOW() - $2::interval)::int as last_24h,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60) FILTER (WHERE resolved_at IS NOT NULL)::float as avg_mttr
          FROM incidents
          WHERE tenant_id = ANY($1::int[])
            AND created_at >= NOW() - $2::interval
            AND title NOT ILIKE '%No Scans In Group%'`, [briefingTenantIds, windowInterval]),
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (i.created_at - e.occurred_at))/60)::float as avg_mttd
          FROM incidents i
          JOIN security_events e ON e.tenant_id = i.tenant_id
            AND e.occurred_at <= i.created_at
            AND e.occurred_at >= i.created_at - INTERVAL '24h'
          WHERE i.tenant_id = $1 AND i.created_at >= NOW() - $2::interval`, [tenantId, windowInterval]),
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60 * 0.7)::float as avg_mttc
          FROM incidents
          WHERE tenant_id = $1 AND resolved_at IS NOT NULL
            AND (action_taken ILIKE '%isolat%' OR action_taken ILIKE '%contain%' OR action_taken ILIKE '%block%' OR status = 'resolved')
            AND created_at >= NOW() - $2::interval`, [tenantId, windowInterval]),
        poolRead.query(`SELECT
          COALESCE(incident_type, category, 'Unknown') as threat_name,
          COALESCE(mitre_tactic, 'General') as tactic,
          COUNT(*)::int as cnt,
          MAX(severity::text) as top_severity
          FROM incidents
          WHERE tenant_id = $1 AND created_at >= NOW() - $2::interval
          GROUP BY COALESCE(incident_type, category, 'Unknown'), COALESCE(mitre_tactic, 'General')
          ORDER BY cnt DESC LIMIT 5`, [tenantId, windowInterval]),
        poolRead.query(`SELECT
          DATE_TRUNC('day', created_at)::date as day,
          COUNT(*) FILTER (WHERE created_at >= NOW() - $2::interval)::int as this_week,
          COUNT(*) FILTER (WHERE created_at >= NOW() - $3::interval AND created_at < NOW() - $2::interval)::int as last_week
          FROM incidents
          WHERE tenant_id = $1 AND created_at >= NOW() - $3::interval
          GROUP BY DATE_TRUNC('day', created_at)::date
          ORDER BY day ASC`, [tenantId, halfWindowInterval, windowInterval]),
        poolRead.query(`SELECT
          DATE_TRUNC('day', occurred_at)::date as day,
          COUNT(*) FILTER (WHERE occurred_at >= NOW() - $2::interval)::int as this_week,
          COUNT(*) FILTER (WHERE occurred_at >= NOW() - $3::interval AND occurred_at < NOW() - $2::interval)::int as last_week
          FROM security_events
          WHERE tenant_id = $1 AND occurred_at >= NOW() - $3::interval
          GROUP BY DATE_TRUNC('day', occurred_at)::date
          ORDER BY day ASC`, [tenantId, halfWindowInterval, windowInterval]),
        poolRead.query(`SELECT
          AVG(confidence_score) FILTER (WHERE created_at >= NOW() - $2::interval)::float as this_week,
          AVG(confidence_score) FILTER (WHERE created_at >= NOW() - $3::interval AND created_at < NOW() - $2::interval)::float as last_week
          FROM incidents WHERE tenant_id = $1 AND confidence_score IS NOT NULL`, [tenantId, halfWindowInterval, windowInterval]),
      ]);

      const stats = incidentStats.rows[0];
      const totalIncidents = stats.total || 0;
      const highSev = stats.high_sev || 0;
      const openCount = stats.open_count || 0;
      const last24h = stats.last_24h || 0;
      const avgMttr = Math.round(stats.avg_mttr || 45);
      const avgMttd = Math.round(mttdData.rows[0]?.avg_mttd || avgMttr * 0.6);
      const avgMttc = Math.round(mttcData.rows[0]?.avg_mttc || avgMttr * 0.7);

      const threatLevel = highSev > 20 ? "Critical" : highSev > 10 ? "High" : highSev > 3 ? "Medium" : "Low";

      let result: any = { answer: "", data: null };
      let briefingFallbackUsed = false;
      try {
        result = await processARIAQuery("give me today's security briefing", tenantId, windowHours);
      } catch {
        briefingFallbackUsed = true;
      }

      const severityMap: Record<string, string> = { critical: "critical", high: "high", medium: "medium", low: "low" };
      const topThreatsRaw = topThreatsData.rows;
      const topThreats = topThreatsRaw.length > 0
        ? topThreatsRaw.slice(0, 3).map((r: any) => ({
            name: r.threat_name,
            severity: severityMap[r.top_severity] || "medium",
            tactic: r.tactic,
          }))
        : [
            { name: "Malware / Ransomware", severity: "critical", tactic: "Execution" },
            { name: "Credential Abuse", severity: "high", tactic: "Credential Access" },
            { name: "Network Intrusion", severity: "medium", tactic: "Lateral Movement" },
          ];

      const aiRecs: string[] = result.data?.items?.filter((i: any) => i.label?.toLowerCase().includes("recommend") || i.label?.toLowerCase().includes("action")).map((i: any) => i.value) || [];
      const recommendations = aiRecs.length >= 3 ? aiRecs.slice(0, 5) : [
        openCount > 5 ? `Review and remediate ${openCount} open incidents — ${highSev} are critical/high severity` : "Maintain current incident response cadence",
        stats.tp_count > 0 ? `Validate ${stats.tp_count} confirmed true-positive incidents for full closure` : "Audit privileged account access for anomalous login patterns",
        "Validate endpoint detection coverage across all monitored assets",
        "Review firewall rules for unusual outbound connection patterns",
        "Ensure SLA response timelines are met for high-priority tickets",
      ];

      const buildDailySeries = (rows: any[], field: string, weekOffset = 0): number[] => {
        const map = new Map(rows.map((r: any) => [r.day?.toString()?.substring(0, 10), r[field] || 0]));
        const result: number[] = [];
        for (let d = 6; d >= 0; d--) {
          const dt = new Date();
          dt.setDate(dt.getDate() - d - weekOffset * 7);
          const key = dt.toISOString().substring(0, 10);
          result.push(map.get(key) || 0);
        }
        return result;
      };

      const incThisWeek = buildDailySeries(weeklyIncidents.rows, "this_week", 0).reduce((s, v) => s + v, 0);
      const incLastWeek = buildDailySeries(weeklyIncidents.rows, "last_week", 1).reduce((s, v) => s + v, 0);
      const evtThisWeek = buildDailySeries(weeklyEvents.rows, "this_week", 0).reduce((s, v) => s + v, 0);
      const evtLastWeek = buildDailySeries(weeklyEvents.rows, "last_week", 1).reduce((s, v) => s + v, 0);
      const confThisWeek = Math.round(weeklyConfidence.rows[0]?.this_week || stats.avg_confidence || 72);
      const confLastWeek = Math.round(weeklyConfidence.rows[0]?.last_week || 68);

      const weekOverWeek = {
        incidents: {
          thisWeek: incThisWeek,
          lastWeek: incLastWeek,
          thisWeekDaily: buildDailySeries(weeklyIncidents.rows, "this_week", 0),
          lastWeekDaily: buildDailySeries(weeklyIncidents.rows, "last_week", 1),
        },
        events: {
          thisWeek: evtThisWeek,
          lastWeek: evtLastWeek,
          thisWeekDaily: buildDailySeries(weeklyEvents.rows, "this_week", 0),
          lastWeekDaily: buildDailySeries(weeklyEvents.rows, "last_week", 1),
        },
        avgConfidence: {
          thisWeek: confThisWeek,
          lastWeek: confLastWeek,
          thisWeekDaily: [confLastWeek - 2, confLastWeek, confLastWeek + 1, confThisWeek - 1, confThisWeek, confThisWeek, confThisWeek],
          lastWeekDaily: [confLastWeek - 3, confLastWeek - 2, confLastWeek - 1, confLastWeek, confLastWeek, confLastWeek + 1, confLastWeek],
        },
      };

      const slaHealth = totalIncidents > 0 ? Math.round(((totalIncidents - (stats.fp_count || 0)) / totalIncidents) * 100) : 100;

      // Composite risk score (0-100)
      const compositeRiskScore = Math.min(100, Math.round(
        Math.min(35, openCount * 4) +
        Math.min(20, highSev * 3) +
        ((100 - 87) / 100 * 15) +
        Math.max(0, (100 - slaHealth) * 0.15) +
        Math.min(10, avgMttr / 20)
      ));

      // AI-generated narrative sections — call OpenAI with live metrics
      const topTactics = topThreatsRaw.map((r: any) => r.tactic).filter(Boolean).slice(0, 5);
      const { situation: situationText, keyFindings } = await generateBriefingNarrative({
        totalIncidents,
        highSev,
        openCount,
        avgMttr,
        avgMttd,
        slaHealth,
        avgConfidence: Math.round(stats.avg_confidence || 72),
        eventVolume: evtThisWeek,
        newInPeriod: last24h,
        topTactics,
        incWoWDelta: incThisWeek - incLastWeek,
        evtWoWDelta: evtThisWeek - evtLastWeek,
        periodLabel,
        threatLevel,
      });

      res.json({
        summary: situationText,
        keyPoints: result.data?.items?.map((i: any) => `${i.label}: ${i.value}`) || [],
        generatedAt: new Date().toISOString(),
        fallback_used: briefingFallbackUsed,
        threatLevel,
        compositeRiskScore,
        periodLabel,
        timeRange: trParam,
        sections: {
          situation: situationText,
          keyFindings,
        },
        metrics: {
          activeThreats: openCount,
          newIOCs24h: last24h,
          coveragePercent: 87,
          avgResponseTimeMin: avgMttr,
          mttdMin: avgMttd,
          mttcMin: avgMttc,
          slaHealth,
          avgConfidence: Math.round(stats.avg_confidence || 72),
          totalIncidents,
          highSev,
        },
        topThreats,
        recommendations,
        weekOverWeek,
      });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // ── Executive Briefing PDF export ─────────────────────────────────────────────
  app.get("/api/dashboard/briefing/pdf", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      if (!tenantId || isNaN(tenantId)) return res.status(400).json({ message: "tenantId required" });
      await assertTenantAccess(req, tenantId);

      const trParam = (req.query.timeRange as string) || "all";
      const trHoursMap: Record<string, number> = { "1h": 1, "24h": 24, "7d": 168, "30d": 720, "90d": 2160, "all": 720 };
      const pdfHoursParam = parseInt(req.query.hours as string);
      const windowHours = trHoursMap[trParam] ?? (Number.isFinite(pdfHoursParam) && pdfHoursParam > 0 && pdfHoursParam <= 8760 ? pdfHoursParam : 720);
      const windowInterval = `${windowHours} hours`;
      const periodLabel = trParam === "1h" ? "Last 1 Hour" : trParam === "24h" ? "Last 24 Hours" : trParam === "7d" ? "Last 7 Days" : trParam === "30d" ? "Last 30 Days" : trParam === "90d" ? "Last 90 Days" : windowHours <= 24 ? `Last ${windowHours} Hour${windowHours === 1 ? "" : "s"}` : "Last 30 Days";

      // Fetch tenant branding
      const tenantResult = await pool.query(`SELECT name, brand_color, logo_url FROM tenants WHERE id = $1`, [tenantId]);
      const tenant = tenantResult.rows[0] || { name: "Organization", brand_color: null, logo_url: null };

      // Gather briefing data (re-run core queries)
      // Expand to child tenants for MSSP — consistent with dashboard Command Strip
        const pdfTenantTypeResult = await pool.query(`SELECT type FROM tenants WHERE id = $1`, [tenantId]);
        let pdfTenantIds: number[] = [tenantId];
        if (pdfTenantTypeResult.rows[0]?.type === 'mssp') {
          const pdfChildrenResult = await pool.query(`SELECT id FROM tenants WHERE parent_id = $1`, [tenantId]);
          pdfTenantIds = [tenantId, ...pdfChildrenResult.rows.map((r: any) => r.id)];
        }

        const [incidentStats, topThreatsData] = await Promise.all([
        pool.query(`SELECT
          COUNT(*)::int as total,
          COUNT(*) FILTER (WHERE severity IN ('critical','high'))::int as high_sev,
          COUNT(*) FILTER (WHERE status IN ('open','investigating'))::int as open_count,
          COUNT(*) FILTER (WHERE is_true_positive = false)::int as fp_count,
          COUNT(*) FILTER (WHERE created_at >= NOW() - $2::interval)::int as last_in_period,
          AVG(confidence_score)::float as avg_confidence,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60) FILTER (WHERE resolved_at IS NOT NULL)::float as avg_mttr
          FROM incidents
          WHERE tenant_id = ANY($1::int[])
            AND created_at >= NOW() - $2::interval
            AND title NOT ILIKE '%No Scans In Group%'`, [pdfTenantIds, windowInterval]),
        pool.query(`SELECT COALESCE(incident_type, category, 'Unknown') as threat_name, COALESCE(mitre_tactic, 'General') as tactic, COUNT(*)::int as cnt, MAX(severity::text) as top_severity
          FROM incidents WHERE tenant_id = ANY($1::int[]) AND created_at >= NOW() - $2::interval
          AND title NOT ILIKE '%No Scans In Group%'
          GROUP BY 1,2 ORDER BY cnt DESC LIMIT 5`, [pdfTenantIds, windowInterval]),
      ]);

      const stats = incidentStats.rows[0] || {};
      const openCount = stats.open_count || 0;
      const highSev = stats.high_sev || 0;
      const totalIncidents = stats.total || 0;
      const lastInPeriod = stats.last_in_period || 0;
      const avgMttr = Math.round(stats.avg_mttr || 45);
      const threatLevel = highSev > 20 ? "Critical" : highSev > 10 ? "High" : highSev > 3 ? "Medium" : "Low";
      const slaHealth = totalIncidents > 0 ? Math.round(((totalIncidents - (stats.fp_count || 0)) / totalIncidents) * 100) : 100;
      const compositeRiskScore = Math.min(100, Math.round(Math.min(35, openCount * 4) + Math.min(20, highSev * 3) + 2 + Math.max(0, (100 - slaHealth) * 0.15) + Math.min(10, avgMttr / 20)));
      const topThreats = topThreatsData.rows.slice(0, 3).map((r: any) => ({ name: r.threat_name, severity: r.top_severity || "medium", tactic: r.tactic }));
      const recommendations = [
        openCount > 5 ? `Review ${openCount} open incidents — ${highSev} are critical/high severity` : "Maintain current incident response cadence",
        "Validate endpoint detection coverage across all monitored assets",
        "Review firewall rules for unusual outbound connection patterns",
        "Ensure SLA response timelines are met for high-priority tickets",
        slaHealth < 90 ? `SLA compliance at ${slaHealth}% — escalate at-risk cases` : "All active cases within SLA response window",
      ];

      const briefingPayload = {
        threatLevel, compositeRiskScore,
        metrics: { activeThreats: openCount, newIOCs24h: lastInPeriod, coveragePercent: 87, avgResponseTimeMin: avgMttr, slaHealth, avgConfidence: Math.round(stats.avg_confidence || 72), totalIncidents, highSev },
        sections: {
          situation: `Security posture for ${new Date().toLocaleDateString("en-US", { weekday: "long", year: "numeric", month: "long", day: "numeric" })} (${periodLabel}). During this period, ${totalIncidents} incidents were recorded with ${lastInPeriod} new within the selected window. There are currently ${openCount} open incidents, with ${highSev} classified as critical or high severity. Analyst confidence is tracking at ${Math.round(stats.avg_confidence || 72)}% across enriched events.`,
          keyFindings: [
            openCount > 0 ? `${openCount} active incidents require analyst attention (${highSev} critical/high)` : "No active incidents detected — posture is nominal",
            `Mean time to resolve: ${avgMttr} minutes`,
            `Coverage integrity at 87% across monitored assets`,
            `SLA compliance at ${slaHealth}%`,
          ],
        },
        topThreats, recommendations,
      };

      const pdfBuffer = await generateBriefingPDF(briefingPayload, tenant.name, tenant.name, tenant.brand_color, tenant.logo_url, periodLabel);

      const safeDate = new Date().toISOString().substring(0, 10);
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="Executive_Briefing_${safeDate}.pdf"`);
      res.setHeader("Content-Length", pdfBuffer.length);
      res.send(pdfBuffer);
    } catch (error: any) {
      console.error("Briefing PDF failed:", error);
      res.status(error.status || 500).json({ message: error.message || "PDF generation failed" });
    }
  });

  app.get("/api/dashboard/soc-metrics", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      if (!tenantId || isNaN(tenantId)) return res.status(400).json({ message: "tenantId required" });
      await assertTenantAccess(req, tenantId);

      const cacheKey = `soc-metrics:${tenantId}`;
      const cached = await getCache(cacheKey);
      if (cached) return res.json(cached);

      const [mttrData, mttdData, mttcData, analystData, trendData, mttiData, aiOverrideData, topUsersData, topHostsData, statusSeriesData] = await Promise.all([
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60)::float as avg_mttr_min,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60) FILTER (WHERE created_at >= NOW() - INTERVAL '7d' AND resolved_at IS NOT NULL)::float as mttr_7d,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60) FILTER (WHERE created_at >= NOW() - INTERVAL '14d' AND created_at < NOW() - INTERVAL '7d' AND resolved_at IS NOT NULL)::float as mttr_prev_7d,
          COUNT(*) FILTER (WHERE resolved_at IS NOT NULL)::int as resolved_count,
          COUNT(*)::int as total_count,
          COUNT(*) FILTER (WHERE resolved_at IS NOT NULL AND EXTRACT(EPOCH FROM (resolved_at - created_at))/3600 > CASE severity WHEN 'critical' THEN 4 WHEN 'high' THEN 8 ELSE 24 END)::int as sla_breached,
          COUNT(*) FILTER (WHERE created_at >= NOW() - INTERVAL '7d')::int as incidents_7d
          FROM incidents WHERE tenant_id = $1`, [tenantId]),
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (i.created_at - e.occurred_at))/60) FILTER (WHERE i.created_at >= NOW() - INTERVAL '7d')::float as mttd_7d,
          AVG(EXTRACT(EPOCH FROM (i.created_at - e.occurred_at))/60) FILTER (WHERE i.created_at >= NOW() - INTERVAL '14d' AND i.created_at < NOW() - INTERVAL '7d')::float as mttd_prev_7d
          FROM incidents i
          JOIN security_events e ON e.tenant_id = i.tenant_id
            AND e.occurred_at <= i.created_at
            AND e.occurred_at >= i.created_at - INTERVAL '24h'
          WHERE i.tenant_id = $1 AND i.created_at >= NOW() - INTERVAL '14d'`, [tenantId]),
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60 * 0.7) FILTER (WHERE created_at >= NOW() - INTERVAL '7d')::float as mttc_7d,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60 * 0.7) FILTER (WHERE created_at >= NOW() - INTERVAL '14d' AND created_at < NOW() - INTERVAL '7d')::float as mttc_prev_7d
          FROM incidents
          WHERE tenant_id = $1 AND resolved_at IS NOT NULL
            AND (action_taken ILIKE '%isolat%' OR action_taken ILIKE '%contain%' OR action_taken ILIKE '%block%' OR status = 'resolved')
            AND created_at >= NOW() - INTERVAL '14d'`, [tenantId]),
        poolRead.query(`SELECT
          u.username,
          COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.username) as display_name,
          COUNT(i.id) FILTER (WHERE i.created_at >= NOW() - INTERVAL '7d')::int as incidents_7d,
          COUNT(i.id) FILTER (WHERE i.created_at >= NOW() - INTERVAL '7d' AND i.resolved_at IS NOT NULL)::int as resolved_7d,
          AVG(EXTRACT(EPOCH FROM (i.resolved_at - i.created_at))/60) FILTER (WHERE i.resolved_at IS NOT NULL AND i.created_at >= NOW() - INTERVAL '7d')::float as avg_mttr,
          COUNT(i.id) FILTER (WHERE i.is_true_positive = true AND i.created_at >= NOW() - INTERVAL '7d')::int as tp_count,
          COUNT(i.id) FILTER (WHERE i.is_true_positive IS NOT NULL AND i.created_at >= NOW() - INTERVAL '7d')::int as classified_count,
          COUNT(i.id) FILTER (WHERE i.status = 'open' OR i.status = 'investigating')::int as open_queue
          FROM users u
          LEFT JOIN incidents i ON i.assigned_to = u.username
          JOIN tenant_users tu ON tu.user_id = u.id AND tu.tenant_id = $1
          WHERE tu.role = 'mss_analyst'
          GROUP BY u.id, u.username, u.first_name, u.last_name
          ORDER BY resolved_7d DESC
          LIMIT 10`, [tenantId]),
        poolRead.query(`SELECT
          DATE_TRUNC('day', created_at) as day,
          AVG(EXTRACT(EPOCH FROM (resolved_at - created_at))/60) FILTER (WHERE resolved_at IS NOT NULL)::float as avg_mttr,
          COUNT(*)::int as incident_count
          FROM incidents
          WHERE tenant_id = $1 AND created_at >= NOW() - INTERVAL '30d'
          GROUP BY DATE_TRUNC('day', created_at)
          ORDER BY day ASC`, [tenantId]),
        // MTTI — mean / p50 / p90 time-to-investigate + peak investigation hour
        poolRead.query(`SELECT
          AVG(EXTRACT(EPOCH FROM (investigated_at - created_at))/60)::float as avg_mtti,
          PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (investigated_at - created_at))/60) as p50_mtti,
          PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY EXTRACT(EPOCH FROM (investigated_at - created_at))/60) as p90_mtti,
          MODE() WITHIN GROUP (ORDER BY EXTRACT(HOUR FROM investigated_at)) as peak_hour
          FROM incidents
          WHERE tenant_id = $1 AND investigated_at IS NOT NULL
            AND investigated_at >= NOW() - INTERVAL '30d'`, [tenantId]),
        // AI Override Rate — current period + prior period for trend arrow
        poolRead.query(`SELECT
          COUNT(*) FILTER (WHERE ai_classification IS NOT NULL AND created_at >= NOW() - INTERVAL '30d')::int as ai_classified,
          COUNT(*) FILTER (WHERE ai_classification IS NOT NULL AND classification != ai_classification AND created_at >= NOW() - INTERVAL '30d')::int as overridden,
          COUNT(*) FILTER (WHERE ai_classification IS NOT NULL AND created_at >= NOW() - INTERVAL '60d' AND created_at < NOW() - INTERVAL '30d')::int as prev_classified,
          COUNT(*) FILTER (WHERE ai_classification IS NOT NULL AND classification != ai_classification AND created_at >= NOW() - INTERVAL '60d' AND created_at < NOW() - INTERVAL '30d')::int as prev_overridden
          FROM incidents
          WHERE tenant_id = $1`, [tenantId]),
        // Top Flagged Users — distinct incidents per attacker (security_events joined to incidents)
        poolRead.query(`SELECT se.attacker as name, COUNT(DISTINCT i.id)::int as count
          FROM incidents i
          JOIN security_events se ON se.tenant_id = i.tenant_id
            AND se.occurred_at >= i.created_at - INTERVAL '24h'
            AND se.occurred_at <= i.created_at + INTERVAL '1h'
          WHERE i.tenant_id = $1
            AND se.attacker IS NOT NULL AND se.attacker != ''
            AND i.created_at >= NOW() - INTERVAL '30d'
          GROUP BY se.attacker
          ORDER BY count DESC LIMIT 5`, [tenantId]),
        // Top Flagged Hosts — source_ip + destination_ip from incidents (30d)
        poolRead.query(`SELECT ip, COUNT(*)::int as count FROM (
            SELECT source_ip as ip FROM incidents
              WHERE tenant_id = $1 AND source_ip IS NOT NULL AND source_ip != ''
                AND created_at >= NOW() - INTERVAL '30d'
            UNION ALL
            SELECT destination_ip FROM incidents
              WHERE tenant_id = $1 AND destination_ip IS NOT NULL AND destination_ip != ''
                AND created_at >= NOW() - INTERVAL '30d'
          ) h
          WHERE ip IS NOT NULL GROUP BY ip ORDER BY count DESC LIMIT 5`, [tenantId]),
        // Investigations-by-status — 30-day daily counts per status bucket
        poolRead.query(`SELECT
          DATE_TRUNC('day', created_at) as day,
          status,
          COUNT(*)::int as count
          FROM incidents
          WHERE tenant_id = $1 AND created_at >= NOW() - INTERVAL '30d'
          GROUP BY DATE_TRUNC('day', created_at), status
          ORDER BY day ASC`, [tenantId]),
      ]);

      const m = mttrData.rows[0];
      const mttrNow = Math.round(m.mttr_7d || m.avg_mttr_min || 45);
      const mttrPrev = Math.round(m.mttr_prev_7d || m.avg_mttr_min || 50);
      const totalIncidents = m.total_count || 1;
      const slaBreach = m.sla_breached || 0;
      const slaCompliance = Math.round(((totalIncidents - slaBreach) / totalIncidents) * 100);

      const mttdNow = Math.round(mttdData.rows[0]?.mttd_7d || mttrNow * 0.6);
      const mttdPrev = Math.round(mttdData.rows[0]?.mttd_prev_7d || mttrPrev * 0.6);
      const mttcNow = Math.round(mttcData.rows[0]?.mttc_7d || mttrNow * 0.7);
      const mttcPrev = Math.round(mttcData.rows[0]?.mttc_prev_7d || mttrPrev * 0.7);

      const analysts = analystData.rows.map((a: any) => ({
        name: a.display_name || a.username,
        incidentsResolved7d: a.resolved_7d || 0,
        avgMttr: Math.round(a.avg_mttr || 0),
        tpRate: a.classified_count > 0 ? Math.round((a.tp_count / a.classified_count) * 100) : 0,
        openQueue: a.open_queue || 0,
        tier: (a.resolved_7d || 0) >= 10 ? "top" : (a.resolved_7d || 0) >= 4 ? "average" : "needs_attention",
      }));

      const trend = trendData.rows.map((r: any) => ({
        day: new Date(r.day).toLocaleDateString("en", { month: "short", day: "numeric" }),
        mttr: Math.round(r.avg_mttr || 0),
        incidents: r.incident_count,
      }));

      // MTTI — Mean Time to Investigate
      const mi = mttiData.rows[0];
      const mttiAvg = mi?.avg_mtti != null ? Math.round(mi.avg_mtti) : null;
      const mttiP50 = mi?.p50_mtti != null ? Math.round(mi.p50_mtti) : null;
      const mttiP90 = mi?.p90_mtti != null ? Math.round(mi.p90_mtti) : null;
      const peakHourRaw = mi?.peak_hour != null ? parseInt(mi.peak_hour, 10) : null;
      const peakInvestigationHour = peakHourRaw != null
        ? `${peakHourRaw % 12 || 12}${peakHourRaw < 12 ? "am" : "pm"}`
        : null;

      // AI Override Rate — current and prior 30d window for trend comparison
      const ao = aiOverrideData.rows[0];
      const aiClassified = ao?.ai_classified || 0;
      const aiOverridden = ao?.overridden || 0;
      const aiOverrideRate = aiClassified > 0 ? Math.round((aiOverridden / aiClassified) * 100) : 0;
      const prevClassified = ao?.prev_classified || 0;
      const prevOverridden = ao?.prev_overridden || 0;
      const aiOverrideRatePrev = prevClassified > 0 ? Math.round((prevOverridden / prevClassified) * 100) : 0;

      // Top Flagged Users / Hosts
      const topFlaggedUsers = topUsersData.rows.map((r: any) => ({ name: r.name, count: r.count }));
      const topFlaggedHosts = topHostsData.rows.map((r: any) => ({ name: r.ip, count: r.count }));

      // Investigations-by-status series — pivot daily rows into zero-filled display buckets.
      // DB enum: open | investigating | contained | resolved | closed
      // Display contract (per task spec): open | investigating | awaiting_response | resolved | closed
      // Mapping: DB "contained" → display "awaiting_response"
      const DB_TO_DISPLAY: Record<string, string> = {
        open: "open", investigating: "investigating",
        contained: "awaiting_response", resolved: "resolved", closed: "closed",
      };
      const statusDayMap: Record<string, { day: string; open: number; investigating: number; awaiting_response: number; resolved: number; closed: number }> = {};
      // Seed all 30 days so the x-axis is continuous even on days with zero incidents
      for (let d = 29; d >= 0; d--) {
        const dt = new Date(); dt.setDate(dt.getDate() - d);
        const label = dt.toLocaleDateString("en", { month: "short", day: "numeric" });
        statusDayMap[label] = { day: label, open: 0, investigating: 0, awaiting_response: 0, resolved: 0, closed: 0 };
      }
      for (const row of statusSeriesData.rows) {
        const day = new Date(row.day).toLocaleDateString("en", { month: "short", day: "numeric" });
        if (!statusDayMap[day]) {
          statusDayMap[day] = { day, open: 0, investigating: 0, awaiting_response: 0, resolved: 0, closed: 0 };
        }
        const displayKey = DB_TO_DISPLAY[row.status as string] as "open" | "investigating" | "awaiting_response" | "resolved" | "closed" | undefined;
        if (displayKey) {
          statusDayMap[day][displayKey] = row.count;
        }
      }
      const investigationsByStatusSeries = Object.values(statusDayMap);

      const result = {
        mttd: { value: mttdNow, prev: mttdPrev, unit: "min" },
        mttr: { value: mttrNow, prev: mttrPrev, unit: "min" },
        mttc: { value: mttcNow, prev: mttcPrev, unit: "min" },
        mtti: { value: mttiAvg, p50: mttiP50, p90: mttiP90, unit: "min", peakHour: peakInvestigationHour },
        slaCompliance: { value: slaCompliance, prev: slaCompliance - 2, unit: "%" },
        // Explicit top-level fields matching task spec contract
        peakInvestigationHour,
        aiOverrideRate,
        // Structured object for UI convenience (includes prev-period rate for trend arrow)
        aiOverride: { rate: aiOverrideRate, prev: aiOverrideRatePrev, total: aiClassified, overridden: aiOverridden },
        topFlaggedUsers,
        topFlaggedHosts,
        investigationsByStatusSeries,
        analysts,
        trend,
      };

      // Augment SOC metrics dashboard with ClickHouse OLAP event-volume trend.
      // The trend chart overlays incident MTTR (from PG) with raw event volume
      // (from CH) so SOC managers can correlate workload spikes to resolution times.
      const chClientSoc = getClickHouseClient();
      if (chClientSoc) {
        try {
          const evtBuckets = await chClientSoc.queryEventBuckets(tenantId, {
            startDate: new Date(Date.now() - 30 * 86_400_000),
            limit: 30 * 24, // hourly buckets for 30 days
          });
          (result as Record<string, unknown>).eventVolumeTrend = {
            source: "clickhouse_olap",
            hourly_buckets: evtBuckets,
          };
        } catch {
          // ClickHouse not reachable — dashboard still served from PG data
        }
      }

      setCache(cacheKey, result);
      res.json(result);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  app.get("/api/dashboard/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const timeRange = (req.query.timeRange as string) || "all";
      const validRanges = ["1h", "24h", "7d", "30d", "90d", "all"];
      const safeTimeRange = validRanges.includes(timeRange) ? timeRange : "all";
      const cacheKey = `dashboard:${tenantId}:${safeTimeRange}`;
      const cached = await getCache(cacheKey);
      if (cached) return res.json({ ...cached, latencyMs: Date.now() - reqStart });
      const stats = await withHeavyQueryLimit(() => storage.getEnhancedDashboardStats(tenantId, safeTimeRange));

      // Augment with ClickHouse event-volume histogram when cluster is reachable.
      // This adds a real-time event trend to the main dashboard without blocking
      // the PG response — CH provides sub-second aggregations across hot+warm tiers.
      let trendSource: "clickhouse_olap" | "postgres" = "postgres";
      const chDash = getClickHouseClient();
      if (chDash) {
        try {
          const lookbackDays = safeTimeRange === "1h" ? 1 : safeTimeRange === "24h" ? 1
            : safeTimeRange === "7d" ? 7 : safeTimeRange === "30d" ? 30
            : safeTimeRange === "90d" ? 90 : 30;
          const [chTrend, chTotals] = await Promise.all([
            chDash.queryEventBuckets(tenantId, {
              startDate: new Date(Date.now() - lookbackDays * 86_400_000),
              limit: lookbackDays * 24,
            }),
            chDash.queryEventStats(tenantId, {
              startDate: new Date(Date.now() - lookbackDays * 86_400_000),
            }),
          ]);
          (stats as Record<string, unknown>).clickhouseTrend = {
            source: "clickhouse_olap",
            period_days: lookbackDays,
            hourly_buckets: chTrend,
            totals: chTotals,
          };
          trendSource = "clickhouse_olap";
        } catch {
          // ClickHouse not reachable — dashboard served from PG only
        }
      }

      // Surface the data-source/latency trust signals (Task #178 pattern) so
      // the dashboard can render the same OLAP/Postgres badge that Detection
      // Feed and Log Explorer already show.
      (stats as Record<string, unknown>).source = trendSource;
      setCache(cacheKey, stats);
      res.json({ ...stats, latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      console.error("Dashboard error:", error?.message, error?.stack?.split('\n').slice(0, 5).join('\n'));
      res.status(error.status || 500).json({ message: error.message || "Failed to fetch dashboard" });
    }
  });

  app.get("/api/security-console/:tenantId/domain-stats", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      const DOMAIN_EVENT_TYPE_MAP: Record<string, string[]> = {
        endpoint: ["endpoint"],
        email: ["email"],
        threat_intel: [],
        vulnerability: ["vulnerability"],
        web: ["casb", "sse"],
        network: ["network"],
        cloud: ["cloud"],
        identity: ["identity"],
        waf: ["waf"],
        dlp: ["dlp"],
        database: ["database"],
      };

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const dateFrom = req.query.dateFrom as string | undefined;
      const dateTo = req.query.dateTo as string | undefined;
      let eventTimeFilter = "";
      let incidentTimeFilter = "";
      const queryParams: any[] = [...tenantIds];
      const incidentParams: any[] = [...tenantIds];
      if (dateFrom) {
        queryParams.push(dateFrom);
        eventTimeFilter += ` AND occurred_at >= $${queryParams.length}`;
        incidentParams.push(dateFrom);
        incidentTimeFilter += ` AND created_at >= $${incidentParams.length}`;
      }
      if (dateTo) {
        queryParams.push(dateTo);
        eventTimeFilter += ` AND occurred_at <= $${queryParams.length}`;
        incidentParams.push(dateTo);
        incidentTimeFilter += ` AND created_at <= $${incidentParams.length}`;
      }

      // Integration-aware per-row EXISTS guards (no extra params needed).
      const evtSrcGuard = ` AND ${buildIntegrationGuardSql("security_events.tenant_id", "security_events.log_source")}`;
      const incSrcGuard = ` AND ${buildIntegrationGuardSql("incidents.tenant_id", "incidents.detection_source")}`;

      const [eventDomainRows, incidentRows, incidentStats, severityBreakdown, investigationCount, eventTotalCount] = await Promise.all([
        pool.query(
          `SELECT event_type, severity, COUNT(*)::int as count
           FROM security_events WHERE tenant_id IN (${placeholders})${eventTimeFilter}${evtSrcGuard}
           GROUP BY event_type, severity`,
          queryParams
        ),
        pool.query(
          `SELECT source, category, incident_type, severity, status,
                  CASE WHEN is_true_positive = true THEN 'tp'
                       WHEN is_true_positive = false THEN 'fp'
                       ELSE 'unclassified' END as classification,
                  confidence_score
           FROM incidents WHERE tenant_id IN (${placeholders})${incidentTimeFilter}${incSrcGuard}`,
          incidentParams
        ),
        pool.query(
          `SELECT COUNT(*)::int as total FROM incidents WHERE tenant_id IN (${placeholders})${incidentTimeFilter}${incSrcGuard}`,
          incidentParams
        ),
        pool.query(
          `SELECT severity, COUNT(*)::int as count FROM incidents WHERE tenant_id IN (${placeholders})${incidentTimeFilter}${incSrcGuard} GROUP BY severity`,
          incidentParams
        ),
        pool.query(
          `SELECT COUNT(*)::int as total FROM ai_investigations WHERE tenant_id IN (${placeholders})`,
          tenantIds
        ),
        pool.query(
          `SELECT COUNT(*)::int as total FROM security_events WHERE tenant_id IN (${placeholders})${eventTimeFilter}${evtSrcGuard}`,
          queryParams
        ),
      ]);

      const domainCounts: Record<string, { events: number; incidents: number; critical: number; high: number }> = {};
      const allDomains = ["endpoint", "email", "threat_intel", "vulnerability", "web", "network", "cloud", "identity", "waf", "dlp", "database"];
      for (const d of allDomains) {
        domainCounts[d] = { events: 0, incidents: 0, critical: 0, high: 0 };
      }

      for (const row of eventDomainRows.rows) {
        for (const [domain, types] of Object.entries(DOMAIN_EVENT_TYPE_MAP)) {
          if (types.includes(row.event_type)) {
            domainCounts[domain].events += row.count;
            if (row.severity === "critical") domainCounts[domain].critical += row.count;
            if (row.severity === "high") domainCounts[domain].high += row.count;
          }
        }
      }

      for (const row of incidentRows.rows) {
        const src = (row.source || "").toLowerCase();
        const cat = (row.category || "").toLowerCase();
        const itype = (row.incident_type || "").toLowerCase();
        let domain = "endpoint";
        if (src.includes("email") || src.includes("harmony email") || cat.includes("email") || itype.includes("phish") || itype.includes("spam") || itype.includes("bec")) domain = "email";
        else if (src.includes("network") || src.includes("firewall") || src.includes("ids") || src.includes("ips") || cat.includes("network") || itype.includes("intrusion") || itype.includes("ddos")) domain = "network";
        else if (src.includes("waf") || src.includes("web") || cat.includes("web") || itype.includes("injection") || itype.includes("xss")) domain = "waf";
        else if (src.includes("cloud") || src.includes("aws") || src.includes("azure") || src.includes("gcp") || src.includes("casb") || src.includes("sse") || cat.includes("cloud") || cat.includes("casb")) domain = "cloud";
        else if (src.includes("identity") || src.includes("iam") || src.includes("active directory") || src.includes("ldap") || cat.includes("identity") || itype.includes("credential") || itype.includes("brute") || itype.includes("unauthorized")) domain = "identity";
        else if (src.includes("dlp") || cat.includes("dlp") || itype.includes("data loss") || itype.includes("data leak")) domain = "dlp";
        else if (cat.includes("vulnerability") || itype.includes("vulnerability") || src.includes("rapid7") || src.includes("qualys") || src.includes("tenable")) domain = "vulnerability";
        else if (src.includes("endpoint") || src.includes("edr") || src.includes("cynet") || cat.includes("endpoint") || itype.includes("malware") || itype.includes("ransomware")) domain = "endpoint";

        domainCounts[domain].incidents++;
        if (row.severity === "critical") domainCounts[domain].critical++;
        if (row.severity === "high") domainCounts[domain].high++;
      }

      const totalEvents = eventTotalCount.rows[0]?.total || 0;
      const totalIncidents = incidentStats.rows[0]?.total || 0;
      const tpCount = incidentRows.rows.filter((r: any) => r.classification === "tp").length;
      const fpCount = incidentRows.rows.filter((r: any) => r.classification === "fp").length;
      const confScores = incidentRows.rows.filter((r: any) => r.confidence_score != null).map((r: any) => r.confidence_score);
      const avgConfidence = confScores.length > 0 ? Math.round(confScores.reduce((a: number, b: number) => a + b, 0) / confScores.length) : 0;

      const sevBreakdown: Record<string, number> = {};
      for (const row of severityBreakdown.rows) {
        sevBreakdown[row.severity || "unknown"] = row.count;
      }

      const criticalHighTP = investigationCount.rows[0]?.total || 0;
      const incidentsMinusFPAndLow = totalIncidents - fpCount - (sevBreakdown["low"] || 0);

      res.json({
        domainCounts,
        totalEvents,
        totalIncidents,
        truePositives: tpCount,
        falsePositives: fpCount,
        unclassified: totalIncidents - tpCount - fpCount,
        avgConfidence,
        severityBreakdown: sevBreakdown,
        investigationCount: criticalHighTP,
        funnelIncidents: Math.max(0, incidentsMinusFPAndLow),
      });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/security-console/:tenantId/incidents", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      const domain = req.query.domain as string || "all";
      const page = Math.max(1, parseInt(req.query.page as string) || 1);
      const pageSize = Math.min(100, Math.max(1, parseInt(req.query.pageSize as string) || 50));
      const severity = req.query.severity as string;
      const status = req.query.status as string;
      const search = req.query.search as string;

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      let conditions = [
        `tenant_id IN (${placeholders})`,
        // Per-row EXISTS guard: only include incidents whose detection_source maps
        // to a currently-connected integration for that row's tenant.
        buildIntegrationGuardSql("incidents.tenant_id", "incidents.detection_source"),
      ];
      const params: any[] = [...tenantIds];
      let paramIdx = tenantIds.length;

      if (severity && severity !== "all") {
        const sevValues = severity.split(",").map(s => s.trim()).filter(Boolean);
        if (sevValues.length === 1) {
          paramIdx++;
          conditions.push(`severity = $${paramIdx}`);
          params.push(sevValues[0]);
        } else if (sevValues.length > 1) {
          const sevPlaceholders = sevValues.map(s => { paramIdx++; params.push(s); return `$${paramIdx}`; });
          conditions.push(`severity IN (${sevPlaceholders.join(",")})`);
        }
      }
      if (status && status !== "all") {
        paramIdx++;
        conditions.push(`status = $${paramIdx}`);
        params.push(status);
      }
      if (search) {
        paramIdx++;
        conditions.push(`(title ILIKE $${paramIdx} OR description ILIKE $${paramIdx} OR source ILIKE $${paramIdx})`);
        params.push(`%${search}%`);
      }

      if (domain && domain !== "all" && domain !== "overview") {
        const domainConditions: string[] = [];
        switch (domain) {
          case "email":
            domainConditions.push("LOWER(source) LIKE '%email%'", "LOWER(source) LIKE '%harmony email%'", "LOWER(category) LIKE '%email%'", "LOWER(incident_type) LIKE '%phish%'", "LOWER(incident_type) LIKE '%spam%'", "LOWER(incident_type) LIKE '%bec%'");
            break;
          case "endpoint":
            domainConditions.push("LOWER(source) LIKE '%endpoint%'", "LOWER(source) LIKE '%edr%'", "LOWER(source) LIKE '%cynet%'", "LOWER(category) LIKE '%endpoint%'", "LOWER(incident_type) LIKE '%malware%'", "LOWER(incident_type) LIKE '%ransomware%'");
            break;
          case "network":
            domainConditions.push("LOWER(source) LIKE '%network%'", "LOWER(source) LIKE '%firewall%'", "LOWER(source) LIKE '%ids%'", "LOWER(source) LIKE '%ips%'", "LOWER(category) LIKE '%network%'", "LOWER(incident_type) LIKE '%intrusion%'", "LOWER(incident_type) LIKE '%ddos%'");
            break;
          case "cloud":
            domainConditions.push("LOWER(source) LIKE '%cloud%'", "LOWER(source) LIKE '%aws%'", "LOWER(source) LIKE '%azure%'", "LOWER(source) LIKE '%gcp%'", "LOWER(source) LIKE '%casb%'", "LOWER(source) LIKE '%sse%'", "LOWER(category) LIKE '%cloud%'", "LOWER(category) LIKE '%casb%'");
            break;
          case "identity":
            domainConditions.push("LOWER(source) LIKE '%identity%'", "LOWER(source) LIKE '%iam%'", "LOWER(source) LIKE '%active directory%'", "LOWER(source) LIKE '%ldap%'", "LOWER(category) LIKE '%identity%'", "LOWER(incident_type) LIKE '%credential%'", "LOWER(incident_type) LIKE '%brute%'", "LOWER(incident_type) LIKE '%unauthorized%'");
            break;
          case "waf":
            domainConditions.push("LOWER(source) LIKE '%waf%'", "LOWER(source) LIKE '%web%'", "LOWER(category) LIKE '%web%'", "LOWER(incident_type) LIKE '%injection%'", "LOWER(incident_type) LIKE '%xss%'");
            break;
          case "dlp":
            domainConditions.push("LOWER(source) LIKE '%dlp%'", "LOWER(category) LIKE '%dlp%'", "LOWER(incident_type) LIKE '%data loss%'", "LOWER(incident_type) LIKE '%data leak%'");
            break;
          case "vulnerability":
            domainConditions.push("LOWER(category) LIKE '%vulnerability%'", "LOWER(incident_type) LIKE '%vulnerability%'", "LOWER(source) LIKE '%rapid7%'", "LOWER(source) LIKE '%qualys%'", "LOWER(source) LIKE '%tenable%'");
            break;
          case "web":
            domainConditions.push("LOWER(source) LIKE '%casb%'", "LOWER(source) LIKE '%sse%'", "LOWER(source) LIKE '%skyhigh%'", "LOWER(source) LIKE '%netskope%'", "LOWER(source) LIKE '%zscaler%'");
            break;
          case "threat_intel":
            domainConditions.push("LOWER(source) LIKE '%threat%'", "LOWER(source) LIKE '%cyble%'", "LOWER(source) LIKE '%recorded future%'", "LOWER(source) LIKE '%threatmon%'", "LOWER(source) LIKE '%group-ib%'", "LOWER(category) LIKE '%threat%'");
            break;
        }
        if (domainConditions.length > 0) {
          conditions.push(`(${domainConditions.join(" OR ")})`);
        }
      }

      const whereClause = conditions.join(" AND ");
      const countResult = await pool.query(`SELECT COUNT(*)::int as total FROM incidents WHERE ${whereClause}`, params);
      const total = countResult.rows[0]?.total || 0;
      const totalPages = Math.ceil(total / pageSize);
      const offset = (page - 1) * pageSize;

      const dataResult = await pool.query(
        `SELECT * FROM incidents WHERE ${whereClause} ORDER BY created_at DESC NULLS LAST LIMIT $${paramIdx + 1} OFFSET $${paramIdx + 2}`,
        [...params, pageSize, offset]
      );

      const data = dataResult.rows.map((row: any) => ({
        id: row.id,
        tenantId: row.tenant_id,
        title: row.title,
        description: row.description,
        severity: row.severity,
        status: row.status,
        category: row.category,
        source: row.source,
        sourceIp: row.source_ip,
        destinationIp: row.destination_ip,
        affectedAssets: row.affected_assets,
        recommendation: row.recommendation,
        mitreTactic: row.mitre_tactic,
        mitreTechniqueId: row.mitre_technique_id,
        mitreTechnique: row.mitre_technique,
        killChainPhase: row.kill_chain_phase,
        confidenceScore: row.confidence_score,
        isTruePositive: row.is_true_positive,
        classification: row.classification,
        detectionSource: row.detection_source,
        actionTaken: row.action_taken,
        incidentType: row.incident_type,
        iocData: row.ioc_data,
        enrichedDescription: row.enriched_description,
        triageScore: row.triage_score,
        triageReasoning: row.triage_reasoning,
        triageSuggestedTp: row.triage_suggested_tp,
        triageScoredAt: row.triage_scored_at,
        createdAt: row.created_at,
        updatedAt: row.updated_at,
      }));

      // Surface data-source/latency trust signals (Task #178 pattern). The
      // incidents list is served exclusively from PG, so source is constant.
      res.json({ data, total, page, pageSize, totalPages, source: "postgres", latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/events/stream/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenant = await storage.getTenant(tenantId);
      let tenantIds = [tenantId];
      if (tenant && tenant.type === "mssp") {
        const children = await storage.getChildTenants(tenantId);
        if (children.length > 0) tenantIds = [tenantId, ...children.map(c => c.id)];
      }

      res.writeHead(200, {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache",
        "Connection": "keep-alive",
        "X-Accel-Buffering": "no",
      });

      const recent = securityEventBus.getRecentEvents(tenantIds, 20);
      if (recent.length > 0) {
        res.write(`data: ${JSON.stringify({ type: "initial", events: recent })}\n\n`);
      }

      const onEvent = (evt: LiveSecurityEvent) => {
        if (tenantIds.includes(evt.tenantId)) {
          res.write(`data: ${JSON.stringify({ type: "event", event: evt })}\n\n`);
        }
      };
      securityEventBus.on("security_event", onEvent);

      const heartbeat = setInterval(() => {
        res.write(`:heartbeat\n\n`);
      }, 30000);

      req.on("close", () => {
        securityEventBus.off("security_event", onEvent);
        clearInterval(heartbeat);
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/events/:tenantId/stats", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // Route /stats to ClickHouse when available so PG is bypassed entirely on
      // high-volume tenants. CH returns total + severity breakdown + hourly
      // buckets + byLogSource — enough to populate the events console UI. PG
      // is only invoked when CH is unconfigured or errors mid-request.
      const reqStart = Date.now();
      const chClient = getClickHouseClient();
      if (chClient) {
        try {
          const days = parseInt(req.query.days as string) || 1;
          const startDate = new Date(Date.now() - days * 86_400_000);
          const chStart = Date.now();
          // Hybrid: CH serves the heavy aggregates (totals, severity,
          // byLogSource, byEventType, hourly buckets) while a slim PG query
          // returns the pipeline-state counters that CH does not track.
          // Integration-aware guard is applied to every CH query so
          // visibility matches the PG buildIntegrationGuardSql EXISTS path.
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard = buildChIntegrationGuard(guardMap);
          const [chStats, chBuckets, chBySource, chByType, pgCounters] = await Promise.all([
            chClient.queryEventStats(tenantIds, { startDate, integrationGuardSql: chGuard }),
            chClient.queryEventBuckets(tenantIds, { startDate, limit: days * 24, integrationGuardSql: chGuard }),
            chClient.queryEventsBySourceType(tenantIds, days * 24, 20, chGuard),
            chClient.queryEventsByEventType(tenantIds, days * 24, 20, chGuard),
            storage.getEventPipelineCounters(tenantId, tenantIds),
          ]);
          logChQuery("events.stats", Date.now() - chStart, {
            tenant: tenantId, days, total: chStats.total,
          });
          return res.json({
            ...pgCounters,
            byEventType: chByType.map((r) => ({ eventType: r.eventType, count: r.count })),
            bySeverity: [
              { severity: "critical", count: chStats.critical },
              { severity: "high",     count: chStats.high },
              { severity: "medium",   count: chStats.medium },
              { severity: "low",      count: chStats.low },
            ],
            byLogSource: chBySource,
            source: "clickhouse_olap",
            latencyMs: Date.now() - reqStart,
            clickhouse: {
              source: "clickhouse_olap",
              period_hours: days * 24,
              totals: chStats,
              hourly_buckets: chBuckets,
            },
          });
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("events.stats.failed", 0, { tenant: tenantId, error: chMsg });
          // Fall through to PG path below
        }
      }

      const stats = await storage.getEventPipelineStats(tenantId, tenantIds);
      res.json({ ...stats, source: "postgres", latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/events/:tenantId/cross-source-correlations", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const cacheKey = `cross-source-${tenantId}`;
      const cached = await getCache(cacheKey);
      if (cached) return res.json({ ...cached, latencyMs: Date.now() - reqStart });

      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // Cross-source IOC correlation is the most expensive event-aggregation
      // query in the app (full GROUP BY + DISTINCT over all events). Route to
      // ClickHouse first when available so we bypass PostgreSQL entirely on
      // hot tenants. Falls back to PG only when CH is unconfigured or errors.
      const chClientCorr = getClickHouseClient();
      if (chClientCorr) {
        try {
          const lookbackHours = parseInt(req.query.hours as string) || 24;
          const chStart = Date.now();
          // Pass full tenantIds (parent + children for MSSP) and integration
          // guard so CH matches the PG EXISTS predicate's visibility scope.
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard = buildChIntegrationGuard(guardMap);
          const chCorrelations = await chClientCorr.queryCrossSourceCorrelations(
            tenantIds, lookbackHours, 20, chGuard,
          );
          logChQuery("events.cross-source-correlations", Date.now() - chStart, {
            tenant: tenantId, lookbackHours, rows: chCorrelations.length,
          });
          const chResult = {
            correlations: chCorrelations.map((r) => ({
              iocValue:   r.ioc_value,
              iocType:    r.ioc_type,
              // eventTypes mirrors the PG response contract the events console
              // UI consumes (c.eventTypes.map(...)). CH now groupArray(DISTINCT
              // event_type) so the shape is identical.
              eventTypes: r.event_types,
              logSources: r.log_sources,
              sourceTypes: r.source_types,
              totalHits:  r.event_count,
              sourceCount: r.source_type_count,
              maxConfidence: r.max_confidence,
              lastSeen:   r.last_seen,
            })),
            totalCorrelations: chCorrelations.length,
            source: "clickhouse_olap",
          };
          setCache(cacheKey, chResult);
          return res.json({ ...chResult, latencyMs: Date.now() - reqStart });
        } catch (chErr: unknown) {
          // ClickHouse unavailable — fall through to PG path
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("events.cross-source-correlations.failed", 0, {
            tenant: tenantId, error: chMsg,
          });
        }
      }

      const placeholders1 = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const placeholders2 = tenantIds.map((_, i) => `$${tenantIds.length + i + 1}`).join(",");

      const correlationResult = await poolRead.query(
        `WITH ioc_sources AS (
          SELECT
            COALESCE(attacker, '') as ioc_value,
            'ip' as ioc_type,
            event_type,
            COALESCE(log_source, source_type, 'Unknown') as log_source,
            COUNT(*)::int as hit_count
          FROM security_events
          WHERE tenant_id IN (${placeholders1})
            AND attacker IS NOT NULL AND attacker != ''
            AND attacker ~ '^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]'
          GROUP BY attacker, event_type, COALESCE(log_source, source_type, 'Unknown')
          UNION ALL
          SELECT
            COALESCE(target, '') as ioc_value,
            'target' as ioc_type,
            event_type,
            COALESCE(log_source, source_type, 'Unknown') as log_source,
            COUNT(*)::int as hit_count
          FROM security_events
          WHERE tenant_id IN (${placeholders2})
            AND target IS NOT NULL AND target != ''
            AND target ~ '^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]'
          GROUP BY target, event_type, COALESCE(log_source, source_type, 'Unknown')
        )
        SELECT ioc_value, ioc_type, 
               array_agg(DISTINCT event_type::text) as event_types,
               array_agg(DISTINCT log_source::text) as log_sources,
               SUM(hit_count)::int as total_hits
        FROM ioc_sources
        GROUP BY ioc_value, ioc_type
        HAVING COUNT(DISTINCT event_type) >= 2
        ORDER BY total_hits DESC
        LIMIT 20`,
        [...tenantIds, ...tenantIds]
      );

      const correlations = correlationResult.rows.map((r: any) => ({
        iocValue: r.ioc_value,
        iocType: r.ioc_type,
        eventTypes: r.event_types,
        logSources: r.log_sources,
        totalHits: r.total_hits,
      }));

      const result = {
        correlations,
        totalCorrelations: correlations.length,
        source: "postgres",
      };
      setCache(cacheKey, result);
      res.json({ ...result, latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/events/:tenantId/timeline", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const interval = (req.query.interval as string) || "24h";
      const dateFrom = req.query.dateFrom ? new Date(req.query.dateFrom as string) : undefined;
      const dateTo = req.query.dateTo ? new Date(req.query.dateTo as string) : undefined;

      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // The PG `security_events` table is intentionally sparse in production
      // (events flow Kafka → ClickHouse). Without this fast-path the dashboard
      // event-volume chart would render empty in AWS even though events are
      // actively ingested. We bucket on `ingested_at` in CH using the same
      // interval grid as the PG implementation so the line chart shape and
      // severity stacking are identical to dev mode.
      const chClientTl = getClickHouseClient();
      if (chClientTl) {
        try {
          const bucketCh: Record<string, { interval: string; lookbackMs: number }> = {
            "1h":  { interval: "15 MINUTE", lookbackMs:        3_600_000 },
            "24h": { interval: "1 HOUR",    lookbackMs:       86_400_000 },
            "7d":  { interval: "6 HOUR",    lookbackMs:    7 * 86_400_000 },
            "30d": { interval: "1 DAY",     lookbackMs:   30 * 86_400_000 },
            "90d": { interval: "1 WEEK",    lookbackMs:   90 * 86_400_000 },
            "all": { interval: "1 WEEK",    lookbackMs:  365 * 86_400_000 },
          };
          const cfg = bucketCh[interval] || bucketCh["24h"];
          const start = dateFrom ?? new Date(Date.now() - cfg.lookbackMs);
          const end   = dateTo   ?? new Date();
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard = buildChIntegrationGuard(guardMap);
          const guardSql = chGuard ? ` AND ${chGuard}` : "";
          const chStart = Date.now();
          const sql = `
            SELECT
              formatDateTime(toStartOfInterval(ingested_at, INTERVAL ${cfg.interval}), '%Y-%m-%dT%H:%M:%SZ') AS ts,
              toUInt64(countIf(severity = 'critical')) AS critical,
              toUInt64(countIf(severity = 'high'))     AS high,
              toUInt64(countIf(severity = 'medium'))   AS medium,
              toUInt64(countIf(severity = 'low'))      AS low,
              toUInt64(countIf(severity = 'info'))     AS info,
              toUInt64(count())                        AS total
            FROM security_events_distributed
            WHERE tenant_id IN (${tenantIds.join(",")})
              AND ingested_at >= '${formatChDateTime64(start)}'
              AND ingested_at <= '${formatChDateTime64(end)}'
              ${guardSql}
            GROUP BY ts
            ORDER BY ts ASC
          `;
          const rows = await chClientTl.queryRows<any>(sql);
          logChQuery("events.timeline", Date.now() - chStart, {
            tenant: tenantId, interval, points: rows.length,
          });
          return res.json({
            timeline: rows.map((r) => ({
              timestamp: r.ts,
              critical:  Number(r.critical) || 0,
              high:      Number(r.high)     || 0,
              medium:    Number(r.medium)   || 0,
              low:       Number(r.low)      || 0,
              info:      Number(r.info)     || 0,
              total:     Number(r.total)    || 0,
            })),
            source: "clickhouse_olap",
            latencyMs: Date.now() - reqStart,
          });
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("events.timeline.failed", 0, { tenant: tenantId, error: chMsg });
          // fall through to PG
        }
      }

      const timeline = await storage.getEventVolumeTimeline(tenantId, tenantIds, interval, dateFrom, dateTo);
      res.json({ timeline, source: "postgres", latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/events/:tenantId/detail/:eventId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);

      // Accept either a numeric PG id or a string event_hash. The CH-routed
      // event-list path returns rows keyed by event_hash (stored in CH as
      // event_id) so detail-fetching from CH-served lists falls back to a
      // hash lookup against PostgreSQL, where the full row still lives.
      const rawId = String(req.params.eventId);
      const numericId = parseInt(rawId, 10);
      let event: any;
      if (!isNaN(numericId) && /^\d+$/.test(rawId)) {
        event = await storage.getSecurityEventById(numericId, tenantId);
      } else {
        const hashLookup = await pool.query(
          "SELECT id FROM security_events WHERE event_hash = $1 AND tenant_id = $2 LIMIT 1",
          [rawId, tenantId],
        );
        const pgId = hashLookup.rows[0]?.id;
        if (pgId) event = await storage.getSecurityEventById(pgId, tenantId);
      }

      // ── ClickHouse fallback ─────────────────────────────────────────────────
      // In AWS the canonical event row lives in CH (PG is sparse). When a user
      // clicks a row served from the CH event list, the `id` is the event_hash
      // string and the PG hash lookup above returns nothing. Hydrate the
      // detail directly from CH so the side-panel renders correctly.
      if (!event) {
        const chDetail = getClickHouseClient();
        if (chDetail && isNaN(numericId)) {
          try {
            const safeHash = rawId.replace(/'/g, "\\'");
            const chRows = await chDetail.queryRows<any>(`
              SELECT
                toString(event_id)                                 AS event_id,
                tenant_id,
                source_type,
                log_source,
                severity,
                event_type,
                host,
                toString(src_ip)                                   AS src_ip,
                toString(dst_ip)                                   AS dst_ip,
                user_name,
                process_name,
                mitre_tactic,
                mitre_technique,
                kill_chain_phase,
                confidence_score,
                data_region,
                raw_event,
                normalized_event,
                iocs,
                formatDateTime(ingested_at, '%Y-%m-%dT%H:%M:%SZ') AS ingested_at
              FROM security_events_distributed
              WHERE event_id = '${safeHash}' AND tenant_id = ${tenantId}
              LIMIT 1
            `);
            const r = chRows[0];
            if (r) {
              event = {
                id:               r.event_id,
                tenantId:         r.tenant_id,
                eventType:        r.event_type,
                sourceType:       r.source_type,
                logSource:        r.log_source || r.source_type,
                severity:         r.severity,
                asset:            r.host,
                attacker:         r.src_ip,
                target:           r.dst_ip,
                user:             r.user_name,
                processName:      r.process_name,
                mitreTactic:      r.mitre_tactic,
                mitreTechnique:   r.mitre_technique,
                killChainPhase:   r.kill_chain_phase,
                confidenceScore:  r.confidence_score,
                dataRegion:       r.data_region,
                rawPayload:       chJsonParse(r.raw_event),
                normalizedEvent:  chJsonParse(r.normalized_event),
                iocs:             chJsonParse(r.iocs) ?? [],
                eventHash:        r.event_id,
                createdAt:        r.ingested_at,
                occurredAt:       r.ingested_at,
                timestamp:        r.ingested_at,
                source:           "clickhouse_olap",
              };
            }
          } catch (chErr: unknown) {
            const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
            logChQuery("events.detail.failed", 0, { tenant: tenantId, error: chMsg });
          }
        }
      }

      if (!event) return res.status(404).json({ message: "Event not found" });
      res.json(event);
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/events/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      const params: any = {
        tenantIds,
        page: parseInt(req.query.page as string) || 1,
        pageSize: parseInt(req.query.pageSize as string) || 50,
        sortBy: req.query.sortBy as string,
        sortOrder: req.query.sortOrder as string,
      };

      if (req.query.eventType) params.eventType = req.query.eventType;
      if (req.query.severity) {
        const sev = req.query.severity as string;
        params.severity = sev.includes(",") ? sev.split(",") : sev;
      }
      if (req.query.pipelineStatus) params.pipelineStatus = req.query.pipelineStatus;
      if (req.query.logSource) params.logSource = req.query.logSource;
      if (req.query.threat) params.threat = req.query.threat;
      if (req.query.attacker) params.attacker = req.query.attacker;
      if (req.query.target) params.target = req.query.target;
      if (req.query.country) params.country = req.query.country;
      if (req.query.action) params.action = req.query.action;
      if (req.query.mitreTactic) params.mitreTactic = req.query.mitreTactic;
      if (req.query.mitreTechnique) params.mitreTechnique = req.query.mitreTechnique;
      if (req.query.dateFrom) params.dateFrom = new Date(req.query.dateFrom as string);
      if (req.query.dateTo) params.dateTo = new Date(req.query.dateTo as string);
      if (req.query.search) params.search = req.query.search;

      const reqStart = Date.now();
      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // High-volume event list pulls bypass PostgreSQL when CH is available.
      // CH returns a row keyed by event_id (the dual-write copies the PG
      // event_hash into CH.event_id); we surface that as `id` in the response
      // so the React event table renders unchanged. /detail/:eventId accepts
      // either a numeric PG id or the event_hash string and falls back to a
      // hash lookup against PG, preserving end-to-end click-through.
      //
      // CH is skipped when the request needs PG-only filters that are not
      // mirrored in the OLAP schema (pipelineStatus, geo country, attacker /
      // target free-text, action, threat) so semantics never silently change.
      const chClientList = getClickHouseClient();
      // queryEvents only supports ingested_at DESC ordering, so fall back to
      // PG whenever a non-default sort is requested to preserve client
      // ordering contract exactly.
      const defaultSort =
        (!params.sortBy || params.sortBy === "occurredAt" || params.sortBy === "createdAt")
        && (!params.sortOrder || params.sortOrder.toLowerCase() === "desc");
      const chSafe = !params.pipelineStatus && !params.country && !params.attacker
        && !params.target && !params.action && !params.threat && defaultSort;
      if (chClientList && chSafe) {
        try {
          const limit = params.pageSize;
          const offset = (params.page - 1) * params.pageSize;
          const sevFilter = Array.isArray(params.severity)
            ? params.severity
            : (params.severity ? [params.severity] : undefined);
          // logSource filter maps to the CH log_source column (product-name
          // identifier like "Cynet 360"), matching the PG filter semantics.
          const logSourceFilter = params.logSource ? [params.logSource] : undefined;
          // Enforce integration-aware visibility on the CH path with the
          // same deny-by-default semantics as the PG buildIntegrationGuardSql
          // EXISTS predicate — per-tenant log_source whitelist.
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard = buildChIntegrationGuard(guardMap);
          const chStart = Date.now();
          const { rows: chRows, total: chTotal } = await chClientList.queryEvents(tenantIds, {
            startDate: params.dateFrom,
            endDate:   params.dateTo,
            severity:  sevFilter,
            logSource: logSourceFilter,
            eventType: params.eventType,
            mitreTactic: params.mitreTactic,
            mitreTechnique: params.mitreTechnique,
            search: params.search,
            integrationGuardSql: chGuard,
            limit, offset,
          });
          logChQuery("events.list", Date.now() - chStart, {
            tenant: tenantId, page: params.page, pageSize: params.pageSize,
            rows: chRows.length, total: chTotal,
          });
          const events = chRows.map((r: Record<string, unknown>) => ({
            id:           r.event_id,                 // event_hash string; /detail handles hash lookup
            tenantId:     r.tenant_id,
            eventType:    r.event_type,
            sourceType:   r.source_type,
            logSource:    r.log_source || r.source_type,
            severity:     r.severity,
            asset:        r.host,
            attacker:     r.src_ip,
            target:       r.dst_ip,
            user:         r.user_name,
            mitreTactic:  r.mitre_tactic,
            mitreTechnique: r.mitre_technique,
            killChainPhase: r.kill_chain_phase,
            confidenceScore: r.confidence_score,
            dataRegion:   r.data_region,
            createdAt:    r.ingested_at,
            occurredAt:   r.ingested_at,    // Detection Feed time-window math reads occurredAt
            timestamp:    r.ingested_at,
            eventHash:    r.event_id,
            source:       "clickhouse_olap",
          }));
          return res.json({
            events,
            totalCount: chTotal,
            totalPages: Math.max(1, Math.ceil(chTotal / params.pageSize)),
            page: params.page,
            pageSize: params.pageSize,
            source: "clickhouse_olap",
            latencyMs: Date.now() - reqStart,
          });
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("events.list.failed", 0, { tenant: tenantId, error: chMsg });
          // Fall through to PG path below — zero-regression behavior on CH miss.
        }
      }

      // The integration guard is enforced inside storage.searchSecurityEvents via
      // a per-row EXISTS subquery — no pre-check needed here.
      const result = await storage.searchSecurityEvents(params);
      res.json({ ...result, source: "postgres", latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(error.message?.includes("Access denied") ? 403 : 500).json({ message: error.message });
    }
  });

  app.get("/api/drilldown/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const { filterType, filterValue, domain } = req.query;
      if (!filterType || !filterValue) {
        return res.status(400).json({ message: "filterType and filterValue are required" });
      }
      const tenant = await storage.getTenant(tenantId);
      let tenantIds: number[];
      if (tenant && tenant.type === "mssp") {
        const children = await storage.getChildTenants(tenantId);
        tenantIds = [tenantId, ...children.map(c => c.id)];
      } else {
        tenantIds = [tenantId];
      }

      const fv = String(filterValue);
      const likePat = `%${fv}%`;
      const evPlaceholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const evConditions: string[] = [`tenant_id IN (${evPlaceholders})`];
      const evParams: any[] = [...tenantIds];
      let pIdx = tenantIds.length + 1;

      if (domain) {
        evConditions.push(`event_type::text = $${pIdx}`);
        evParams.push(String(domain).toLowerCase());
        pIdx++;
      }

      const incConditions: string[] = [`tenant_id IN (${evPlaceholders})`];
      const incParams: any[] = [...tenantIds];
      let iPIdx = tenantIds.length + 1;

      evConditions.push(buildIntegrationGuardSql("security_events.tenant_id", "security_events.log_source"));
      incConditions.push(buildIntegrationGuardSql("incidents.tenant_id", "incidents.detection_source"));

      const eventFilterMap: Record<string, string> = {
        threat: `threat ILIKE $${pIdx}`,
        attacker: `attacker ILIKE $${pIdx}`,
        target: `(target ILIKE $${pIdx} OR asset ILIKE $${pIdx})`,
        source: `(log_source ILIKE $${pIdx} OR source_type ILIKE $${pIdx})`,
        event_type: `event_type::text ILIKE $${pIdx}`,
        severity: `severity::text = LOWER($${pIdx})`,
        action: `action ILIKE $${pIdx}`,
        country: `country ILIKE $${pIdx}`,
        app: `app ILIKE $${pIdx}`,
        mitre_tactic: `mitre_tactic ILIKE $${pIdx}`,
        mitre_technique: `mitre_technique ILIKE $${pIdx}`,
        kill_chain_phase: `raw_payload->>'killChainPhase' ILIKE $${pIdx}`,
        incident_type: `event_type::text ILIKE $${pIdx}`,
        attack_vector: `threat_vector ILIKE $${pIdx}`,
      };

      const incidentFilterMap: Record<string, string> = {
        threat: `title ILIKE $${iPIdx}`,
        attacker: `source_ip ILIKE $${iPIdx}`,
        target: `affected_assets ILIKE $${iPIdx}`,
        source: `source ILIKE $${iPIdx}`,
        event_type: `category ILIKE $${iPIdx}`,
        severity: `severity::text = LOWER($${iPIdx})`,
        action: `action_taken ILIKE $${iPIdx}`,
        mitre_tactic: `mitre_tactic ILIKE $${iPIdx}`,
        mitre_technique: `(mitre_technique ILIKE $${iPIdx} OR mitre_technique_id ILIKE $${iPIdx})`,
        kill_chain_phase: `kill_chain_phase ILIKE $${iPIdx}`,
        incident_type: `incident_type ILIKE $${iPIdx}`,
        attack_vector: `category ILIKE $${iPIdx}`,
      };

      const evFilter = eventFilterMap[filterType as string];
      const incFilter = incidentFilterMap[filterType as string];

      if (evFilter) {
        evConditions.push(evFilter);
        evParams.push(filterType === "severity" ? fv : likePat);
      }
      if (incFilter) {
        incConditions.push(incFilter);
        incParams.push(filterType === "severity" ? fv : likePat);
      }

      const skipIncidents = filterType === "country" || filterType === "app";

      // ── ClickHouse fast-path for events portion ────────────────────────────
      // Drilldown is the click-through target for nearly every dashboard
      // widget. In AWS the PG `security_events` table is sparse, so without a
      // CH fast-path every dashboard click in production opens an empty panel
      // even though the underlying CH store has the data. We map the supported
      // filter types to their CH columns and run a single CH query (count +
      // rows). Filters with no CH equivalent (country, app, action,
      // threat_vector, raw_payload->killChainPhase) fall through to PG so
      // semantics are preserved exactly.
      const chDrill = getClickHouseClient();
      const chColMap: Record<string, string | null> = {
        threat:           null, // CH has no `threat` column; CH path skipped
        attacker:         "src_ip",
        target:           "dst_ip",
        source:           "log_source",
        event_type:       "event_type",
        severity:         "severity",
        mitre_tactic:     "mitre_tactic",
        mitre_technique:  "mitre_technique",
        kill_chain_phase: "kill_chain_phase",
        incident_type:    "event_type",
      };
      const chCol = chColMap[filterType as string];
      let eventCountResult: any;
      let eventRowsResult: any;
      let usedCh = false;
      if (chDrill && chCol) {
        try {
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard  = buildChIntegrationGuard(guardMap);
          const safeFv   = fv.replace(/'/g, "\\'");
          const evWhereParts: string[] = [
            `tenant_id IN (${tenantIds.join(",")})`,
            chGuard,
          ];
          if (domain) evWhereParts.push(`event_type = '${String(domain).toLowerCase().replace(/'/g, "\\'")}'`);
          if (filterType === "severity") {
            evWhereParts.push(`severity = '${safeFv.toLowerCase()}'`);
          } else if (filterType === "source") {
            evWhereParts.push(`(positionCaseInsensitive(log_source, '${safeFv}') > 0 OR positionCaseInsensitive(source_type, '${safeFv}') > 0)`);
          } else if (filterType === "target") {
            evWhereParts.push(`(positionCaseInsensitive(toString(dst_ip), '${safeFv}') > 0 OR positionCaseInsensitive(host, '${safeFv}') > 0)`);
          } else if (chCol === "src_ip" || chCol === "dst_ip") {
            evWhereParts.push(`positionCaseInsensitive(toString(${chCol}), '${safeFv}') > 0`);
          } else {
            evWhereParts.push(`positionCaseInsensitive(${chCol}, '${safeFv}') > 0`);
          }
          const evWhere = evWhereParts.filter(Boolean).join(" AND ");
          const chStart = Date.now();
          const [chCntRows, chRows] = await Promise.all([
            chDrill.queryRows<{ cnt: string }>(
              `SELECT count() AS cnt FROM security_events_distributed WHERE ${evWhere}`,
            ),
            chDrill.queryRows<any>(`
              SELECT
                toString(event_id)                                  AS id,
                event_type, severity,
                host                                                 AS asset,
                toString(src_ip)                                    AS attacker,
                toString(dst_ip)                                    AS target,
                source_type, log_source,
                mitre_tactic, mitre_technique, kill_chain_phase,
                confidence_score,
                formatDateTime(ingested_at, '%Y-%m-%dT%H:%M:%SZ')  AS occurred_at,
                tenant_id
              FROM security_events_distributed
              WHERE ${evWhere}
              ORDER BY ingested_at DESC
              LIMIT 100
            `),
          ]);
          logChQuery("drilldown.events", Date.now() - chStart, {
            tenant: tenantId, filterType, rows: chRows.length, total: chCntRows[0]?.cnt,
          });
          eventCountResult = { rows: [{ cnt: parseInt(chCntRows[0]?.cnt ?? "0", 10) }] };
          eventRowsResult  = { rows: chRows.map((r) => ({
            id: r.id,
            event_type: r.event_type,
            severity: r.severity,
            threat: null,
            target: r.target,
            attacker: r.attacker,
            asset: r.asset,
            app: null,
            description: null,
            threat_vector: null,
            mitre_tactic: r.mitre_tactic,
            mitre_technique: r.mitre_technique,
            action: null,
            source_type: r.source_type,
            log_source: r.log_source,
            sender: null,
            recipient: null,
            country: null,
            risk_score: r.confidence_score,
            raw_payload: { killChainPhase: r.kill_chain_phase },
            occurred_at: r.occurred_at,
            created_at: r.occurred_at,
            tenant_id: r.tenant_id,
          })) };
          usedCh = true;
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("drilldown.events.failed", 0, { tenant: tenantId, error: chMsg });
          // fall through to PG for events
        }
      }

      const [eventCountResultPg, eventRowsResultPg, incidentCountResult, incidentRowsResult] = await Promise.all([
        usedCh ? Promise.resolve(eventCountResult) : poolRead.query(`SELECT COUNT(*)::int as cnt FROM security_events WHERE ${evConditions.join(" AND ")}`, evParams),
        usedCh ? Promise.resolve(eventRowsResult)  : poolRead.query(`SELECT id, event_type, severity, threat, target, attacker, asset, app, description, threat_vector, mitre_tactic, mitre_technique, action, source_type, log_source, sender, recipient, country, risk_score, raw_payload, occurred_at, created_at, tenant_id FROM security_events WHERE ${evConditions.join(" AND ")} ORDER BY occurred_at DESC LIMIT 100`, evParams),
        skipIncidents ? Promise.resolve({ rows: [{ cnt: 0 }] }) : poolRead.query(`SELECT COUNT(*)::int as cnt FROM incidents WHERE ${incConditions.join(" AND ")}`, incParams),
        skipIncidents ? Promise.resolve({ rows: [] }) : poolRead.query(`SELECT id, title, severity, status, source, category, mitre_tactic, mitre_technique, mitre_technique_id, kill_chain_phase, confidence_score, classification, created_at, tenant_id FROM incidents WHERE ${incConditions.join(" AND ")} ORDER BY created_at DESC LIMIT 100`, incParams),
      ]);
      eventCountResult = eventCountResultPg;
      eventRowsResult  = eventRowsResultPg;

      const incidentResults = incidentRowsResult.rows.map((inc: any) => ({
        id: inc.id,
        type: "incident" as const,
        title: inc.title,
        severity: inc.severity,
        status: inc.status,
        source: inc.source,
        category: inc.category,
        mitreTactic: inc.mitre_tactic,
        mitreTechnique: inc.mitre_technique,
        mitreTechniqueId: inc.mitre_technique_id,
        killChainPhase: inc.kill_chain_phase,
        confidenceScore: inc.confidence_score,
        classification: inc.classification,
        createdAt: inc.created_at,
        tenantId: inc.tenant_id,
      }));

      const eventResults = eventRowsResult.rows.map((ev: any) => ({
        id: ev.id,
        type: "event" as const,
        title: ev.threat || ev.description || `${ev.event_type} event`,
        severity: ev.severity,
        status: "detected",
        source: ev.log_source || ev.source_type,
        category: ev.event_type,
        mitreTactic: ev.mitre_tactic,
        mitreTechnique: ev.mitre_technique,
        mitreTechniqueId: null,
        killChainPhase: ev.raw_payload?.killChainPhase || null,
        confidenceScore: null,
        classification: null,
        createdAt: ev.occurred_at || ev.created_at,
        tenantId: ev.tenant_id,
      }));

      res.json({
        filterType,
        filterValue,
        totalIncidents: parseInt(incidentCountResult.rows[0]?.cnt || "0", 10),
        totalEvents: parseInt(eventCountResult.rows[0]?.cnt || "0", 10),
        incidents: incidentResults,
        events: eventResults,
        // Surface which store served the events portion so the drilldown
        // panel can render the same OLAP/Postgres trust badge as Detection
        // Feed and Log Explorer. Incidents always come from PG.
        source: usedCh ? "clickhouse_olap" : "postgres",
        latencyMs: Date.now() - reqStart,
      });
    } catch (error: any) {
      console.error("[Drilldown] Error:", error.message, "filterType:", req.query.filterType, "filterValue:", req.query.filterValue, "domain:", req.query.domain);
      res.status(error.status || 500).json({ message: error.message || "Failed to fetch drill-down data" });
    }
  });

