  app.get("/api/ai-activity/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      const access = await getUserTenantAccess(req);
      let tenantIds = [tenantId];
      if (access.role === "platform_admin" || access.role === "mss_admin") {
        const children = await storage.getChildTenants(tenantId);
        tenantIds = [tenantId, ...children.map((c: any) => c.id)];
      }

      const statsRes = await pool.query(`
        SELECT
          COUNT(*) FILTER (WHERE ai_pipeline_status = 'running') as active_pipelines,
          COUNT(*) FILTER (WHERE ai_handled = true AND ai_pipeline_status = 'completed' AND resolved_at >= CURRENT_DATE) as resolved_today,
          COUNT(*) FILTER (WHERE ai_escalated = true AND updated_at >= CURRENT_DATE) as escalated_today,
          COUNT(*) FILTER (WHERE ai_handled = true) as total_ai_handled,
          ROUND(AVG(ai_confidence) FILTER (WHERE ai_confidence IS NOT NULL))::int as avg_confidence,
          COUNT(*) FILTER (WHERE ai_escalated = true) as total_escalated
        FROM tickets WHERE tenant_id = ANY($1)
      `, [tenantIds]);

      const stats = statsRes.rows[0] || {};
      const totalHandled = parseInt(stats.total_ai_handled || "0");
      const totalEscalated = parseInt(stats.total_escalated || "0");
      const escalationRate = totalHandled > 0 ? Math.round((totalEscalated / totalHandled) * 100) : 0;

      const ticketsRes = await pool.query(`
        SELECT t.id, t.title, t.priority, t.status, t.category, t.ai_agent_name, t.ai_confidence,
               t.ai_escalated, t.ai_pipeline_status, t.created_at, t.resolved_at, t.tenant_id
        FROM tickets t
        WHERE t.tenant_id = ANY($1) AND t.ai_handled = true
        ORDER BY t.created_at DESC
        LIMIT 100
      `, [tenantIds]);

      const ticketIds = ticketsRes.rows.map((t: any) => t.id);
      let stepsMap: Record<number, any[]> = {};
      if (ticketIds.length > 0) {
        const stepsRes = await pool.query(
          `SELECT * FROM ai_ticket_tasks WHERE ticket_id = ANY($1) ORDER BY created_at ASC`,
          [ticketIds]
        );
        for (const step of stepsRes.rows) {
          if (!stepsMap[step.ticket_id]) stepsMap[step.ticket_id] = [];
          stepsMap[step.ticket_id].push(step);
        }
      }

      res.json({
        stats: {
          activePipelines: parseInt(stats.active_pipelines || "0"),
          resolvedToday: parseInt(stats.resolved_today || "0"),
          escalatedToday: parseInt(stats.escalated_today || "0"),
          avgConfidence: parseInt(stats.avg_confidence || "0"),
          totalAiHandled: totalHandled,
          escalationRate,
        },
        tickets: ticketsRes.rows.map((t: any) => ({
          ...t,
          steps: stepsMap[t.id] || [],
        })),
      });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to fetch AI activity" });
    }
  });

  app.patch("/api/tickets/:id", isAuthenticated, async (req: any, res) => {
    try {
      const id = parseInt(req.params.id);
      const existing = await storage.getTicket(id);
      if (!existing) return res.status(404).json({ message: "Ticket not found" });

      const access = await assertTenantAccess(req, existing.tenantId);
      assertMSSRole(access);

      const { status } = req.body;
      if (!status) return res.status(400).json({ message: "Status is required" });

      const ticket = await storage.updateTicket(id, { status });

      if (status === "resolved" || status === "closed") {
        const userId = req.user?.id || req.user?.claims?.sub || "";
        try {
          const slaBreached = existing.slaBreached;
          const metrics = ["tickets_closed"];
          if (!slaBreached) metrics.push("tickets_closed_within_sla");
          for (const m of metrics) {
            const challengeRows = await pool.query(
              `SELECT id, target_value FROM security_challenges WHERE metric = $1 AND is_active = true AND (tenant_id IS NULL OR tenant_id = $2)`, [m, existing.tenantId]
            );
            for (const ch of challengeRows.rows) {
              const ep = await pool.query(
                `SELECT id, current_value, completed_at FROM user_challenge_progress WHERE user_id = $1 AND challenge_id = $2 AND tenant_id = $3`,
                [userId, ch.id, existing.tenantId]
              );
              if (ep.rows.length === 0) {
                await pool.query(
                  `INSERT INTO user_challenge_progress (user_id, challenge_id, tenant_id, current_value, target_value) VALUES ($1, $2, $3, 1, $4)`,
                  [userId, ch.id, existing.tenantId, ch.target_value]
                );
                if (1 >= ch.target_value) {
                  await pool.query(`UPDATE user_challenge_progress SET completed_at = NOW() WHERE user_id = $1 AND challenge_id = $2 AND tenant_id = $3`, [userId, ch.id, existing.tenantId]);
                }
              } else if (!ep.rows[0].completed_at) {
                const newVal = ep.rows[0].current_value + 1;
                const setCompleted = newVal >= ch.target_value ? ", completed_at = NOW()" : "";
                await pool.query(`UPDATE user_challenge_progress SET current_value = $1, updated_at = NOW()${setCompleted} WHERE id = $2`, [newVal, ep.rows[0].id]);
              }
            }
          }
          const pc = await pool.query(`SELECT id FROM user_gamification_profiles WHERE user_id = $1 AND tenant_id = $2`, [userId, existing.tenantId]);
          if (pc.rows.length === 0) {
            await pool.query(`INSERT INTO user_gamification_profiles (user_id, tenant_id, total_xp, level, badges) VALUES ($1, $2, 0, 1, '[]')`, [userId, existing.tenantId]);
          }
          await pool.query(`UPDATE user_gamification_profiles SET last_activity_date = NOW(), updated_at = NOW() WHERE user_id = $1 AND tenant_id = $2`, [userId, existing.tenantId]);
        } catch (e) { /* non-critical */ }
      }

      res.json(ticket);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to update ticket" });
    }
  });

