  app.post("/api/admin/tenants/:tenantId/sso", isAuthenticated, isSuperAdminOrPlatformAdmin, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const { provider, displayName, config, allowedDomains, enabled, enforceSsoOnly } = req.body;
      if (!provider || !config) return res.status(400).json({ message: "provider and config are required" });

      const { tenantSsoConfigs } = await import("@shared/models/auth");
      const { db: dbI } = await import("./db");
      const { eq } = await import("drizzle-orm");

      const [existing] = await dbI.select().from(tenantSsoConfigs).where(eq(tenantSsoConfigs.tenantId, tenantId));
      if (existing) {
        const [updated] = await dbI.update(tenantSsoConfigs)
          .set({ provider, displayName, config, allowedDomains: allowedDomains || [], enabled: enabled !== false, enforceSsoOnly: !!enforceSsoOnly, updatedAt: new Date() })
          .where(eq(tenantSsoConfigs.tenantId, tenantId))
          .returning();
        return res.json(updated);
      }
      const [created] = await dbI.insert(tenantSsoConfigs)
        .values({ tenantId, provider, displayName, config, allowedDomains: allowedDomains || [], enabled: enabled !== false, enforceSsoOnly: !!enforceSsoOnly })
        .returning();
      res.status(201).json(created);
    } catch (err) {
      res.status(500).json({ message: "Failed to save SSO config" });
    }
  });

