  // ========== SMART TICKET ASSIGNMENT ==========
  app.post("/api/tickets/smart-assign", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      const tenantId = req.body.tenantId;
      await assertTenantAccess(req, tenantId);

      const priority = req.body.priority || "medium";
      const serviceId = req.body.serviceId ? parseInt(req.body.serviceId) : null;

      const now = new Date();
      const todayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate());
      const todayEnd = new Date(todayStart.getTime() + 86400000);

      const implMembers = await storage.getTeamMembersByType(tenantId, "implementation");
      const activeMembers = implMembers.filter(m => m.isActive);
      if (activeMembers.length === 0) return res.json({ assignedTo: null, reason: "No active implementation team members" });

      const shifts = await storage.getShiftRostersByDate(tenantId, todayStart, todayEnd);
      const onShiftMemberIds = new Set(shifts.map(s => s.teamMemberId));
      const onShiftMembers = activeMembers.filter(m => onShiftMemberIds.has(m.id));
      const candidatePool = onShiftMembers.length > 0 ? onShiftMembers : activeMembers;

      const allTickets = await storage.getTickets(tenantId);
      const openTickets = allTickets.filter(t => t.status === "open" || t.status === "in_progress");
      const workloadMap: Record<string, number> = {};
      candidatePool.forEach(m => { workloadMap[m.name] = 0; });
      openTickets.forEach(t => {
        if (t.assignedTo && workloadMap[t.assignedTo] !== undefined) {
          workloadMap[t.assignedTo]++;
        }
      });

      let bestAgent = candidatePool[0];
      let minLoad = Infinity;
      candidatePool.forEach(m => {
        const load = workloadMap[m.name] || 0;
        if (load < minLoad) { minLoad = load; bestAgent = m; }
      });

      let responseDueAt: Date | null = null;
      let resolutionDueAt: Date | null = null;
      if (serviceId) {
        const slas = await storage.getSlaDefinitions(serviceId);
        const matchingSla = slas.find(s => s.priority === priority) || slas[0];
        if (matchingSla) {
          responseDueAt = new Date(now.getTime() + matchingSla.responseTimeMinutes * 60000);
          resolutionDueAt = new Date(now.getTime() + matchingSla.resolutionTimeMinutes * 60000);
        }
      }

      res.json({
        assignedTo: bestAgent.name,
        agentId: bestAgent.id,
        onShift: onShiftMemberIds.has(bestAgent.id),
        currentLoad: workloadMap[bestAgent.name] || 0,
        responseDueAt,
        resolutionDueAt,
        reason: onShiftMembers.length > 0
          ? `Assigned to ${bestAgent.name} (on shift, ${minLoad} open tickets)`
          : `Assigned to ${bestAgent.name} (lowest workload: ${minLoad} open tickets, no shift roster found)`
      });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to assign" });
    }
  });

  // ========== AI PROJECT EXECUTIVE REPORT ==========
  app.post("/api/ai/project-report", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      const { projectId, reportType } = req.body;
      const project = await storage.getProject(projectId);
      if (!project) return res.status(404).json({ message: "Project not found" });
      await assertTenantAccess(req, project.tenantId);

      const [tasksList, scopeItems, activities, risks, logs] = await Promise.all([
        storage.getTasks(projectId),
        storage.getProjectScopes(projectId),
        storage.getProjectActivities(projectId),
        storage.getProjectRisks(projectId),
        storage.getActivityLogs(projectId),
      ]);

      const totalTasks = tasksList.length;
      const doneTasks = tasksList.filter(t => t.status === "done").length;
      const progress = totalTasks > 0 ? Math.round((doneTasks / totalTasks) * 100) : 0;

      const inclusions = scopeItems.filter(s => s.scopeType === "inclusion").map(s => s.title);
      const exclusions = scopeItems.filter(s => s.scopeType === "exclusion").map(s => s.title);

      const recentLogs = logs.slice(0, 20).map(l => `[${new Date(l.createdAt).toLocaleDateString()}] ${l.description}`).join("\n");

      const prompt = reportType === "executive"
        ? `Generate an Executive Summary report for the project "${project.name}".

Project Details:
- Status: ${project.status}
- Start: ${project.startDate ? new Date(project.startDate).toLocaleDateString() : "N/A"}
- End: ${project.endDate ? new Date(project.endDate).toLocaleDateString() : "N/A"}
- Overall Progress: ${progress}% (${doneTasks}/${totalTasks} tasks done)

Scope Inclusions: ${inclusions.join(", ") || "None defined"}
Scope Exclusions: ${exclusions.join(", ") || "None defined"}

Activities: ${activities.map(a => `${a.title} (${a.status}, ${a.percentComplete}%)`).join(", ") || "None"}

Open Risks: ${risks.filter(r => r.status === "open").map(r => `${r.title} [${r.probability}/${r.impact}]`).join(", ") || "None"}

Provide a professional executive summary with: 1) Project Health Overview, 2) Key Accomplishments, 3) Current Risks & Issues, 4) Next Steps & Recommendations. Format in markdown.`
        : `Generate a Daily Activity Report for project "${project.name}".

Recent Activity Log:
${recentLogs || "No recent activities"}

Current Tasks Status:
- Backlog: ${tasksList.filter(t => t.status === "backlog").length}
- To Do: ${tasksList.filter(t => t.status === "todo").length}
- In Progress: ${tasksList.filter(t => t.status === "in_progress").length}
- Review: ${tasksList.filter(t => t.status === "review").length}
- Done: ${tasksList.filter(t => t.status === "done").length}

Activities Progress: ${activities.map(a => `${a.title}: ${a.percentComplete}% (${a.status})`).join(", ") || "None"}

Create a concise daily status report with: 1) Today's Highlights, 2) Activities Completed, 3) In Progress Items, 4) Blockers, 5) Next Day Plan. Format in markdown.`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [
          { role: "system", content: "You are a professional project manager generating reports for MSSP security projects." },
          { role: "user", content: prompt }
        ],
        max_completion_tokens: 2000,
      });

      const content = completion.choices[0]?.message?.content || "Report generation failed";
      const dateStr = new Date().toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
      const title = reportType === "executive"
        ? `Executive Summary - ${project.name} - ${dateStr}`
        : `Daily Activity Report - ${project.name} - ${dateStr}`;

      const report = await storage.createReport({
        tenantId: project.tenantId,
        title,
        reportType: "executive_summary",
        period: reportType === "executive" ? "monthly" : "daily",
        executiveSummary: content,
        generatedBy: access.userId,
        status: "published",
      });

      await storage.createActivityLog({ projectId, description: `${reportType === "executive" ? "Executive Summary" : "Daily Activity Report"} generated`, logType: "report_generated", createdBy: access.userId });

      res.json({ report, content });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to generate report" });
    }
  });

