  app.post("/api/report-schedules", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const { tenantId, name, reportType, period, frequency, customPrompt, recipientEmails } = req.body;
      if (!tenantId || !name || !frequency) return res.status(400).json({ message: "tenantId, name, and frequency are required" });
      await assertTenantAccess(req, tenantId);

      const freqMs: Record<string, number> = {
        daily: 86400000,
        weekly: 604800000,
        biweekly: 1209600000,
        monthly: 2592000000,
        quarterly: 7776000000,
      };
      const nextRunAt = new Date(Date.now() + (freqMs[frequency] || freqMs.monthly));

      const schedule = await storage.createReportSchedule({
        tenantId,
        name,
        reportType: reportType || "executive_summary",
        period: period || "last_month",
        frequency,
        customPrompt: customPrompt || null,
        recipientEmails: recipientEmails || [],
        enabled: true,
        nextRunAt,
        createdBy: req.user?.claims?.sub || null,
      });
      res.json(schedule);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to create schedule" });
    }
  });

