  // Security Controls Library: Detect products for a tenant
  app.get("/api/security-controls/detect/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const products = await detectTenantProducts(tenantId);

      const existingDocs = await storage.getDocuments(tenantId);
      const autoGenDocs = existingDocs.filter((d: any) => d.isAutoGenerated && d.sourceProduct);

      const productsWithStatus = products.map(p => {
        const productDocs = autoGenDocs.filter((d: any) => d.sourceProduct === p.id);
        const docStatus: Record<string, { docId: number; generatedAt: string; version: number; isStale: boolean }> = {};
        for (const doc of productDocs) {
          const daysSinceUpdate = Math.floor((Date.now() - new Date(doc.updatedAt).getTime()) / (1000 * 60 * 60 * 24));
          docStatus[doc.docType || ""] = {
            docId: doc.id,
            generatedAt: doc.updatedAt.toISOString(),
            version: doc.generatedVersion || 1,
            isStale: daysSinceUpdate > (doc.staleDays || 90),
          };
        }
        return {
          ...p,
          existingDocs: docStatus,
          totalDocs: productDocs.length,
          hasStale: Object.values(docStatus).some(d => d.isStale),
        };
      });

      res.json(productsWithStatus);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to detect products" });
    }
  });

