  // AI: Ticket duplicate detection
  app.post("/api/ai/ticket-duplicates", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      const { title, description, tenantId } = req.body;
      if (!title) return res.status(400).json({ message: "title is required" });

      const tid = tenantId || access.tenantId;
      if (tenantId) {
        await assertTenantAccess(req, tenantId);
      }
      const existingTickets = await storage.getTickets(tid);
      const openTickets = existingTickets
        .filter((t: any) => t.status === "open" || t.status === "in_progress" || t.status === "waiting")
        .slice(0, 50);

      if (openTickets.length === 0) {
        return res.json({ duplicates: [], hasDuplicates: false });
      }

      const ticketSummaries = openTickets.map((t: any) => `[ID:${t.id}] "${t.title}" - ${t.description?.substring(0, 100) || "no description"}`).join("\n");

      const prompt = `You are a support ticket duplicate detection system. Compare this new ticket against existing open tickets and identify potential duplicates.

New Ticket:
Title: "${title}"
${description ? `Description: "${description}"` : ""}

Existing Open Tickets:
${ticketSummaries}

Respond in JSON:
{
  "duplicates": [
    {
      "ticketId": <number>,
      "similarity": <0-100>,
      "reason": "brief explanation of similarity"
    }
  ],
  "hasDuplicates": <boolean - true if any similarity >= 60>
}

Only include tickets with similarity >= 40. Sort by similarity descending. Max 5 results.`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        response_format: { type: "json_object" },
        max_completion_tokens: 1024,
      });

      const result = JSON.parse(response.choices[0]?.message?.content || '{"duplicates":[],"hasDuplicates":false}');
      const enrichedDuplicates = (result.duplicates || []).map((d: any) => {
        const match = openTickets.find((t: any) => t.id === d.ticketId);
        return { ...d, title: match?.title || "", status: match?.status || "", priority: match?.priority || "" };
      });
      res.json({ ...result, duplicates: enrichedDuplicates });
    } catch (error: any) {
      console.error("Error detecting duplicates:", error);
      res.status(error.status || 500).json({ message: error.message || "Failed to detect duplicates" });
    }
  });

