  // AI: Ticket predictive analytics
  app.post("/api/ai/ticket-analytics", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const tid = access.tenantId;

      const allTickets = await storage.getTickets(tid);

      const openTickets = allTickets.filter((t: any) => t.status === "open" || t.status === "in_progress");
      const resolvedTickets = allTickets.filter((t: any) => t.status === "resolved" || t.status === "closed");
      const slaBreachedCount = allTickets.filter((t: any) => t.slaBreached).length;

      const categoryDistribution: Record<string, number> = {};
      const priorityDistribution: Record<string, number> = {};
      allTickets.forEach((t: any) => {
        categoryDistribution[t.category || "general"] = (categoryDistribution[t.category || "general"] || 0) + 1;
        priorityDistribution[t.priority] = (priorityDistribution[t.priority] || 0) + 1;
      });

      let avgResolutionMs = 0;
      const resolvedWithTimes = resolvedTickets.filter((t: any) => t.updatedAt && t.createdAt);
      if (resolvedWithTimes.length > 0) {
        const totalMs = resolvedWithTimes.reduce((sum: number, t: any) => {
          return sum + (new Date(t.updatedAt).getTime() - new Date(t.createdAt).getTime());
        }, 0);
        avgResolutionMs = totalMs / resolvedWithTimes.length;
      }
      const avgResolutionHours = Math.round(avgResolutionMs / 3600000 * 10) / 10;

      const recentTickets = allTickets.slice(0, 30).map((t: any) => `[${t.priority}] "${t.title}" (${t.status}, ${t.category || "general"})`).join("\n");

      const prompt = `You are a predictive analytics engine for an MSSP. Analyze ticket patterns and provide insights.

Ticket Statistics:
- Total: ${allTickets.length}
- Open: ${openTickets.length}
- Resolved: ${resolvedTickets.length}
- SLA Breached: ${slaBreachedCount}
- Avg Resolution: ${avgResolutionHours}h
- Categories: ${JSON.stringify(categoryDistribution)}
- Priorities: ${JSON.stringify(priorityDistribution)}

Recent Tickets:
${recentTickets}

Respond in JSON:
{
  "volumeTrend": "increasing|stable|decreasing",
  "predictedVolumeNext7Days": <number>,
  "topIssueCategories": [{"category": "name", "percentage": <number>, "trend": "up|stable|down"}],
  "bottlenecks": ["identified bottleneck 1", "bottleneck 2"],
  "recommendations": ["actionable recommendation 1", "recommendation 2", "recommendation 3"],
  "riskAlerts": [{"title": "alert title", "severity": "low|medium|high|critical", "description": "brief description"}],
  "teamLoadScore": <0-100>,
  "healthScore": <0-100>
}`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        response_format: { type: "json_object" },
        max_completion_tokens: 2048,
      });

      const result = JSON.parse(response.choices[0]?.message?.content || "{}");
      res.json({
        ...result,
        stats: {
          total: allTickets.length,
          open: openTickets.length,
          resolved: resolvedTickets.length,
          slaBreached: slaBreachedCount,
          avgResolutionHours,
          categoryDistribution,
          priorityDistribution,
        },
      });
    } catch (error: any) {
      console.error("Error with ticket analytics:", error);
      res.status(error.status || 500).json({ message: error.message || "Failed to generate analytics" });
    }
  });

