  app.post("/api/ai/enrich-description/:id", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const id = parseInt(req.params.id);
      const incident = await storage.getIncidentGuarded(id);
      if (!incident) return res.status(404).json({ message: "Incident not found" });
      await assertTenantAccess(req, incident.tenantId);

      const evtResult = await poolRead.query(
        `SELECT raw_payload FROM security_events WHERE tenant_id = $1 AND threat ILIKE $2 LIMIT 3`,
        [incident.tenantId, `%${(incident.title || "").substring(0, 50)}%`]
      );

      let rawContext = "";
      for (const row of evtResult.rows) {
        if (row.raw_payload) {
          rawContext += `\n\nLinked Event Raw Data:\n${JSON.stringify(row.raw_payload, null, 2).substring(0, 2000)}`;
        }
      }

      let assetContext = "";
      try {
        const affectedHost = incident.affectedAssets || "";
        if (affectedHost) {
          const assetResult = await poolRead.query(
            `SELECT hostname, ip_address, operating_system, risk_score, risk_level, user_name, endpoint_group,
                    software_inventory
             FROM assets WHERE tenant_id = $1 AND (hostname ILIKE $2 OR ip_address = $2) LIMIT 1`,
            [incident.tenantId, affectedHost]
          );
          if (assetResult.rows[0]) {
            const a = assetResult.rows[0];
            const swCount = Array.isArray(a.software_inventory) ? a.software_inventory.length : 0;
            assetContext += `\n\nAsset Intelligence:
Device: ${a.hostname || "N/A"} | IP: ${a.ip_address || "N/A"} | OS: ${a.operating_system || "N/A"}
Risk: ${a.risk_level || "N/A"} (Score: ${a.risk_score || 0}) | User: ${a.user_name || "N/A"}
Endpoint Group: ${a.endpoint_group || "N/A"} | Software Installed: ${swCount} apps`;
          }
          const userResult = await poolRead.query(
            `SELECT user_name, department, risk_level, risk_score, total_requests, denied_requests, account_type
             FROM user_assets WHERE tenant_id = $1 AND user_name ILIKE $2 LIMIT 1`,
            [incident.tenantId, `%${affectedHost.split("\\").pop() || affectedHost}%`]
          );
          if (userResult.rows[0]) {
            const u = userResult.rows[0];
            assetContext += `\nUser Context: ${u.user_name} | Dept: ${u.department || "N/A"} | Risk: ${u.risk_level || "N/A"} (${u.risk_score || 0}) | Type: ${u.account_type || "Unknown"} | Denied Requests: ${u.denied_requests || 0}`;
          }
        }
      } catch (e: any) { /* asset lookup is best-effort */ }

      const incidentContext = `Incident Title: ${incident.title}
Severity: ${incident.severity}
Status: ${incident.status}
Source: ${incident.source || "N/A"}
Category: ${incident.category || "N/A"}
Incident Type: ${incident.incidentType || "N/A"}
Affected Assets: ${incident.affectedAssets || "N/A"}
Description: ${incident.description || "N/A"}
Action Taken: ${incident.actionTaken || "N/A"}
MITRE Tactic: ${incident.mitreTactic || "N/A"}
MITRE Technique: ${incident.mitreTechnique || "N/A"}
Kill Chain Phase: ${incident.killChainPhase || "N/A"}
Detection Source: ${incident.detectionSource || "N/A"}
Created: ${incident.createdAt}
${rawContext}${assetContext}`;

      const aiRes = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        temperature: 0.3,
        max_tokens: 2000,
        messages: [
          { role: "system", content: DESCRIPTION_ENRICH_PROMPT },
          { role: "user", content: incidentContext },
        ],
        response_format: { type: "json_object" },
      });

      const content = aiRes.choices[0]?.message?.content;
      if (!content) return res.status(500).json({ message: "No AI response" });

      const parsed = JSON.parse(content);
      const enrichedDescription = parsed.description || content;

      const updated = await storage.updateIncident(id, { enrichedDescription } as any);
      res.json(updated);
    } catch (error: any) {
      console.error("AI description enrichment error:", error);
      res.status(error.status || 500).json({ message: error.message || "Failed to enrich description" });
    }
  });

  app.post("/api/ai/enrich-descriptions", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const { tenantId } = req.body;
      if (!tenantId) return res.status(400).json({ message: "tenantId is required" });
      await assertTenantAccess(req, tenantId);

      res.writeHead(200, { "Content-Type": "text/event-stream", "Cache-Control": "no-cache", Connection: "keep-alive" });

      const accessibleIds = await getAccessibleTenantIds(tenantId, storage);
      const placeholders = accessibleIds.map((_, i) => `$${i + 1}`).join(",");
      const unenrichedResult = await poolRead.query(
        `SELECT id, tenant_id, title, description, severity, status, source, category, incident_type, affected_assets, action_taken, mitre_tactic, mitre_technique, kill_chain_phase, detection_source, created_at
         FROM incidents WHERE tenant_id IN (${placeholders}) AND enriched_description IS NULL
         ORDER BY created_at DESC LIMIT 100`,
        accessibleIds
      );

      const unenriched = unenrichedResult.rows;
      const total = unenriched.length;
      res.write(`data: ${JSON.stringify({ type: "start", total })}\n\n`);

      let enriched = 0;
      let failed = 0;

      for (const inc of unenriched) {
        try {
          const evtResult = await poolRead.query(
            `SELECT raw_payload FROM security_events WHERE tenant_id = $1 AND threat ILIKE $2 LIMIT 2`,
            [inc.tenant_id, `%${(inc.title || "").substring(0, 50)}%`]
          );

          let rawContext = "";
          for (const evt of evtResult.rows) {
            if (evt.raw_payload) {
              rawContext += `\nLinked Event Raw Data:\n${JSON.stringify(evt.raw_payload, null, 2).substring(0, 1500)}`;
            }
          }

          const ctx = `Incident Title: ${inc.title}\nSeverity: ${inc.severity}\nStatus: ${inc.status}\nSource: ${inc.source || "N/A"}\nCategory: ${inc.category || "N/A"}\nType: ${inc.incident_type || "N/A"}\nAssets: ${inc.affected_assets || "N/A"}\nDescription: ${inc.description || "N/A"}\nAction: ${inc.action_taken || "N/A"}\nMITRE: ${inc.mitre_tactic || "N/A"} / ${inc.mitre_technique || "N/A"}\nCreated: ${inc.created_at}${rawContext}`;

          const aiRes = await openai.chat.completions.create({
            model: "gpt-4o-mini",
            temperature: 0.3,
            max_tokens: 2000,
            messages: [
              { role: "system", content: DESCRIPTION_ENRICH_PROMPT },
              { role: "user", content: ctx },
            ],
            response_format: { type: "json_object" },
          });

          const content = aiRes.choices[0]?.message?.content;
          if (content) {
            const parsed = JSON.parse(content);
            await pool.query(
              `UPDATE incidents SET enriched_description = $1 WHERE id = $2`,
              [parsed.description || content, inc.id]
            );
            enriched++;
          } else {
            failed++;
          }
        } catch (err: any) {
          failed++;
          console.error(`Description enrichment failed for incident ${inc.id}:`, err.message);
        }

        res.write(`data: ${JSON.stringify({ type: "progress", enriched, failed, total })}\n\n`);
      }

      await deleteCachePrefix("incidents:");
      res.write(`data: ${JSON.stringify({ type: "complete", enriched, failed, total })}\n\n`);
      res.end();
    } catch (error: any) {
      console.error("Bulk description enrichment error:", error);
      if (!res.headersSent) {
        res.status(error.status || 500).json({ message: error.message || "Failed to bulk enrich descriptions" });
      }
    }
  });

