  app.post("/api/security-integrations/:id/pull-data", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const id = parseInt(req.params.id);
      const existing = await storage.getSecurityIntegration(id);
      if (!existing) {
        return res.status(404).json({ message: "Integration not found" });
      }
      const access = await assertTenantAccess(req, existing.tenantId);
      assertMSSRole(access);

      if (existing.status !== "connected") {
        return res.status(400).json({ message: "Integration must be connected before pulling data" });
      }

      const connector = getConnector(existing);

      if (connector) {
        const pullResult = await connector.pullData(req.body?.cursor);
        const eventsCount = pullResult.totalPulled;

        const existingConfig = (existing.configJson as Record<string, any>) || {};
        const now = new Date();
        let updatedConfig = { ...existingConfig };
        let displayMessage: string;

        if (eventsCount > 0) {
          displayMessage = pullResult.message;
          updatedConfig.lastSuccessfulPullAt = now.toISOString();
          updatedConfig.lastSuccessfulPullCount = eventsCount;
        } else {
          const lastSuccessAt = existingConfig.lastSuccessfulPullAt;
          const lastSuccessCount = existingConfig.lastSuccessfulPullCount || 0;
          if (lastSuccessAt) {
            displayMessage = `Up to date \u2014 no new data since last successful pull (${lastSuccessCount} items on ${new Date(lastSuccessAt).toLocaleDateString()})`;
          } else {
            displayMessage = `Up to date \u2014 no new data available`;
          }
        }

        await storage.updateSecurityIntegration(id, {
          lastPollAt: now,
          lastPollStatus: eventsCount > 0 ? "running" : "success",
          lastPollMessage: eventsCount > 0 ? `Pull succeeded (${eventsCount} events) — enrichment pipeline running…` : displayMessage,
          eventsImported: (existing.eventsImported || 0) + eventsCount,
          configJson: updatedConfig,
        });

        const pullUser = req.user as any;
        await storage.logIntegrationAudit({
          tenantId: existing.tenantId,
          integrationId: id,
          platformName: existing.platformName,
          platformKey: existing.platformKey,
          action: "pull_data",
          userId: pullUser?.claims?.sub || pullUser?.id || null,
          username: pullUser?.claims?.email || pullUser?.email || null,
          details: { eventsPulled: eventsCount, hasMore: pullResult.hasMore, cursor: pullResult.cursor, message: pullResult.message },
        });

        if (eventsCount > 0) {
          const batch = await createIngestBatch(
            existing.tenantId,
            pullResult.events,
            "connector",
            existing.platformKey,
            { integrationId: id, platformName: existing.platformName }
          );

          console.log(`[Pull] Running enrichment pipeline for batch ${batch.id} (${eventsCount} events from ${existing.platformName}, tenant ${existing.tenantId})`);
          runPipelineAsync(batch.id, existing.tenantId, pullResult.events, {
            skipNormalization: true,
            vendorHint: existing.platformKey,
            integrationId: id,
          });
        }
        await deleteCachePrefix(`tenants:${existing.tenantId}:integrations`);

        res.json({
          success: true,
          eventsImported: eventsCount,
          totalEvents: (existing.eventsImported || 0) + eventsCount,
          hasMore: pullResult.hasMore,
          cursor: pullResult.cursor,
          message: displayMessage,
          pipelineTriggered: eventsCount > 0,
          timestamp: new Date().toISOString(),
        });
      } else {
        res.json({
          success: false,
          eventsImported: 0,
          totalEvents: existing.eventsImported || 0,
          message: `No connector available for ${existing.platformName}. Configure API credentials to enable data pulling.`,
          timestamp: new Date().toISOString(),
        });
      }
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Data pull failed" });
    }
  });

