  app.get("/api/assets/:tenantId/cis-stats", isAuthenticated, async (req: any, res: Response) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const statsRes = await pool.query(
        `SELECT
           COUNT(*) FILTER (WHERE cis_score IS NOT NULL) as scored,
           ROUND(AVG(cis_score) FILTER (WHERE cis_score IS NOT NULL)) as avg_cis,
           COUNT(*) FILTER (WHERE cis_score >= 70) as green,
           COUNT(*) FILTER (WHERE cis_score >= 40 AND cis_score < 70) as amber,
           COUNT(*) FILTER (WHERE cis_score < 40 AND cis_score IS NOT NULL) as red
         FROM assets WHERE tenant_id = $1 AND status != 'decommissioned'`,
        [tenantId]
      );
      const critRes = await pool.query(
        `SELECT criticality, COUNT(*) as count
         FROM assets WHERE tenant_id = $1 AND status != 'decommissioned'
         GROUP BY criticality`,
        [tenantId]
      );
      const critDist: Record<string, number> = {};
      for (const r of critRes.rows) {
        critDist[r.criticality || "unclassified"] = parseInt(r.count);
      }
      const sr = statsRes.rows[0] || {};
      const totalCount = await pool.query(`SELECT COUNT(*) as total FROM assets WHERE tenant_id = $1 AND status != 'decommissioned'`, [tenantId]);
      const total = parseInt(totalCount.rows[0]?.total ?? "0");
      const scored = parseInt(sr.scored ?? "0");
      const mappedRes = await pool.query(`SELECT COUNT(*) as cnt FROM assets WHERE tenant_id = $1 AND primary_user_id IS NOT NULL AND status != 'decommissioned'`, [tenantId]);
      const mappedAssets = parseInt(mappedRes.rows[0]?.cnt ?? "0");
      res.json({
        avgCisScore: sr.avg_cis ? parseFloat(sr.avg_cis) : null,
        scoredAssets: scored,
        unscoredAssets: total - scored,
        greenAssets: parseInt(sr.green ?? "0"),
        amberAssets: parseInt(sr.amber ?? "0"),
        redAssets: parseInt(sr.red ?? "0"),
        criticalityDistribution: critDist,
        mappedAssets,
        unmappedAssets: total - mappedAssets,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

