  /**
   * Debug endpoint: probe /api/full/host and return raw response structure.
   * Useful for verifying the actual Cynet API response field names and pagination behaviour.
   * Query params: ?skip=0&top=5  (default top=5 to keep response small)
   */
  app.get("/api/security-integrations/:id/probe-full-host", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const id = parseInt(req.params.id);
      const existing = await storage.getSecurityIntegration(id);
      if (!existing) return res.status(404).json({ message: "Integration not found" });
      const access = await assertTenantAccess(req, existing.tenantId);
      assertMSSRole(access);

      if (existing.platformKey !== "cynet") {
        return res.status(400).json({ message: "Probe is only available for Cynet 360 integrations" });
      }

      const connector = getConnector(existing);
      if (!connector || !("authenticate" in connector)) {
        return res.status(400).json({ message: "Cynet connector not available" });
      }

      const cynetConnector = connector as any;
      const token = await cynetConnector.authenticate();
      const baseUrl = cynetConnector.getApiBase();
      const skip = parseInt(String(req.query.skip || "0"));
      const top = Math.min(parseInt(String(req.query.top || "5")), 50);

      // Try multiple URL variants so we can tell which one the tenant's API accepts
      const variants: Array<{ label: string; url: string }> = [
        { label: "LastSeen-90d+Name=*", url: `${baseUrl}/api/full/host?LastSeen=${encodeURIComponent(cynetConnector.getLastSeenParam(90))}&Name=*&Skip=${skip}&Top=${top}` },
        { label: "NoDateFilter+Name=*",  url: `${baseUrl}/api/full/host?Name=*&Skip=${skip}&Top=${top}` },
        { label: "NoParams",             url: `${baseUrl}/api/full/host?Skip=${skip}&Top=${top}` },
      ];

      const results: Array<{ label: string; url: string; status: number; totalCount: number | null; entityCount: number; topLevelKeys: string[]; sampleEntityKeys: string[]; hasSoftware: boolean; softwareCount: number; softwareFieldName: string | null; sampleEntity: any }> = [];

      for (const v of variants) {
        try {
          const { status, data } = await (cynetConnector as any).httpRequest(v.url, {
            headers: cynetConnector.authHeaders(token),
            timeout: 20000,
          });
          const entities: any[] = data?.Entities || (Array.isArray(data) ? data : []);
          const totalCount = data?.TotalCount ?? data?.totalCount ?? data?.Total ?? data?.total ?? null;
          const sampleEntity = entities[0] || null;
          const SW_KEYS = [
            "InstalledSoftware","installed_software","InstalledApplications","installed_applications",
            "Applications","applications","AppsList","apps_list","SoftwareList","software_list",
            "Programs","programs","Softwares","software","installed_apps","Packages","packages",
            "AppList","app_list",
          ];
          const swKey = SW_KEYS.find(k => sampleEntity && Array.isArray(sampleEntity[k]) && sampleEntity[k].length > 0) || null;
          const rawSw = swKey ? sampleEntity[swKey] : null;
          results.push({
            label: v.label,
            url: v.url,
            status,
            totalCount,
            entityCount: entities.length,
            topLevelKeys: Object.keys(data || {}),
            sampleEntityKeys: Object.keys(sampleEntity || {}),
            hasSoftware: !!rawSw,
            softwareCount: Array.isArray(rawSw) ? rawSw.length : 0,
            softwareFieldName: swKey,
            sampleEntity,
          });
        } catch (e: any) {
          results.push({ label: v.label, url: v.url, status: -1, totalCount: null, entityCount: 0, topLevelKeys: [], sampleEntityKeys: [], hasSoftware: false, softwareCount: 0, softwareFieldName: null, sampleEntity: { error: e.message } });
        }
      }

      res.json({ probeResults: results, timestamp: new Date().toISOString() });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Probe failed" });
    }
  });

