  const classifyAppCategory = (appName: string): string => {
    const lower = appName.toLowerCase();
    for (const cat of APP_CATEGORIES) {
      for (const pattern of cat.patterns) {
        if (pattern.test(lower)) return cat.category;
      }
    }
    return "other";
  };

  app.get("/api/assets/software-analytics", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const access = await getUserTenantAccess(req);
      let tenantId: number | null = null;
      if (req.query.tenantId) {
        const parsed = parseInt(String(req.query.tenantId));
        if (!isNaN(parsed) && parsed > 0) tenantId = parsed;
      } else if (access.tenantId && typeof access.tenantId === 'number' && !isNaN(access.tenantId) && access.tenantId > 0) {
        tenantId = access.tenantId;
      }
      if (tenantId) await assertTenantAccess(req, tenantId);
      const swAnalyticsCacheKey = `software-analytics:${tenantId ?? "all"}`;
      const swAnalyticsCached = await getCache(swAnalyticsCacheKey);
      if (swAnalyticsCached) return res.json(swAnalyticsCached);

      const softwareAnalyticsResult = await withHeavyQueryLimit(async () => {
      let allAssets: any[] = [];
      let allEvents: any[] = [];
      let allIncidents: any[] = [];
      const tenantIds: number[] = [];

      if (!tenantId) {
        const allTenants = await storage.getTenants();
        const tids = access.isMSS
          ? allTenants.map(t => t.id).filter((id): id is number => typeof id === 'number' && !isNaN(id) && id > 0)
          : (access.tenantId && typeof access.tenantId === 'number' && !isNaN(access.tenantId) && access.tenantId > 0) ? [access.tenantId] : [];
        for (const tid of tids) {
          if (typeof tid !== 'number' || isNaN(tid) || tid <= 0) continue;
          tenantIds.push(tid);
          try {
            const a = await storage.getAssetsSoftwareData(tid);
            allAssets.push(...a);
          } catch (e: any) {
            if (e?.message?.includes('NaN')) continue;
            throw e;
          }
        }
      } else {
        if (typeof tenantId === 'number' && !isNaN(tenantId) && tenantId > 0) {
          tenantIds.push(tenantId);
          try {
            allAssets = await storage.getAssetsSoftwareData(tenantId);
          } catch (e: any) {
            if (e?.message?.includes('NaN')) allAssets = [];
            else throw e;
          }
        }
      }

      if (tenantIds.length > 0) {
        allEvents = await storage.getSecurityEventsLightForTenants(tenantIds);
        for (const tid of tenantIds) {
          if (typeof tid !== 'number' || isNaN(tid) || tid <= 0) continue;
          try {
            const incidents = await storage.getIncidents(tid);
            allIncidents.push(...incidents);
          } catch {}
        }
      }

      const totalAssets = allAssets.length;
      const assetsWithSoftware = allAssets.filter(a => a.softwareInventory && Array.isArray(a.softwareInventory) && a.softwareInventory.length > 0);

      const appCountMap = new Map<string, number>();
      const appCategoryCountMap = new Map<string, Map<string, number>>();
      for (const ac of APP_CATEGORIES) {
        appCategoryCountMap.set(ac.category, new Map());
      }
      const toolsByCategory = new Map<string, Map<string, { tool: string; category: string; assets: Set<number>; hostnames: Map<number, string> }>>();
      const assetSecurityTools = new Map<number, Set<string>>();
      const assetEndpointAgents = new Map<number, string[]>();
      const riskApps = new Map<string, { app: string; category: string; assets: Array<{ id: number; hostname: string }> }>();

      for (const [catKey] of Object.entries(SECURITY_TOOL_CATEGORIES)) {
        toolsByCategory.set(catKey, new Map());
      }

      const registerToolForAsset = (toolName: string, category: string, assetId: number, hostname: string) => {
        if (!toolsByCategory.has(category)) toolsByCategory.set(category, new Map());
        const catMap = toolsByCategory.get(category)!;
        if (!catMap.has(toolName)) {
          catMap.set(toolName, { tool: toolName, category, assets: new Set(), hostnames: new Map() });
        }
        catMap.get(toolName)!.assets.add(assetId);
        catMap.get(toolName)!.hostnames.set(assetId, hostname);

        if (!assetSecurityTools.has(assetId)) assetSecurityTools.set(assetId, new Set());
        assetSecurityTools.get(assetId)!.add(`${category}:${toolName}`);

        if (category === "endpoint_security") {
          if (!assetEndpointAgents.has(assetId)) assetEndpointAgents.set(assetId, []);
          const agents = assetEndpointAgents.get(assetId)!;
          if (!agents.includes(toolName)) agents.push(toolName);
        }
      }

      const registerRiskApp = (appName: string, category: string, assetId: number, hostname: string) => {
        const key = `${category}:${appName}`;
        if (!riskApps.has(key)) {
          riskApps.set(key, { app: appName, category, assets: [] });
        }
        const existing = riskApps.get(key)!;
        if (!existing.assets.find(a => a.id === assetId)) {
          existing.assets.push({ id: assetId, hostname });
        }
      }

      const tenantDefaultToolMap: Record<string, string> = {
        "pkf": "Cynet EPS", "fedfina": "Palo Alto Cortex", "macm": "CrowdStrike Falcon", "aspire": "Cynet EPS",
      };
      const tenantNameCache = new Map<number, string>();
      for (const tid of tenantIds) {
        try {
          const t = await storage.getTenant(tid);
          if (t?.name) tenantNameCache.set(tid, t.name.toLowerCase());
        } catch {}
      }
      const getTenantFallbackTool = (tenantId: number | null | undefined): string => {
        if (!tenantId) return "Endpoint Security (EDR/XDR)";
        const tName = tenantNameCache.get(tenantId) || '';
        for (const [key, tool] of Object.entries(tenantDefaultToolMap)) {
          if (tName.includes(key)) return tool;
        }
        return "Endpoint Security (EDR/XDR)";
      };

      for (const asset of allAssets) {
        const sw = (asset.softwareInventory as any[]) || [];
        const seen = new Set<string>();
        const swNames: string[] = [];

        for (const s of sw) {
          const nameKey = (s.name || '').toLowerCase();
          if (!seen.has(nameKey)) {
            seen.add(nameKey);
            appCountMap.set(s.name, (appCountMap.get(s.name) || 0) + 1);
            swNames.push(s.name);
            const appCat = classifyAppCategory(s.name);
            const catMap = appCategoryCountMap.get(appCat) || new Map();
            catMap.set(s.name, (catMap.get(s.name) || 0) + 1);
            appCategoryCountMap.set(appCat, catMap);
          }
        }

        if (swNames.length > 0) {
          const detected = classifySecurityTools(swNames);
          for (const [, info] of detected) {
            if (["remote_access", "p2p", "anonymizer"].includes(info.category)) {
              registerRiskApp(info.name, info.category, asset.id, asset.hostname);
            } else {
              registerToolForAsset(info.name, info.category, asset.id, asset.hostname);
            }
          }
        }

        const assetContext = [
          asset.source || '',
          asset.preventionPolicy || '',
          asset.endpointGroup || '',
          asset.agentVersion || '',
          asset.contentVersion || '',
          asset.deploymentType || '',
        ].filter(Boolean);

        if (assetContext.length > 0) {
          const detected = classifySecurityTools(assetContext);
          for (const [, info] of detected) {
            if (!["remote_access", "p2p", "anonymizer"].includes(info.category)) {
              registerToolForAsset(info.name, info.category, asset.id, asset.hostname);
            }
          }
        }

        if (asset.source === "import" || asset.status === "active" || asset.preventionPolicy) {
          const hasEndpoint = assetEndpointAgents.has(asset.id) && (assetEndpointAgents.get(asset.id)!.length > 0);
          if (!hasEndpoint) {
            registerToolForAsset(getTenantFallbackTool(asset.tenantId), "endpoint_security", asset.id, asset.hostname);
          }
        }
      }

      const assetsByHostname = new Map<string, { id: number; hostname: string }>();
      for (const asset of allAssets) {
        assetsByHostname.set(asset.hostname?.toLowerCase(), { id: asset.id, hostname: asset.hostname });
      }

      for (const event of allEvents) {
        const eventAssetName = (event.asset || '').toLowerCase();
        const matchedAsset = assetsByHostname.get(eventAssetName);
        if (!matchedAsset) continue;

        const eventContext = [
          event.logSource || '',
          event.sourceType || '',
          event.app || '',
          event.action || '',
        ].filter(Boolean);

        if (eventContext.length > 0) {
          const detected = classifySecurityTools(eventContext);
          for (const [, info] of detected) {
            if (["remote_access", "p2p", "anonymizer"].includes(info.category)) {
              registerRiskApp(info.name, info.category, matchedAsset.id, matchedAsset.hostname);
            } else {
              registerToolForAsset(info.name, info.category, matchedAsset.id, matchedAsset.hostname);
            }
          }
        }

        if (event.sourceType) {
          const st = event.sourceType.toLowerCase();
          if (st.includes("web proxy") || st.includes("casb") || st.includes("swg")) {
            registerToolForAsset("Web Security (SSE)", "web_security", matchedAsset.id, matchedAsset.hostname);
          }
        }
      }

      for (const incident of allIncidents) {
        const incidentContext = [
          incident.source || '',
          incident.detectionSource || '',
          incident.category || '',
        ].filter(Boolean);

        if (incidentContext.length > 0) {
          const detected = classifySecurityTools(incidentContext);
          const affectedAssetNames = (typeof incident.affectedAssets === 'string' ? incident.affectedAssets.split(',') : Array.isArray(incident.affectedAssets) ? incident.affectedAssets : []).map((n: string) => n.trim().toLowerCase());
          for (const assetName of affectedAssetNames) {
            const matchedAsset = assetsByHostname.get(assetName);
            if (matchedAsset) {
              for (const [, info] of detected) {
                if (!["remote_access", "p2p", "anonymizer"].includes(info.category)) {
                  registerToolForAsset(info.name, info.category, matchedAsset.id, matchedAsset.hostname);
                }
              }
            }
          }
        }

        const src = (incident.source || '').toLowerCase();
        const det = (incident.detectionSource || '').toLowerCase();
        if (src.includes("edr") || det.includes("edr") || src.includes("endpoint")) {
          const affectedAssetNames2 = (typeof incident.affectedAssets === 'string' ? incident.affectedAssets.split(',') : Array.isArray(incident.affectedAssets) ? incident.affectedAssets : []).map((n: string) => n.trim().toLowerCase());
          for (const assetName of affectedAssetNames2) {
            const matchedAsset2 = assetsByHostname.get(assetName);
            if (matchedAsset2 && !assetEndpointAgents.has(matchedAsset2.id)) {
              registerToolForAsset(getTenantFallbackTool(incident.tenantId), "endpoint_security", matchedAsset2.id, matchedAsset2.hostname);
            }
          }
        }
      }

      const topApps = Array.from(appCountMap.entries())
        .map(([name, count]) => ({ name, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 30);

      const isUpdateOrPatch = (name: string): boolean => {
        const lower = name.toLowerCase();
        return (
          lower.startsWith('update for ') ||
          lower.startsWith('security update ') ||
          lower.startsWith('definition update ') ||
          lower.startsWith('hotfix for ') ||
          lower.includes('kb') && (lower.includes('update') || lower.includes('hotfix')) ||
          /\(kb\d{6,}\)/.test(lower) ||
          lower.startsWith('microsoft update ') ||
          lower.startsWith('windows update ') ||
          lower === 'microsoft update health tools'
        );
      };

      const softwareVersionMap = new Map<string, { name: string; version: string; systems: Array<{ id: number; hostname: string }> }>();
      for (const asset of allAssets) {
        const sw = (asset.softwareInventory as any[]) || [];
        const seen = new Set<string>();
        for (const s of sw) {
          const displayName = s.name || '';
          if (isUpdateOrPatch(displayName)) continue;
          const version = s.version || 'Unknown';
          const rowKey = `${displayName.toLowerCase()}|||${version}`;
          if (seen.has(rowKey)) continue;
          seen.add(rowKey);
          if (!softwareVersionMap.has(rowKey)) {
            softwareVersionMap.set(rowKey, { name: displayName, version, systems: [] });
          }
          softwareVersionMap.get(rowKey)!.systems.push({ id: asset.id, hostname: asset.hostname });
        }
      }
      const osVersionMap = new Map<string, { name: string; version: string; systems: Array<{ id: number; hostname: string }> }>();
      for (const asset of allAssets) {
        const os = (asset as any).operatingSystem || (asset as any).operating_system || '';
        if (!os || typeof os !== 'string') continue;
        const osKey = os.toLowerCase().trim();
        if (!osKey) continue;
        if (!osVersionMap.has(osKey)) {
          osVersionMap.set(osKey, { name: os.trim(), version: '', systems: [] });
        }
        osVersionMap.get(osKey)!.systems.push({ id: asset.id, hostname: asset.hostname });
      }

      const softwareEntries = Array.from(softwareVersionMap.values())
        .map(sw => ({
          name: sw.name,
          version: sw.version,
          systemCount: sw.systems.length,
          systems: sw.systems.slice(0, 50),
        }));

      const osEntries = Array.from(osVersionMap.values())
        .map(sw => ({
          name: sw.name,
          version: sw.version,
          systemCount: sw.systems.length,
          systems: sw.systems.slice(0, 50),
        }));

      const allSoftware = [...softwareEntries, ...osEntries]
        .sort((a, b) => b.systemCount - a.systemCount);

      const securityCategories: Array<{
        category: string; label: string; icon: string; color: string;
        tools: Array<{ tool: string; assetCount: number; assets: Array<{ id: number; hostname: string }> }>;
        totalAssets: number;
      }> = [];

      for (const [catKey, catMeta] of Object.entries(SECURITY_TOOL_CATEGORIES)) {
        const catMap = toolsByCategory.get(catKey);
        if (!catMap || catMap.size === 0) continue;
        const allCatAssets = new Set<number>();
        const tools = Array.from(catMap.values())
          .map(t => {
            t.assets.forEach(id => allCatAssets.add(id));
            return {
              tool: t.tool,
              assetCount: t.assets.size,
              assets: Array.from(t.hostnames.entries()).map(([id, hostname]) => ({ id, hostname })).slice(0, 200),
            };
          })
          .sort((a, b) => b.assetCount - a.assetCount);

        securityCategories.push({
          category: catKey,
          label: catMeta.label,
          icon: catMeta.icon,
          color: catMeta.color,
          tools,
          totalAssets: allCatAssets.size,
        });
      }

      const endpointProtectedSet = new Set<number>();
      const epCat = toolsByCategory.get("endpoint_security");
      if (epCat) {
        for (const [, t] of epCat) { t.assets.forEach(id => endpointProtectedSet.add(id)); }
      }
      const protectedAssets = allAssets
        .filter(a => endpointProtectedSet.has(a.id))
        .map(a => ({ id: a.id, hostname: a.hostname, agents: assetEndpointAgents.get(a.id) || ["Endpoint Security"] }));
      const unprotectedAssets = allAssets
        .filter(a => !endpointProtectedSet.has(a.id))
        .map(a => ({ id: a.id, hostname: a.hostname }));

      const multiAgentAssets = Array.from(assetEndpointAgents.entries())
        .filter(([, agents]) => agents.length > 1)
        .map(([assetId, agents]) => {
          const asset = allAssets.find(a => a.id === assetId);
          return { id: assetId, hostname: asset?.hostname || '', agents, agentCount: agents.length };
        })
        .sort((a, b) => b.agentCount - a.agentCount)
        .slice(0, 200);

      const riskAppsList = Array.from(riskApps.values())
        .map(ra => ({ app: ra.app, type: ra.category === "remote_access" ? "Remote Access" : ra.category === "p2p" ? "P2P" : "Anonymizer", assetCount: ra.assets.length, assets: ra.assets.slice(0, 50) }))
        .sort((a, b) => b.assetCount - a.assetCount);

      const totalProtected = protectedAssets.length;
      const totalUnprotected = unprotectedAssets.length;
      const totalWithSoftwareData = assetsWithSoftware.length;

      const endpointAgents = epCat ? Array.from(epCat.values())
        .map(t => ({ agent: t.tool, assetCount: t.assets.size, assets: Array.from(t.hostnames.entries()).map(([id, hostname]) => ({ id, hostname })).slice(0, 50) }))
        .sort((a, b) => b.assetCount - a.assetCount)
        : [];

      const appCategories = APP_CATEGORIES
        .map(ac => {
          const catApps = appCategoryCountMap.get(ac.category);
          const totalApps = catApps ? Array.from(catApps.values()).reduce((sum, c) => sum + c, 0) : 0;
          const topCatApps = catApps
            ? Array.from(catApps.entries()).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count).slice(0, 10)
            : [];
          return { category: ac.category, label: ac.label, color: ac.color, totalApps, uniqueApps: catApps?.size || 0, topApps: topCatApps };
        })
        .filter(c => c.totalApps > 0)
        .sort((a, b) => b.totalApps - a.totalApps);

      const { enrichSoftwareWithEOL, getEOLSummary } = await import("./eol-database");
      const enrichedSoftware = enrichSoftwareWithEOL(allSoftware);
      const eolSummary = getEOLSummary(enrichedSoftware);

      return {
        totalAssets,
        totalWithSoftwareData,
        totalWithoutSoftwareData: totalAssets - totalWithSoftwareData,
        topApps,
        allSoftware: enrichedSoftware,
        eolSummary,
        appCategories,
        securityCategories,
        endpointSecurity: {
          totalProtected,
          totalUnprotected,
          coveragePercent: totalAssets > 0 ? Math.round((totalProtected / totalAssets) * 100) : 0,
          agents: endpointAgents,
          protectedAssets: protectedAssets.slice(0, 100),
          unprotectedAssets: unprotectedAssets.slice(0, 100),
        },
        multiAgent: {
          totalCount: multiAgentAssets.length,
          assets: multiAgentAssets,
        },
        p2pVpn: {
          totalAssets: new Set(riskAppsList.flatMap(a => a.assets.map(x => x.id))).size,
          apps: riskAppsList,
        },
      };
      });
      setCache(swAnalyticsCacheKey, softwareAnalyticsResult, 300_000);
      res.json(softwareAnalyticsResult);
    } catch (error: any) {
      const errMsg = String(error?.message || error || '');
      if (errMsg.includes('NaN') || errMsg.includes('invalid input syntax')) {
        res.json({
          totalAssets: 0, totalWithSoftwareData: 0, totalWithoutSoftwareData: 0,
          topApps: [], allSoftware: [], appCategories: [], securityCategories: [],
          endpointSecurity: { totalProtected: 0, totalUnprotected: 0, coveragePercent: 0, agents: [], protectedAssets: [], unprotectedAssets: [] },
          multiAgent: { totalCount: 0, assets: [] },
          p2pVpn: { totalAssets: 0, apps: [] },
        });
        return;
      }
      res.status(error.status || 500).json({ message: errMsg || "sw-analytics-v3-error" });
    }
  });

  app.get("/api/assets/:id", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const id = parseInt(req.params.id);
      const asset = await storage.getAsset(id);
      if (!asset) return res.status(404).json({ message: "Asset not found" });
      await assertTenantAccess(req, asset.tenantId);
      // Enrich with authoritative risk_scores table (same source as device list & detail views)
      let enrichedRiskScore: number | null = null;
      let enrichedRiskLevel: string | null = null;
      if (asset.hostname) {
        try {
          const rsRow = await pool.query(
            `SELECT overall_score, risk_level FROM risk_scores WHERE tenant_id = $1 AND entity_type = 'asset' AND entity_identifier = $2 LIMIT 1`,
            [asset.tenantId, asset.hostname]
          );
          if (rsRow.rows.length > 0) {
            enrichedRiskScore = rsRow.rows[0].overall_score ?? null;
            enrichedRiskLevel = rsRow.rows[0].risk_level ?? null;
          }
        } catch {}
      }
      // Use COALESCE semantics: risk_scores table → asset.riskScore (no intermediate fallback)
      const finalRiskScore = enrichedRiskScore !== null ? enrichedRiskScore : (asset.riskScore ?? null);
      const finalRiskLevel = enrichedRiskLevel || asset.riskLevel || null;
      res.json({ ...asset, riskScore: finalRiskScore, riskLevel: finalRiskLevel });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to get asset" });
    }
  });

  app.patch("/api/assets/:id", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const id = parseInt(req.params.id);
      const existing = await storage.getAsset(id);
      if (!existing) return res.status(404).json({ message: "Asset not found" });
      await assertTenantAccess(req, existing.tenantId);
      const updated = await storage.updateAsset(id, req.body);
      res.json(updated);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to update asset" });
    }
  });

  app.post("/api/_migrate/batch", async (req: Request, res: Response) => {
    try {
      const key = req.headers["x-migrate-key"];
      if (key !== "secureops-migrate-2026") {
        return res.status(403).json({ message: "Forbidden" });
      }
      const { table, rows } = req.body;
      if (!table || !rows || !Array.isArray(rows)) {
        return res.status(400).json({ message: "Invalid payload" });
      }
      let inserted = 0;
      for (const row of rows) {
        const cols = Object.keys(row);
        const colList = cols.map(c => `"${c}"`).join(", ");
        const placeholders = cols.map((_, i) => `$${i + 1}`).join(", ");
        const vals = cols.map(c => {
          const v = row[c];
          if (v !== null && typeof v === "object" && !Array.isArray(v)) return JSON.stringify(v);
          if (Array.isArray(v)) return JSON.stringify(v);
          return v;
        });
        try {
          await pool.query(
            `INSERT INTO "${table}" (${colList}) VALUES (${placeholders}) ON CONFLICT (id) DO NOTHING`,
            vals
          );
          inserted++;
        } catch (e: any) {
          console.error(`Migration insert error (${table}):`, e.message?.substring(0, 100));
        }
      }
      res.json({ inserted, total: rows.length });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/_migrate/clear", async (req: Request, res: Response) => {
    try {
      const key = req.headers["x-migrate-key"];
      if (key !== "secureops-migrate-2026") {
        return res.status(403).json({ message: "Forbidden" });
      }
      // NOTE: security_integrations is intentionally excluded — it stores persistent
      // operational config (EDR/SIEM credentials) that is never re-seeded by the batch
      // import. Use GET /api/_migrate/export-integrations to snapshot before clearing.
      const tables = [
        "ticket_feedback", "ticket_attachments", "ticket_comments", "tickets",
        "tasks", "projects", "reports", "report_schedules",
        "sla_definitions", "shift_rosters",
        "security_events", "incidents", "user_assets", "assets",
        "licenses", "team_members", "services", "messages", "conversations",
        "documents", "tenant_users", "superadmins", "sessions", "users", "tenants"
      ];
      const results: Record<string, string> = {};
      console.log(`[Migrate/Clear] Operation started at ${new Date().toISOString()} — clearing ${tables.length} tables`);
      for (const t of tables) {
        try {
          const countRes = await pool.query(`SELECT COUNT(*) FROM "${t}"`);
          const rowCount = parseInt(countRes.rows[0].count, 10);
          await pool.query(`DELETE FROM "${t}"`);
          console.log(`[Migrate/Clear] Cleared "${t}": ${rowCount} row(s) deleted`);
          results[t] = `cleared (${rowCount} rows)`;
        } catch (e: any) {
          console.error(`[Migrate/Clear] Error clearing "${t}": ${e.message}`);
          results[t] = `error: ${e.message?.substring(0, 60)}`;
        }
      }
      console.log(`[Migrate/Clear] Operation complete. security_integrations preserved.`);
      res.json(results);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/_migrate/export-integrations", async (req: Request, res: Response) => {
    try {
      const key = req.headers["x-migrate-key"];
      if (key !== "secureops-migrate-2026") {
        return res.status(403).json({ message: "Forbidden" });
      }
      const { rows } = await pool.query(`SELECT * FROM security_integrations ORDER BY tenant_id, id`);
      console.log(`[Migrate/Export] Exported ${rows.length} security_integrations row(s) at ${new Date().toISOString()}`);
      res.json({ exported_at: new Date().toISOString(), count: rows.length, integrations: rows });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/_migrate/reset-sequences", async (req: Request, res: Response) => {
    try {
      const key = req.headers["x-migrate-key"];
      if (key !== "secureops-migrate-2026") {
        return res.status(403).json({ message: "Forbidden" });
      }
      const tables = [
        "tenants", "users", "tenant_users", "superadmins", "incidents",
        "security_events", "assets", "user_assets", "reports", "report_schedules",
        "services", "team_members", "projects", "tasks", "tickets", "licenses"
      ];
      const results: Record<string, string> = {};
      for (const t of tables) {
        try {
          await pool.query(
            `SELECT setval(pg_get_serial_sequence('"${t}"', 'id'), COALESCE((SELECT MAX(id) FROM "${t}"), 1), true)`
          );
          results[t] = "reset";
        } catch (e: any) {
          results[t] = `skip: ${e.message?.substring(0, 60)}`;
        }
      }
      res.json(results);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ==================== Risk Intelligence API ====================
