  app.get("/api/v1/ingest/status/:batchId/stream", async (req: any, res) => {
    try {
      const apiKey = await authenticateApiKey(req.headers.authorization);
      if (!apiKey) {
        return res.status(401).json({ message: "Invalid or missing API key" });
      }

      const batchId = Number(req.params.batchId);
      if (!batchId || isNaN(batchId)) {
        return res.status(400).json({ message: "Invalid batch ID" });
      }

      const batch = await storage.getIngestBatch(batchId);
      if (!batch) {
        return res.status(404).json({ message: "Batch not found" });
      }

      if (batch.tenantId !== apiKey.tenantId) {
        return res.status(403).json({ message: "Access denied to this batch" });
      }

      res.writeHead(200, {
        "Content-Type": "text/event-stream",
        "Cache-Control": "no-cache",
        Connection: "keep-alive",
        "X-Accel-Buffering": "no",
      });

      res.write(`data: ${JSON.stringify({ stage: batch.status, totalEvents: batch.totalEvents, processedEvents: batch.processedEvents, errorCount: batch.errorCount })}\n\n`);

      if (batch.status === "complete" || batch.status === "failed") {
        res.write(`data: ${JSON.stringify({ stage: batch.status, totalEvents: batch.totalEvents, processedEvents: batch.processedEvents, errorCount: batch.errorCount, metadata: batch.metadata })}\n\n`);
        return res.end();
      }

      const unsubscribe = subscribeToPipeline(batchId, (progress: PipelineProgress) => {
        try {
          res.write(`data: ${JSON.stringify(progress)}\n\n`);
          if (progress.stage === "complete" || progress.stage === "failed") {
            setTimeout(() => { try { res.end(); } catch {} }, 500);
          }
        } catch {}
      });

      const timeout = setTimeout(() => {
        unsubscribe();
        try { res.end(); } catch {}
      }, 300000);

      req.on("close", () => {
        unsubscribe();
        clearTimeout(timeout);
      });
    } catch (error: any) {
      console.error("SSE stream error:", error);
      res.status(500).json({ message: error.message });
    }
  });

