  // DLQ retry: invokes runPipelineAsync directly (not re-queued to RAW_EVENTS topic).
  // Intentional: operator-triggered retries are synchronous and tracked via DLQ entry status,
  // giving deterministic visibility into outcome. Re-queuing via Kafka would restore
  // normal partition/order semantics but loses direct retry observability.
  app.patch("/api/admin/ingest/dlq/:id/retry", isAuthenticated, async (req: any, res) => {
    try {
      let isPlatformAdmin = false;
      try {
        const access = await getUserTenantAccess(req);
        isPlatformAdmin = access.role === "platform_admin";
      } catch {}
      if (!req.session?.isSuperAdmin && !isPlatformAdmin) {
        return res.status(403).json({ error: "Platform admin access required" });
      }

      const id = Number(req.params.id);
      if (!id) return res.status(400).json({ error: "Invalid ID" });

      const entry = await storage.getDlqEntries();
      const dlqEntry = entry.find((e) => e.id === id);
      if (!dlqEntry) return res.status(404).json({ error: "DLQ entry not found" });

      await storage.updateDlqEntry(id, {
        status: "retrying",
        lastRetryAt: new Date(),
        retryCount: (dlqEntry.retryCount || 0) + 1,
      });

      const isReplayable =
        dlqEntry.tenantId &&
        dlqEntry.batchId &&
        dlqEntry.rawPayload &&
        (() => {
          const raw = dlqEntry.rawPayload as Record<string, any>;
          const evts = raw.events || raw.payload?.events || [];
          return Array.isArray(evts) && evts.length > 0;
        })();

      if (isReplayable) {
        const raw = dlqEntry.rawPayload as Record<string, any>;
        const events = raw.events || raw.payload?.events || [];
        runPipelineAsync(dlqEntry.batchId!, dlqEntry.tenantId!, events, {
          vendorHint: raw.vendorHint || raw.payload?.vendorHint,
        }).then(() => {
          storage.updateDlqEntry(id, { status: "recovered", recoveredAt: new Date() }).catch(() => {});
        }).catch(() => {
          storage.updateDlqEntry(id, { status: "failed" }).catch(() => {});
        });
      } else {
        // No replayable events (e.g. malformed envelope, missing batchId, empty payload).
        // Mark abandoned immediately so the entry does not remain stuck in 'retrying'.
        storage.updateDlqEntry(id, {
          status: "failed",
          metadata: { abandonReason: "non-replayable: no events or missing tenant/batch context" },
        }).catch(() => {});
      }

      res.json({ message: "Retry initiated", id });
    } catch (err: any) {
      res.status(500).json({ error: err.message });
    }
  });

  app.get("/api/entity-profile/:tenantId/:entityType/:entityName", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = Number(req.params.tenantId);
      const entityType = req.params.entityType;
      const entityName = decodeURIComponent(req.params.entityName);
      if (!tenantId || !entityType || !entityName) return res.status(400).json({ message: "Missing parameters" });
      if (!["host", "user", "email", "application"].includes(entityType)) return res.status(400).json({ message: "Invalid entity type" });
      await assertTenantAccess(req, tenantId);

      const tenant = await storage.getTenant(tenantId);
      let childIds: number[] = [];
      if (tenant && tenant.type === "mssp") {
        const children = await storage.getChildTenants(tenantId);
        childIds = children.map(c => c.id);
      }

      if (entityType === "application") {
        const appProfile = await getApplicationProfile(pool, tenantId, entityName, childIds.length > 0 ? childIds : undefined);
        return res.json({
          entity: {
            name: entityName,
            type: "application",
            totalEvents: appProfile.totalEvents,
            uniqueUsers: appProfile.uniqueUsers,
            categories: appProfile.categories,
            sources: appProfile.sources,
            totalUploadsMB: appProfile.totalUploadsMB,
            totalDownloadsMB: appProfile.totalDownloadsMB,
            firstSeen: appProfile.firstSeen,
            lastSeen: appProfile.lastSeen,
            cloudRiskData: appProfile.cloudRiskData,
            riskLevel: appProfile.cloudRiskData
              ? (appProfile.cloudRiskData.confidenceIndex >= 70 ? "low" : appProfile.cloudRiskData.confidenceIndex >= 40 ? "medium" : "high")
              : (appProfile.totalEvents > 100 ? "medium" : "low"),
          },
          profile: {
            recentEvents: appProfile.recentEvents,
            linkedIncidents: [],
          },
          appProfile,
          correlated: { hosts: [], users: [], emails: [] },
        });
      }

      const inventory = await buildEntityInventory(pool, tenantId, childIds.length > 0 ? childIds : undefined);
      
      let entityData: any = null;
      const nameLower = entityName.toLowerCase();
      if (entityType === "host") {
        entityData = inventory.hosts.find((h: any) => h.name.toLowerCase() === nameLower);
      } else if (entityType === "user") {
        entityData = inventory.users.find((u: any) => u.name.toLowerCase() === nameLower);
      } else if (entityType === "email") {
        entityData = inventory.emails.find((e: any) => e.address.toLowerCase() === nameLower);
      }

      const profile = await getEntityProfile(pool, tenantId, entityType, entityName, childIds.length > 0 ? childIds : undefined);

      const correlatedHosts = entityType !== "host" 
        ? inventory.hosts.filter((h: any) => {
            if (entityType === "user") return h.linkedUsers.some((u: string) => u.toLowerCase() === nameLower);
            if (entityType === "email") return h.linkedEmails.some((e: string) => e.toLowerCase() === nameLower);
            return false;
          })
        : [];

      const correlatedUsers = entityType !== "user"
        ? inventory.users.filter((u: any) => {
            if (entityType === "host") return u.devices.some((d: string) => d.toLowerCase() === nameLower);
            if (entityType === "email") return u.emails.some((e: string) => e.toLowerCase() === nameLower);
            return false;
          })
        : [];

      const correlatedEmails = entityType !== "email"
        ? inventory.emails.filter((e: any) => {
            if (entityType === "host") return e.linkedDevices.some((d: string) => d.toLowerCase() === nameLower);
            if (entityType === "user") return e.linkedUsers.some((u: string) => u.toLowerCase() === nameLower);
            return false;
          })
        : [];

      res.json({
        entity: entityData,
        profile,
        correlated: {
          hosts: correlatedHosts.slice(0, 50),
          users: correlatedUsers.slice(0, 50),
          emails: correlatedEmails.slice(0, 50),
        },
      });
    } catch (error: any) {
      console.error("Entity profile error:", error);
      res.status(500).json({ message: error.message });
    }
  });

