      const { ruleId } = req.params;
      const ruleRow = await pool.query(
        `SELECT id, rule_yaml, title FROM sigma_rules WHERE rule_id = $1 LIMIT 1`,
        [ruleId]
      );
      if (!ruleRow.rows.length) return res.status(404).json({ message: "Rule not found" });
      const { id, rule_yaml, title } = ruleRow.rows[0];
      const { gradeSigmaRule } = await import("./predictive-attack-engine");
      const { grade, suggestion } = await gradeSigmaRule(rule_yaml ?? "", title ?? "");
      await pool.query(
        `UPDATE sigma_rules SET quality_grade = $1, ai_suggestion = $2, updated_at = NOW() WHERE id = $3`,
        [grade, suggestion, id]
      );
      res.json({ ruleId, grade, suggestion });
