  app.get("/api/assets/:tenantId/profile-completeness", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      const statsRes = await pool.query(`
        SELECT 
          COUNT(*)::int as total,
          ROUND(AVG(
            (CASE WHEN hostname IS NOT NULL AND hostname != '' THEN 1 ELSE 0 END +
             CASE WHEN ip_address IS NOT NULL AND ip_address != '' THEN 1 ELSE 0 END +
             CASE WHEN mac_address IS NOT NULL AND mac_address != '' THEN 1 ELSE 0 END +
             CASE WHEN operating_system IS NOT NULL AND operating_system != '' THEN 1 ELSE 0 END +
             CASE WHEN processor IS NOT NULL AND processor != '' THEN 1 ELSE 0 END +
             CASE WHEN total_physical_memory IS NOT NULL AND total_physical_memory != '' THEN 1 ELSE 0 END +
             CASE WHEN system_model IS NOT NULL AND system_model != '' THEN 1 ELSE 0 END +
             CASE WHEN system_manufacturer IS NOT NULL AND system_manufacturer != '' THEN 1 ELSE 0 END +
             CASE WHEN endpoint_type IS NOT NULL AND endpoint_type != '' THEN 1 ELSE 0 END +
             CASE WHEN agent_version IS NOT NULL AND agent_version != '' THEN 1 ELSE 0 END +
             CASE WHEN last_seen IS NOT NULL THEN 1 ELSE 0 END +
             CASE WHEN risk_score IS NOT NULL THEN 1 ELSE 0 END +
             CASE WHEN bios_serial_number IS NOT NULL AND bios_serial_number != '' THEN 1 ELSE 0 END +
             CASE WHEN prevention_policy IS NOT NULL AND prevention_policy != '' THEN 1 ELSE 0 END +
             CASE WHEN (COALESCE(last_logged_in_user, '') != '' AND last_logged_in_user != '1') OR (COALESCE(user_name, '') != '' AND user_name != '1') THEN 1 ELSE 0 END +
             CASE WHEN software_inventory IS NOT NULL AND software_inventory::text NOT IN ('null', '[]', '') THEN 1 ELSE 0 END
            ) * 100.0 / 16
          ))::int as avg_completeness,
          COUNT(*) FILTER (WHERE 
            hostname IS NOT NULL AND ip_address IS NOT NULL AND mac_address IS NOT NULL AND
            operating_system IS NOT NULL AND processor IS NOT NULL AND total_physical_memory IS NOT NULL AND
            system_model IS NOT NULL AND system_manufacturer IS NOT NULL AND endpoint_type IS NOT NULL AND
            agent_version IS NOT NULL AND last_seen IS NOT NULL AND risk_score IS NOT NULL AND
            bios_serial_number IS NOT NULL AND prevention_policy IS NOT NULL AND
            software_inventory IS NOT NULL AND software_inventory::text NOT IN ('null', '[]', '')
          )::int as complete_profiles
        FROM assets WHERE tenant_id = $1
      `, [tenantId]);

      const row = statsRes.rows[0];
      const total = row.total || 0;
      const avgCompleteness = row.avg_completeness || 0;
      const completeProfiles = row.complete_profiles || 0;

      const distRes = await pool.query(`
        SELECT 
          COUNT(*) FILTER (WHERE score >= 95)::int as full,
          COUNT(*) FILTER (WHERE score >= 75 AND score < 95)::int as high,
          COUNT(*) FILTER (WHERE score >= 50 AND score < 75)::int as medium,
          COUNT(*) FILTER (WHERE score < 50)::int as low
        FROM (
          SELECT (
            (CASE WHEN hostname IS NOT NULL AND hostname != '' THEN 1 ELSE 0 END +
             CASE WHEN ip_address IS NOT NULL AND ip_address != '' THEN 1 ELSE 0 END +
             CASE WHEN mac_address IS NOT NULL AND mac_address != '' THEN 1 ELSE 0 END +
             CASE WHEN operating_system IS NOT NULL AND operating_system != '' THEN 1 ELSE 0 END +
             CASE WHEN processor IS NOT NULL AND processor != '' THEN 1 ELSE 0 END +
             CASE WHEN total_physical_memory IS NOT NULL AND total_physical_memory != '' THEN 1 ELSE 0 END +
             CASE WHEN system_model IS NOT NULL AND system_model != '' THEN 1 ELSE 0 END +
             CASE WHEN system_manufacturer IS NOT NULL AND system_manufacturer != '' THEN 1 ELSE 0 END +
             CASE WHEN endpoint_type IS NOT NULL AND endpoint_type != '' THEN 1 ELSE 0 END +
             CASE WHEN agent_version IS NOT NULL AND agent_version != '' THEN 1 ELSE 0 END +
             CASE WHEN last_seen IS NOT NULL THEN 1 ELSE 0 END +
             CASE WHEN risk_score IS NOT NULL THEN 1 ELSE 0 END +
             CASE WHEN bios_serial_number IS NOT NULL AND bios_serial_number != '' THEN 1 ELSE 0 END +
             CASE WHEN prevention_policy IS NOT NULL AND prevention_policy != '' THEN 1 ELSE 0 END +
             CASE WHEN (COALESCE(last_logged_in_user, '') != '' AND last_logged_in_user != '1') OR (COALESCE(user_name, '') != '' AND user_name != '1') THEN 1 ELSE 0 END +
             CASE WHEN software_inventory IS NOT NULL AND software_inventory::text NOT IN ('null', '[]', '') THEN 1 ELSE 0 END
            ) * 100.0 / 16
          ) as score
          FROM assets WHERE tenant_id = $1
        ) sub
      `, [tenantId]);

      res.json({
        totalAssets: total,
        averageCompleteness: avgCompleteness,
        completeProfiles: completeProfiles,
        distribution: distRes.rows[0] || { full: 0, high: 0, medium: 0, low: 0 },
      });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to compute completeness" });
    }
  });

  // ─── Domain Distribution API ───
  app.get("/api/assets/:tenantId/domain-distribution", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const domainDistCacheKey = `domain-dist:${tenantId}`;
      const domainDistCached = await getCache(domainDistCacheKey);
      if (domainDistCached) return res.json(domainDistCached);

      const COUNTRY_MAP: Record<string, string> = {
        KE: "Kenya", UG: "Uganda", TZ: "Tanzania", RW: "Rwanda", NG: "Nigeria",
        ZA: "South Africa", GH: "Ghana", ET: "Ethiopia", EG: "Egypt", MA: "Morocco",
        US: "United States", UK: "United Kingdom", GB: "United Kingdom", IN: "India",
        AE: "UAE", SA: "Saudi Arabia", SG: "Singapore", AU: "Australia",
      };
      const CITY_MAP: Record<string, string> = {
        NRB: "Nairobi", KLA: "Kampala", DAR: "Dar es Salaam", KGL: "Kigali",
        MSA: "Mombasa", NKR: "Nakuru", MLD: "Malindi", NBI: "Nairobi",
        LAG: "Lagos", JHB: "Johannesburg", CPT: "Cape Town", ACC: "Accra",
      };
      const TYPE_MAP: Record<string, string> = {
        EP: "Endpoints", SRV: "Servers",
      };

      const result = await pool.query(
        `SELECT endpoint_group, COUNT(*) as count FROM assets WHERE tenant_id = $1 AND endpoint_group IS NOT NULL GROUP BY endpoint_group ORDER BY count DESC`,
        [tenantId]
      );

      const domainData: Array<{ name: string; country: string; city: string; type: string; count: number; group: string }> = [];
      const countryTotals: Record<string, number> = {};
      const locationTotals: Record<string, { country: string; city: string; endpoints: number; servers: number; total: number }> = {};

      for (const row of result.rows) {
        const group = row.endpoint_group || "";
        const count = parseInt(row.count);
        const parts = group.split("-");

        let country = "", city = "", type = "";

        if (parts.length >= 4) {
          const countryCode = parts[1]?.toUpperCase();
          const cityCode = parts[2]?.toUpperCase();
          const typeCode = parts[3]?.toUpperCase().replace(/[^A-Z]/g, "");
          country = COUNTRY_MAP[countryCode] || countryCode || "Unknown";
          city = CITY_MAP[cityCode] || cityCode || "";
          type = TYPE_MAP[typeCode] || typeCode || "Other";
        } else if (parts.length >= 3) {
          const countryCode = parts[1]?.toUpperCase();
          const cityCode = parts[2]?.toUpperCase();
          country = COUNTRY_MAP[countryCode] || countryCode || "Unknown";
          city = CITY_MAP[cityCode] || cityCode || "";
          type = "Endpoints";
        } else {
          country = "Other";
          city = group;
          type = "Other";
        }

        const locationKey = `${country}-${city}`;
        if (!locationTotals[locationKey]) {
          locationTotals[locationKey] = { country, city, endpoints: 0, servers: 0, total: 0 };
        }
        locationTotals[locationKey].total += count;
        if (type === "Servers") {
          locationTotals[locationKey].servers += count;
        } else {
          locationTotals[locationKey].endpoints += count;
        }

        countryTotals[country] = (countryTotals[country] || 0) + count;

        domainData.push({ name: `${country}${city ? " - " + city : ""}`, country, city, type, count, group });
      }

      const byCountry = Object.entries(countryTotals).map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
      const byLocation = Object.values(locationTotals).map(l => ({
        name: `${l.country}${l.city ? " - " + l.city : ""}`,
        country: l.country,
        city: l.city,
        endpoints: l.endpoints,
        servers: l.servers,
        value: l.total,
      })).sort((a, b) => b.value - a.value);

      const domainDistResponse = { byCountry, byLocation, details: domainData };
      setCache(domainDistCacheKey, domainDistResponse, 300_000);
      res.json(domainDistResponse);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

