  // Stagger background service startup to prevent DB connection stampede at boot.
  // Each scheduler gets a small randomized jitter (50-500ms) before registering
  // its setInterval — enough to desync simultaneous timer registration without
  // delaying actual periodic work (which starts after each scheduler's own interval).
  const startupJitter = (minMs = 50, maxMs = 500) =>
    Math.floor(Math.random() * (maxMs - minMs + 1)) + minMs;

  setTimeout(() => {
    pollingTimer = setInterval(runPollingCycle, POLLING_CHECK_INTERVAL_MS);
    console.log(`[Polling] Connector polling scheduler started (checking every ${POLLING_CHECK_INTERVAL_MS / 1000}s)`);
  }, startupJitter(50, 200));

  setTimeout(() => { startInvestigationScheduler(180000); }, startupJitter(100, 300));
  setTimeout(() => { startAssetSyncScheduler(); }, startupJitter(150, 350));

