  setTimeout(() => {
    scheduleLearningDigests(async () => {
      try {
        const r = await pool.query(`SELECT id FROM tenants WHERE status = 'active'`);
        return r.rows.map((row: any) => Number(row.id));
      } catch { return []; }
    });
  }, startupJitter(200, 400));

