  setTimeout(async () => {
    const { scheduleCyberLLMEngine } = await import('./cyber-llm-engine');
    scheduleCyberLLMEngine(async () => {
      try {
        const r = await pool.query(`SELECT id FROM tenants WHERE status = 'active'`);
        return r.rows.map((row: any) => Number(row.id));
      } catch { return []; }
    });
  }, startupJitter(300, 500));

  // Federated Intel Propagation — runs every 2 minutes, propagates approved nominations platform-wide
  const FEDERATED_PROPAGATION_INTERVAL_MS = 2 * 60 * 1000; // 2 minutes
  setTimeout(() => {
    setInterval(async () => {
      try {
        await ensureFederatedIntelTables();
        const result = await runFederatedIntelPropagation();
        if (result.processed > 0) {
          console.log(`[FederatedIntel] Propagation complete — processed: ${result.processed}, propagated: ${result.propagated}, alerts: ${result.alertsGenerated}`);
        }
      } catch (err: any) {
        console.error("[FederatedIntel] Propagation error:", err.message);
      }
    }, FEDERATED_PROPAGATION_INTERVAL_MS);
    console.log("[FederatedIntel] Propagation scheduler started (every 2 minutes)");
  }, startupJitter(250, 500));

  // ─── T001: Correlate Entities — Link Users to Assets ───
  app.post("/api/correlate-entities/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      res.writeHead(200, { "Content-Type": "text/event-stream", "Cache-Control": "no-cache", Connection: "keep-alive" });
      const send = (data: any) => res.write(`data: ${JSON.stringify(data)}\n\n`);

      send({ type: "start", phase: "Loading data..." });

      const assetsRes = await pool.query(`SELECT id, hostname, ip_address, user_name, last_logged_in_user FROM assets WHERE tenant_id = $1`, [tenantId]);
      const assets = assetsRes.rows;
      const hostnameToAssetId = new Map<string, number>();
      const ipToAssetId = new Map<string, number>();
      for (const a of assets) {
        hostnameToAssetId.set(a.hostname.toLowerCase(), a.id);
        if (a.ip_address) ipToAssetId.set(a.ip_address.toLowerCase(), a.id);
      }

      const userAssetsRes = await pool.query(`SELECT id, user_name, email, linked_asset_ids FROM user_assets WHERE tenant_id = $1`, [tenantId]);
      const userAssets = userAssetsRes.rows;
      const userNameToId = new Map<string, number>();
      for (const u of userAssets) {
        userNameToId.set(u.user_name.toLowerCase(), u.id);
      }

      const userToAssetIds = new Map<string, Set<number>>();
      const assetToUsers = new Map<number, Set<string>>();
      let correlated = 0;

      // Phase 1: Cynet User↔Host correlation
      send({ type: "progress", phase: "Phase 1: Cynet User↔Host correlation", correlated });
      const cynetEventsRes = await pool.query(
        `SELECT raw_payload->>'User/Risk' as user_risk, raw_payload->>'Host/Risk' as host_risk
         FROM security_events WHERE tenant_id = $1 AND log_source = 'Cynet 360'
         AND raw_payload->>'User/Risk' IS NOT NULL AND raw_payload->>'Host/Risk' IS NOT NULL`,
        [tenantId]
      );

      for (const row of cynetEventsRes.rows) {
        const userRisk = row.user_risk || "";
        const hostRisk = row.host_risk || "";

        const userMatch = userRisk.match(/(?:.*\\)?([^/]+)\/\d+/);
        const hostMatch = hostRisk.match(/([^/]+)\/\d+/);
        if (!userMatch || !hostMatch) continue;

        const userName = userMatch[1].toLowerCase().trim();
        const hostName = hostMatch[1].toLowerCase().trim();

        if (userName === "nt authority - system" || userName === "system" || userName === "administrator") continue;

        const assetId = hostnameToAssetId.get(hostName) || hostnameToAssetId.get(hostName.split("-")[0]);
        if (!assetId) continue;

        if (!userToAssetIds.has(userName)) userToAssetIds.set(userName, new Set());
        userToAssetIds.get(userName)!.add(assetId);

        if (!assetToUsers.has(assetId)) assetToUsers.set(assetId, new Set());
        assetToUsers.get(assetId)!.add(userName);
        correlated++;
      }
      send({ type: "progress", phase: "Phase 1 complete", correlated });

      // Phase 2: Skyhigh User→Asset via IP
      send({ type: "progress", phase: "Phase 2: Skyhigh User→Asset via IP", correlated });
      const skyhighEventsRes = await pool.query(
        `SELECT DISTINCT raw_payload->>'userName' as user_name, raw_payload->>'sourceIp' as source_ip
         FROM security_events WHERE tenant_id = $1 AND log_source = 'Skyhigh Security SSE'
         AND raw_payload->>'userName' IS NOT NULL AND raw_payload->>'sourceIp' IS NOT NULL`,
        [tenantId]
      );

      for (const row of skyhighEventsRes.rows) {
        const userName = (row.user_name || "").toLowerCase().trim();
        if (!userName) continue;

        const ips = (row.source_ip || "").split(",").map((ip: string) => ip.trim().toLowerCase()).filter(Boolean);
        for (const ip of ips) {
          const assetId = ipToAssetId.get(ip);
          if (assetId) {
            if (!userToAssetIds.has(userName)) userToAssetIds.set(userName, new Set());
            userToAssetIds.get(userName)!.add(assetId);
            if (!assetToUsers.has(assetId)) assetToUsers.set(assetId, new Set());
            assetToUsers.get(assetId)!.add(userName);
            correlated++;
          }
        }
      }
      send({ type: "progress", phase: "Phase 2 complete", correlated });

      // Phase 3: Email→User enrichment from Checkpoint
      send({ type: "progress", phase: "Phase 3: Email→User enrichment", correlated });
      const checkpointRes = await pool.query(
        `SELECT DISTINCT raw_payload->>'recipients' as recipients
         FROM security_events WHERE tenant_id = $1 AND log_source = 'Checkpoint Harmony Email'
         AND raw_payload->>'recipients' IS NOT NULL`,
        [tenantId]
      );

      const emailToUser = new Map<string, string>();
      for (const row of checkpointRes.rows) {
        const recipients = (row.recipients || "").split(/[,;]/).map((e: string) => e.trim().toLowerCase()).filter(Boolean);
        for (const email of recipients) {
          const prefix = email.split("@")[0];
          if (prefix && userNameToId.has(prefix)) {
            emailToUser.set(prefix, email);
          }
        }
      }

      let emailsUpdated = 0;
      for (const [userName, email] of emailToUser) {
        const userId = userNameToId.get(userName);
        if (userId) {
          const existing = userAssets.find(u => u.id === userId);
          if (existing && !existing.email) {
            await pool.query(`UPDATE user_assets SET email = $1 WHERE id = $2`, [email, userId]);
            emailsUpdated++;
          }
        }
      }
      send({ type: "progress", phase: "Phase 3 complete", correlated, emailsUpdated });

      // Write results: update user_assets.linkedAssetIds
      send({ type: "progress", phase: "Writing user→asset links..." });
      let usersLinked = 0;
      for (const [userName, assetIds] of userToAssetIds) {
        const userId = userNameToId.get(userName);
        if (userId) {
          const idsArray = Array.from(assetIds);
          await pool.query(`UPDATE user_assets SET linked_asset_ids = $1::jsonb WHERE id = $2`, [JSON.stringify(idsArray), userId]);
          usersLinked++;
        }
      }

      // Write results: update assets.last_logged_in_user
      let assetsUpdated = 0;
      for (const [assetId, users] of assetToUsers) {
        const usersArr = Array.from(users).filter(u => u !== "administrator");
        if (usersArr.length > 0) {
          await pool.query(`UPDATE assets SET last_logged_in_user = $1 WHERE id = $2`, [usersArr[0], assetId]);
          assetsUpdated++;
        }
      }

      send({ type: "complete", correlated, usersLinked, assetsUpdated, emailsUpdated });
      res.end();
    } catch (error: any) {
      console.error("Entity correlation error:", error);
      if (!res.headersSent) {
        res.status(error.status || 500).json({ message: error.message || "Failed to correlate entities" });
      }
    }
  });

  // ─── T002: Enrich Assets from Existing Event Data ───
  app.post("/api/enrich-assets/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      assertMSSRole(access);
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      res.writeHead(200, { "Content-Type": "text/event-stream", "Cache-Control": "no-cache", Connection: "keep-alive" });
      const send = (data: any) => res.write(`data: ${JSON.stringify(data)}\n\n`);

      send({ type: "start", phase: "Loading assets and events..." });

      const assetsRes = await pool.query(`SELECT id, hostname, ip_address, user_name, endpoint_group, operating_system FROM assets WHERE tenant_id = $1`, [tenantId]);
      const assets = assetsRes.rows;

      const cynetEventsRes = await pool.query(
        `SELECT raw_payload, asset, severity, risk_score FROM security_events
         WHERE tenant_id = $1 AND log_source = 'Cynet 360'`, [tenantId]
      );
      const cynetEvents = cynetEventsRes.rows;

      const userAssetsRes = await pool.query(`SELECT id, user_name, linked_asset_ids FROM user_assets WHERE tenant_id = $1`, [tenantId]);
      const userAssets = userAssetsRes.rows;

      const skyhighByUser = new Map<string, Array<{ serviceName: string; serviceCategory: string; activityType: string; sourceIp: string; country: string; activityCount: number }>>();
      const skyhighRes = await pool.query(
        `SELECT raw_payload->>'userName' as user_name, raw_payload->>'serviceName' as service_name,
                raw_payload->>'serviceCategory' as service_category, raw_payload->>'activityType' as activity_type,
                raw_payload->>'sourceIp' as source_ip, raw_payload->>'country' as country,
                COALESCE((raw_payload->>'activityCount')::int, 1) as activity_count
         FROM security_events WHERE tenant_id = $1 AND log_source = 'Skyhigh Security SSE'
         AND raw_payload->>'userName' IS NOT NULL`, [tenantId]
      );
      for (const row of skyhighRes.rows) {
        const un = (row.user_name || "").toLowerCase();
        if (!un) continue;
        if (!skyhighByUser.has(un)) skyhighByUser.set(un, []);
        skyhighByUser.get(un)!.push({
          serviceName: row.service_name || "",
          serviceCategory: row.service_category || "",
          activityType: row.activity_type || "",
          sourceIp: row.source_ip || "",
          country: row.country || "",
          activityCount: row.activity_count || 1,
        });
      }

      let enriched = 0;
      const total = assets.length;

      for (const asset of assets) {
        const hostKey = asset.hostname.toLowerCase();
        const enrichmentData: any = {};

        const matchedCynet = cynetEvents.filter(e => {
          const p = e.raw_payload;
          if (!p) return false;
          const hostRisk = p["Host/Risk"] || "";
          return hostRisk.toLowerCase().startsWith(hostKey + "/") || hostRisk.toLowerCase().startsWith(hostKey + "-");
        });

        if (matchedCynet.length > 0) {
          const loggedInUsers = new Set<string>();
          let maxRisk = 0;
          const scanGroups = new Set<string>();
          const epsActions = new Set<string>();
          const incidents: string[] = [];

          for (const evt of matchedCynet) {
            const p = evt.raw_payload;
            if (!p) continue;
            const userRisk = p["User/Risk"] || "";
            const userMatch = userRisk.match(/(?:.*\\)?([^/]+)\/(\d+)/);
            if (userMatch) {
              const u = userMatch[1].toLowerCase();
              if (u !== "nt authority - system" && u !== "system") loggedInUsers.add(u);
            }
            const totalRisk = parseInt(p["Total Risk"] || "0");
            if (totalRisk > maxRisk) maxRisk = totalRisk;
            if (p["Scan Group Name"]) scanGroups.add(p["Scan Group Name"]);
            if (p["Last EPS Auto-Remediation Action"]) epsActions.add(p["Last EPS Auto-Remediation Action"]);
            if (p["Incident Name"]) incidents.push(p["Incident Name"]);
          }

          enrichmentData.loggedInUsers = Array.from(loggedInUsers);
          enrichmentData.maxRiskScore = maxRisk;
          enrichmentData.scanGroups = Array.from(scanGroups);
          enrichmentData.epsActions = Array.from(epsActions);
          enrichmentData.cynetIncidents = incidents.slice(0, 20);
          enrichmentData.securitySource = "Cynet 360";
        }

        const linkedUserAssets = userAssets.filter(ua => {
          const linked = ua.linked_asset_ids;
          return Array.isArray(linked) && linked.includes(asset.id);
        });

        if (linkedUserAssets.length > 0) {
          const cloudApps = new Map<string, { name: string; category: string; totalActivity: number; activityTypes: Set<string> }>();
          const loginHistory: Array<{ user: string; ip: string; country: string }> = [];

          for (const ua of linkedUserAssets) {
            const un = ua.user_name.toLowerCase();
            const activities = skyhighByUser.get(un) || [];
            for (const act of activities) {
              if (act.serviceName) {
                const key = act.serviceName.toLowerCase();
                if (!cloudApps.has(key)) {
                  cloudApps.set(key, { name: act.serviceName, category: act.serviceCategory, totalActivity: 0, activityTypes: new Set() });
                }
                const app = cloudApps.get(key)!;
                app.totalActivity += act.activityCount;
                if (act.activityType) app.activityTypes.add(act.activityType);
              }
              if (act.activityType === "login") {
                loginHistory.push({ user: un, ip: act.sourceIp, country: act.country });
              }
            }
          }

          enrichmentData.cloudApplications = Array.from(cloudApps.values()).map(a => ({
            name: a.name, category: a.category, totalActivity: a.totalActivity,
            activityTypes: Array.from(a.activityTypes),
          })).sort((a, b) => b.totalActivity - a.totalActivity).slice(0, 50);
          enrichmentData.linkedUserNames = linkedUserAssets.map(ua => ua.user_name);
          enrichmentData.loginHistory = loginHistory.slice(0, 30);
        }

        if (Object.keys(enrichmentData).length > 0) {
          enrichmentData.enrichedAt = new Date().toISOString();
          const updateFields: string[] = [`enrichment_data = $1`];
          const updateValues: any[] = [JSON.stringify(enrichmentData)];
          let paramIdx = 2;

          if (enrichmentData.loggedInUsers?.length > 0 && !asset.last_logged_in_user) {
            updateFields.push(`last_logged_in_user = $${paramIdx}`);
            updateValues.push(enrichmentData.loggedInUsers[0]);
            paramIdx++;
          }

          updateValues.push(asset.id);
          await pool.query(
            `UPDATE assets SET ${updateFields.join(", ")} WHERE id = $${paramIdx}`,
            updateValues
          );
          enriched++;
        }

        if (enriched % 50 === 0 || enriched === total) {
          send({ type: "progress", enriched, total });
        }
      }

      send({ type: "complete", enriched, total });
      res.end();
    } catch (error: any) {
      console.error("Asset enrichment error:", error);
      if (!res.headersSent) {
        res.status(error.status || 500).json({ message: error.message || "Failed to enrich assets" });
      }
    }
  });

