  app.patch("/api/email-configurations/:tenantId/:id", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const id = parseInt(req.params.id);
      const access = await getUserTenantAccess(req);
      if (!["platform_admin", "mss_admin", "soc_manager"].includes(access.role)) {
        return res.status(403).json({ message: "Insufficient permissions" });
      }
      const { provider, name, config, fromEmail, fromName, isDefault, isActive } = req.body;
      if (isDefault) {
        await pool.query(`UPDATE email_configurations SET is_default = false WHERE tenant_id = $1`, [tenantId]);
      }
      const sets: string[] = [];
      const vals: any[] = [];
      let idx = 1;
      if (provider !== undefined) { sets.push(`provider = $${idx++}`); vals.push(provider); }
      if (name !== undefined) { sets.push(`name = $${idx++}`); vals.push(name); }
      if (config !== undefined) { sets.push(`config = $${idx++}`); vals.push(JSON.stringify(config)); }
      if (fromEmail !== undefined) { sets.push(`from_email = $${idx++}`); vals.push(fromEmail); }
      if (fromName !== undefined) { sets.push(`from_name = $${idx++}`); vals.push(fromName); }
      if (isDefault !== undefined) { sets.push(`is_default = $${idx++}`); vals.push(isDefault); }
      if (isActive !== undefined) { sets.push(`is_active = $${idx++}`); vals.push(isActive); }
      sets.push(`updated_at = NOW()`);
      vals.push(id, tenantId);
      const result = await pool.query(
        `UPDATE email_configurations SET ${sets.join(", ")} WHERE id = $${idx++} AND tenant_id = $${idx} RETURNING id, tenant_id, provider, name, from_email, from_name, is_default, is_active, updated_at`,
        vals
      );
      res.json(result.rows[0]);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

