  // === Notification Routes ===
  app.post("/api/ai-investigations/:tenantId/:id/send-notification", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const investigationId = parseInt(req.params.id);
      const { recipients } = req.body;
      if (!recipients || !Array.isArray(recipients) || recipients.length === 0) {
        return res.status(400).json({ message: "Recipients required" });
      }

      const invResult = await pool.query(
        `SELECT ai.*, i.title as incident_title, i.severity as incident_severity, i.status as incident_status,
         i.source_ip, i.destination_ip, i.affected_assets, i.source as source_category,
         i.action_taken, i.description as incident_description, i.incident_type,
         i.detection_source, i.source as incident_source
         FROM ai_investigations ai
         JOIN incidents i ON ai.incident_id = i.id
         WHERE ai.id = $1 AND ai.tenant_id = $2`,
        [investigationId, tenantId]
      );
      if (invResult.rows.length === 0) return res.status(404).json({ message: "Investigation not found" });
      const inv = invResult.rows[0];

      if (!inv.verdict) {
        try {
          const verdictResult = await generateVerdict(investigationId);
          inv.verdict = verdictResult.verdict;
          inv.verdict_reasoning = verdictResult.verdictReasoning;
        } catch (e) {
          inv.verdict = "inconclusive";
          inv.verdict_reasoning = "Verdict generation unavailable.";
        }
      }

      const tenantResult = await pool.query(`SELECT name, timezone, brand_color, logo_url FROM tenants WHERE id = $1`, [tenantId]);
      const tenant = tenantResult.rows[0] || { name: "Unknown", timezone: "UTC", brand_color: "#3b82f6", logo_url: null };

      const domain = classifySecurityDomain({
        source: inv.incident_source || inv.source_category,
        category: inv.source_category,
        incident_type: inv.incident_type,
        title: inv.incident_title,
      });

      const actionToken = crypto.randomBytes(32).toString("hex");
      const baseUrl = `${req.protocol}://${req.get("host")}`;

      const incidentForClassify = {
        title: inv.incident_title, incident_type: inv.incident_type,
        category: inv.source_category, source: inv.incident_source || inv.source_category,
        description: inv.incident_description,
      };
      const attackType = classifyAttackType(incidentForClassify) as any;

      const emailContent = generateNotificationEmail({
        domain: domain.toLowerCase().replace(/\s+/g, "_") as any,
        attackType,
        incident: {
          id: inv.incident_id,
          title: inv.incident_title || "Untitled Incident",
          severity: inv.incident_severity || "medium",
          status: inv.incident_status || "open",
          sourceIp: inv.source_ip,
          destinationIp: inv.destination_ip,
          affectedAssets: inv.affected_assets,
          sourceCategory: inv.source_category,
          actionTaken: inv.action_taken,
          description: inv.incident_description,
          incidentType: inv.incident_type,
          detectionSource: inv.detection_source,
          attackVector: null,
        },
        investigation: (() => {
          const parseJsonField = (val: any, fallback: any = null) => {
            if (val === null || val === undefined) return fallback;
            if (typeof val === "string") {
              try { return JSON.parse(val); } catch { return fallback; }
            }
            return val;
          };
          const parsedAC = parseJsonField(inv.attack_chain, []);
          const parsedIOC = parseJsonField(inv.iocs_summary, []);
          const parsedAE = parseJsonField(inv.affected_entities, []);
          const parsedF = parseJsonField(inv.findings, {});
          const parsedR = parseJsonField(inv.recommendations, {});
          return {
            executiveSummary: inv.executive_summary || "",
            technicalReport: inv.technical_report || "",
            riskScore: inv.risk_score ?? 0,
            confidenceScore: inv.confidence_score ?? 0,
            attackChain: Array.isArray(parsedAC) ? parsedAC : [],
            iocsSummary: Array.isArray(parsedIOC) ? parsedIOC : [],
            affectedEntities: Array.isArray(parsedAE) ? parsedAE : [],
            findings: (typeof parsedF === "object" && parsedF && !Array.isArray(parsedF)) ? parsedF : {},
            recommendations: (typeof parsedR === "object" && parsedR && !Array.isArray(parsedR)) ? parsedR : {},
            verdict: inv.verdict || "inconclusive",
            verdictReasoning: inv.verdict_reasoning || "Verdict not yet determined.",
          };
        })(),
        tenant: { name: tenant.name, timezone: tenant.timezone || "UTC", brandColor: tenant.brand_color || "#3b82f6", logoUrl: tenant.logo_url || null },
        actionToken,
        baseUrl,
      });

      const configResult = await pool.query(
        `SELECT * FROM email_configurations WHERE tenant_id = $1 AND is_active = true ORDER BY is_default DESC LIMIT 1`,
        [tenantId]
      );

      let sendResult = { success: false, error: "No email configuration found" };
      if (configResult.rows.length > 0) {
        sendResult = await sendEmail(configResult.rows[0], {
          to: recipients,
          subject: emailContent.subject,
          html: emailContent.html,
        });
      }

      const notifResult = await pool.query(
        `INSERT INTO incident_notifications (tenant_id, incident_id, investigation_id, recipients, notification_type, domain, verdict, email_subject, email_body, status, action_token, sent_at, created_at)
         VALUES ($1, $2, $3, $4, 'ai_investigation_complete', $5, $6, $7, $8, $9, $10, $11, NOW()) RETURNING *`,
        [
          tenantId, inv.incident_id, investigationId,
          recipients, domain.toLowerCase().replace(/\s+/g, "_"),
          inv.verdict, emailContent.subject, emailContent.html,
          sendResult.success ? "sent" : "failed",
          actionToken,
          sendResult.success ? new Date() : null,
        ]
      );

      res.json({
        notification: notifResult.rows[0],
        sendResult,
      });
    } catch (error: any) {
      console.error("[Notification] Error:", error);
      res.status(500).json({ message: error.message });
    }
  });

