  // === Notification Action Routes (token-based, no auth required) ===
  app.get("/api/notification-action/:token", async (req, res) => {
    try {
      const { token } = req.params;
      const result = await pool.query(
        `SELECT n.*, i.title as incident_title, i.severity as incident_severity, i.status as incident_status,
         t.name as tenant_name
         FROM incident_notifications n
         JOIN incidents i ON n.incident_id = i.id
         JOIN tenants t ON n.tenant_id = t.id
         WHERE n.action_token = $1`,
        [token]
      );
      if (result.rows.length === 0) return res.status(404).json({ message: "Invalid or expired token" });
      const notif = result.rows[0];
      const createdAt = new Date(notif.created_at).getTime();
      const TOKEN_EXPIRY_MS = 72 * 60 * 60 * 1000;
      if (Date.now() - createdAt > TOKEN_EXPIRY_MS) {
        return res.status(410).json({ message: "This action link has expired (72-hour limit)" });
      }
      res.json({
        incidentId: notif.incident_id,
        incidentTitle: notif.incident_title,
        severity: notif.incident_severity,
        status: notif.incident_status,
        verdict: notif.verdict,
        tenantName: notif.tenant_name,
        domain: notif.domain,
        actionTaken: notif.action_taken,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/notification-action/:token/execute", async (req, res) => {
    try {
      const { token } = req.params;
      const { action } = req.body;
      const validActions = ["close", "false_positive", "escalate", "acknowledge", "share"];
      if (!validActions.includes(action)) {
        return res.status(400).json({ message: "Invalid action" });
      }

      const result = await pool.query(
        `SELECT n.*, i.tenant_id as inc_tenant_id FROM incident_notifications n JOIN incidents i ON n.incident_id = i.id WHERE n.action_token = $1`, [token]
      );
      if (result.rows.length === 0) return res.status(404).json({ message: "Invalid or expired token" });
      const notif = result.rows[0];

      const createdAt = new Date(notif.created_at).getTime();
      const TOKEN_EXPIRY_MS = 72 * 60 * 60 * 1000;
      if (Date.now() - createdAt > TOKEN_EXPIRY_MS) {
        return res.status(410).json({ message: "This action link has expired (72-hour limit)" });
      }

      if (action === "share") {
        const invResult = await pool.query(
          `SELECT id FROM ai_investigations WHERE incident_id = $1 AND tenant_id = $2 ORDER BY id DESC LIMIT 1`,
          [notif.incident_id, notif.tenant_id]
        );
        const investigationId = invResult.rows[0]?.id;
        return res.json({
          message: "Investigation report link generated",
          shareUrl: investigationId ? `/ai-analyst/${notif.tenant_id}/${investigationId}` : null,
        });
      }

      if (notif.action_taken && action !== "share") {
        return res.status(400).json({ message: `Action already taken: ${notif.action_taken}` });
      }

      let actionLabel = "";
      if (action === "close") {
        await pool.query(`UPDATE incidents SET status = 'closed' WHERE id = $1`, [notif.incident_id]);
        actionLabel = "Incident Closed";
      } else if (action === "false_positive") {
        await pool.query(
          `UPDATE incidents SET status = 'closed', is_true_positive = false, classification = 'False Positive' WHERE id = $1`,
          [notif.incident_id]
        );
        actionLabel = "Reported as False Positive";
      } else if (action === "escalate") {
        await pool.query(
          `UPDATE incidents SET severity = CASE WHEN severity = 'low' THEN 'medium' WHEN severity = 'medium' THEN 'high' WHEN severity = 'high' THEN 'critical' ELSE severity END, status = 'escalated' WHERE id = $1`,
          [notif.incident_id]
        );
        actionLabel = "Escalated to Tier 2";
      } else if (action === "acknowledge") {
        await pool.query(
          `UPDATE incidents SET status = 'acknowledged' WHERE id = $1`,
          [notif.incident_id]
        );
        actionLabel = "Acknowledged & Monitoring";
      }

      await pool.query(
        `UPDATE incident_notifications SET action_taken = $1, action_taken_at = NOW() WHERE id = $2`,
        [action, notif.id]
      );

      res.json({ message: actionLabel || `Action '${action}' completed successfully` });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/risk-by-category", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const result = await pool.query(
        `SELECT
          CASE
            WHEN LOWER(endpoint_type) IN ('server', 'virtual machine', 'esxi host', 'hypervisor') THEN 'Servers'
            WHEN LOWER(endpoint_type) IN ('workstation', 'laptop', 'desktop', 'endpoint') THEN 'Endpoints'
            WHEN LOWER(endpoint_type) IN ('iot', 'ot', 'sensor', 'appliance', 'network device', 'printer', 'camera') THEN 'IoT'
            WHEN LOWER(endpoint_type) IN ('cloud', 'cloud instance', 'container', 'lambda', 'serverless') OR LOWER(COALESCE(cloud_provider, '')) != '' THEN 'Cloud'
            WHEN endpoint_type IS NULL OR endpoint_type = '' THEN 'Unknown'
            ELSE 'Other'
          END as category,
          COUNT(*) as count,
          COALESCE(AVG(CASE WHEN risk_score > 100 THEN ROUND(risk_score::numeric * 100 / 1000) ELSE risk_score END), 0) as avg_risk,
          COALESCE(MAX(CASE WHEN risk_score > 100 THEN ROUND(risk_score::numeric * 100 / 1000) ELSE risk_score END), 0) as max_risk,
          COUNT(CASE WHEN risk_level IN ('critical', 'high') THEN 1 END) as high_risk_count
        FROM assets
        WHERE tenant_id IN (${placeholders})
        GROUP BY category
        ORDER BY count DESC`,
        tenantIds
      );

      const categories: Record<string, { count: number; avgRisk: number; maxRisk: number; highRiskCount: number }> = {};
      for (const row of result.rows) {
        const cat = row.category;
        if (cat === "Unknown" || cat === "Other") continue;
        categories[cat] = {
          count: parseInt(row.count),
          avgRisk: Math.round(parseFloat(row.avg_risk)),
          maxRisk: Math.round(parseFloat(row.max_risk)),
          highRiskCount: parseInt(row.high_risk_count),
        };
      }

      const unknown = result.rows.find(r => r.category === "Unknown" || r.category === "Other");
      if (unknown && Object.keys(categories).length === 0) {
        categories["Servers"] = {
          count: parseInt(unknown.count),
          avgRisk: Math.round(parseFloat(unknown.avg_risk)),
          maxRisk: Math.round(parseFloat(unknown.max_risk)),
          highRiskCount: parseInt(unknown.high_risk_count),
        };
      }

      res.json(categories);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Failed to fetch risk by category" });
    }
  });

  app.get("/api/asset-inventory/:tenantId/export-excel", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (!Number.isInteger(tenantId) || tenantId <= 0) {
        return res.status(400).json({ message: "Invalid tenant ID" });
      }
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const ExcelJS = (await import("exceljs")).default;

      const [assetResult, tenantResult] = await Promise.all([
        pool.query(
          `SELECT hostname, ip_address, operating_system, status, cloud_region,
                  endpoint_group, user_name, last_seen, enrichment_data
           FROM assets WHERE tenant_id IN (${placeholders})
           ORDER BY hostname ASC`,
          tenantIds
        ),
        pool.query(`SELECT name FROM tenants WHERE id = $1`, [tenantId]),
      ]);

      const rawTenantName = tenantResult.rows[0]?.name || `Tenant ${tenantId}`;
      const tenantName = sanitizeCell(rawTenantName);
      const { lookupEOL } = await import("./eol-database");

      function sanitizeCell(val: string): string {
        if (!val) return val;
        if (/^[=+\-@\t\r]/.test(val)) return "'" + val;
        return val;
      }

      function deriveOsFamily(os: string | null): string {
        if (!os) return "Unknown";
        const lower = os.toLowerCase();
        if (lower.includes("windows")) return "Windows";
        if (lower.includes("ubuntu") || lower.includes("debian") || lower.includes("centos") || lower.includes("rhel") || lower.includes("red hat") || lower.includes("fedora") || lower.includes("suse") || lower.includes("linux")) return "Linux";
        if (lower.includes("aix")) return "AIX";
        if (lower.includes("vios")) return "VIOS";
        if (lower.includes("macos") || lower.includes("mac os") || lower.includes("darwin")) return "macOS";
        if (lower.includes("solaris") || lower.includes("sunos")) return "Solaris";
        if (lower.includes("freebsd") || lower.includes("openbsd") || lower.includes("netbsd")) return "BSD";
        if (lower.includes("vmware") || lower.includes("esxi")) return "VMware";
        return "Other";
      }

      const NAVY = "1B2A4A";
      const TEAL = "2C5F7C";
      const LIGHT_GRAY = "F2F2F2";
      const ACCENT = "3A7CA5";
      const BORDER_COLOR = "BFC0C2";
      const WHITE = "FFFFFF";
      const DARK_TEXT = "1B2A4A";

      const fontBase = { name: "Calibri", size: 10 };
      const fontWhiteBold = { ...fontBase, bold: true, color: { argb: WHITE } };
      const fontDarkBold = { ...fontBase, bold: true, color: { argb: DARK_TEXT } };
      const fontDark = { ...fontBase, color: { argb: DARK_TEXT } };
      const thinBorder: Partial<ExcelJS.Borders> = {
        top: { style: "thin" as const, color: { argb: BORDER_COLOR } },
        bottom: { style: "thin" as const, color: { argb: BORDER_COLOR } },
        left: { style: "thin" as const, color: { argb: BORDER_COLOR } },
        right: { style: "thin" as const, color: { argb: BORDER_COLOR } },
      };

      const assets = assetResult.rows.map((row: any) => {
        const enrichment = row.enrichment_data || {};
        const os = row.operating_system || "";
        const osFamily = deriveOsFamily(os);
        const applicationOwner = enrichment.applicationOwner || enrichment.application_owner || row.user_name || "";
        const location = enrichment.location || row.cloud_region || row.endpoint_group || "";
        let eolStatus = "";
        let eosStatus = "";
        if (enrichment.eolDate || enrichment.eosDate) {
          eolStatus = enrichment.eolStatus || (enrichment.eolDate ? `EOL: ${enrichment.eolDate}` : "");
          eosStatus = enrichment.eosStatus || (enrichment.eosDate ? `EOS: ${enrichment.eosDate}` : "");
        } else if (os) {
          const eolResult = lookupEOL(os, os);
          if (eolResult) {
            eolStatus = eolResult.eolStatus === "ended" ? `Ended (${eolResult.eolDate})` : eolResult.eolStatus === "approaching" ? `Approaching (${eolResult.eolDate})` : "Active";
            eosStatus = eolResult.eosStatus === "ended" ? `Ended (${eolResult.eosDate})` : eolResult.eosStatus === "approaching" ? `Approaching (${eolResult.eosDate})` : "Active";
          }
        }
        return {
          hostname: sanitizeCell(row.hostname || ""),
          ipAddress: sanitizeCell(row.ip_address || ""),
          osFamily,
          operatingSystem: sanitizeCell(os),
          status: sanitizeCell((row.status || "active").charAt(0).toUpperCase() + (row.status || "active").slice(1)),
          applicationOwner: sanitizeCell(applicationOwner),
          location: sanitizeCell(location),
          eolStatus: sanitizeCell(eolStatus),
          eosStatus: sanitizeCell(eosStatus),
        };
      });

      const statusCounts: Record<string, number> = {};
      const osFamilyCounts: Record<string, number> = {};
      const osVersionCounts: Record<string, { osFamily: string; count: number }> = {};
      const appOwnerCounts: Record<string, { total: number; active: number; inactive: number; decommissioned: number }> = {};

      for (const a of assets) {
        statusCounts[a.status] = (statusCounts[a.status] || 0) + 1;
        if (a.status === "Active") {
          osFamilyCounts[a.osFamily] = (osFamilyCounts[a.osFamily] || 0) + 1;
          const osKey = a.operatingSystem || "Unknown";
          if (!osVersionCounts[osKey]) osVersionCounts[osKey] = { osFamily: a.osFamily, count: 0 };
          osVersionCounts[osKey].count++;
        }
        const owner = a.applicationOwner || "Unassigned";
        if (!appOwnerCounts[owner]) appOwnerCounts[owner] = { total: 0, active: 0, inactive: 0, decommissioned: 0 };
        appOwnerCounts[owner].total++;
        if (a.status === "Active") appOwnerCounts[owner].active++;
        else if (a.status === "Inactive" || a.status === "Offline") appOwnerCounts[owner].inactive++;
        else if (a.status === "Decommissioned") appOwnerCounts[owner].decommissioned++;
      }

      const totalAssets = assets.length;
      const totalActive = Object.values(osFamilyCounts).reduce((s, c) => s + c, 0);

      const wb = new ExcelJS.Workbook();
      wb.creator = "SecureOps Platform";
      wb.created = new Date();

      // ─── Sheet 1: Cover ───
      const cover = wb.addWorksheet("Cover", { properties: { tabColor: { argb: NAVY } } });
      cover.properties.defaultColWidth = 20;
      cover.getColumn(1).width = 5;
      cover.getColumn(2).width = 50;
      cover.getColumn(3).width = 30;
      cover.getColumn(4).width = 5;

      for (let r = 1; r <= 3; r++) {
        cover.mergeCells(r, 1, r, 4);
        const row = cover.getRow(r);
        row.getCell(1).fill = { type: "pattern", pattern: "solid", fgColor: { argb: NAVY } };
        row.height = r === 1 ? 15 : 10;
      }

      cover.mergeCells(5, 2, 5, 3);
      const titleCell = cover.getRow(5).getCell(2);
      titleCell.value = "Asset Inventory Report";
      titleCell.font = { name: "Calibri", size: 28, bold: true, color: { argb: NAVY } };
      titleCell.alignment = { vertical: "middle" };
      cover.getRow(5).height = 45;

      cover.mergeCells(7, 2, 7, 3);
      const subtitleCell = cover.getRow(7).getCell(2);
      subtitleCell.value = `Prepared for ${tenantName}`;
      subtitleCell.font = { name: "Calibri", size: 14, color: { argb: TEAL } };

      cover.mergeCells(8, 2, 8, 3);
      const confCell = cover.getRow(8).getCell(2);
      confCell.value = "CONFIDENTIAL";
      confCell.font = { name: "Calibri", size: 11, bold: true, color: { argb: "C0392B" }, italic: true };

      const reportDate = new Date().toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });

      const coverDetails = [
        ["Report Date", reportDate],
        ["Total Assets", totalAssets.toLocaleString()],
        ["Active Assets", totalActive.toLocaleString()],
        ["OS Families", Object.keys(osFamilyCounts).length.toString()],
        ["Application Owners", Object.keys(appOwnerCounts).length.toString()],
      ];

      let coverRow = 11;
      cover.mergeCells(coverRow, 2, coverRow, 3);
      const summLabel = cover.getRow(coverRow).getCell(2);
      summLabel.value = "Report Summary";
      summLabel.font = { name: "Calibri", size: 13, bold: true, color: { argb: NAVY } };
      summLabel.border = { bottom: { style: "medium", color: { argb: ACCENT } } };
      cover.getRow(coverRow).height = 25;
      coverRow += 1;

      for (const [label, value] of coverDetails) {
        const r = cover.getRow(coverRow);
        r.getCell(2).value = label;
        r.getCell(2).font = { ...fontBase, color: { argb: "666666" } };
        r.getCell(3).value = value;
        r.getCell(3).font = fontDarkBold;
        r.getCell(3).alignment = { horizontal: "left" };
        r.height = 22;
        coverRow++;
      }

      coverRow += 2;
      cover.mergeCells(coverRow, 2, coverRow, 3);
      const footerCell = cover.getRow(coverRow).getCell(2);
      footerCell.value = `Generated by SecureOps Platform · ${reportDate}`;
      footerCell.font = { name: "Calibri", size: 9, italic: true, color: { argb: "999999" } };

      for (let r = coverRow + 2; r <= coverRow + 3; r++) {
        cover.mergeCells(r, 1, r, 4);
        cover.getRow(r).getCell(1).fill = { type: "pattern", pattern: "solid", fgColor: { argb: NAVY } };
        cover.getRow(r).height = 10;
      }

      // ─── Sheet 2: Executive Dashboard ───
      const dashboard = wb.addWorksheet("Executive Dashboard", { properties: { tabColor: { argb: TEAL } } });

      function addSectionTitle(ws: ExcelJS.Worksheet, row: number, title: string, colSpan: number): number {
        ws.mergeCells(row, 1, row, colSpan);
        const cell = ws.getRow(row).getCell(1);
        cell.value = title;
        cell.font = { name: "Calibri", size: 12, bold: true, color: { argb: WHITE } };
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: NAVY } };
        cell.alignment = { vertical: "middle", horizontal: "left", indent: 1 };
        cell.border = thinBorder;
        ws.getRow(row).height = 28;
        return row + 1;
      }

      function addTableHeaders(ws: ExcelJS.Worksheet, row: number, headers: string[], widths: number[]): number {
        const r = ws.getRow(row);
        headers.forEach((h, i) => {
          const cell = r.getCell(i + 1);
          cell.value = h;
          cell.font = fontWhiteBold;
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: TEAL } };
          cell.alignment = { vertical: "middle", horizontal: i === 0 ? "left" : "center" };
          cell.border = thinBorder;
          ws.getColumn(i + 1).width = Math.max(ws.getColumn(i + 1).width || 0, widths[i]);
        });
        r.height = 22;
        return row + 1;
      }

      function addDataRow(ws: ExcelJS.Worksheet, row: number, values: (string | number)[], isAlt: boolean, pctCols: number[] = []): number {
        const r = ws.getRow(row);
        values.forEach((v, i) => {
          const cell = r.getCell(i + 1);
          cell.value = v;
          cell.font = fontDark;
          cell.fill = isAlt ? { type: "pattern", pattern: "solid", fgColor: { argb: LIGHT_GRAY } } : { type: "pattern", pattern: "solid", fgColor: { argb: WHITE } };
          cell.alignment = { vertical: "middle", horizontal: i === 0 ? "left" : "center" };
          cell.border = thinBorder;
          if (pctCols.includes(i) && typeof v === "number") {
            cell.numFmt = "0.0%";
            cell.value = v / 100;
          }
        });
        r.height = 20;
        return row + 1;
      }

      function addTotalsRow(ws: ExcelJS.Worksheet, row: number, values: (string | number)[], pctCols: number[] = []): number {
        const r = ws.getRow(row);
        values.forEach((v, i) => {
          const cell = r.getCell(i + 1);
          cell.value = v;
          cell.font = fontDarkBold;
          cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "E8E8E8" } };
          cell.alignment = { vertical: "middle", horizontal: i === 0 ? "left" : "center" };
          cell.border = {
            ...thinBorder,
            top: { style: "medium", color: { argb: NAVY } },
          };
          if (pctCols.includes(i) && typeof v === "number") {
            cell.numFmt = "0.0%";
            cell.value = v / 100;
          }
        });
        r.height = 22;
        return row + 1;
      }

      let dRow = 2;

      // Section 1: Systems by Status
      dRow = addSectionTitle(dashboard, dRow, "SYSTEMS BY STATUS", 3);
      dRow = addTableHeaders(dashboard, dRow, ["Status", "Count", "% of Total"], [25, 15, 15]);
      const statusEntries = Object.entries(statusCounts).sort((a, b) => b[1] - a[1]);
      statusEntries.forEach(([status, count], idx) => {
        const pct = totalAssets > 0 ? (count / totalAssets) * 100 : 0;
        dRow = addDataRow(dashboard, dRow, [status, count, pct], idx % 2 === 1, [2]);
      });
      dRow = addTotalsRow(dashboard, dRow, ["Total", totalAssets, 100], [2]);
      dRow += 2;

      // Section 2: Active Assets by OS Family
      dRow = addSectionTitle(dashboard, dRow, "ACTIVE ASSETS BY OS FAMILY", 3);
      dRow = addTableHeaders(dashboard, dRow, ["OS Family", "Count", "% of Active"], [25, 15, 15]);
      const osFamilyEntries = Object.entries(osFamilyCounts).sort((a, b) => b[1] - a[1]);
      osFamilyEntries.forEach(([family, count], idx) => {
        const pct = totalActive > 0 ? (count / totalActive) * 100 : 0;
        dRow = addDataRow(dashboard, dRow, [family, count, pct], idx % 2 === 1, [2]);
      });
      dRow = addTotalsRow(dashboard, dRow, ["Total", totalActive, 100], [2]);
      dRow += 2;

      // Section 3: Active Assets by OS Version (top 25)
      dRow = addSectionTitle(dashboard, dRow, "ACTIVE ASSETS BY OS VERSION (TOP 25)", 4);
      dRow = addTableHeaders(dashboard, dRow, ["Operating System", "OS Family", "Count", "% of Active"], [40, 18, 15, 15]);
      dashboard.getColumn(1).width = 40;
      const osVersionEntries = Object.entries(osVersionCounts).sort((a, b) => b[1].count - a[1].count).slice(0, 25);
      osVersionEntries.forEach(([osName, data], idx) => {
        const pct = totalActive > 0 ? (data.count / totalActive) * 100 : 0;
        dRow = addDataRow(dashboard, dRow, [osName, data.osFamily, data.count, pct], idx % 2 === 1, [3]);
      });
      const osVersionTotal = osVersionEntries.reduce((s, [, d]) => s + d.count, 0);
      const osVersionPct = totalActive > 0 ? (osVersionTotal / totalActive) * 100 : 0;
      dRow = addTotalsRow(dashboard, dRow, ["Total (shown)", "", osVersionTotal, osVersionPct], [3]);
      dRow += 2;

      // Section 4: Assets by Application Owner
      dRow = addSectionTitle(dashboard, dRow, "ASSETS BY APPLICATION OWNER", 5);
      dRow = addTableHeaders(dashboard, dRow, ["Application Owner", "Total Assets", "Active", "Inactive", "Decommissioned"], [30, 15, 15, 15, 18]);
      const appEntries = Object.entries(appOwnerCounts).sort((a, b) => b[1].total - a[1].total).slice(0, 50);
      appEntries.forEach(([owner, data], idx) => {
        dRow = addDataRow(dashboard, dRow, [owner, data.total, data.active, data.inactive, data.decommissioned], idx % 2 === 1);
      });
      const appTotals = appEntries.reduce((acc, [, d]) => ({ total: acc.total + d.total, active: acc.active + d.active, inactive: acc.inactive + d.inactive, decommissioned: acc.decommissioned + d.decommissioned }), { total: 0, active: 0, inactive: 0, decommissioned: 0 });
      dRow = addTotalsRow(dashboard, dRow, ["Total (shown)", appTotals.total, appTotals.active, appTotals.inactive, appTotals.decommissioned]);

      dashboard.views = [{ state: "frozen" as const, ySplit: 1, xSplit: 0 }];

      // ─── Sheet 3: Asset Inventory (Detail) ───
      const detail = wb.addWorksheet("Asset Inventory (Detail)", { properties: { tabColor: { argb: ACCENT } } });
      const detailHeaders = ["Hostname", "IP Address", "OS Family", "Operating System", "Status", "Application Owner", "Location", "EOL Status", "EOS Status"];
      const detailWidths = [30, 18, 14, 32, 18, 28, 25, 22, 22];

      const headerRow = detail.getRow(1);
      detailHeaders.forEach((h, i) => {
        const cell = headerRow.getCell(i + 1);
        cell.value = h;
        cell.font = fontWhiteBold;
        cell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: NAVY } };
        cell.alignment = { vertical: "middle", horizontal: "left" };
        cell.border = thinBorder;
        detail.getColumn(i + 1).width = detailWidths[i];
      });
      headerRow.height = 24;

      assets.forEach((a, idx) => {
        const r = detail.getRow(idx + 2);
        const vals = [a.hostname, a.ipAddress, a.osFamily, a.operatingSystem, a.status, a.applicationOwner, a.location, a.eolStatus, a.eosStatus];
        vals.forEach((v, i) => {
          const cell = r.getCell(i + 1);
          cell.value = v;
          cell.font = fontDark;
          cell.fill = idx % 2 === 1 ? { type: "pattern", pattern: "solid", fgColor: { argb: LIGHT_GRAY } } : { type: "pattern", pattern: "solid", fgColor: { argb: WHITE } };
          cell.alignment = { vertical: "middle", horizontal: "left" };
          cell.border = thinBorder;
        });
        r.height = 18;
      });

      detail.autoFilter = { from: { row: 1, column: 1 }, to: { row: Math.max(assets.length + 1, 2), column: 9 } };
      detail.views = [{ state: "frozen" as const, ySplit: 1, xSplit: 0 }];

      const buf = await wb.xlsx.writeBuffer();

      res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
      res.setHeader("Content-Disposition", `attachment; filename="Asset_Inventory_${tenantId}_${new Date().toISOString().slice(0, 10)}.xlsx"`);
      res.send(Buffer.from(buf));
    } catch (error: any) {
      console.error("Asset inventory Excel export error:", error);
      res.status(error.status || 500).json({ message: error.message || "Failed to export asset inventory" });
    }
  });

  app.get("/api/asset-inventory/:tenantId/summary", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [deviceResult, userResult, ipResult, softwareResult, domainResult, riskResult, anomalyResult] = await Promise.all([
        pool.query(`SELECT COUNT(*)::int as count FROM assets WHERE tenant_id IN (${placeholders})`, tenantIds),
        pool.query(`SELECT COUNT(*)::int as count FROM user_assets WHERE tenant_id IN (${placeholders})`, tenantIds),
        pool.query(`SELECT COUNT(DISTINCT ip_address)::int as count FROM assets WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != ''`, tenantIds),
        pool.query(`SELECT COUNT(*)::int as count FROM (SELECT DISTINCT jsonb_array_elements(software_inventory)->>'name' as sw_name FROM assets WHERE tenant_id IN (${placeholders}) AND software_inventory IS NOT NULL AND jsonb_typeof(software_inventory) = 'array') sub`, tenantIds),
        pool.query(`SELECT COUNT(*)::int as count FROM (SELECT DISTINCT jsonb_array_elements_text(top_sites) as domain FROM user_assets WHERE tenant_id IN (${placeholders}) AND top_sites IS NOT NULL AND jsonb_typeof(top_sites) = 'array') sub`, tenantIds),
        pool.query(`SELECT risk_level, COUNT(*)::int as count FROM risk_scores WHERE tenant_id IN (${placeholders}) GROUP BY risk_level`, tenantIds),
        pool.query(`SELECT COUNT(*)::int as count FROM (SELECT ip_address FROM assets WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != '' AND status = 'active' GROUP BY ip_address HAVING COUNT(*) > 1) sub`, tenantIds),
      ]);

      const riskDistribution: Record<string, number> = {};
      for (const row of riskResult.rows) {
        riskDistribution[row.risk_level] = row.count;
      }

      res.json({
        devices: deviceResult.rows[0]?.count || 0,
        users: userResult.rows[0]?.count || 0,
        ips: ipResult.rows[0]?.count || 0,
        software: softwareResult.rows[0]?.count || 0,
        domains: domainResult.rows[0]?.count || 0,
        anomalies: anomalyResult.rows[0]?.count || 0,
        riskDistribution,
      });
    } catch (error: any) {
      console.error("Asset inventory summary error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/devices", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const page = parseInt(req.query.page as string) || 1;
      const pageSize = Math.min(parseInt(req.query.pageSize as string) || 50, 200);
      const search = (req.query.search as string) || "";
      const riskLevel = req.query.riskLevel as string;
      const os = req.query.os as string;
      const status = req.query.status as string;
      const sortBy = req.query.sortBy as string || "hostname";
      const sortOrder = (req.query.sortOrder as string) === "desc" ? "DESC" : "ASC";

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const params: any[] = [...tenantIds];
      let paramIdx = tenantIds.length;

      let whereClause = `a.tenant_id IN (${placeholders})`;

      if (search) {
        paramIdx++;
        whereClause += ` AND (a.hostname ILIKE $${paramIdx} OR a.ip_address ILIKE $${paramIdx} OR a.user_name ILIKE $${paramIdx})`;
        params.push(`%${search}%`);
      }
      if (riskLevel) {
        paramIdx++;
        whereClause += ` AND COALESCE(r.risk_level, a.risk_level, 'low') = $${paramIdx}`;
        params.push(riskLevel);
      }
      if (os) {
        paramIdx++;
        whereClause += ` AND a.operating_system ILIKE $${paramIdx}`;
        params.push(`%${os}%`);
      }
      if (status) {
        if (status === "decom_planned") {
          whereClause += ` AND a.status != 'decommissioned' AND (a.enrichment_data->>'decommissionStatus' = 'planned' OR a.enrichment_data->>'decommissionStatus' = 'planned_1yr' OR a.enrichment_data->>'decommissionStatus' = 'planned_2yr' OR (a.enrichment_data->>'decommissionTimeline' IS NOT NULL AND a.enrichment_data->>'decommissionTimeline' != '' AND a.enrichment_data->>'decommissionTimeline' != ' '))`;
        } else {
          paramIdx++;
          whereClause += ` AND a.status = $${paramIdx}`;
          params.push(status);
        }
      }
      const criticality = req.query.criticality as string;
      if (criticality && criticality !== 'all') {
        if (criticality === 'unclassified') {
          whereClause += ` AND (a.criticality IS NULL OR a.criticality = 'unclassified')`;
        } else {
          paramIdx++;
          whereClause += ` AND a.criticality = $${paramIdx}`;
          params.push(criticality);
        }
      }

      const allowedSorts: Record<string, string> = {
        hostname: "a.hostname",
        ip_address: "a.ip_address",
        operating_system: "a.operating_system",
        risk_score: "COALESCE(r.overall_score, a.risk_score, 0)",
        status: "a.status",
        last_seen: "a.last_seen",
        incident_count: "a.incident_count",
        vulnerability_count: "a.vulnerability_count",
        cis_score: "a.cis_score",
      };
      const sortColumn = allowedSorts[sortBy] || "a.hostname";

      const countQuery = `SELECT COUNT(*)::int as total FROM assets a LEFT JOIN risk_scores r ON r.tenant_id = a.tenant_id AND r.entity_type = 'asset' AND r.entity_identifier = a.hostname WHERE ${whereClause}`;
      const countResult = await pool.query(countQuery, params);
      const total = countResult.rows[0]?.total || 0;

      const offset = (page - 1) * pageSize;
      const dataQuery = `
        SELECT a.id, a.hostname, a.ip_address, a.operating_system, a.user_name, a.status,
               a.last_seen, a.incident_count, a.vulnerability_count, a.endpoint_type,
               a.agent_version, a.endpoint_group, a.cloud_provider, a.cloud_region, a.tags,
               a.content_version, a.prevention_policy, a.extensions_policy, a.device_health,
               a.processor, a.total_physical_memory, a.storage_info, a.system_model,
               a.system_manufacturer, a.bios_serial_number, a.software_inventory,
               a.cis_score, a.cis_benchmark, a.criticality, a.primary_user_email,
               a.risk_level as asset_risk_level, a.risk_score as asset_risk_score,
               r.overall_score as risk_score, r.risk_level, r.pillar_scores, r.risk_breakdown,
               r.score_delta, r.previous_score
        FROM assets a
        LEFT JOIN risk_scores r ON r.tenant_id = a.tenant_id AND r.entity_type = 'asset' AND r.entity_identifier = a.hostname
        WHERE ${whereClause}
        ORDER BY ${sortColumn} ${sortOrder}
        LIMIT $${paramIdx + 1} OFFSET $${paramIdx + 2}
      `;
      params.push(pageSize, offset);

      const dataResult = await pool.query(dataQuery, params);

      const { computeProfileCompleteness } = await import("./asset-profile-enricher");

      res.json({
        data: dataResult.rows.map(row => ({
          id: row.id,
          hostname: row.hostname,
          ipAddress: row.ip_address,
          operatingSystem: row.operating_system,
          user: row.user_name,
          status: row.status,
          lastSeen: row.last_seen,
          incidentCount: row.incident_count || 0,
          vulnerabilityCount: row.vulnerability_count || 0,
          endpointType: row.endpoint_type,
          agentVersion: row.agent_version,
          contentVersion: row.content_version,
          preventionPolicy: row.prevention_policy,
          extensionsPolicy: row.extensions_policy,
          deviceHealth: row.device_health,
          processor: row.processor,
          totalPhysicalMemory: row.total_physical_memory,
          storageInfo: row.storage_info,
          systemModel: row.system_model,
          systemManufacturer: row.system_manufacturer,
          biosSerialNumber: row.bios_serial_number,
          softwareInventory: row.software_inventory,
          criticality: row.criticality ?? null,
          cisScore: row.cis_score ?? null,
          cisBenchmark: row.cis_benchmark ?? null,
          primaryUserEmail: row.primary_user_email ?? null,
          endpointGroup: row.endpoint_group,
          cloudProvider: row.cloud_provider,
          cloudRegion: row.cloud_region,
          tags: row.tags,
          riskScore: row.risk_score ?? row.asset_risk_score ?? 0,
          riskLevel: row.risk_level ?? row.asset_risk_level ?? "low",
          pillarScores: row.pillar_scores,
          riskBreakdown: row.risk_breakdown,
          scoreDelta: row.score_delta,
          previousScore: row.previous_score,
          profileCompleteness: computeProfileCompleteness(row),
        })),
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
      });
    } catch (error: any) {
      console.error("Asset inventory devices error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/users", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const page = parseInt(req.query.page as string) || 1;
      const pageSize = Math.min(parseInt(req.query.pageSize as string) || 50, 200);
      const search = (req.query.search as string) || "";
      const riskLevel = req.query.riskLevel as string;
      const department = req.query.department as string;
      const accountType = req.query.accountType as string;
      const sortBy = req.query.sortBy as string || "user_name";
      const sortOrder = (req.query.sortOrder as string) === "desc" ? "DESC" : "ASC";

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const params: any[] = [...tenantIds];
      let paramIdx = tenantIds.length;

      let whereClause = `u.tenant_id IN (${placeholders})`;

      if (search) {
        paramIdx++;
        whereClause += ` AND (u.user_name ILIKE $${paramIdx} OR u.email ILIKE $${paramIdx} OR u.department ILIKE $${paramIdx})`;
        params.push(`%${search}%`);
      }
      if (riskLevel) {
        paramIdx++;
        whereClause += ` AND COALESCE(r.risk_level, u.risk_level, 'low') = $${paramIdx}`;
        params.push(riskLevel);
      }
      if (department) {
        paramIdx++;
        whereClause += ` AND u.department ILIKE $${paramIdx}`;
        params.push(`%${department}%`);
      }

      const whereClauseNoType = whereClause;
      const paramsNoType = [...params];
      const paramIdxNoType = paramIdx;

      if (accountType) {
        whereClause += ` AND (COALESCE(u.account_type, 'Unknown') = $${paramIdx + 1} OR COALESCE(u.account_type, 'Unknown') IN ('Unknown', 'Domain'))`;
        paramIdx++;
        params.push(accountType);
      }

      const allowedSorts: Record<string, string> = {
        user_name: "u.user_name",
        email: "u.email",
        department: "u.department",
        risk_score: "COALESCE(r.overall_score, u.risk_score, 0)",
        total_requests: "u.total_requests",
        last_activity: "u.last_activity",
      };
      const sortColumn = allowedSorts[sortBy] || "u.user_name";

      const countQuery = `SELECT COUNT(*)::int as total FROM user_assets u LEFT JOIN risk_scores r ON r.tenant_id = u.tenant_id AND r.entity_type = 'user' AND r.entity_identifier = u.user_name WHERE ${whereClause}`;
      const countResult = await pool.query(countQuery, params);
      const total = countResult.rows[0]?.total || 0;

      const offset = (page - 1) * pageSize;
      const dataQuery = `
        SELECT u.id, u.user_name, u.email, u.department, u.title, u.user_status,
               u.total_requests, u.allowed_requests, u.denied_requests, u.isolated_requests,
               u.sites_visited, u.total_bytes_mb, u.downloaded_bytes_mb, u.uploaded_bytes_mb,
               u.last_activity, u.risk_level as user_risk_level, u.risk_score as user_risk_score,
               u.url_categories, u.application_names,
               u.top_sites, u.linked_asset_ids,
               COALESCE(u.account_type, 'Unknown') as account_type,
               r.overall_score as risk_score, r.risk_level, r.pillar_scores, r.risk_breakdown,
               r.score_delta, r.previous_score,
               (SELECT COUNT(*)::int FROM assets a WHERE a.tenant_id = u.tenant_id AND a.user_name = u.user_name) as device_count
        FROM user_assets u
        LEFT JOIN risk_scores r ON r.tenant_id = u.tenant_id AND r.entity_type = 'user' AND r.entity_identifier = u.user_name
        WHERE ${whereClause}
        ORDER BY ${sortColumn} ${sortOrder}
        LIMIT $${paramIdx + 1} OFFSET $${paramIdx + 2}
      `;
      params.push(pageSize, offset);

      const dataResult = await pool.query(dataQuery, params);

      const { domainPrefixes, deviceHostnames } = await discoverDomainPrefixes(tenantIds, placeholders);
      if (domainPrefixes.size > 0) {
        console.log(`[DomainDiscovery] Tenant ${tenantId}: discovered domains: ${Array.from(domainPrefixes).join(", ")}`);
      }

      let classifiedTotal = total;
      if (accountType) {
        try {
          const typeCountResult = await pool.query(
            `SELECT u.user_name, COALESCE(u.account_type, 'Unknown') as account_type FROM user_assets u WHERE ${whereClauseNoType}`,
            paramsNoType
          );
          let cnt = 0;
          for (const row of typeCountResult.rows) {
            let acType = row.account_type || "Unknown";
            if (row.user_name) {
              if (acType === "Unknown") {
                acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
              } else if (acType === "Domain" && row.user_name.includes("\\")) {
                const prefix = row.user_name.split("\\")[0].toLowerCase();
                if (deviceHostnames.has(prefix) || (/\d/.test(prefix) && !domainPrefixes.has(prefix)) || (prefix.includes("-") && !domainPrefixes.has(prefix))) {
                  acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
                }
              }
            }
            if (acType === accountType) cnt++;
          }
          classifiedTotal = cnt;
        } catch (_e) {}
      }

      const classifiedRows = dataResult.rows.map(row => {
        let acType = row.account_type || "Unknown";
        if (row.user_name) {
          if (acType === "Unknown") {
            acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
          } else if (acType === "Domain" && row.user_name.includes("\\")) {
            const prefix = row.user_name.split("\\")[0].toLowerCase();
            if (deviceHostnames.has(prefix) || (/\d/.test(prefix) && !domainPrefixes.has(prefix)) || (prefix.includes("-") && !domainPrefixes.has(prefix))) {
              acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
            }
          }
        }
        return { ...row, account_type: acType };
      }).filter(row => {
        if (!accountType) return true;
        return row.account_type === accountType;
      });

      (async () => {
        try {
          const reclassifyUsers = await pool.query(
            `SELECT id, user_name, account_type FROM user_assets WHERE tenant_id IN (${placeholders}) AND (account_type IS NULL OR account_type = 'Unknown' OR account_type = 'Domain')`,
            tenantIds
          );
          if (reclassifyUsers.rows.length > 0) {
            const updates: { id: number; acType: string }[] = [];
            for (const u of reclassifyUsers.rows) {
              const acType = classifyUserAccountType(u.user_name, domainPrefixes, deviceHostnames);
              if (u.account_type === 'Domain') {
                if (u.user_name && u.user_name.includes('\\')) {
                  const prefix = u.user_name.split('\\')[0].toLowerCase();
                  const isDevice = deviceHostnames.has(prefix);
                  const hasDigits = /\d/.test(prefix);
                  if (isDevice || (hasDigits && !domainPrefixes.has(prefix)) || (prefix.includes("-") && !domainPrefixes.has(prefix))) {
                    updates.push({ id: u.id, acType });
                  }
                }
              } else if (acType !== "Unknown") {
                updates.push({ id: u.id, acType });
              }
            }
            for (const upd of updates) {
              await pool.query(`UPDATE user_assets SET account_type = $1 WHERE id = $2`, [upd.acType, upd.id]);
            }
            if (updates.length > 0) {
              console.log(`[UserClassification] Reclassified ${updates.length}/${reclassifyUsers.rows.length} users for tenant ${tenantId} (domains: ${Array.from(domainPrefixes).join(", ")})`);
            }
          }
        } catch (err: any) {
          console.error("[UserClassification] Background classification error:", err.message);
        }
      })();

      res.json({
        data: classifiedRows.map(row => ({
          id: row.id,
          userName: row.user_name,
          email: row.email,
          department: row.department,
          title: row.title,
          status: row.user_status,
          totalRequests: row.total_requests || 0,
          allowedRequests: row.allowed_requests || 0,
          deniedRequests: row.denied_requests || 0,
          isolatedRequests: row.isolated_requests || 0,
          sitesVisited: row.sites_visited || 0,
          totalBytesMB: row.total_bytes_mb || 0,
          downloadedBytesMB: row.downloaded_bytes_mb || 0,
          uploadedBytesMB: row.uploaded_bytes_mb || 0,
          lastActivity: row.last_activity,
          riskScore: row.risk_score ?? row.user_risk_score ?? 0,
          riskLevel: row.risk_level ?? row.user_risk_level ?? "low",
          pillarScores: row.pillar_scores,
          riskBreakdown: row.risk_breakdown,
          scoreDelta: row.score_delta,
          previousScore: row.previous_score,
          deviceCount: row.device_count || 0,
          urlCategories: row.url_categories,
          applicationNames: row.application_names,
          topSites: row.top_sites,
          linkedAssetIds: row.linked_asset_ids,
          accountType: row.account_type || "Unknown",
        })),
        total: accountType ? classifiedTotal : total,
        page,
        pageSize,
        totalPages: accountType ? Math.ceil(classifiedTotal / pageSize) : Math.ceil(total / pageSize),
      });
    } catch (error: any) {
      console.error("Asset inventory users error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/asset-inventory/:tenantId/classify-users", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const { domainPrefixes, deviceHostnames } = await discoverDomainPrefixes(tenantIds, placeholders);
      console.log(`[ClassifyUsers] Tenant ${tenantId}: discovered domains: ${Array.from(domainPrefixes).join(", ") || "(none)"}, device hostnames: ${deviceHostnames.size}`);

      const users = await pool.query(
        `SELECT id, user_name, account_type FROM user_assets WHERE tenant_id IN (${placeholders})`,
        tenantIds
      );

      let updated = 0;
      for (const u of users.rows) {
        const acType = classifyUserAccountType(u.user_name, domainPrefixes, deviceHostnames);
        if (acType !== "Unknown" && acType !== u.account_type) {
          await pool.query(`UPDATE user_assets SET account_type = $1 WHERE id = $2`, [acType, u.id]);
          updated++;
        }
      }
      res.json({ total: users.rows.length, classified: updated, discoveredDomains: Array.from(domainPrefixes), deviceHostnames: deviceHostnames.size });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/asset-inventory/:tenantId/sync-users", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const usersFromAssets = await pool.query(`
        SELECT a.tenant_id, a.user_name,
               COUNT(*)::int as device_count,
               array_agg(DISTINCT a.id) as asset_ids,
               MAX(COALESCE(a.risk_score, 0))::int as max_risk_score,
               CASE
                 WHEN MAX(COALESCE(a.risk_score, 0)) >= 80 THEN 'critical'
                 WHEN MAX(COALESCE(a.risk_score, 0)) >= 60 THEN 'high'
                 WHEN MAX(COALESCE(a.risk_score, 0)) >= 40 THEN 'medium'
                 ELSE 'low'
               END as risk_level,
               MAX(a.endpoint_group) as department,
               MAX(a.last_seen) as last_activity
        FROM assets a
        WHERE a.tenant_id IN (${placeholders})
          AND a.user_name IS NOT NULL AND a.user_name != ''
        GROUP BY a.tenant_id, a.user_name
      `, tenantIds);

      let synced = 0;
      for (const row of usersFromAssets.rows) {
        const existing = await pool.query(
          `SELECT id FROM user_assets WHERE tenant_id = $1 AND user_name = $2`,
          [row.tenant_id, row.user_name]
        );
        if (existing.rows.length === 0) {
          await pool.query(`
            INSERT INTO user_assets (tenant_id, user_name, department, risk_score, risk_level, linked_asset_ids, last_activity, user_status)
            VALUES ($1, $2, $3, $4, $5, $6, $7, 'active')
          `, [row.tenant_id, row.user_name, row.department, row.max_risk_score, row.risk_level, JSON.stringify(row.asset_ids), row.last_activity]);
          synced++;
        } else {
          await pool.query(`
            UPDATE user_assets SET risk_score = $1, risk_level = $2, linked_asset_ids = $3, last_activity = $4, department = COALESCE(department, $5), updated_at = NOW()
            WHERE tenant_id = $6 AND user_name = $7
          `, [row.max_risk_score, row.risk_level, JSON.stringify(row.asset_ids), row.last_activity, row.department, row.tenant_id, row.user_name]);
          synced++;
        }
      }

      res.json({ total: usersFromAssets.rows.length, synced });
    } catch (error: any) {
      console.error("Sync users error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/user-type-distribution", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const { domainPrefixes, deviceHostnames } = await discoverDomainPrefixes(tenantIds, placeholders);

      const allUsers = await pool.query(
        `SELECT user_name, COALESCE(account_type, 'Unknown') as account_type FROM user_assets WHERE tenant_id IN (${placeholders})`,
        tenantIds
      );

      const distribution: Record<string, number> = {};
      for (const row of allUsers.rows) {
        let acType = row.account_type || "Unknown";
        if (row.user_name) {
          if (acType === "Unknown") {
            acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
          } else if (acType === "Domain" && row.user_name.includes("\\")) {
            const prefix = row.user_name.split("\\")[0].toLowerCase();
            if (deviceHostnames.has(prefix) || (/\d/.test(prefix) && !domainPrefixes.has(prefix)) || (prefix.includes("-") && !domainPrefixes.has(prefix))) {
              acType = classifyUserAccountType(row.user_name, domainPrefixes, deviceHostnames);
            }
          }
        }
        distribution[acType] = (distribution[acType] || 0) + 1;
      }
      res.json(distribution);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/ips", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const page = parseInt(req.query.page as string) || 1;
      const pageSize = Math.min(parseInt(req.query.pageSize as string) || 50, 200);
      const search = (req.query.search as string) || "";
      const anomalyOnly = req.query.anomalyOnly === "true";
      const sortBy = req.query.sortBy as string || "ip_address";
      const sortOrder = (req.query.sortOrder as string) === "desc" ? "DESC" : "ASC";

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const params: any[] = [...tenantIds];
      let paramIdx = tenantIds.length;

      let havingClause = "";
      if (anomalyOnly) {
        havingClause = "HAVING COUNT(*) FILTER (WHERE a.status = 'active') > 1";
      }

      let searchClause = "";
      if (search) {
        paramIdx++;
        searchClause = `AND a.ip_address ILIKE $${paramIdx}`;
        params.push(`%${search}%`);
      }

      const allowedSorts: Record<string, string> = {
        ip_address: "ip_address",
        device_count: "device_count",
        user_count: "user_count",
        last_seen: "last_seen",
      };
      const sortColumn = allowedSorts[sortBy] || "ip_address";

      const baseQuery = `
        SELECT a.ip_address,
               COUNT(DISTINCT a.id)::int as device_count,
               COUNT(DISTINCT a.user_name) FILTER (WHERE a.user_name IS NOT NULL AND a.user_name != '')::int as user_count,
               MAX(a.last_seen) as last_seen,
               CASE
                 WHEN a.ip_address ~ '^(10\\.|172\\.(1[6-9]|2[0-9]|3[01])\\.|192\\.168\\.)' THEN 'private'
                 WHEN a.ip_address ~ '^(127\\.|169\\.254\\.)' THEN 'loopback'
                 ELSE 'public'
               END as ip_type,
               COUNT(*) FILTER (WHERE a.status = 'active')::int as active_device_count,
               CASE WHEN COUNT(*) FILTER (WHERE a.status = 'active') > 1 THEN true ELSE false END as anomaly_flag,
               array_agg(DISTINCT a.hostname) FILTER (WHERE a.hostname IS NOT NULL) as hostnames
        FROM assets a
        WHERE a.tenant_id IN (${placeholders}) AND a.ip_address IS NOT NULL AND a.ip_address != '' ${searchClause}
        GROUP BY a.ip_address
        ${havingClause}
      `;

      const countQuery = `SELECT COUNT(*)::int as total FROM (${baseQuery}) sub`;
      const countResult = await pool.query(countQuery, params);
      const total = countResult.rows[0]?.total || 0;

      const offset = (page - 1) * pageSize;
      paramIdx++;
      const limitParam = paramIdx;
      paramIdx++;
      const offsetParam = paramIdx;
      params.push(pageSize, offset);

      const dataQuery = `SELECT * FROM (${baseQuery}) sub ORDER BY ${sortColumn} ${sortOrder} LIMIT $${limitParam} OFFSET $${offsetParam}`;
      const dataResult = await pool.query(dataQuery, params);

      res.json({
        data: dataResult.rows.map(row => ({
          ipAddress: row.ip_address,
          ipType: row.ip_type,
          deviceCount: row.device_count,
          userCount: row.user_count,
          lastSeen: row.last_seen,
          activeDeviceCount: row.active_device_count,
          anomalyFlag: row.anomaly_flag,
          hostnames: row.hostnames || [],
        })),
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
      });
    } catch (error: any) {
      console.error("Asset inventory IPs error:", error);
      res.status(500).json({ message: error.message });
    }
  });

