  async function discoverDomainPrefixes(tenantIds: number[], placeholders: string): Promise<{ domainPrefixes: Set<string>; deviceHostnames: Set<string> }> {
    const domainPrefixes = new Set<string>();
    const deviceHostnames = new Set<string>();
    try {
      const [prefixResult, hostnameResult] = await Promise.all([
        pool.query(`
          SELECT LOWER(split_part(user_name, '\\', 1)) as prefix,
                 COUNT(DISTINCT LOWER(split_part(user_name, '\\', 2))) as unique_users
          FROM user_assets
          WHERE tenant_id IN (${placeholders})
            AND user_name LIKE '%\\%'
            AND split_part(user_name, '\\', 2) != ''
          GROUP BY LOWER(split_part(user_name, '\\', 1))
          ORDER BY unique_users DESC
        `, tenantIds),
        pool.query(`SELECT DISTINCT LOWER(hostname) as hostname FROM assets WHERE tenant_id IN (${placeholders}) AND hostname IS NOT NULL AND hostname != ''`, tenantIds),
      ]);

      for (const row of hostnameResult.rows) {
        if (row.hostname) deviceHostnames.add(row.hostname);
      }

      const totalUniqueUsers = prefixResult.rows.reduce((sum: number, r: any) => sum + parseInt(r.unique_users), 0);
      const tenPercentThreshold = Math.max(3, Math.floor(totalUniqueUsers * 0.10));

      for (const row of prefixResult.rows) {
        const prefix = row.prefix;
        const uniqueUsers = parseInt(row.unique_users);
        const hasDigits = /\d/.test(prefix);
        const hasHyphen = prefix.includes("-");
        const isMachinePattern = /^(desktop|laptop|pc|win|srv|wks|vm|node|host|workstation|nb|lt|dt)-/i.test(prefix);

        if (deviceHostnames.has(prefix)) continue;

        if (uniqueUsers <= 10 && (hasDigits || isMachinePattern || hasHyphen)) {
          continue;
        }

        if (uniqueUsers >= tenPercentThreshold && !hasDigits && !hasHyphen) {
          domainPrefixes.add(prefix);
        }
      }

      if (domainPrefixes.size === 0 && prefixResult.rows.length > 0) {
        const topPrefix = prefixResult.rows[0];
        if (parseInt(topPrefix.unique_users) >= 3 && !/\d/.test(topPrefix.prefix) && !topPrefix.prefix.includes("-") && !deviceHostnames.has(topPrefix.prefix)) {
          domainPrefixes.add(topPrefix.prefix);
        }
      }

      console.log(`[DomainDiscovery] Total unique users: ${totalUniqueUsers}, 10% threshold: ${tenPercentThreshold}, domains: ${Array.from(domainPrefixes).join(", ") || "(none)"}, device hostnames: ${deviceHostnames.size}`);
    } catch (err: any) {
      console.error("[DomainDiscovery] Error:", err.message);
    }
    return { domainPrefixes, deviceHostnames };
  }

  function classifyUserAccountType(userName: string, domainPrefixes?: Set<string>, deviceHostnames?: Set<string>): string {
    if (!userName) return "Unknown";
    const u = userName.toLowerCase().trim();
    const systemBuiltIn = [
      "system", "local service", "network service", "local system",
      "nt authority", "defaultaccount", "wdagutilityaccount",
      "umfd-", "sshd", "root", "daemon", "nobody", "www-data",
      "systemd", "dbus", "ntp", "postfix", "mysql", "postgres",
    ];
    if (systemBuiltIn.some(s => u === s || u.startsWith(`${s}\\`) || u.endsWith(`\\${s}`) || u.includes(`\\${s}`))) return "System Built-in";
    if (/^(nt authority|nt service|window manager|font driver host)/i.test(u)) return "System Built-in";
    if (/^(svc[_-]|service[_-]|srvc[_-]|_svc|sql_|iis_|mss_|app_|web_|api_)/i.test(u) || u.includes("$")) return "Service";
    if (/(guest|visitor|temp_user|temporary)/i.test(u)) return "Guest";

    if (u.includes("\\")) {
      const parts = u.split("\\");
      const prefix = parts[0];
      const suffix = parts.slice(1).join("\\");

      if (/^(svc[_-]|service[_-]|srvc[_-]|_svc|sql_|iis_|mss_|app_|web_|api_)/i.test(suffix) || suffix.endsWith("$")) return "Service";

      const isKnownDevice = deviceHostnames ? deviceHostnames.has(prefix) : false;

      if (isKnownDevice) {
        if (/^(admin|administrator)$/i.test(suffix)) return "Local Admin";
        return "Local User";
      }

      if (/^(admin|administrator)$/i.test(suffix)) {
        if (domainPrefixes && domainPrefixes.has(prefix)) return "Domain";
        return "Local Admin";
      }

      if (domainPrefixes && domainPrefixes.size > 0) {
        if (domainPrefixes.has(prefix)) return "Domain";
        return "Local User";
      }

      const hasDigits = /\d/.test(prefix);
      const hasHyphen = prefix.includes("-");
      const isMachinePattern = /^(desktop|laptop|pc|win|srv|wks|vm|node|host|workstation|nb|lt|dt)-/i.test(prefix);
      if (hasDigits || isMachinePattern || hasHyphen) return "Local User";

      if (!hasDigits && prefix.length >= 3 && prefix.length <= 15 && /^[a-z]+$/i.test(prefix)) return "Domain";

      return "Local User";
    }

    if (u.includes("@")) {
      if (/@(gmail|yahoo|hotmail|outlook)\./i.test(u)) return "Cloud";
      return "Domain";
    }

    if (/^[a-z]{2,4}\d{3,}/i.test(u)) return "Local User";
    if (/^(admin|administrator)$/i.test(u)) return "Local Admin";
    return "Domain";
  }

  function classifySoftware(name: string): { category: string; vendor: string } {
    for (const entry of SOFTWARE_CATEGORIES) {
      if (entry.pattern.test(name)) {
        return { category: entry.category, vendor: entry.vendor };
      }
    }
    return { category: "Unknown", vendor: "Unknown" };
  }

