  function lookupAppCategory(domain: string): string {
    const lower = domain.toLowerCase().trim();
    if (KNOWN_APP_CATEGORIES[lower]) return KNOWN_APP_CATEGORIES[lower];
    for (const [key, category] of Object.entries(KNOWN_APP_CATEGORIES)) {
      if (lower.includes(key) || key.includes(lower)) return category;
    }
    return "";
  }

  app.get("/api/asset-inventory/:tenantId/domains", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const page = parseInt(req.query.page as string) || 1;
      const pageSize = Math.min(parseInt(req.query.pageSize as string) || 50, 200);
      const search = (req.query.search as string) || "";
      const sortBy = req.query.sortBy as string || "user_count";
      const sortOrder = (req.query.sortOrder as string) === "asc" ? "ASC" : "DESC";

      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");
      const params: any[] = [...tenantIds];
      let paramIdx = tenantIds.length;

      let searchClause = "";
      if (search) {
        paramIdx++;
        searchClause = `AND domain ILIKE $${paramIdx}`;
        params.push(`%${search}%`);
      }

      const allowedSorts: Record<string, string> = {
        domain: "domain",
        user_count: "user_count",
        total_requests: "total_requests",
      };
      const sortColumn = allowedSorts[sortBy] || "user_count";

      const baseQuery = `
        SELECT
          domain,
          COUNT(DISTINCT u.id)::int as user_count,
          MAX(c.service_category) as cloud_risk_category,
          SUM(COALESCE(u.total_requests, 0))::int as total_requests
        FROM user_assets u,
             jsonb_array_elements_text(u.top_sites) as domain
        LEFT JOIN cloud_app_risk_scores c
          ON LOWER(c.app_name) = LOWER(domain)
          AND c.tenant_id IN (${placeholders})
        WHERE u.tenant_id IN (${placeholders})
          AND u.top_sites IS NOT NULL
          AND jsonb_typeof(u.top_sites) = 'array'
          ${searchClause}
        GROUP BY domain
      `;

      const countQuery = `SELECT COUNT(*)::int as total FROM (${baseQuery}) sub`;
      const countParams = [...params];
      const countResult = await pool.query(countQuery, countParams);
      const total = countResult.rows[0]?.total || 0;

      const offset = (page - 1) * pageSize;
      paramIdx++;
      const limitParam = paramIdx;
      paramIdx++;
      const offsetParam = paramIdx;
      params.push(pageSize, offset);

      const dataQuery = `SELECT * FROM (${baseQuery}) sub ORDER BY ${sortColumn} ${sortOrder} LIMIT $${limitParam} OFFSET $${offsetParam}`;
      const dataResult = await pool.query(dataQuery, params);

      res.json({
        data: dataResult.rows.map(row => {
          const cloudCategory = row.cloud_risk_category || "";
          const ruleCategory = lookupAppCategory(row.domain);
          const finalCategory = cloudCategory || ruleCategory || "Unknown";
          return {
            domain: row.domain,
            userCount: row.user_count,
            category: finalCategory,
            totalRequests: row.total_requests,
          };
        }),
        total,
        page,
        pageSize,
        totalPages: Math.ceil(total / pageSize),
      });
    } catch (error: any) {
      console.error("Asset inventory domains error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/correlations", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const entityType = req.query.entityType as string;
      const entityId = req.query.entityId as string;

      if (!entityType || !entityId) {
        return res.status(400).json({ message: "entityType and entityId are required" });
      }

      const result: any = { entityType, entityId, relatedDevices: [], relatedUsers: [], relatedIPs: [], relatedSoftware: [] };

      if (entityType === "device") {
        const deviceResult = await pool.query(
          `SELECT id, hostname, ip_address, user_name, operating_system, status, last_seen, software_inventory
           FROM assets WHERE tenant_id = $1 AND (id::text = $2 OR hostname = $2)`,
          [tenantId, entityId]
        );
        if (deviceResult.rows.length > 0) {
          const device = deviceResult.rows[0];
          result.device = { hostname: device.hostname, ipAddress: device.ip_address, user: device.user_name, os: device.operating_system, status: device.status, lastSeen: device.last_seen };

          if (device.ip_address) {
            const ipDevices = await pool.query(
              `SELECT id, hostname, user_name, status, last_seen FROM assets WHERE tenant_id = $1 AND ip_address = $2 AND id != $3`,
              [tenantId, device.ip_address, device.id]
            );
            result.relatedDevices = ipDevices.rows.map(r => ({ id: r.id, hostname: r.hostname, user: r.user_name, status: r.status, lastSeen: r.last_seen, relation: "shared_ip" }));
          }

          if (device.user_name) {
            const userResult = await pool.query(
              `SELECT id, user_name, email, department, risk_score, last_activity FROM user_assets WHERE tenant_id = $1 AND user_name = $2`,
              [tenantId, device.user_name]
            );
            result.relatedUsers = userResult.rows.map(r => ({ id: r.id, userName: r.user_name, email: r.email, department: r.department, riskScore: r.risk_score, lastActivity: r.last_activity }));
          }

          if (device.software_inventory && Array.isArray(device.software_inventory)) {
            result.relatedSoftware = device.software_inventory.slice(0, 50).map((sw: any) => ({ name: sw.name, category: sw.category, source: sw.source }));
          }

          if (device.ip_address) {
            result.relatedIPs = [{ ipAddress: device.ip_address, relation: "primary" }];
          }
        }
      } else if (entityType === "user") {
        const userResult = await pool.query(
          `SELECT id, user_name, email, department, risk_score, last_activity, top_sites FROM user_assets WHERE tenant_id = $1 AND (id::text = $2 OR user_name = $2)`,
          [tenantId, entityId]
        );
        if (userResult.rows.length > 0) {
          const user = userResult.rows[0];
          result.user = { userName: user.user_name, email: user.email, department: user.department, riskScore: user.risk_score, lastActivity: user.last_activity };

          const devices = await pool.query(
            `SELECT id, hostname, ip_address, operating_system, status, last_seen FROM assets WHERE tenant_id = $1 AND user_name = $2`,
            [tenantId, user.user_name]
          );
          result.relatedDevices = devices.rows.map(r => ({ id: r.id, hostname: r.hostname, ipAddress: r.ip_address, os: r.operating_system, status: r.status, lastSeen: r.last_seen }));
          result.relatedIPs = devices.rows.filter(r => r.ip_address).map(r => ({ ipAddress: r.ip_address, hostname: r.hostname }));
        }
      } else if (entityType === "ip") {
        const devices = await pool.query(
          `SELECT id, hostname, user_name, operating_system, status, last_seen FROM assets WHERE tenant_id = $1 AND ip_address = $2`,
          [tenantId, entityId]
        );
        result.relatedDevices = devices.rows.map(r => ({ id: r.id, hostname: r.hostname, user: r.user_name, os: r.operating_system, status: r.status, lastSeen: r.last_seen }));

        const userNames = [...new Set(devices.rows.map(r => r.user_name).filter(Boolean))];
        if (userNames.length > 0) {
          const usersPlaceholders = userNames.map((_, i) => `$${i + 2}`).join(",");
          const users = await pool.query(
            `SELECT id, user_name, email, department, risk_score FROM user_assets WHERE tenant_id = $1 AND user_name IN (${usersPlaceholders})`,
            [tenantId, ...userNames]
          );
          result.relatedUsers = users.rows.map(r => ({ id: r.id, userName: r.user_name, email: r.email, department: r.department, riskScore: r.risk_score }));
        }
      } else if (entityType === "software") {
        const devices = await pool.query(
          `SELECT a.id, a.hostname, a.ip_address, a.user_name, a.status, a.last_seen
           FROM assets a
           WHERE a.tenant_id = $1
             AND a.software_inventory IS NOT NULL
             AND jsonb_typeof(a.software_inventory) = 'array'
             AND EXISTS (SELECT 1 FROM jsonb_array_elements(a.software_inventory) sw WHERE sw->>'name' = $2)`,
          [tenantId, entityId]
        );
        result.relatedDevices = devices.rows.map(r => ({ id: r.id, hostname: r.hostname, ipAddress: r.ip_address, user: r.user_name, status: r.status, lastSeen: r.last_seen }));
      }

      res.json(result);
    } catch (error: any) {
      if (error.status === 403) return res.status(403).json({ message: error.message });
      console.error("Asset inventory correlations error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/anomalies", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [ipAnomalies, userAnomalies] = await Promise.all([
        pool.query(`
          SELECT ip_address,
                 COUNT(*)::int as device_count,
                 array_agg(DISTINCT hostname) as hostnames,
                 array_agg(DISTINCT user_name) FILTER (WHERE user_name IS NOT NULL) as users,
                 MIN(last_seen) as first_seen,
                 MAX(last_seen) as last_seen
          FROM assets
          WHERE tenant_id IN (${placeholders})
            AND ip_address IS NOT NULL AND ip_address != ''
            AND status = 'active'
          GROUP BY ip_address
          HAVING COUNT(*) > 1
          ORDER BY COUNT(*) DESC
          LIMIT 100
        `, tenantIds),
        pool.query(`
          SELECT a.user_name,
                 COUNT(DISTINCT a.id)::int as device_count,
                 array_agg(DISTINCT a.hostname) as hostnames,
                 array_agg(DISTINCT a.ip_address) FILTER (WHERE a.ip_address IS NOT NULL) as ips,
                 MIN(a.last_seen) as first_seen,
                 MAX(a.last_seen) as last_seen
          FROM assets a
          WHERE a.tenant_id IN (${placeholders})
            AND a.user_name IS NOT NULL AND a.user_name != ''
            AND a.status = 'active'
          GROUP BY a.user_name
          HAVING COUNT(DISTINCT a.id) > 3
          ORDER BY COUNT(DISTINCT a.id) DESC
          LIMIT 100
        `, tenantIds),
      ]);

      const anomalies = [
        ...ipAnomalies.rows.map(row => ({
          type: "shared_ip" as const,
          severity: row.device_count > 4 ? "high" : row.device_count > 2 ? "medium" : "low",
          description: `IP ${row.ip_address} is assigned to ${row.device_count} active devices`,
          ipAddress: row.ip_address,
          deviceCount: row.device_count,
          entities: {
            hostnames: row.hostnames || [],
            users: row.users || [],
          },
          firstSeen: row.first_seen,
          lastSeen: row.last_seen,
        })),
        ...userAnomalies.rows.map(row => ({
          type: "multi_device_user" as const,
          severity: row.device_count > 6 ? "high" : row.device_count > 4 ? "medium" : "low",
          description: `User ${row.user_name} is active on ${row.device_count} devices`,
          userName: row.user_name,
          deviceCount: row.device_count,
          entities: {
            hostnames: row.hostnames || [],
            ips: row.ips || [],
          },
          firstSeen: row.first_seen,
          lastSeen: row.last_seen,
        })),
      ];

      anomalies.sort((a, b) => {
        const severityOrder: Record<string, number> = { high: 0, medium: 1, low: 2 };
        return (severityOrder[a.severity] ?? 2) - (severityOrder[b.severity] ?? 2);
      });

      res.json({
        anomalies,
        total: anomalies.length,
        summary: {
          sharedIPs: ipAnomalies.rows.length,
          multiDeviceUsers: userAnomalies.rows.length,
          highSeverity: anomalies.filter(a => a.severity === "high").length,
          mediumSeverity: anomalies.filter(a => a.severity === "medium").length,
          lowSeverity: anomalies.filter(a => a.severity === "low").length,
        },
      });
    } catch (error: any) {
      console.error("Asset inventory anomalies error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/eol-software", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const result = await pool.query(`
        SELECT software_inventory FROM assets
        WHERE tenant_id IN (${placeholders})
          AND software_inventory IS NOT NULL AND software_inventory != 'null'
      `, tenantIds);

      const softwareMap = new Map<string, { name: string; version: string; deviceCount: number }>();
      for (const row of result.rows) {
        const inv = row.software_inventory;
        if (!Array.isArray(inv)) continue;
        for (const sw of inv) {
          if (!sw?.name) continue;
          const key = `${sw.name}|||${sw.version || "N/A"}`;
          const existing = softwareMap.get(key);
          if (existing) {
            existing.deviceCount++;
          } else {
            softwareMap.set(key, { name: sw.name, version: sw.version || "N/A", deviceCount: 1 });
          }
        }
      }

      const { enrichSoftwareWithEOL } = await import("./eol-database");
      const softwareList = Array.from(softwareMap.values());
      const enriched = enrichSoftwareWithEOL(softwareList.map(s => ({
        name: s.name,
        version: s.version,
        systemCount: s.deviceCount,
      })));

      const eolSoftware = enriched
        .filter((s: any) => s.eol)
        .map((s: any) => ({
          name: s.name,
          version: s.version,
          deviceCount: s.systemCount,
          eolDate: s.eol.eolDate,
          eosDate: s.eol.eosDate,
          eolStatus: s.eol.eolStatus,
          eosStatus: s.eol.eosStatus,
          product: s.eol.product,
          vendor: s.eol.vendor,
        }))
        .sort((a: any, b: any) => b.deviceCount - a.deviceCount);

      const totalEnded = eolSoftware.filter((s: any) => s.eolStatus === "ended" || s.eosStatus === "ended").length;
      const totalApproaching = eolSoftware.filter((s: any) => s.eolStatus === "approaching" || s.eosStatus === "approaching").length;
      const totalActive = eolSoftware.filter((s: any) => s.eolStatus === "active" && s.eosStatus === "active").length;

      res.json({
        software: eolSoftware,
        summary: {
          totalWithEOLData: eolSoftware.length,
          totalEnded,
          totalApproaching,
          totalActive,
          totalDevicesAffected: eolSoftware.filter((s: any) => s.eolStatus === "ended" || s.eosStatus === "ended")
            .reduce((sum: number, s: any) => sum + s.deviceCount, 0),
        },
      });
    } catch (error: any) {
      console.error("EOL software error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/device-types", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const result = await pool.query(`
        SELECT COALESCE(NULLIF(endpoint_type, ''), 'Unknown') as device_type,
               COUNT(*)::int as count
        FROM assets
        WHERE tenant_id IN (${placeholders})
        GROUP BY COALESCE(NULLIF(endpoint_type, ''), 'Unknown')
        ORDER BY count DESC
      `, tenantIds);

      res.json({
        deviceTypes: result.rows.map(r => ({
          type: r.device_type,
          count: r.count,
        })),
        total: result.rows.reduce((s: number, r: any) => s + r.count, 0),
      });
    } catch (error: any) {
      console.error("Device types error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/ip-ranges", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const [result, totalResult] = await Promise.all([
        pool.query(`
          SELECT substring(ip_address from '^([0-9]+\\.[0-9]+\\.[0-9]+)\\.' ) as subnet,
                 COUNT(*)::int as asset_count,
                 array_agg(DISTINCT hostname ORDER BY hostname) as sample_hosts,
                 mode() WITHIN GROUP (ORDER BY cloud_region) as top_region
          FROM assets
          WHERE tenant_id IN (${placeholders})
            AND ip_address IS NOT NULL AND ip_address != ''
          GROUP BY substring(ip_address from '^([0-9]+\\.[0-9]+\\.[0-9]+)\\.' )
          HAVING substring(ip_address from '^([0-9]+\\.[0-9]+\\.[0-9]+)\\.' ) IS NOT NULL
          ORDER BY asset_count DESC
          LIMIT 30
        `, tenantIds),
        pool.query(`
          SELECT COUNT(DISTINCT substring(ip_address from '^([0-9]+\\.[0-9]+\\.[0-9]+)\\.' ))::int as total_subnets,
                 COUNT(*)::int as total_assets
          FROM assets
          WHERE tenant_id IN (${placeholders})
            AND ip_address IS NOT NULL AND ip_address != ''
            AND substring(ip_address from '^([0-9]+\\.[0-9]+\\.[0-9]+)\\.' ) IS NOT NULL
        `, tenantIds),
      ]);
      const totalSubnets = totalResult.rows[0]?.total_subnets || 0;
      const totalAssetsWithIP = totalResult.rows[0]?.total_assets || 0;

      const isPrivateSubnet = (subnet: string): boolean => {
        if (!subnet) return false;
        const parts = subnet.split(".").map(Number);
        if (parts[0] === 10) return true;
        if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
        if (parts[0] === 192 && parts[1] === 168) return true;
        return false;
      };

      const regionToCountry: Record<string, string> = {
        "us-east-1": "United States", "us-east-2": "United States", "us-west-1": "United States", "us-west-2": "United States",
        "eu-west-1": "Ireland", "eu-west-2": "United Kingdom", "eu-west-3": "France", "eu-central-1": "Germany", "eu-north-1": "Sweden", "eu-south-1": "Italy",
        "ap-south-1": "India", "ap-south-2": "India", "ap-southeast-1": "Singapore", "ap-southeast-2": "Australia",
        "ap-northeast-1": "Japan", "ap-northeast-2": "South Korea", "ap-northeast-3": "Japan", "ap-east-1": "Hong Kong",
        "sa-east-1": "Brazil", "ca-central-1": "Canada", "me-south-1": "Bahrain", "me-central-1": "UAE",
        "af-south-1": "South Africa", "il-central-1": "Israel",
        "eastus": "United States", "westus": "United States", "westeurope": "Netherlands", "northeurope": "Ireland",
        "southeastasia": "Singapore", "eastasia": "Hong Kong", "centralindia": "India", "southafricanorth": "South Africa",
      };

      const getSubnetLocation = (subnet: string, region: string | null): string => {
        if (region && regionToCountry[region]) return regionToCountry[region];
        if (region && !/^\d{4}-\d{2}-\d{2}/.test(region)) return region;
        if (!isPrivateSubnet(subnet)) {
          const parts = subnet.split(".").map(Number);
          if (parts[0] >= 1 && parts[0] <= 126) return "Public Range";
          return "Public Range";
        }
        return "Local Network";
      };

      const ranges = result.rows.map(r => ({
        subnet: r.subnet + ".0/24",
        subnetPrefix: r.subnet,
        assetCount: r.asset_count,
        isPrivate: isPrivateSubnet(r.subnet),
        sampleHosts: (r.sample_hosts || []).slice(0, 5),
        location: getSubnetLocation(r.subnet, r.top_region),
        cloudRegion: r.top_region || null,
      }));

      const privateCount = ranges.filter(r => r.isPrivate).length;
      const publicCount = ranges.filter(r => !r.isPrivate).length;

      res.json({
        ranges,
        summary: {
          totalRanges: ranges.length,
          totalSubnets,
          privateRanges: privateCount,
          publicRanges: publicCount,
          totalAssetsWithIP,
        },
      });
    } catch (error: any) {
      console.error("IP ranges error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  // DNS cache for email domain auth lookups (60-min TTL)
  const emailDomainDnsCache = new Map<string, { spf: string; dkim: string; dmarc: string; cachedAt: number }>();

  app.get("/api/asset-inventory/:tenantId/email-domains", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const result = await pool.query(`
        SELECT
          split_part(sender, '@', 2) as domain,
          COUNT(*)::int as event_count,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), '')) IN ('phishing', 'malware', 'bec', 'ransomware'))::int as malicious_count,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), '')) IN ('spam', 'suspicious', 'spoofing'))::int as suspicious_count,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), 'clean')) NOT IN ('phishing', 'malware', 'bec', 'ransomware', 'spam', 'suspicious', 'spoofing'))::int as clean_count,
          MAX(occurred_at) as last_seen,
          COUNT(DISTINCT COALESCE(NULLIF(recipient, ''), NULLIF(split_part(COALESCE(raw_payload->>'recipients', ''), ';', 1), '')))::int as recipients_targeted,
          COUNT(*) FILTER (WHERE severity IN ('critical', 'high'))::int as high_sev_count,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(action, '')) IN ('quarantined', 'quarantine', 'blocked'))::int as quarantined_count,
          (array_agg(COALESCE(NULLIF(NULLIF(raw_payload->>'spfResult', ''), 'N/A'), substring(description from 'SPF: ([^ |]+)')) ORDER BY occurred_at DESC) FILTER (WHERE COALESCE(NULLIF(NULLIF(raw_payload->>'spfResult', ''), 'N/A'), substring(description from 'SPF: ([^ |]+)')) IS NOT NULL))[1] as spf_result,
          (array_agg(COALESCE(NULLIF(NULLIF(raw_payload->>'dkimResult', ''), 'N/A'), substring(description from 'DKIM: ([^ |]+)')) ORDER BY occurred_at DESC) FILTER (WHERE COALESCE(NULLIF(NULLIF(raw_payload->>'dkimResult', ''), 'N/A'), substring(description from 'DKIM: ([^ |]+)')) IS NOT NULL))[1] as dkim_result,
          (array_agg(COALESCE(NULLIF(NULLIF(raw_payload->>'dmarcResult', ''), 'N/A'), substring(description from 'DMARC: ([^ |]+)')) ORDER BY occurred_at DESC) FILTER (WHERE COALESCE(NULLIF(NULLIF(raw_payload->>'dmarcResult', ''), 'N/A'), substring(description from 'DMARC: ([^ |]+)')) IS NOT NULL))[1] as dmarc_result
        FROM security_events
        WHERE tenant_id IN (${placeholders})
          AND sender IS NOT NULL AND sender LIKE '%@%'
        GROUP BY domain
        HAVING split_part(sender, '@', 2) != ''
        ORDER BY event_count DESC
        LIMIT 100
      `, tenantIds);

      const normalizeAuthStatus = (val: string | null | undefined): string => {
        if (!val) return "unknown";
        const v = val.trim().toLowerCase();
        if (v === "n/a" || v === "na" || v === "" || v === "none" || v === "null") return "unknown";
        if (v === "pass" || v === "fail" || v === "softfail" || v === "neutral" || v === "temperror" || v === "permerror") return v;
        return v;
      };

      const domains = result.rows.map(r => {
        let riskScore = 0;
        const total = r.event_count || 1;
        const maliciousCount = r.malicious_count || 0;
        const suspiciousCount = r.suspicious_count || 0;
        const highSevCount = r.high_sev_count || 0;
        const effectiveMalicious = Math.max(maliciousCount, highSevCount);
        const maliciousRatio = effectiveMalicious / total;
        riskScore += Math.min(maliciousRatio * 60, 60);
        const suspiciousRatio = suspiciousCount / total;
        riskScore += Math.min(suspiciousRatio * 20, 20);

        const spfNorm = normalizeAuthStatus(r.spf_result);
        const dkimNorm = normalizeAuthStatus(r.dkim_result);
        const dmarcNorm = normalizeAuthStatus(r.dmarc_result);

        if (dmarcNorm === "fail" || dmarcNorm === "none") riskScore += 10;
        if (spfNorm === "fail" || spfNorm === "softfail") riskScore += 5;
        if (dkimNorm === "fail") riskScore += 5;
        riskScore = Math.min(Math.round(riskScore), 100);

        let riskLevel = "low";
        if (riskScore >= 75) riskLevel = "critical";
        else if (riskScore >= 50) riskLevel = "high";
        else if (riskScore >= 25) riskLevel = "medium";

        return {
          domain: r.domain,
          eventCount: r.event_count,
          maliciousCount: effectiveMalicious,
          suspiciousCount,
          cleanCount: r.clean_count,
          quarantinedCount: r.quarantined_count || 0,
          recipientsTargeted: r.recipients_targeted,
          lastSeen: r.last_seen,
          spfStatus: spfNorm,
          dkimStatus: dkimNorm,
          dmarcStatus: dmarcNorm,
          riskScore,
          riskLevel,
        };
      });


      // Batch DNS lookups for domains where auth status is unknown (up to 20, with 60-min cache)
      const DNS_TIMEOUT_LIST = 3000;
      const dnsListModule = await import('dns');
      const dnsResolveList = (fn: () => Promise<string[][]>) =>
        Promise.race([
          fn().catch(() => null),
          new Promise<null>((resolve) => setTimeout(() => resolve(null), DNS_TIMEOUT_LIST)),
        ]);
      const DNS_CACHE_TTL = 60 * 60 * 1000;
      const dnsPendingDomains = domains
        .filter(d => d.spfStatus === 'unknown' || d.dkimStatus === 'unknown' || d.dmarcStatus === 'unknown')
        .slice(0, 20);
      if (dnsPendingDomains.length > 0) {
        await Promise.allSettled(
          dnsPendingDomains.map(async (dom) => {
            const cached = emailDomainDnsCache.get(dom.domain);
            if (cached && (Date.now() - cached.cachedAt) < DNS_CACHE_TTL) {
              if (dom.spfStatus === 'unknown') dom.spfStatus = cached.spf;
              if (dom.dkimStatus === 'unknown') dom.dkimStatus = cached.dkim;
              if (dom.dmarcStatus === 'unknown') dom.dmarcStatus = cached.dmarc;
              return;
            }
            try {
              const [spfR, dmarcR, dkimR1, dkimR2, dkimR3] = await Promise.allSettled([
                dnsResolveList(() => dnsListModule.promises.resolveTxt(dom.domain)),
                dnsResolveList(() => dnsListModule.promises.resolveTxt('_dmarc.' + dom.domain)),
                dnsResolveList(() => dnsListModule.promises.resolveTxt('selector1._domainkey.' + dom.domain)),
                dnsResolveList(() => dnsListModule.promises.resolveTxt('google._domainkey.' + dom.domain)),
                dnsResolveList(() => dnsListModule.promises.resolveTxt('selector2._domainkey.' + dom.domain)),
              ]);
              const spfTxt = spfR.status === 'fulfilled' && spfR.value ? (spfR.value as string[][]).flat().find((r: string) => r.startsWith('v=spf1')) : null;
              const spf = spfTxt ? 'configured' : 'not_found';
              const dmarcTxt = dmarcR.status === 'fulfilled' && dmarcR.value ? (dmarcR.value as string[][]).flat().find((r: string) => r.startsWith('v=DMARC1')) : null;
              const dmarc = dmarcTxt ? 'configured' : 'not_found';
              const hasDkim = (dkimR1.status === 'fulfilled' && dkimR1.value && (dkimR1.value as string[][]).flat().length > 0)
                || (dkimR2.status === 'fulfilled' && dkimR2.value && (dkimR2.value as string[][]).flat().length > 0)
                || (dkimR3.status === 'fulfilled' && dkimR3.value && (dkimR3.value as string[][]).flat().length > 0);
              const dkim = hasDkim ? 'configured' : 'not_found';
              emailDomainDnsCache.set(dom.domain, { spf, dkim, dmarc, cachedAt: Date.now() });
              if (dom.spfStatus === 'unknown') dom.spfStatus = spf;
              if (dom.dkimStatus === 'unknown') dom.dkimStatus = dkim;
              if (dom.dmarcStatus === 'unknown') dom.dmarcStatus = dmarc;
            } catch {
              // keep 'unknown' if DNS fails
            }
          })
        );
      }

      res.json({
        domains,
        total: domains.length,
        summary: {
          totalDomains: domains.length,
          criticalDomains: domains.filter(d => d.riskLevel === "critical").length,
          highRiskDomains: domains.filter(d => d.riskLevel === "high").length,
          mediumRiskDomains: domains.filter(d => d.riskLevel === "medium").length,
          lowRiskDomains: domains.filter(d => d.riskLevel === "low").length,
        },
      });
    } catch (error: any) {
      console.error("Email domains error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/web-domain-detail/:domain", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const domain = decodeURIComponent(req.params.domain);
      await assertTenantAccess(req, tenantId);

      const usersRes = await pool.query(`
        SELECT u.id, u.user_name, u.email, u.department, u.risk_score, u.total_requests,
               u.last_activity, u.top_sites
        FROM user_assets u
        WHERE u.tenant_id = $1
          AND u.top_sites IS NOT NULL
          AND jsonb_typeof(u.top_sites) = 'array'
          AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(u.top_sites) AS site WHERE site = $2
          )
        ORDER BY u.total_requests DESC NULLS LAST
        LIMIT 50
      `, [tenantId, domain]);

      const cloudRiskRes = await pool.query(`
        SELECT app_name, service_category, risk_score, is_sanctioned
        FROM cloud_app_risk_scores
        WHERE tenant_id = $1 AND LOWER(app_name) = LOWER($2)
        LIMIT 1
      `, [tenantId, domain]);
      const cloudRisk = cloudRiskRes.rows[0] || null;

      const eventsRes = await pool.query(`
        SELECT COUNT(*)::int as event_count,
               COUNT(*) FILTER (WHERE severity IN ('critical','high'))::int as high_sev_count,
               MIN(occurred_at) as first_seen,
               MAX(occurred_at) as last_seen,
               COUNT(DISTINCT COALESCE(NULLIF(raw_payload->>'User',''), NULLIF(raw_payload->>'Username','')))::int as unique_users_in_events
        FROM security_events
        WHERE tenant_id = $1
          AND (target = $2 OR asset ILIKE '%' || $2 || '%' OR raw_payload->>'url' ILIKE '%' || $2 || '%'
               OR raw_payload->>'domain' = $2 OR raw_payload->>'Host' = $2)
      `, [tenantId, domain]);
      const eventStats = eventsRes.rows[0] || {};

      const users = usersRes.rows.map(u => ({
        id: u.id,
        userName: u.user_name,
        email: u.email,
        department: u.department,
        riskScore: u.risk_score,
        totalRequests: u.total_requests,
        lastActivity: u.last_activity,
      }));

      const totalRequests = users.reduce((sum, u) => sum + (u.totalRequests || 0), 0);

      res.json({
        domain,
        userCount: users.length,
        totalRequests,
        users,
        category: cloudRisk?.service_category || lookupAppCategory(domain) || "Unknown",
        cloudRisk: cloudRisk ? {
          riskScore: cloudRisk.risk_score,
          isSanctioned: cloudRisk.is_sanctioned,
          category: cloudRisk.service_category,
        } : null,
        eventStats: {
          eventCount: eventStats.event_count || 0,
          highSevCount: eventStats.high_sev_count || 0,
          firstSeen: eventStats.first_seen,
          lastSeen: eventStats.last_seen,
          uniqueUsers: eventStats.unique_users_in_events || 0,
        },
      });
    } catch (error: any) {
      console.error("Web domain detail error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/email-domain-detail/:domain", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const domain = decodeURIComponent(req.params.domain).toLowerCase();
      await assertTenantAccess(req, tenantId);

      const senderDomainMatch = `(LOWER(split_part(sender, '@', 2)) = $2 OR LOWER(COALESCE(raw_payload->>'senderDomain', '')) = $2)`;
      const seSenderDomainMatch = `(LOWER(split_part(se.sender, '@', 2)) = $2 OR LOWER(COALESCE(se.raw_payload->>'senderDomain', '')) = $2)`;

      const timelineRes = await pool.query(`
        SELECT DATE(occurred_at) as day, COUNT(*)::int as total,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), '')) IN ('phishing','malware','bec','ransomware'))::int as malicious,
          COUNT(*) FILTER (WHERE LOWER(COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), '')) IN ('spam','suspicious','spoofing'))::int as suspicious
        FROM security_events
        WHERE tenant_id = $1 AND ${senderDomainMatch}
        AND occurred_at >= NOW() - INTERVAL '30 days'
        GROUP BY day ORDER BY day
      `, [tenantId, domain]);

      const incidentsRes = await pool.query(`
        SELECT id, title, severity, status, created_at as occurred_at
        FROM incidents
        WHERE tenant_id = $1 AND (
          description ILIKE '%' || $2 || '%' OR
          title ILIKE '%' || $2 || '%' OR
          EXISTS (
            SELECT 1 FROM security_events se
            WHERE se.incident_id = incidents.id AND se.tenant_id = $1
            AND ${seSenderDomainMatch}
          )
        )
        ORDER BY created_at DESC LIMIT 10
      `, [tenantId, domain]);

      const authHistoryRes = await pool.query(`
        SELECT DATE(occurred_at) as day,
          COALESCE(NULLIF(NULLIF(raw_payload->>'spfResult', ''), 'N/A'), substring(description from 'SPF: ([^ |]+)')) as spf,
          COALESCE(NULLIF(NULLIF(raw_payload->>'dkimResult', ''), 'N/A'), substring(description from 'DKIM: ([^ |]+)')) as dkim,
          COALESCE(NULLIF(NULLIF(raw_payload->>'dmarcResult', ''), 'N/A'), substring(description from 'DMARC: ([^ |]+)')) as dmarc
        FROM security_events
        WHERE tenant_id = $1 AND ${senderDomainMatch}
          AND occurred_at >= NOW() - INTERVAL '30 days'
        ORDER BY occurred_at DESC LIMIT 50
      `, [tenantId, domain]);

      const recentEventsRes = await pool.query(`
        SELECT id, severity, threat, sender, recipient, action,
          COALESCE(NULLIF(raw_payload->>'threatType', ''), NULLIF(raw_payload->>'emailThreatType', ''), 'clean') as threat_type,
          COALESCE(NULLIF(raw_payload->>'subject', ''), NULLIF(raw_payload->>'emailSubject', '')) as subject,
          COALESCE(NULLIF(recipient, ''), raw_payload->>'recipients') as full_recipient,
          occurred_at
        FROM security_events
        WHERE tenant_id = $1 AND ${senderDomainMatch}
        ORDER BY occurred_at DESC LIMIT 20
      `, [tenantId, domain]);

      const recipientsRes = await pool.query(`
        SELECT DISTINCT LOWER(TRIM(r)) as recipient_email
        FROM (
          SELECT unnest(
            string_to_array(recipient, ';')
          ) AS r
          FROM security_events
          WHERE tenant_id = $1 AND ${senderDomainMatch}
            AND recipient IS NOT NULL AND recipient != ''
          UNION
          SELECT unnest(
            string_to_array(raw_payload->>'recipients', ';')
          ) AS r
          FROM security_events
          WHERE tenant_id = $1 AND ${senderDomainMatch}
            AND raw_payload->>'recipients' IS NOT NULL AND raw_payload->>'recipients' != ''
        ) sub
        WHERE TRIM(r) != ''
        LIMIT 50
      `, [tenantId, domain]);

      const authHistory: Record<string, { spf: string[]; dkim: string[]; dmarc: string[] }> = {};
      for (const row of authHistoryRes.rows) {
        const day = row.day?.toISOString?.()?.split("T")[0] || "";
        if (!authHistory[day]) authHistory[day] = { spf: [], dkim: [], dmarc: [] };
        if (row.spf) authHistory[day].spf.push(row.spf.toLowerCase());
        if (row.dkim) authHistory[day].dkim.push(row.dkim.toLowerCase());
        if (row.dmarc) authHistory[day].dmarc.push(row.dmarc.toLowerCase());
      }

      res.json({
        domain,
        timeline: (() => {
          // Generate complete 30-day series with zero-fill for days with no events
          const tlMap = new Map<string, { total: number; malicious: number; suspicious: number }>();
          for (const r of timelineRes.rows) {
            const d = r.day?.toISOString?.()?.split("T")[0];
            if (d) tlMap.set(d, { total: r.total, malicious: r.malicious, suspicious: r.suspicious });
          }
          const days30: Array<{ day: string; total: number; malicious: number; suspicious: number }> = [];
          for (let i = 29; i >= 0; i--) {
            const d = new Date();
            d.setUTCDate(d.getUTCDate() - i);
            const dayStr = d.toISOString().split("T")[0];
            const row = tlMap.get(dayStr);
            days30.push({ day: dayStr, total: row?.total ?? 0, malicious: row?.malicious ?? 0, suspicious: row?.suspicious ?? 0 });
          }
          return days30;
        })(),
        linkedIncidents: incidentsRes.rows.map(r => ({ id: r.id, title: r.title, severity: r.severity, status: r.status, occurredAt: r.occurred_at })),
        authHistory: Object.entries(authHistory).map(([day, data]) => ({
          day,
          spfPass: data.spf.filter(s => s === "pass").length,
          spfFail: data.spf.filter(s => s !== "pass" && s !== "unknown").length,
          dkimPass: data.dkim.filter(s => s === "pass").length,
          dkimFail: data.dkim.filter(s => s !== "pass" && s !== "unknown").length,
          dmarcPass: data.dmarc.filter(s => s === "pass").length,
          dmarcFail: data.dmarc.filter(s => s !== "pass" && s !== "unknown").length,
        })),
        recentEvents: recentEventsRes.rows.map(r => ({
          id: r.id,
          severity: r.severity,
          threat: r.threat,
          threatType: r.threat_type,
          sender: r.sender,
          recipient: r.full_recipient,
          subject: r.subject,
          action: r.action,
          occurredAt: r.occurred_at,
        })),
        targetedRecipients: recipientsRes.rows.map(r => r.recipient_email).filter(Boolean),
      });
    } catch (error: any) {
      console.error("Email domain detail error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/email-domain-dns/:domain", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const domain = decodeURIComponent(req.params.domain).toLowerCase().trim();
      await assertTenantAccess(req, tenantId);

      if (!domain || domain.length > 255 || !/^[a-z0-9.-]+\.[a-z]{2,}$/.test(domain)) {
        return res.status(400).json({ message: "Invalid domain" });
      }

      const dns = await import("dns");
      const DNS_TIMEOUT = 4000;

      async function dnsResolveWithTimeout<T>(fn: () => Promise<T>): Promise<T | null> {
        try {
          return await Promise.race([
            fn(),
            new Promise<null>((resolve) => setTimeout(() => resolve(null), DNS_TIMEOUT)),
          ]);
        } catch { return null; }
      }

      const [spfRecords, dmarcRecords, ...dkimResults] = await Promise.allSettled([
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(domain)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`_dmarc.${domain}`)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`default._domainkey.${domain}`)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`selector1._domainkey.${domain}`)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`selector2._domainkey.${domain}`)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`google._domainkey.${domain}`)),
        dnsResolveWithTimeout(() => dns.promises.resolveTxt(`mail._domainkey.${domain}`)),
      ]);

      let spf: { status: string; record: string | null } = { status: "missing", record: null };
      if (spfRecords.status === "fulfilled" && spfRecords.value) {
        const flat = (spfRecords.value as string[][]).map(r => r.join("")).join(" ");
        const spfMatch = flat.match(/(v=spf1[^"]*)/i);
        if (spfMatch) spf = { status: "pass", record: spfMatch[1].substring(0, 200) };
      }

      let dmarc: { status: string; record: string | null; policy: string | null } = { status: "missing", record: null, policy: null };
      if (dmarcRecords.status === "fulfilled" && dmarcRecords.value) {
        const flat = (dmarcRecords.value as string[][]).map(r => r.join("")).join(" ");
        const dmarcMatch = flat.match(/(v=DMARC1[^"]*)/i);
        if (dmarcMatch) {
          const policyMatch = dmarcMatch[1].match(/p=(\w+)/i);
          dmarc = { status: "pass", record: dmarcMatch[1].substring(0, 200), policy: policyMatch ? policyMatch[1] : null };
        }
      }

      let dkim: { status: string; selector: string | null } = { status: "missing", selector: null };
      const dkimSelectors = ["default", "selector1", "selector2", "google", "mail"];
      for (let i = 0; i < dkimResults.length; i++) {
        const r = dkimResults[i];
        if (r.status === "fulfilled" && r.value) {
          const flat = (r.value as string[][]).map(rec => rec.join("")).join(" ");
          if (flat.includes("v=DKIM1") || flat.includes("p=")) {
            dkim = { status: "pass", selector: dkimSelectors[i] };
            break;
          }
        }
      }

      let dnssec: { status: string } = { status: "missing" };
      try {
        const dnskeyLookup: (domain: string, rrtype: string) => Promise<string[]> = dns.promises.resolve;
        const dnskeyResult = await Promise.race([
          dnskeyLookup(domain, "DNSKEY"),
          new Promise<null>((resolve) => setTimeout(() => resolve(null), DNS_TIMEOUT)),
        ]);
        if (dnskeyResult && Array.isArray(dnskeyResult) && dnskeyResult.length > 0) {
          dnssec = { status: "pass" };
        }
      } catch { }

      const blocklists = [
        { name: "Spamhaus DBL", query: `${domain}.dbl.spamhaus.org` },
        { name: "SURBL MULTI", query: `${domain}.multi.surbl.org` },
        { name: "URIBL MULTI", query: `${domain}.multi.uribl.com` },
      ];
      const blocklistResults: { name: string; listed: boolean; response: string | null }[] = [];
      const blResults = await Promise.allSettled(
        blocklists.map(bl =>
          Promise.race([
            dns.promises.resolve4(bl.query),
            new Promise<null>((resolve) => setTimeout(() => resolve(null), DNS_TIMEOUT)),
          ])
        )
      );
      let listedCount = 0;
      for (let i = 0; i < blocklists.length; i++) {
        const r = blResults[i];
        if (r.status === "fulfilled" && r.value && (r.value as string[]).length > 0) {
          const addr = (r.value as string[])[0];
          if (addr !== "127.255.255.252" && addr !== "127.255.255.254" && addr !== "127.255.255.255") {
            blocklistResults.push({ name: blocklists[i].name, listed: true, response: addr });
            listedCount++;
          } else {
            blocklistResults.push({ name: blocklists[i].name, listed: false, response: null });
          }
        } else {
          blocklistResults.push({ name: blocklists[i].name, listed: false, response: null });
        }
      }

      let reputationScore = 100;
      if (listedCount >= 3) reputationScore = 10;
      else if (listedCount === 2) reputationScore = 30;
      else if (listedCount === 1) reputationScore = 55;
      const reputationLevel = reputationScore <= 30 ? "malicious" : reputationScore <= 60 ? "suspicious" : "clean";

      const securityScore = ((spf.status === "pass" ? 1 : 0) + (dkim.status === "pass" ? 1 : 0) + (dmarc.status === "pass" ? 1 : 0) + (dnssec.status === "pass" ? 1 : 0));
      const securityGrade = securityScore >= 4 ? "A" : securityScore === 3 ? "B" : securityScore === 2 ? "C" : securityScore === 1 ? "D" : "F";

      res.json({
        domain,
        spf,
        dkim,
        dmarc,
        dnssec,
        blocklists: blocklistResults,
        reputationScore,
        reputationLevel,
        securityScore,
        securityGrade,
      });
    } catch (error: any) {
      console.error("Email domain DNS error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/assets/:tenantId/device-telemetry/:assetId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const assetId = parseInt(req.params.assetId);
      await assertTenantAccess(req, tenantId);

      const assetResult = await pool.query(
        `SELECT * FROM assets WHERE id = $1 AND tenant_id = $2`,
        [assetId, tenantId]
      );
      if (assetResult.rows.length === 0) return res.status(404).json({ message: "Asset not found" });
      const asset = assetResult.rows[0];
      const hostname = asset.hostname || "";
      const ipAddr = asset.ip_address || "";

      const ed = asset.enrichment_data ? (typeof asset.enrichment_data === "string" ? JSON.parse(asset.enrichment_data) : asset.enrichment_data) : {};

      const ipHistory = new Set<string>();
      if (ipAddr) ipHistory.add(ipAddr);
      if (ed.ipAddresses) {
        const arr = Array.isArray(ed.ipAddresses) ? ed.ipAddresses : [ed.ipAddresses];
        arr.forEach((ip: string) => { if (ip) ipHistory.add(ip); });
      }

      const macHistory = new Set<string>();
      if (asset.mac_address) macHistory.add(asset.mac_address);
      if (ed.macAddress) macHistory.add(ed.macAddress);

      const users = new Set<string>();
      if (asset.user_name) users.add(asset.user_name);
      if (asset.last_logged_in_user) users.add(asset.last_logged_in_user);
      if (ed.loggedInUsers?.length > 0) {
        for (const u of ed.loggedInUsers) {
          if (u && u.toLowerCase() !== "system" && u.toLowerCase() !== "administrator") users.add(u);
        }
      }

      let eventsResult: any = { rows: [] };
      if (hostname) {
        const hostnameKeys = ["Host", "Hostname", "host", "hostname", "Computer", "computer", "device_name", "DeviceName", "machine_name", "MachineName", "host_name", "computerName"];
        const hostnameConditions = hostnameKeys.map(k => `raw_payload->>'${k}' ILIKE $2`).join(" OR ");
        eventsResult = await pool.query(
          `SELECT target, raw_payload, log_source, source_type, occurred_at
           FROM security_events WHERE tenant_id = $1
           AND (asset ILIKE $2 OR target ILIKE $2 ${ipAddr ? `OR target = $3` : ``}
             OR raw_payload->>'Host/Risk' ILIKE $2 || '/%'
             OR ${hostnameConditions})
           ORDER BY occurred_at DESC LIMIT 500`,
          ipAddr ? [tenantId, `%${hostname}%`, ipAddr] : [tenantId, `%${hostname}%`]
        );
      } else if (ipAddr) {
        eventsResult = await pool.query(
          `SELECT target, raw_payload, log_source, source_type, occurred_at
           FROM security_events WHERE tenant_id = $1 AND target = $2
           ORDER BY occurred_at DESC LIMIT 500`,
          [tenantId, ipAddr]
        );
      }

      const securitySources = new Set<string>();
      const observedApps = new Map<string, { name: string; source: string; lastSeen: string }>();
      let lastLoginUser: string | null = null;
      let lastLoginAt: string | null = null;

      const loginUserFields = ["User", "Username", "Logged In User", "LoggedUser", "logged_user", "LastLoggedUser", "user_name"];
      const loginCoalesceExpr = loginUserFields.map(f => `NULLIF(NULLIF(TRIM(raw_payload->>'${f}'), ''), 'N/A')`).join(", ");
      if (hostname || ipAddr) {
        const loginHostKeys = ["Host", "Hostname", "host", "hostname", "Computer", "computer", "device_name", "DeviceName", "machine_name", "MachineName", "host_name", "computerName"];
        const loginHostConditions = loginHostKeys.map(k => `raw_payload->>'${k}' ILIKE $2`).join(" OR ");
        const loginQuery = hostname
          ? `SELECT COALESCE(${loginCoalesceExpr}) as login_user, occurred_at
             FROM security_events WHERE tenant_id = $1
             AND (asset ILIKE $2 OR target ILIKE $2 ${ipAddr ? `OR target = $3` : ``}
               OR raw_payload->>'Host/Risk' ILIKE $2 || '/%'
               OR ${loginHostConditions})
             AND COALESCE(${loginCoalesceExpr}) IS NOT NULL
             ORDER BY occurred_at DESC LIMIT 1`
          : `SELECT COALESCE(${loginCoalesceExpr}) as login_user, occurred_at
             FROM security_events WHERE tenant_id = $1 AND target = $2
             AND COALESCE(${loginCoalesceExpr}) IS NOT NULL
             ORDER BY occurred_at DESC LIMIT 1`;
        try {
          const loginResult = await pool.query(loginQuery, hostname && ipAddr ? [tenantId, `%${hostname}%`, ipAddr] : hostname ? [tenantId, `%${hostname}%`] : [tenantId, ipAddr]);
          if (loginResult.rows.length > 0) {
            const rawLogin = loginResult.rows[0].login_user;
            if (rawLogin && typeof rawLogin === "string") {
              const parsed = rawLogin.includes("\\") ? rawLogin.split("\\")[1] : rawLogin;
              const clean = parsed?.trim().toLowerCase();
              if (clean && clean !== "system" && clean !== "administrator" && clean !== "nt authority - system" && clean !== "n/a") {
                lastLoginUser = parsed.trim();
                lastLoginAt = loginResult.rows[0].occurred_at;
              }
            }
          }
        } catch { }
      }

      const SYSTEM_BINARIES = new Set([
        "svchost.exe", "csrss.exe", "lsass.exe", "winlogon.exe", "services.exe", "smss.exe",
        "wininit.exe", "explorer.exe", "dwm.exe", "taskhost.exe", "conhost.exe", "dllhost.exe",
        "rundll32.exe", "cmd.exe", "powershell.exe", "msiexec.exe", "wmiprvse.exe", "spoolsv.exe",
        "searchindexer.exe", "ntoskrnl.exe", "system", "idle", "registry", "wuauclt.exe",
        "trustedinstaller.exe", "tiworker.exe", "mpcmdrun.exe", "consent.exe", "dashost.exe",
        "taskhostw.exe", "runtimebroker.exe", "ctfmon.exe", "fontdrvhost.exe", "sihost.exe",
        "applicationframehost.exe", "systemsettings.exe", "startmenuexperiencehost.exe",
        "searchapp.exe", "textinputhost.exe", "shellexperiencehost.exe", "lockapp.exe",
      ]);

      for (const evt of eventsResult.rows) {
        if (evt.log_source) evt.log_source.split(",").forEach((s: string) => securitySources.add(s.trim()));
        if (evt.source_type) securitySources.add(evt.source_type);
        if (evt.target && /^[\d.]+$/.test(evt.target)) ipHistory.add(evt.target);
        const rp = evt.raw_payload;
        if (rp) {
          const payload = typeof rp === "string" ? (() => { try { return JSON.parse(rp); } catch { return null; } })() : rp;
          if (payload) {
            if (payload["MAC Address"]) macHistory.add(payload["MAC Address"]);
            const evtUser = payload["User"] || payload["Username"] || payload["Logged In User"] || payload["LoggedUser"] || payload["logged_user"] || payload["LastLoggedUser"] || payload["user_name"];
            if (evtUser && typeof evtUser === "string") {
              const rawU = evtUser.includes("\\") ? evtUser.split("\\")[1] : evtUser;
              const uClean = rawU?.trim().toLowerCase();
              if (uClean && uClean !== "system" && uClean !== "administrator" && uClean !== "nt authority - system" && uClean !== "n/a") {
                users.add(rawU.trim());
              }
            }

            const appFields = [
              payload["App/Risk"], payload["application"], payload["process_name"],
              payload["app_name"], payload["AppName"], payload["Application"],
              payload["ProcessName"], payload["Image"], payload["ParentImage"],
              payload["File/Risk"], payload["Alert Name"], payload["Threat Name"],
              payload["Incident Name"], payload["TargetFileName"], payload["Module"],
              payload["CommandLine"], payload["OriginalFileName"],
              payload["Product"], payload["Company"],
            ];
            for (const appVal of appFields) {
              if (!appVal || typeof appVal !== "string") continue;
              let appName = appVal;
              if (appName.includes("/")) appName = appName.split("/")[0];
              if (appName.includes("\\")) appName = appName.split("\\").pop() || appName;
              if (appName.includes(" - ")) appName = appName.split(" - ")[0];
              appName = appName.replace(/\.exe$/i, "").replace(/\.dll$/i, "").replace(/\.sys$/i, "").trim();
              if (!appName || appName.length < 2 || appName.length > 80) continue;
              const appLower = appName.toLowerCase();
              if (SYSTEM_BINARIES.has(appLower) || SYSTEM_BINARIES.has(appLower + ".exe")) continue;
              if (/^[a-f0-9]{32,}$/i.test(appName)) continue;
              if (/^(update|hotfix|security update|definition update)/i.test(appName)) continue;
              const key = appLower;
              if (!observedApps.has(key)) {
                observedApps.set(key, {
                  name: appName,
                  source: "event_telemetry",
                  lastSeen: evt.occurred_at ? new Date(evt.occurred_at).toISOString() : "",
                });
              }
            }
          }
        }
      }

      const cynetUserRes = await pool.query(
        `SELECT DISTINCT raw_payload->>'User/Risk' as user_risk
         FROM security_events WHERE tenant_id = $1 AND log_source = 'Cynet 360'
         AND raw_payload->>'Host/Risk' ILIKE $2 || '/%'`,
        [tenantId, hostname]
      );
      for (const row of cynetUserRes.rows) {
        const userRisk = row.user_risk || "";
        const um = userRisk.match(/(?:.*\\)?([^/]+)\/(\d+)/);
        if (um) {
          const u = um[1].toLowerCase().trim();
          if (u !== "nt authority - system" && u !== "system" && u !== "administrator") users.add(u);
        }
      }

      const swInventory = (() => {
        const raw = (asset.software_inventory as any[]) || [];
        if (!Array.isArray(raw)) return [];
        const seen = new Set<string>();
        return raw.filter((sw: any) => {
          const name = sw.name || '';
          const key = `${name.toLowerCase()}||${(sw.version || '').toLowerCase()}`;
          if (seen.has(key)) return false;
          seen.add(key);
          const l = name.toLowerCase();
          if (l.startsWith('update for ') || l.startsWith('security update ') || l.startsWith('definition update ') || l.startsWith('hotfix for ')) return false;
          return true;
        }).map((sw: any) => ({
          name: sw.name || '',
          version: sw.version || '',
          vendor: sw.vendor || '',
          installDate: sw.installDate || '',
        }));
      })();

      const hardwareProfile = {
        processor: asset.processor || null,
        totalPhysicalMemory: asset.total_physical_memory || null,
        storageInfo: asset.storage_info || null,
        systemModel: asset.system_model || null,
        systemManufacturer: asset.system_manufacturer || null,
        biosSerialNumber: asset.bios_serial_number || null,
        deviceHealth: asset.device_health || null,
      };

      const existingSwNames = new Set(swInventory.map((s: any) => s.name.toLowerCase()));
      const observedSwList = Array.from(observedApps.values())
        .filter(app => !existingSwNames.has(app.name.toLowerCase()))
        .map(app => ({ name: app.name, version: "", vendor: "", installDate: "", source: "event_telemetry", lastSeen: app.lastSeen }));

      if (!lastLoginUser && asset.last_logged_in_user) {
        lastLoginUser = asset.last_logged_in_user;
        lastLoginAt = asset.last_seen ? new Date(asset.last_seen).toISOString() : null;
      }

      res.json({
        assetId: asset.id,
        hostname: asset.hostname,
        operatingSystem: asset.operating_system || null,
        status: asset.status || "active",
        endpointGroup: asset.endpoint_group || null,
        agentVersion: asset.agent_version || null,
        ipAddresses: Array.from(ipHistory),
        macAddresses: Array.from(macHistory),
        loggedInUsers: Array.from(users),
        softwareInventory: [...swInventory, ...observedSwList],
        hardwareProfile,
        enrichmentData: ed,
        securitySources: Array.from(securitySources),
        eventCount: eventsResult.rows.length,
        lastLoginUser,
        lastLoginAt,
      });
    } catch (error: any) {
      console.error("Device telemetry error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/security-coverage", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const logSourceResult = await pool.query(`
        SELECT log_source, source_type, COUNT(*)::int as event_count, MAX(occurred_at) as last_event
        FROM security_events
        WHERE tenant_id IN (${placeholders}) AND log_source IS NOT NULL
        GROUP BY log_source, source_type
        ORDER BY event_count DESC
      `, tenantIds);

      const [totalDevicesResult, emailTotalResult, identityTotalResult, emailCoveredResult, identityCoveredResult, windowsDevicesResult] = await Promise.all([
        pool.query(`
          SELECT COUNT(*)::int as total FROM assets WHERE tenant_id IN (${placeholders})
        `, tenantIds),
        pool.query(`
          SELECT COUNT(DISTINCT email)::int as total
          FROM user_assets
          WHERE tenant_id IN (${placeholders}) AND email IS NOT NULL AND email LIKE '%@%'
        `, tenantIds),
        pool.query(`
          SELECT COUNT(*)::int as total
          FROM user_assets
          WHERE tenant_id IN (${placeholders})
        `, tenantIds),
        pool.query(`
          SELECT COUNT(DISTINCT target)::int as covered
          FROM security_events
          WHERE tenant_id IN (${placeholders})
            AND source_type = 'Email Security'
            AND target IS NOT NULL AND target LIKE '%@%'
        `, tenantIds),
        pool.query(`
          SELECT COUNT(DISTINCT COALESCE(target, attacker))::int as covered
          FROM security_events
          WHERE tenant_id IN (${placeholders})
            AND (source_type ILIKE '%identity%' OR source_type ILIKE '%auth%' OR event_type = 'identity'
              OR source_type = 'CASB' OR source_type = 'Web Proxy')
            AND COALESCE(target, attacker) IS NOT NULL
        `, tenantIds),
        // Domain-joined proxy: Windows corporate assets are typically AD domain-joined
        pool.query(`
          SELECT COUNT(*)::int as domain_joined
          FROM assets
          WHERE tenant_id IN (${placeholders})
            AND operating_system ILIKE '%windows%'
        `, tenantIds),
      ]);
      const totalDevices = totalDevicesResult.rows[0]?.total || 0;
      const totalEmails = emailTotalResult.rows[0]?.total || 0;
      const totalIdentityUsers = identityTotalResult.rows[0]?.total || 0;
      const emailsCovered = emailCoveredResult.rows[0]?.covered || 0;
      const identityCovered = identityCoveredResult.rows[0]?.covered || 0;
      // Windows devices = domain-joined estimate (AD proxy for Identity coverage)
      const windowsDeviceCount = windowsDevicesResult.rows[0]?.domain_joined || 0;

      const agentResult = await pool.query(`
        SELECT
          agent_version,
          prevention_policy,
          COUNT(*)::int as device_count
        FROM assets
        WHERE tenant_id IN (${placeholders}) AND agent_version IS NOT NULL AND agent_version != ''
        GROUP BY agent_version, prevention_policy
        ORDER BY device_count DESC
      `, tenantIds);

      const swSecResult = await pool.query(`
        SELECT
          sw->>'name' as sw_name,
          COUNT(DISTINCT a.id)::int as device_count
        FROM assets a, jsonb_array_elements(a.software_inventory) as sw
        WHERE a.tenant_id IN (${placeholders})
          AND a.software_inventory IS NOT NULL
          AND jsonb_typeof(a.software_inventory) = 'array'
        GROUP BY sw->>'name'
        HAVING COUNT(DISTINCT a.id) >= 5
        ORDER BY device_count DESC
      `, tenantIds);

      interface ToolInfo {
        name: string;
        vendor: string;
        category: string;
        domainCategory: string;
        devicesCovered: number;
        eventCount: number;
        lastEventTime: string | null;
        detectedFrom: string;
      }

      const toolMap = new Map<string, ToolInfo>();

      const TOOL_DOMAIN_MAP: Record<string, string> = {
        "Endpoint Security": "Endpoint Protection",
        "EDR/XDR": "Endpoint Protection",
        "Anti-Malware": "Endpoint Protection",
        "Autonomous Breach Protection": "Endpoint Protection",
        "Email Security": "Email Security",
        "Cloud Security": "Cloud & Web Security",
        "SIEM": "SecOps",
        "Vulnerability Management": "Vulnerability Management",
        "Identity & Access": "Identity & Access",
        "Network Access Control": "Network Security",
        "Network Security": "Network Security",
        "Backup & Recovery": "Backup & Recovery",
        "Data Loss Prevention": "Data Loss Prevention",
        "Remote Access": "Remote Access",
      };

      for (const row of logSourceResult.rows) {
        const combined = `${row.log_source || ""} ${row.source_type || ""}`;
        for (const mapping of LOG_SOURCE_PATTERNS) {
          if (mapping.pattern.test(combined)) {
            const def = PRODUCT_DEFINITIONS[mapping.productId];
            if (def) {
              const existing = toolMap.get(def.name);
              if (existing) {
                existing.eventCount += row.event_count;
                if (row.last_event && (!existing.lastEventTime || row.last_event > existing.lastEventTime)) {
                  existing.lastEventTime = row.last_event;
                }
              } else {
                const classified = classifySoftware(def.name);
                toolMap.set(def.name, {
                  name: def.name,
                  vendor: def.vendor,
                  category: def.category,
                  domainCategory: TOOL_DOMAIN_MAP[classified.category] || TOOL_DOMAIN_MAP[def.category] || "Other",
                  devicesCovered: 0,
                  eventCount: row.event_count,
                  lastEventTime: row.last_event,
                  detectedFrom: "Security Events",
                });
              }
            }
            break;
          }
        }
      }

      for (const row of swSecResult.rows) {
        const classified = classifySoftware(row.sw_name);
        if (classified.category !== "Unknown" && TOOL_DOMAIN_MAP[classified.category]) {
          const key = row.sw_name;
          if (!toolMap.has(key)) {
            toolMap.set(key, {
              name: row.sw_name,
              vendor: classified.vendor,
              category: classified.category,
              domainCategory: TOOL_DOMAIN_MAP[classified.category] || "Other",
              devicesCovered: row.device_count,
              eventCount: 0,
              lastEventTime: null,
              detectedFrom: "Software Inventory",
            });
          } else {
            const existing = toolMap.get(key)!;
            existing.devicesCovered = Math.max(existing.devicesCovered, row.device_count);
          }
        }
      }

      const cynet360 = toolMap.get("Cynet 360 AutoXDR");
      const cynetEPS = toolMap.get("CynetEPS");
      if (cynet360 && cynetEPS) {
        cynet360.devicesCovered = Math.max(cynet360.devicesCovered, cynetEPS.devicesCovered);
        cynet360.category = "Autonomous Breach Protection";
        toolMap.delete("CynetEPS");
      } else if (cynetEPS && !cynet360) {
        cynetEPS.name = "Cynet 360 AutoXDR";
        cynetEPS.category = "Autonomous Breach Protection";
        cynetEPS.domainCategory = "Endpoint Protection";
        toolMap.delete("CynetEPS");
        toolMap.set("Cynet 360 AutoXDR", cynetEPS);
      }

      let endpointAgentCovered = 0;
      for (const row of agentResult.rows) {
        endpointAgentCovered += row.device_count;
      }
      const endpointTools = Array.from(toolMap.values()).filter(t => t.domainCategory === "Endpoint Protection");
      for (const tool of endpointTools) {
        if (tool.devicesCovered === 0) {
          tool.devicesCovered = Math.min(endpointAgentCovered, totalDevices);
        }
      }

      const detectedTools = Array.from(toolMap.values()).sort((a, b) => b.eventCount - a.eventCount);

      const SECURITY_DOMAINS = [
        "Endpoint Protection", "Email Security", "Cloud & Web Security", "Network Security",
        "Vulnerability Management", "Identity & Access", "SecOps",
        "Backup & Recovery", "Data Loss Prevention"
      ];

      // Smart Identity coverage: domain-joined assets imply Active Directory = identity covered.
      // Smart SecOps coverage: customer on the platform = SIEM/monitoring always covered;
      // depth is proportional to how many other security tool domains are integrated.

      const coverageByDomain: Record<string, any> = {};
      let secopsIntegratedDomains = 0; // tracked for gap detection
      for (const domain of SECURITY_DOMAINS) {
        const domainTools = detectedTools.filter(t => t.domainCategory === domain);
        let domainTotal = totalDevices;
        let domainCovered = domainTools.reduce((max, t) => Math.max(max, t.devicesCovered), 0);
        const syntheticTools: string[] = [];
        const syntheticVendors: string[] = [];

        if (domain === "Email Security") {
          domainTotal = totalEmails > 0 ? totalEmails : totalDevices;
          domainCovered = emailsCovered > 0 ? emailsCovered : domainCovered;
        } else if (domain === "Identity & Access") {
          domainTotal = totalIdentityUsers > 0 ? totalIdentityUsers : totalDevices;
          domainCovered = identityCovered > 0 ? identityCovered : domainCovered;
          // Smart: use Windows assets as domain-joined proxy. Corporate Windows machines
          // are typically AD domain-joined; Linux/macOS are generally not.
          if (domainCovered === 0 && totalDevices > 0) {
            domainCovered = windowsDeviceCount;
            domainTotal = totalDevices;
            syntheticTools.push("Active Directory (Domain)");
            syntheticVendors.push("Microsoft");
          }
        } else if (domain === "SecOps") {
          // The platform IS the SIEM base, but coverage quality reflects how many
          // security control domains are actually feeding data into it.
          // With only Endpoint (~1/8 domains) → ~12-13%; all 8 domains → 100%.
          const otherDomains = SECURITY_DOMAINS.filter(d => d !== "SecOps");
          const integratedDomains = otherDomains.filter(d =>
            detectedTools.some(t => t.domainCategory === d)
          ).length;
          secopsIntegratedDomains = integratedDomains; // capture for gaps filter
          domainTotal = otherDomains.length;
          // min 1 so the platform itself counts as a base data source (small non-zero floor)
          domainCovered = Math.max(1, integratedDomains);
          syntheticTools.push("Cyber Command Center (Platform)");
          syntheticVendors.push("MSSP Platform");
          if (integratedDomains > 0) {
            syntheticTools.push(`${integratedDomains} Security Domain${integratedDomains !== 1 ? "s" : ""} Integrated`);
            syntheticVendors.push("Multi-Vendor");
          }
        }

        const allTools = [...domainTools.map(t => t.name), ...syntheticTools];
        const allVendors = [...domainTools.map(t => t.vendor), ...syntheticVendors];
        const rawPercent = domainTotal > 0 ? Math.round((domainCovered / domainTotal) * 100) : (allTools.length > 0 ? 100 : 0);

        coverageByDomain[domain] = {
          covered: domainCovered,
          total: domainTotal,
          tools: allTools,
          vendors: allVendors,
          percent: Math.min(100, rawPercent),
          eventCount: domainTools.reduce((sum, t) => sum + t.eventCount, 0),
          status: allTools.length === 0 ? "not_detected" : domainCovered >= domainTotal * 0.8 ? "good" : domainCovered >= domainTotal * 0.5 ? "partial" : "low",
        };
      }

      const gaps = SECURITY_DOMAINS
        .filter(d => {
          if (d === "SecOps") {
            // SecOps has a synthetic platform tool always, but gaps should reflect
            // whether any real security control domains are feeding the platform.
            return secopsIntegratedDomains === 0;
          }
          return coverageByDomain[d].tools.length === 0;
        })
        .map(d => `No ${d} tools detected`);

      const domainValues = Object.values(coverageByDomain) as any[];
      const activeDomains = domainValues.filter((d: any) => d.tools.length > 0);
      const overallScore = activeDomains.length > 0
        ? Math.round(activeDomains.reduce((sum: number, d: any) => sum + d.percent, 0) / SECURITY_DOMAINS.length)
        : 0;

      res.json({
        detectedTools,
        coverageByDomain,
        gaps,
        overallScore,
        totalDevices,
        totalTools: detectedTools.length,
      });
    } catch (error: any) {
      console.error("Security coverage error:", error);
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/asset-inventory/:tenantId/tool-covered-devices", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const toolName = (req.query.toolName as string || "").trim();
      if (!toolName) return res.status(400).json({ message: "toolName is required" });

      const toolLower = toolName.toLowerCase();

      // Find assets covered by this tool via software_inventory OR source field
      const result = await pool.query(`
        SELECT DISTINCT
          a.id,
          COALESCE(a.hostname, 'Unknown') as hostname,
          a.ip_address,
          COALESCE(a.operating_system, 'Unknown') as operating_system,
          a.last_seen,
          COALESCE(a.risk_level, 'low') as risk_level,
          COALESCE(a.asset_type, 'Unknown') as asset_type
        FROM assets a
        WHERE a.tenant_id = $1
          AND (
            LOWER(COALESCE(a.source, '')) ILIKE $2
            OR EXISTS (
              SELECT 1 FROM jsonb_array_elements(
                CASE WHEN jsonb_typeof(a.software_inventory) = 'array' THEN a.software_inventory ELSE '[]'::jsonb END
              ) sw
              WHERE LOWER(sw->>'name') ILIKE $2
            )
          )
        ORDER BY a.hostname
        LIMIT 200
      `, [tenantId, `%${toolLower}%`]);

      // If no direct match, try searching via security_events log_source
      if (result.rows.length === 0) {
        const eventsResult = await pool.query(`
          SELECT DISTINCT
            a.id,
            COALESCE(a.hostname, e.target) as hostname,
            a.ip_address,
            COALESCE(a.operating_system, 'Unknown') as operating_system,
            a.last_seen,
            COALESCE(a.risk_level, 'low') as risk_level,
            COALESCE(a.asset_type, 'Unknown') as asset_type
          FROM security_events e
          LEFT JOIN assets a ON (
            a.tenant_id = e.tenant_id AND (
              LOWER(a.hostname) = LOWER(e.target) OR
              a.ip_address = e.target
            )
          )
          WHERE e.tenant_id = $1
            AND (LOWER(COALESCE(e.log_source,'')) ILIKE $2 OR LOWER(COALESCE(e.source_type,'')) ILIKE $2)
            AND e.target IS NOT NULL
          ORDER BY hostname
          LIMIT 200
        `, [tenantId, `%${toolLower}%`]);
        return res.json({ devices: eventsResult.rows, total: eventsResult.rows.length, toolName });
      }

      res.json({ devices: result.rows, total: result.rows.length, toolName });
    } catch (error: any) {
      console.error("Tool covered devices error:", error);
      res.status(500).json({ message: error.message });
    }
  });

