  app.get("/api/asset-inventory/:tenantId/network-segmentation", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const tenantIds = [tenantId];
      const placeholders = tenantIds.map((_, i) => `$${i + 1}`).join(",");

      const result = await pool.query(`
        SELECT
          ip_address, hostname, risk_score, status, endpoint_type, operating_system
        FROM assets
        WHERE tenant_id IN (${placeholders}) AND ip_address IS NOT NULL AND ip_address != ''
        ORDER BY ip_address
      `, tenantIds);

      const subnets: Record<string, { subnet: string; assets: number; avgRisk: number; riskSum: number; critical: number; high: number; medium: number; low: number; types: Record<string, number> }> = {};

      for (const row of result.rows) {
        const ip = row.ip_address || "";
        const parts = ip.split(".");
        if (parts.length < 3) continue;
        const subnet = `${parts[0]}.${parts[1]}.${parts[2]}.0/24`;
        if (!subnets[subnet]) {
          subnets[subnet] = { subnet, assets: 0, avgRisk: 0, riskSum: 0, critical: 0, high: 0, medium: 0, low: 0, types: {} };
        }
        const s = subnets[subnet];
        s.assets++;
        const risk = row.risk_score || 0;
        s.riskSum += risk;
        if (risk >= 80) s.critical++;
        else if (risk >= 60) s.high++;
        else if (risk >= 40) s.medium++;
        else s.low++;
        const etype = row.endpoint_type || "Unknown";
        s.types[etype] = (s.types[etype] || 0) + 1;
      }

      const segments = Object.values(subnets)
        .map(s => ({ ...s, avgRisk: s.assets > 0 ? Math.round(s.riskSum / s.assets) : 0 }))
        .sort((a, b) => b.assets - a.assets)
        .slice(0, 20);

      res.json({ segments });
    } catch (error: any) {
      console.error("Network segmentation error:", error);
      res.status(500).json({ message: error.message });
    }
  });

