  app.get("/api/ai-workforce/:tenantId/effectiveness", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const range = (req.query.range as string) || "all";

      let intervalClause = "";
      if (range === "24h") intervalClause = "AND al.created_at > NOW() - INTERVAL '24 hours'";
      else if (range === "7d") intervalClause = "AND al.created_at > NOW() - INTERVAL '7 days'";
      else if (range === "30d") intervalClause = "AND al.created_at > NOW() - INTERVAL '30 days'";

      const agentMetrics = await pool.query(`
        SELECT 
          tm.id as agent_id, tm.name, tm.ai_specialization as specialization,
          COUNT(al.id)::int as total_actions,
          COUNT(al.id) FILTER (WHERE al.created_at > NOW() - INTERVAL '24 hours')::int as actions_today,
          COUNT(al.id) FILTER (WHERE al.confidence >= 70)::int as successful_actions,
          COALESCE(AVG(al.confidence), 0)::int as avg_confidence,
          COALESCE(AVG(al.duration), 0)::int as avg_duration,
          COUNT(al.id) FILTER (WHERE al.human_reviewed = true)::int as reviewed_count,
          COUNT(al.id) FILTER (WHERE al.human_override = true)::int as override_count
        FROM team_members tm
        LEFT JOIN ai_agent_activity_log al ON al.agent_id = tm.id AND al.tenant_id = $1 ${intervalClause}
        WHERE tm.tenant_id = $1 AND tm.is_ai = true
        GROUP BY tm.id, tm.name, tm.ai_specialization
        ORDER BY tm.name
      `, [tenantId]);

      const typeBreakdown = await pool.query(`
        SELECT 
          al.agent_id, activity_type, COUNT(*)::int as count
        FROM ai_agent_activity_log al
        JOIN team_members tm ON tm.id = al.agent_id
        WHERE al.tenant_id = $1 ${intervalClause}
        GROUP BY al.agent_id, activity_type
      `, [tenantId]);

      const dailyTrend = await pool.query(`
        SELECT 
          DATE(al.created_at) as day,
          al.agent_id,
          tm.name as agent_name,
          COUNT(*)::int as total,
          COUNT(*) FILTER (WHERE al.confidence >= 70)::int as successful,
          COALESCE(AVG(al.confidence), 0)::int as avg_confidence,
          COALESCE(AVG(al.duration), 0)::int as avg_duration
        FROM ai_agent_activity_log al
        JOIN team_members tm ON tm.id = al.agent_id
        WHERE al.tenant_id = $1 AND al.created_at > NOW() - INTERVAL '30 days'
        GROUP BY DATE(al.created_at), al.agent_id, tm.name
        ORDER BY day
      `, [tenantId]);

      const typeMap = new Map<number, Record<string, number>>();
      for (const row of typeBreakdown.rows) {
        if (!typeMap.has(row.agent_id)) typeMap.set(row.agent_id, {});
        typeMap.get(row.agent_id)![row.activity_type] = row.count;
      }

      const agents = agentMetrics.rows.map((a: any) => ({
        agentId: a.agent_id,
        name: a.name,
        specialization: a.specialization,
        totalActions: a.total_actions,
        actionsToday: a.actions_today,
        successRate: a.total_actions > 0 ? Math.round((a.successful_actions / a.total_actions) * 100) : 0,
        avgConfidence: a.avg_confidence,
        avgDuration: a.avg_duration,
        reviewedCount: a.reviewed_count,
        overrideCount: a.override_count,
        overrideRate: a.reviewed_count > 0 ? Math.round((a.override_count / a.reviewed_count) * 100) : 0,
        typeBreakdown: typeMap.get(a.agent_id) || {},
      }));

      const trendDayMap = new Map<string, any>();
      for (const row of dailyTrend.rows) {
        const dayStr = new Date(row.day).toISOString().split("T")[0];
        if (!trendDayMap.has(dayStr)) trendDayMap.set(dayStr, { day: dayStr });
        const entry = trendDayMap.get(dayStr)!;
        entry[`${row.agent_name}_confidence`] = row.avg_confidence;
        entry[`${row.agent_name}_actions`] = row.total;
        entry[`${row.agent_name}_successRate`] = row.total > 0 ? Math.round((row.successful / row.total) * 100) : 0;
      }

      res.json({
        agents,
        trend: Array.from(trendDayMap.values()),
        agentNames: agentMetrics.rows.map((a: any) => a.name),
      });
    } catch (error: any) {
      console.error("AI effectiveness error:", error);
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  app.get("/api/global-search", isAuthenticated, async (req: any, res) => {
    try {
      const q = (req.query.q as string || "").trim();
      const tenantId = parseInt(req.query.tenantId as string);
      const limit = Math.min(parseInt(req.query.limit as string) || 5, 20);

      if (q.length < 2) {
        return res.json({ results: { assets: [], users: [], incidents: [], events: [], tickets: [], knowledgeBase: [], projects: [], reports: [], iocs: [] }, totalCount: 0 });
      }

      if (!tenantId || isNaN(tenantId)) {
        return res.status(400).json({ message: "tenantId is required" });
      }

      await assertTenantAccess(req, tenantId);

      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const tenantPlaceholders = tenantIds.map((_, i) => `$${i + 2}`).join(", ");
      const tenantParams = tenantIds as any[];

      const [assetsRes, usersRes, incidentsRes, eventsRes, ticketsRes, docsRes, projectsRes, reportsRes, iocsRes] = await Promise.all([
        pool.query(
          `SELECT id, hostname, ip_address, operating_system, risk_level FROM assets WHERE tenant_id IN (${tenantPlaceholders}) AND (hostname ILIKE '%' || $1 || '%' OR ip_address ILIKE '%' || $1 || '%' OR operating_system ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, user_name, email, department, account_type, risk_level FROM user_assets WHERE tenant_id IN (${tenantPlaceholders}) AND (user_name ILIKE '%' || $1 || '%' OR email ILIKE '%' || $1 || '%' OR department ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, title, severity, status FROM incidents WHERE tenant_id IN (${tenantPlaceholders}) AND (title ILIKE '%' || $1 || '%' OR description ILIKE '%' || $1 || '%' OR source ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, event_type, threat, severity FROM security_events WHERE tenant_id IN (${tenantPlaceholders}) AND (threat ILIKE '%' || $1 || '%' OR target ILIKE '%' || $1 || '%' OR attacker ILIKE '%' || $1 || '%' OR description ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, title, priority, status FROM tickets WHERE tenant_id IN (${tenantPlaceholders}) AND (title ILIKE '%' || $1 || '%' OR description ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, title, category FROM documents WHERE tenant_id IN (${tenantPlaceholders}) AND (title ILIKE '%' || $1 || '%' OR content ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, name, status FROM projects WHERE tenant_id IN (${tenantPlaceholders}) AND (name ILIKE '%' || $1 || '%' OR description ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, title, report_type, period FROM reports WHERE tenant_id IN (${tenantPlaceholders}) AND (title ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
        pool.query(
          `SELECT id, indicator_type, indicator_value, reputation, confidence FROM threat_intel_iocs WHERE tenant_id IN (${tenantPlaceholders}) AND (indicator_value ILIKE '%' || $1 || '%' OR context ILIKE '%' || $1 || '%') LIMIT $${tenantIds.length + 2}`,
          [q, ...tenantParams, limit]
        ),
      ]);

      const results = {
        assets: assetsRes.rows.map(r => ({ id: r.id, hostname: r.hostname, ipAddress: r.ip_address, operatingSystem: r.operating_system, riskLevel: r.risk_level })),
        users: usersRes.rows.map(r => ({ id: r.id, userName: r.user_name, email: r.email, department: r.department, accountType: r.account_type, riskLevel: r.risk_level })),
        incidents: incidentsRes.rows.map(r => ({ id: r.id, title: r.title, severity: r.severity, status: r.status })),
        events: eventsRes.rows.map(r => ({ id: r.id, eventType: r.event_type, threat: r.threat, severity: r.severity })),
        tickets: ticketsRes.rows.map(r => ({ id: r.id, title: r.title, priority: r.priority, status: r.status })),
        knowledgeBase: docsRes.rows.map(r => ({ id: r.id, title: r.title, category: r.category })),
        projects: projectsRes.rows.map(r => ({ id: r.id, name: r.name, status: r.status })),
        reports: reportsRes.rows.map(r => ({ id: r.id, title: r.title, reportType: r.report_type, period: r.period })),
        iocs: iocsRes.rows.map(r => ({ id: r.id, type: r.indicator_type, value: r.indicator_value, reputation: r.reputation, confidence: r.confidence })),
      };

      const totalCount = Object.values(results).reduce((sum, arr) => sum + arr.length, 0);

      res.json({ results, totalCount });
    } catch (error: any) {
      console.error("[Global Search Error]", error.message);
      res.status(500).json({ message: error.message });
    }
  });

