  interface AdvSearchRule {
    field: string;
    op: string;
    value: any;
  }

  interface AdvSearchGroup {
    operator: string;
    rules: (AdvSearchRule | AdvSearchGroup)[];
  }

  function isAdvSearchGroup(item: AdvSearchRule | AdvSearchGroup): item is AdvSearchGroup {
    return "operator" in item && "rules" in item;
  }

  function buildSqlWhereClause(
    query: AdvSearchGroup,
    params: any[],
    fieldMap: Record<string, string>
  ): string {
    if (!query.rules || query.rules.length === 0) return "TRUE";

    const clauses: string[] = [];

    for (const rule of query.rules) {
      if (isAdvSearchGroup(rule)) {
        const nested = buildSqlWhereClause(rule, params, fieldMap);
        if (nested && nested !== "TRUE") {
          clauses.push(`(${nested})`);
        }
      } else {
        const col = fieldMap[rule.field];
        if (!col) continue;

        const quotedCol = `"${col}"`;
        let clause = "";

        switch (rule.op) {
          case "contains": {
            params.push(`%${rule.value}%`);
            clause = `${quotedCol}::text ILIKE $${params.length}`;
            break;
          }
          case "starts_with": {
            params.push(`${rule.value}%`);
            clause = `${quotedCol}::text ILIKE $${params.length}`;
            break;
          }
          case "ends_with": {
            params.push(`%${rule.value}`);
            clause = `${quotedCol}::text ILIKE $${params.length}`;
            break;
          }
          case "equals": {
            params.push(rule.value);
            clause = `${quotedCol}::text = $${params.length}`;
            break;
          }
          case "not_equals": {
            params.push(rule.value);
            clause = `${quotedCol}::text != $${params.length}`;
            break;
          }
          case "gt": {
            params.push(rule.value);
            clause = `${quotedCol} > $${params.length}`;
            break;
          }
          case "lt": {
            params.push(rule.value);
            clause = `${quotedCol} < $${params.length}`;
            break;
          }
          case "between": {
            let v1: any, v2: any;
            if (Array.isArray(rule.value) && rule.value.length === 2) {
              v1 = rule.value[0]; v2 = rule.value[1];
            } else if (rule.value && rule.value2) {
              v1 = rule.value; v2 = rule.value2;
            }
            if (v1 !== undefined && v2 !== undefined) {
              params.push(v1);
              const p1 = params.length;
              params.push(v2);
              const p2 = params.length;
              clause = `${quotedCol} BETWEEN $${p1} AND $${p2}`;
            }
            break;
          }
          case "in": {
            let values: any[] = [];
            if (Array.isArray(rule.value)) {
              values = rule.value;
            } else if (typeof rule.value === "string" && rule.value.includes(",")) {
              values = rule.value.split(",").map((v: string) => v.trim()).filter(Boolean);
            } else if (rule.value) {
              values = [rule.value];
            }
            if (values.length > 0) {
              const placeholders = values.map((v: any) => {
                params.push(v);
                return `$${params.length}`;
              });
              clause = `${quotedCol}::text IN (${placeholders.join(", ")})`;
            }
            break;
          }
          case "is_empty": {
            clause = `(${quotedCol} IS NULL OR ${quotedCol}::text = '')`;
            break;
          }
          case "is_not_empty": {
            clause = `(${quotedCol} IS NOT NULL AND ${quotedCol}::text != '')`;
            break;
          }
          case "in_subnet": {
            params.push(`${rule.value}.%`);
            clause = `${quotedCol}::text ILIKE $${params.length}`;
            break;
          }
          case "last_n_days": {
            const days = parseInt(rule.value, 10);
            if (!isNaN(days) && days > 0) {
              clause = `${quotedCol} >= NOW() - INTERVAL '${days} days'`;
            }
            break;
          }
          case "after": {
            params.push(rule.value);
            clause = `${quotedCol} > $${params.length}`;
            break;
          }
          case "before": {
            params.push(rule.value);
            clause = `${quotedCol} < $${params.length}`;
            break;
          }
          default:
            continue;
        }

        if (clause) {
          clauses.push(clause);
        }
      }
    }

    if (clauses.length === 0) return "TRUE";

    const op = query.operator?.toUpperCase() || "AND";

    switch (op) {
      case "AND":
        return clauses.join(" AND ");
      case "OR":
        return clauses.join(" OR ");
      case "NOT":
        return `NOT (${clauses.join(" AND ")})`;
      case "NOR":
        return `NOT (${clauses.join(" OR ")})`;
      default:
        return clauses.join(" AND ");
    }
  }

  const advancedSearchBodySchema = z.object({
    tenantId: z.number(),
    query: z.object({
      operator: z.string(),
      rules: z.array(z.any()),
    }),
    page: z.number().optional().default(1),
    limit: z.number().optional().default(50),
    sortBy: z.string().optional(),
    sortDir: z.enum(["asc", "desc"]).optional().default("desc"),
  });

  app.post("/api/advanced-search/:module", isAuthenticated, async (req: any, res) => {
    try {
      const moduleName = req.params.module;
      const moduleConfig = MODULE_FIELD_MAPS[moduleName];
      if (!moduleConfig) {
        return res.status(400).json({ message: `Unknown module: ${moduleName}. Valid modules: ${Object.keys(MODULE_FIELD_MAPS).join(", ")}` });
      }

      const parsed = advancedSearchBodySchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Invalid request body", errors: parsed.error.issues });
      }

      const { tenantId, query, page, limit, sortBy, sortDir } = parsed.data;
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      const params: any[] = [];
      const whereClause = buildSqlWhereClause(query, params, moduleConfig.fields);

      const tenantPlaceholders = tenantIds.map((id) => {
        params.push(id);
        return `$${params.length}`;
      });
      const tenantFilter = `tenant_id IN (${tenantPlaceholders.join(", ")})`;

      const fullWhere = `${tenantFilter} AND (${whereClause})`;

      let orderClause = "id DESC";
      if (sortBy) {
        const sortCol = moduleConfig.fields[sortBy] || sortBy;
        if (Object.values(moduleConfig.fields).includes(sortCol) || sortCol === "id") {
          orderClause = `"${sortCol}" ${sortDir === "asc" ? "ASC" : "DESC"}`;
        }
      }

      const offset = (page - 1) * limit;

      const countQuery = `SELECT COUNT(*) as total FROM "${moduleConfig.table}" WHERE ${fullWhere}`;
      const countResult = await pool.query(countQuery, params);
      const total = parseInt(countResult.rows[0]?.total || "0", 10);

      const dataParams = [...params];
      dataParams.push(limit);
      const limitIdx = dataParams.length;
      dataParams.push(offset);
      const offsetIdx = dataParams.length;

      const dataQuery = `SELECT * FROM "${moduleConfig.table}" WHERE ${fullWhere} ORDER BY ${orderClause} LIMIT $${limitIdx} OFFSET $${offsetIdx}`;
      const dataResult = await pool.query(dataQuery, dataParams);

      const MODULE_ALIASES: Record<string, Record<string, string>> = {
        assets: { userName: "user" },
      };
      const aliases = MODULE_ALIASES[moduleName] || {};

      const camelRows = dataResult.rows.map((row: any) => {
        const out: any = {};
        for (const [key, val] of Object.entries(row)) {
          const camel = key.replace(/_([a-z])/g, (_, c) => c.toUpperCase());
          out[camel] = val;
          if (aliases[camel]) {
            out[aliases[camel]] = val;
          }
        }
        return out;
      });

      res.json({
        data: camelRows,
        total,
        totalPages: Math.ceil(total / limit),
        page,
        limit,
      });
    } catch (error: any) {
      console.error("[Advanced Search] Error:", error.message);
      res.status(500).json({ message: error.message });
    }
  });

