  // --- Compare Reports ---
  app.get("/api/reports/:tenantId/compare", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = Number(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const { report1, report2 } = req.query;
      if (!report1 || !report2) {
        return res.status(400).json({ message: "report1 and report2 query params required" });
      }
      const r1 = await pool.query(`SELECT * FROM reports WHERE id = $1 AND tenant_id = $2`, [Number(report1), tenantId]);
      const r2 = await pool.query(`SELECT * FROM reports WHERE id = $1 AND tenant_id = $2`, [Number(report2), tenantId]);
      if (!r1.rows[0] || !r2.rows[0]) {
        return res.status(404).json({ message: "One or both reports not found" });
      }
      const a = r1.rows[0];
      const b = r2.rows[0];
      const dataA = typeof a.data === "string" ? JSON.parse(a.data) : (a.data || {});
      const dataB = typeof b.data === "string" ? JSON.parse(b.data) : (b.data || {});

      function extractScore(d: any, ...keys: string[]): number | null {
        for (const k of keys) {
          if (d[k] !== undefined && d[k] !== null) return Number(d[k]);
          if (d.executiveSummary?.[k] !== undefined) return Number(d.executiveSummary[k]);
          if (d.overview?.[k] !== undefined) return Number(d.overview[k]);
        }
        return null;
      }

      function countFindings(d: any): number {
        if (Array.isArray(d.findings)) return d.findings.length;
        if (Array.isArray(d.keyFindings)) return d.keyFindings.length;
        if (Array.isArray(d.criticalFindings)) return d.criticalFindings.length;
        return 0;
      }

      const riskA = extractScore(dataA, "riskScore", "overallRiskScore", "riskLevel");
      const riskB = extractScore(dataB, "riskScore", "overallRiskScore", "riskLevel");
      const matA = extractScore(dataA, "maturityScore", "overallMaturity", "maturityLevel");
      const matB = extractScore(dataB, "maturityScore", "overallMaturity", "maturityLevel");
      const findA = countFindings(dataA);
      const findB = countFindings(dataB);

      const improved: string[] = [];
      const degraded: string[] = [];
      const unchanged: string[] = [];

      if (riskA !== null && riskB !== null) {
        if (riskB < riskA) improved.push("Risk score decreased (improved)");
        else if (riskB > riskA) degraded.push("Risk score increased");
        else unchanged.push("Risk score unchanged");
      }
      if (matA !== null && matB !== null) {
        if (matB > matA) improved.push("Maturity score improved");
        else if (matB < matA) degraded.push("Maturity score decreased");
        else unchanged.push("Maturity score unchanged");
      }
      if (findB < findA) improved.push("Fewer findings reported");
      else if (findB > findA) degraded.push("More findings reported");
      else unchanged.push("Finding count unchanged");

      res.json({
        reportA: { id: a.id, title: a.title, type: a.report_type, createdAt: a.created_at, data: dataA },
        reportB: { id: b.id, title: b.title, type: b.report_type, createdAt: b.created_at, data: dataB },
        deltas: {
          riskScore: riskA !== null && riskB !== null ? { before: riskA, after: riskB, change: riskB - riskA } : null,
          maturityScore: matA !== null && matB !== null ? { before: matA, after: matB, change: matB - matA } : null,
          findings: { before: findA, after: findB, change: findB - findA },
        },
        summary: { improved, degraded, unchanged },
      });
    } catch (error: any) {
      console.error("[Compare Reports] Error:", error.message);
      res.status(500).json({ message: error.message });
    }
  });

