  app.get("/api/device-posture/:tenantId/assess", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      const [policiesResult, assetsResult] = await Promise.all([
        pool.query(`SELECT * FROM device_posture_policies WHERE tenant_id = $1 AND is_active = true`, [tenantId]),
        pool.query(`SELECT id, hostname, ip_address, operating_system, status, risk_level, risk_score,
                           device_health, vulnerability_count, last_seen, software_inventory, enrichment_data
                    FROM assets WHERE tenant_id = $1`, [tenantId]),
      ]);

      const policies = policiesResult.rows;
      const assets = assetsResult.rows;
      const { lookupEOL } = await import("./eol-database");

      function deriveOsFamily(os: string | null): string {
        if (!os) return "Unknown";
        const lower = os.toLowerCase();
        if (lower.includes("windows")) return "Windows";
        if (lower.includes("ubuntu") || lower.includes("debian") || lower.includes("centos") || lower.includes("rhel") || lower.includes("red hat") || lower.includes("fedora") || lower.includes("suse") || lower.includes("linux")) return "Linux";
        if (lower.includes("aix")) return "AIX";
        if (lower.includes("vios")) return "VIOS";
        if (lower.includes("macos") || lower.includes("mac os") || lower.includes("darwin")) return "macOS";
        if (lower.includes("solaris") || lower.includes("sunos")) return "Solaris";
        if (lower.includes("vmware") || lower.includes("esxi")) return "VMware";
        return "Other";
      }

      function hasEdr(asset: any): boolean {
        const sw = asset.software_inventory;
        if (Array.isArray(sw)) {
          const edrPatterns = /crowdstrike|falcon|sentinelone|sentinel one|defender|cynet|sophos|trend\s*micro|eset|kaspersky|bitdefender|symantec|mcafee|trellix|carbon\s*black|cortex\s*xdr|cylance/i;
          if (sw.some((s: any) => edrPatterns.test(s.name || s))) return true;
        }
        const enrichment = asset.enrichment_data || {};
        if (enrichment.edrAgent || enrichment.hasEdr) return true;
        const agentVersion = asset.agent_version;
        if (agentVersion && agentVersion.length > 0) return true;
        return false;
      }

      function evaluateRule(rule: any, deviceData: any): boolean {
        const { field, operator, value } = rule;
        const deviceValue = deviceData[field];
        if (deviceValue === undefined || deviceValue === null) {
          if (operator === "not_equals" || operator === "not_contains" || operator === "not_in") return true;
          return false;
        }
        const dv = String(deviceValue).toLowerCase();
        const rv = Array.isArray(value) ? value.map((v: string) => v.toLowerCase()) : String(value).toLowerCase();

        switch (operator) {
          case "equals": return dv === rv;
          case "not_equals": return dv !== rv;
          case "contains": return dv.includes(rv as string);
          case "not_contains": return !dv.includes(rv as string);
          case "in": {
            const arr = Array.isArray(value) ? value.map((v: string) => v.toLowerCase().trim()) : String(value).split(",").map((v: string) => v.toLowerCase().trim());
            return arr.includes(dv);
          }
          case "not_in": {
            const arr2 = Array.isArray(value) ? value.map((v: string) => v.toLowerCase().trim()) : String(value).split(",").map((v: string) => v.toLowerCase().trim());
            return !arr2.includes(dv);
          }
          case "less_than": return parseFloat(deviceValue) < parseFloat(value as string);
          case "greater_than": return parseFloat(deviceValue) > parseFloat(value as string);
          default: return true;
        }
      }

      const enrichedAssets = assets.map((a: any) => {
        const os = a.operating_system || "";
        const osFamily = deriveOsFamily(os);
        let eolStatus = "Unknown";
        let eosStatus = "Unknown";
        const enrichment = a.enrichment_data || {};
        if (enrichment.eolDate || enrichment.eosDate) {
          eolStatus = enrichment.eolStatus || "Unknown";
          eosStatus = enrichment.eosStatus || "Unknown";
        } else if (os) {
          const eolResult = lookupEOL(os, os);
          if (eolResult) {
            eolStatus = eolResult.eolStatus;
            eosStatus = eolResult.eosStatus;
          }
        }
        const lastSeenDays = a.last_seen ? Math.floor((Date.now() - new Date(a.last_seen).getTime()) / (1000 * 60 * 60 * 24)) : 9999;

        return {
          id: a.id,
          hostname: a.hostname,
          ip_address: a.ip_address,
          os_family: osFamily,
          operating_system: os,
          status: a.status || "active",
          risk_level: a.risk_level || "unknown",
          risk_score: a.risk_score || 0,
          device_health: a.device_health || "unknown",
          vulnerability_count: a.vulnerability_count || 0,
          has_edr: hasEdr(a) ? "yes" : "no",
          last_seen_days: lastSeenDays,
          eol_status: eolStatus,
          eos_status: eosStatus,
          cis_score: a.cis_score ?? null,
          criticality: a.criticality ?? null,
        };
      });

      const policyResults = policies.map((policy: any) => {
        const rules = policy.rules || [];
        let compliant = 0;
        let nonCompliant = 0;
        const failingDevices: any[] = [];

        for (const device of enrichedAssets) {
          const failedRules: string[] = [];
          for (const rule of rules) {
            if (!evaluateRule(rule, device)) {
              failedRules.push(`${rule.field} ${rule.operator} ${Array.isArray(rule.value) ? rule.value.join(",") : rule.value}`);
            }
          }
          if (failedRules.length > 0) {
            nonCompliant++;
            if (failingDevices.length < 200) {
              failingDevices.push({
                id: device.id,
                hostname: device.hostname,
                ipAddress: device.ip_address,
                osFamily: device.os_family,
                operatingSystem: device.operating_system,
                status: device.status,
                cisScore: device.cis_score ?? null,
                criticality: device.criticality ?? null,
                failedRules,
                failedCount: failedRules.length,
              });
            }
          } else {
            compliant++;
          }
        }

        return {
          policyId: policy.id,
          policyName: policy.name,
          description: policy.description,
          rulesCount: rules.length,
          compliant,
          nonCompliant,
          total: enrichedAssets.length,
          complianceRate: enrichedAssets.length > 0 ? Math.round((compliant / enrichedAssets.length) * 100) : 0,
          failingDevices,
        };
      });

      const nonCompliantDeviceIds = new Set<number>();
      for (const pr of policyResults) {
        const policyRules = (policies.find((p: any) => p.id === pr.policyId)?.rules) || [];
        for (const device of enrichedAssets) {
          if (nonCompliantDeviceIds.has(device.id)) continue;
          for (const rule of policyRules) {
            if (!evaluateRule(rule, device)) {
              nonCompliantDeviceIds.add(device.id);
              break;
            }
          }
        }
      }
      const overallNonCompliant = nonCompliantDeviceIds.size;
      const overallCompliant = enrichedAssets.length - overallNonCompliant;

      res.json({
        summary: {
          totalDevices: enrichedAssets.length,
          compliant: overallCompliant,
          nonCompliant: overallNonCompliant,
          complianceRate: enrichedAssets.length > 0 ? Math.round((overallCompliant / enrichedAssets.length) * 100) : 0,
          activePolicies: policies.length,
        },
        policies: policyResults,
      });
    } catch (error: any) {
      console.error("Device posture assessment error:", error);
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // ── Threat Intelligence Feed Management ──

