  app.post("/api/attack-paths/:tenantId/narrative", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const { nodeId, nodeName, paths, blastRadius } = req.body;
      if (!paths || !Array.isArray(paths)) return res.status(400).json({ message: "paths required" });

      const graph = await buildAttackGraph(pool, tenantId);
      const nodeInfo = graph.nodes.find(n => n.id === nodeId);
      const crownJewelNames = graph.nodes.filter(n => n.isCrownJewel).map(n => n.label).slice(0, 5).join(", ");

      const pathDescriptions = paths.slice(0, 3).map((p: any, i: number) => {
        const nodeLabels = p.nodes.map((id: string) => graph.nodes.find(n => n.id === id)?.label || id).join(" → ");
        return `Path ${i + 1}: ${nodeLabels} (${p.hops} hops, techniques: ${p.techniques.slice(0, 2).join(", ") || "Network traversal"})`;
      }).join("\n");

      const prompt = `You are a senior threat analyst. Generate a concise (3-4 sentences) plain-English attack path narrative for a SOC team.

Compromised Node: "${nodeName || nodeId}" (risk score: ${nodeInfo?.riskScore || "unknown"}, type: ${nodeInfo?.type || "device"})
Crown Jewel Assets in Environment: ${crownJewelNames || "none tagged"}
Blast Radius: ${blastRadius?.reachable || 0} assets reachable within 2 hops, ${blastRadius?.crownJewelsReachable || 0} crown jewels at risk

Attack Paths:
${pathDescriptions || "No direct paths to crown jewels identified."}

Write a concise, actionable narrative explaining the most critical attack path and immediate recommended containment. Be specific about asset names and techniques.`;

      const completion = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        max_tokens: 350,
      });

      res.json({ narrative: completion.choices[0].message.content });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: "AI narrative unavailable" });
    }
  });

