  app.get("/api/hunt/:tenantId/pivot", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const { entity, entityType } = req.query;
      if (!entity) return res.status(400).json({ message: "entity parameter required" });

      const placeholders = tenantIds.map((_: any, i: number) => `$${i + 1}`).join(",");
      const entityVal = `%${String(entity)}%`;
      const pIdx = tenantIds.length + 1;

      let entityCondition: string;
      switch (entityType) {
        case "ip":
          entityCondition = `(source_ip ILIKE $${pIdx} OR destination_ip ILIKE $${pIdx})`;
          break;
        case "hostname":
          entityCondition = `(asset ILIKE $${pIdx} OR target ILIKE $${pIdx})`;
          break;
        case "user":
          entityCondition = `(attacker ILIKE $${pIdx} OR target ILIKE $${pIdx})`;
          break;
        case "hash":
          entityCondition = `(threat ILIKE $${pIdx} OR attacker ILIKE $${pIdx})`;
          break;
        default:
          entityCondition = `(source_ip ILIKE $${pIdx} OR destination_ip ILIKE $${pIdx} OR attacker ILIKE $${pIdx} OR target ILIKE $${pIdx} OR asset ILIKE $${pIdx} OR threat ILIKE $${pIdx})`;
      }

      const eventsResult = await pool.query(
        `SELECT * FROM security_events WHERE tenant_id IN (${placeholders}) AND ${entityCondition}
         ORDER BY occurred_at DESC LIMIT 200`,
        [...tenantIds, entityVal]
      );

      const incidentsResult = await pool.query(
        `SELECT * FROM incidents WHERE tenant_id IN (${placeholders}) AND (
          source_ip ILIKE $${pIdx} OR destination_ip ILIKE $${pIdx} OR affected_assets ILIKE $${pIdx} OR title ILIKE $${pIdx} OR description ILIKE $${pIdx}
        ) ORDER BY created_at DESC LIMIT 100`,
        [...tenantIds, entityVal]
      );

      const sourceSummary: Record<string, number> = {};
      for (const evt of eventsResult.rows) {
        const src = evt.event_type || "unknown";
        sourceSummary[src] = (sourceSummary[src] || 0) + 1;
      }

      const timeline = eventsResult.rows.map((evt: any) => ({
        id: evt.id,
        type: "event" as const,
        timestamp: evt.occurred_at || evt.created_at,
        source: evt.event_type,
        severity: evt.severity,
        summary: evt.threat || evt.action || "Event",
        logSource: evt.log_source,
      })).concat(incidentsResult.rows.map((inc: any) => ({
        id: inc.id,
        type: "incident" as const,
        timestamp: inc.created_at,
        source: inc.source,
        severity: inc.severity,
        summary: inc.title,
        logSource: inc.detection_source,
      }))).sort((a: any, b: any) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      res.json({
        entity: String(entity),
        entityType: entityType || "auto",
        events: eventsResult.rows,
        incidents: incidentsResult.rows,
        sourceSummary,
        timeline,
        totalEvents: eventsResult.rows.length,
        totalIncidents: incidentsResult.rows.length,
      });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // NL Hunt: typeahead/autocomplete suggestions (dimension-aware)
  app.get("/api/hunt/:tenantId/typeahead", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const partial = String(req.query.q || "").slice(0, 200);
      const { getTypeaheadSuggestions, buildContextSuggestions } = await import("./nl-hunt-engine.js");

      // Fetch real tenant event dimensions for context-aware suggestions
      let contextTemplates: string[] = [];
      try {
        const ph = tenantIds.map((_: any, i: number) => `$${i + 1}`).join(",");
        const dimRes = await pool.query(
          `SELECT
            array_agg(DISTINCT event_type::text) FILTER (WHERE event_type IS NOT NULL) AS event_types,
            array_agg(DISTINCT mitre_tactic::text) FILTER (WHERE mitre_tactic IS NOT NULL) AS tactics,
            array_agg(DISTINCT log_source::text) FILTER (WHERE log_source IS NOT NULL) AS log_sources
           FROM (SELECT event_type, mitre_tactic, log_source FROM security_events WHERE tenant_id IN (${ph}) LIMIT 5000) sub`,
          tenantIds
        );
        const row = dimRes.rows[0] || {};
        contextTemplates = buildContextSuggestions(
          (row.event_types || []).slice(0, 5),
          (row.tactics || []).filter(Boolean).slice(0, 5),
          (row.log_sources || []).filter(Boolean).slice(0, 3)
        );
      } catch (e) {
        // non-fatal — fall back to base templates
      }

      const suggestions = getTypeaheadSuggestions(partial, contextTemplates);
      res.json({ suggestions });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/hunt/:tenantId/nl-query", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });
      await assertTenantAccess(req, tenantId);
      const { nlQuery, limit = 50, explain = false } = req.body;
      if (!nlQuery || typeof nlQuery !== "string" || nlQuery.trim().length < 3) {
        return res.status(400).json({ message: "nlQuery must be at least 3 characters" });
      }
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const { translateNLToHunt, buildSafeQuery, generateEventExplanation } = await import("./nl-hunt-engine.js");
      const translation = await translateNLToHunt(nlQuery.trim(), tenantId, tenantIds);

      // Build fully parameterized query — no AI SQL ever reaches the DB
      const tenantPlaceholders = tenantIds.map((_: any, i: number) => `$${i + 1}`).join(",");
      const tenantParams: any[] = [...tenantIds];

      const { clauses, params: filterParams } = buildSafeQuery(
        translation.resolvedFilters,
        tenantIds.length + 1
      );

      const allParams = [...tenantParams, ...filterParams];
      const whereFilter = clauses.length > 0 ? `AND (${clauses.join(" AND ")})` : "";
      const queryLimit = Math.min(parseInt(String(limit)) || 50, 200);

      const eventsRes = await pool.query(
        `SELECT id, event_type, severity, threat, target, attacker, asset, app, description,
                mitre_tactic, mitre_technique, log_source, occurred_at, country, action, risk_score
         FROM security_events
         WHERE tenant_id IN (${tenantPlaceholders}) ${whereFilter}
         ORDER BY occurred_at DESC
         LIMIT ${queryLimit}`,
        allParams
      );

      const events = eventsRes.rows;
      const totalCount = events.length;

      const severityCounts: Record<string, number> = {};
      const mitreTactics = new Set<string>();
      for (const e of events) {
        severityCounts[e.severity] = (severityCounts[e.severity] || 0) + 1;
        if (e.mitre_tactic) mitreTactics.add(e.mitre_tactic);
      }
      const criticalHigh = (severityCounts.critical || 0) + (severityCounts.high || 0);
      const hostSet = new Set(events.map((e: any) => e.asset || e.target).filter(Boolean));

      const resultSummary = `Found ${totalCount} event${totalCount !== 1 ? "s" : ""} matching ${translation.searchDescription}.${criticalHigh > 0 ? ` ${criticalHigh} are high or critical severity.` : ""} ${mitreTactics.size > 0 ? `MITRE tactics: ${[...mitreTactics].slice(0, 3).join(", ")}.` : ""} ${hostSet.size > 0 ? `${hostSet.size} unique asset${hostSet.size > 1 ? "s" : ""} affected.` : ""}`.trim();

      // Generate per-event AI explanations for top results (up to 10)
      const eventsWithExplanations = [...events];
      if (explain && events.length > 0) {
        const topN = events.slice(0, 10);
        const explanations = await Promise.allSettled(
          topN.map((e: any) => generateEventExplanation(e, nlQuery.trim()))
        );
        for (let i = 0; i < topN.length; i++) {
          const result = explanations[i];
          eventsWithExplanations[i] = {
            ...eventsWithExplanations[i],
            aiExplanation: result.status === "fulfilled" ? result.value : "Matched hunt criteria.",
          };
        }
      }

      res.json({
        events: eventsWithExplanations,
        totalCount,
        resultSummary,
        naturalLanguageSummary: translation.naturalLanguageSummary,
        resolvedFilters: translation.resolvedFilters,
        searchDescription: translation.searchDescription,
        suggestions: translation.suggestions,
        severityCounts,
        mitreTactics: [...mitreTactics],
      });
    } catch (error: any) {
      console.error("[NL Hunt] Error:", error.message);
      res.status(500).json({ message: error.message });
    }
  });

