  app.post("/api/bas/:tenantId/run", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const { scenarioId } = req.body;
      if (!scenarioId) return res.status(400).json({ message: "scenarioId required" });

      const [scenario] = await db.select().from(basScenarios)
        .where(and(eq(basScenarios.id, scenarioId), eq(basScenarios.tenantId, tenantId)));
      if (!scenario) return res.status(404).json({ message: "Scenario not found" });

      const [run] = await db.insert(basRuns).values({
        tenantId,
        scenarioId,
        status: "pending",
        triggeredBy: req.user?.username || "system",
      }).returning();

      // Run async (fire and forget with background exec)
      setImmediate(async () => {
        try {
          await runBASScenario(run.id, scenario);
        } catch (e) {
          console.error("[BAS] Run failed:", e);
        }
      });

      res.status(202).json({ runId: run.id, status: "pending", message: "BAS simulation started" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/bas/:tenantId/dashboard", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);

      const runs = await db.select({
        id: basRuns.id,
        overallScore: basRuns.overallScore,
        detectionScore: basRuns.detectionScore,
        preventionScore: basRuns.preventionScore,
        exposureScore: basRuns.exposureScore,
        status: basRuns.status,
        scenarioCategory: basScenarios.category,
        completedAt: basRuns.completedAt,
      })
        .from(basRuns)
        .leftJoin(basScenarios, eq(basRuns.scenarioId, basScenarios.id))
        .where(and(eq(basRuns.tenantId, tenantId), eq(basRuns.status, "completed")));

      const scenarioCount = await db.select({ id: basScenarios.id })
        .from(basScenarios)
        .where(and(eq(basScenarios.tenantId, tenantId), eq(basScenarios.isActive, true)));

      const avgOverall = runs.length ? Math.round(runs.reduce((s, r) => s + (r.overallScore || 0), 0) / runs.length) : 0;
      const avgDetection = runs.length ? Math.round(runs.reduce((s, r) => s + (r.detectionScore || 0), 0) / runs.length) : 0;
      const avgPrevention = runs.length ? Math.round(runs.reduce((s, r) => s + (r.preventionScore || 0), 0) / runs.length) : 0;
      const avgExposure = runs.length ? Math.round(runs.reduce((s, r) => s + (r.exposureScore || 0), 0) / runs.length) : 0;

      // Category breakdown
      const categoryMap: Record<string, { totalScore: number; count: number }> = {};
      for (const r of runs) {
        if (r.scenarioCategory) {
          if (!categoryMap[r.scenarioCategory]) categoryMap[r.scenarioCategory] = { totalScore: 0, count: 0 };
          categoryMap[r.scenarioCategory].totalScore += r.overallScore || 0;
          categoryMap[r.scenarioCategory].count++;
        }
      }
      const categoryBreakdown = Object.entries(categoryMap).map(([cat, v]) => ({
        category: cat,
        avgScore: Math.round(v.totalScore / v.count),
        runs: v.count,
      }));

      res.json({
        totalRuns: runs.length,
        totalScenarios: scenarioCount.length,
        avgOverallScore: avgOverall,
        avgDetectionScore: avgDetection,
        avgPreventionScore: avgPrevention,
        avgExposureScore: avgExposure,
        categoryBreakdown,
        trend: runs.slice(-10).map(r => ({ date: r.completedAt, score: r.overallScore })),
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

