  // Shared intel feed — platform-wide anonymized IOCs (no tenant attribution)
  app.get("/api/shared-intel/feed", isAuthenticated, async (req: any, res) => {
    try {
      await ensureFederatedIntelTables();
      const { iocType, reputation, page = "1", pageSize = "50" } = req.query;
      const parsedPage = Math.max(1, parseInt(page as string, 10) || 1);
      const parsedSize = Math.min(100, parseInt(pageSize as string, 10) || 50);
      const offset = (parsedPage - 1) * parsedSize;

      // Build shared WHERE clause (apply same filters to both count and data queries)
      const filterParams: (string | number)[] = [];
      let whereClause = `WHERE is_active = TRUE`;
      if (iocType) { filterParams.push(iocType as string); whereClause += ` AND ioc_type = $${filterParams.length}`; }
      if (reputation) { filterParams.push(reputation as string); whereClause += ` AND reputation = $${filterParams.length}`; }

      const countResult = await pool.query(`SELECT COUNT(*) FROM shared_threat_intel ${whereClause}`, filterParams);
      const total = parseInt(countResult.rows[0].count, 10);

      const dataParams = [...filterParams, parsedSize, offset];
      const dataResult = await pool.query(
        `SELECT * FROM shared_threat_intel ${whereClause} ORDER BY propagated_at DESC LIMIT $${filterParams.length + 1} OFFSET $${filterParams.length + 2}`,
        dataParams
      );

      res.json({ items: dataResult.rows, total });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

