  // Contribution scores (platform-wide leaderboard)
  app.get("/api/shared-intel/contribution-scores", isAuthenticated, async (req: any, res) => {
    try {
      const scores = await getContributionScores();
      // Anonymization: only MSS admin / platform admin can see real tenant names in the leaderboard.
      // Regular tenants see pseudonymous labels (Community Member #N, ranked by contribution_score desc).
      const userId = req.user?.claims?.sub;
      const mssAdminRoles = ["platform_admin", "mss_admin"];
      const adminRes = await pool.query(
        `SELECT 1 FROM tenant_users WHERE user_id = $1 AND role = ANY($2::text[]) LIMIT 1`,
        [userId, mssAdminRoles]
      );
      const isMssAdmin = adminRes.rows.length > 0 || req.session?.isSuperAdmin;
      // Resolve caller's primary tenant (lowest tenant_id) for deterministic own-tenant identification
      const callerTenantRow = await pool.query(
        `SELECT tenant_id FROM tenant_users WHERE user_id = $1 ORDER BY tenant_id ASC LIMIT 1`,
        [userId]
      );
      const callerTenantId = callerTenantRow.rows[0]?.tenant_id ?? null;
      const anonymized = scores.map((entry, idx) => ({
        ...entry,
        tenant_name: isMssAdmin
          ? entry.tenant_name           // Full name visible to admins only
          : entry.tenant_id === callerTenantId
            ? entry.tenant_name         // Own tenant: show real name
            : `Community Member #${idx + 1}`, // Others: pseudonymous label
      }));
      res.json(anonymized);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

