  app.get("/api/cases/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      const { status, severity, priority, search, page = "1", pageSize = "50" } = req.query;
      const pg = parseInt(page as string);
      const ps = parseInt(pageSize as string);
      const offset = (pg - 1) * ps;

      let where = `WHERE c.tenant_id = $1`;
      const params: any[] = [tenantId];
      let idx = 2;

      if (status) { where += ` AND c.status = $${idx++}`; params.push(status); }
      if (severity) { where += ` AND c.severity = $${idx++}`; params.push(severity); }
      if (priority) { where += ` AND c.priority = $${idx++}`; params.push(priority); }
      if (search) { where += ` AND (c.title ILIKE $${idx} OR c.description ILIKE $${idx})`; params.push(`%${search}%`); idx++; }

      const countResult = await pool.query(`SELECT COUNT(*) as total FROM cases c ${where}`, params);
      const total = parseInt(countResult.rows[0].total);

      const result = await pool.query(
        `SELECT c.*,
          (SELECT COUNT(*) FROM case_incidents ci WHERE ci.case_id = c.id) as incident_count,
          (SELECT COUNT(*) FROM case_evidence ce WHERE ce.case_id = c.id) as evidence_count,
          (SELECT COUNT(*) FROM case_timeline ct WHERE ct.case_id = c.id) as timeline_count
        FROM cases c ${where}
        ORDER BY c.created_at DESC
        LIMIT $${idx} OFFSET $${idx + 1}`,
        [...params, ps, offset]
      );

      res.json({ cases: result.rows, total, page: pg, pageSize: ps, totalPages: Math.ceil(total / ps) });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

