  app.patch("/api/cases/:tenantId/:caseId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const caseId = parseInt(req.params.caseId);
      const access = await assertTenantAccess(req, tenantId);
      const { title, description, severity, status, priority, assigneeId, mitreTactics, tags } = req.body;

      const existing = await pool.query(`SELECT * FROM cases WHERE id = $1 AND tenant_id = $2`, [caseId, tenantId]);
      if (existing.rows.length === 0) return res.status(404).json({ message: "Case not found" });

      const sets: string[] = [];
      const vals: any[] = [];
      let idx = 1;
      if (title !== undefined) { sets.push(`title = $${idx++}`); vals.push(title); }
      if (description !== undefined) { sets.push(`description = $${idx++}`); vals.push(description); }
      if (severity !== undefined) { sets.push(`severity = $${idx++}`); vals.push(severity); }
      if (status !== undefined) { sets.push(`status = $${idx++}`); vals.push(status); }
      if (priority !== undefined) { sets.push(`priority = $${idx++}`); vals.push(priority); }
      if (assigneeId !== undefined) { sets.push(`assignee_id = $${idx++}`); vals.push(assigneeId); }
      if (mitreTactics !== undefined) { sets.push(`mitre_tactics = $${idx++}`); vals.push(mitreTactics); }
      if (tags !== undefined) { sets.push(`tags = $${idx++}`); vals.push(tags); }
      sets.push(`updated_at = NOW()`);

      if (sets.length === 1) return res.status(400).json({ message: "No fields to update" });

      const result = await pool.query(
        `UPDATE cases SET ${sets.join(", ")} WHERE id = $${idx} AND tenant_id = $${idx + 1} RETURNING *`,
        [...vals, caseId, tenantId]
      );

      const changes: string[] = [];
      if (status !== undefined && status !== existing.rows[0].status) changes.push(`Status changed to ${status}`);
      if (severity !== undefined && severity !== existing.rows[0].severity) changes.push(`Severity changed to ${severity}`);
      if (priority !== undefined && priority !== existing.rows[0].priority) changes.push(`Priority changed to ${priority}`);
      if (assigneeId !== undefined && assigneeId !== existing.rows[0].assignee_id) changes.push(`Assigned to ${assigneeId}`);

      if (changes.length > 0) {
        await pool.query(
          `INSERT INTO case_timeline (case_id, action, actor, details) VALUES ($1, $2, $3, $4)`,
          [caseId, "Case Updated", access.userId, changes.join("; ")]
        );
      }

      res.json(result.rows[0]);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

