  app.put("/api/tenants/:id/retention-policy", isAuthenticated, async (req: any, res) => {
    try {
      const access = await getUserTenantAccess(req);
      if (!access.isPlatformAdmin && !access.isMSS) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const tenantId = parseInt(req.params.id);
      const { retentionHotDays, retentionWarmDays, retentionColdDays, archiveStorageProvider } = req.body;

      const schema = z.object({
        retentionHotDays: z.number().int().min(1).max(365).optional(),
        retentionWarmDays: z.number().int().min(1).max(3650).optional(),
        retentionColdDays: z.number().int().min(1).max(7300).optional(),
        archiveStorageProvider: z.enum(["s3", "azure", "gcs", "minio"]).nullable().optional(),
      });

      const parsed = schema.parse({ retentionHotDays, retentionWarmDays, retentionColdDays, archiveStorageProvider });

      const setClauses: string[] = [];
      const values: any[] = [];
      let idx = 1;

      if (parsed.retentionHotDays !== undefined) {
        setClauses.push(`retention_hot_days = $${idx++}`);
        values.push(parsed.retentionHotDays);
      }
      if (parsed.retentionWarmDays !== undefined) {
        setClauses.push(`retention_warm_days = $${idx++}`);
        values.push(parsed.retentionWarmDays);
      }
      if (parsed.retentionColdDays !== undefined) {
        setClauses.push(`retention_cold_days = $${idx++}`);
        values.push(parsed.retentionColdDays);
      }
      if (parsed.archiveStorageProvider !== undefined) {
        setClauses.push(`archive_storage_provider = $${idx++}`);
        values.push(parsed.archiveStorageProvider);
      }

      if (setClauses.length === 0) {
        return res.status(400).json({ message: "No retention fields provided" });
      }

      values.push(tenantId);
      const result = await pool.query(
        `UPDATE tenants SET ${setClauses.join(", ")} WHERE id = $${idx} RETURNING *`,
        values
      );

      if (result.rows.length === 0) {
        return res.status(404).json({ message: "Tenant not found" });
      }

      await deleteCachePrefix("/api/tenant");
      res.json(result.rows[0]);
    } catch (error: any) {
      if (error.name === "ZodError") {
        return res.status(400).json({ message: "Invalid retention policy", errors: error.errors });
      }
      res.status(error.status || 500).json({ message: error.message || "Failed to update retention policy" });
    }
  });

