  // Warranty & License lookup by serial number
  app.post("/api/assets/:id/warranty-lookup", isAuthenticated, async (req: any, res) => {
    try {
      const assetId = parseInt(req.params.id);
      const asset = await db.select().from(assets).where(eq(assets.id, assetId)).limit(1);
      if (!asset.length) return res.status(404).json({ message: "Asset not found" });
      const a = asset[0];
      const serial = a.biosSerialNumber || req.body.serialNumber;
      const manufacturer = (a.systemManufacturer || "").toLowerCase();

      // Real warranty lookup requires vendor API credentials (Dell TechDirect, HP Warranty, Lenovo Warranty).
      // No external credentials are configured — return honest empty response instead of fabricated dates.
      const lookupData = {
        serial: serial || null,
        manufacturer: a.systemManufacturer || null,
        model: a.systemModel || null,
        purchaseDate: null,
        warrantyExpiry: null,
        warrantyStatus: "unknown",
        daysRemaining: null,
        warrantyType: null,
        supportLevel: null,
        licenseExpiry: null,
        licenseStatus: "unknown",
        lookupTimestamp: new Date().toISOString(),
        lookupSource: "Third-party lookup not configured — manual entry required",
      };

      await db.update(assets).set({
        warrantyExpiry: lookupData.warrantyExpiry ? new Date(lookupData.warrantyExpiry) : null,
        warrantyStatus: lookupData.warrantyStatus,
        purchaseDate: lookupData.purchaseDate ? new Date(lookupData.purchaseDate) : null,
        licenseExpiry: lookupData.licenseExpiry ? new Date(lookupData.licenseExpiry) : null,
        licenseStatus: lookupData.licenseStatus,
        warrantyLookupData: lookupData,
        updatedAt: new Date(),
      }).where(eq(assets.id, assetId));

      res.json(lookupData);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

