  // Asset hardware & OS reports overview
  app.get("/api/asset-inventory/:tenantId/intelligence-reports", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const allAssets = await storage.getAssetsLight(tenantId);

      const countBy = (key: keyof typeof allAssets[0]) => {
        const map: Record<string, number> = {};
        for (const a of allAssets) {
          const v = (a[key] as string) || "Unknown";
          map[v] = (map[v] || 0) + 1;
        }
        return Object.entries(map).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count).slice(0, 20);
      };

      const parseOSFamily = (os: string) => {
        if (!os) return "Unknown";
        const o = os.toLowerCase();
        if (o.includes("windows 11")) return "Windows 11";
        if (o.includes("windows 10")) return "Windows 10";
        if (o.includes("windows server 2022")) return "Windows Server 2022";
        if (o.includes("windows server 2019")) return "Windows Server 2019";
        if (o.includes("windows server 2016")) return "Windows Server 2016";
        if (o.includes("windows")) return "Windows (Other)";
        if (o.includes("ubuntu 22")) return "Ubuntu 22.04";
        if (o.includes("ubuntu 20")) return "Ubuntu 20.04";
        if (o.includes("ubuntu")) return "Ubuntu (Other)";
        if (o.includes("rhel") || o.includes("red hat")) return "Red Hat Enterprise Linux";
        if (o.includes("centos")) return "CentOS";
        if (o.includes("debian")) return "Debian";
        if (o.includes("macos") || o.includes("mac os")) return "macOS";
        if (o.includes("kali")) return "Kali Linux";
        return "Other Linux/Unix";
      };

      const osFamilyMap: Record<string, number> = {};
      for (const a of allAssets) {
        const family = parseOSFamily(a.operatingSystem || "");
        osFamilyMap[family] = (osFamilyMap[family] || 0) + 1;
      }
      const byOSFamily = Object.entries(osFamilyMap).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);

      const parseMemoryGB = (mem: string) => {
        if (!mem) return "Unknown";
        const gb = parseFloat(mem);
        if (isNaN(gb)) return "Unknown";
        if (gb < 4) return "< 4 GB";
        if (gb < 8) return "4–8 GB";
        if (gb < 16) return "8–16 GB";
        if (gb < 32) return "16–32 GB";
        if (gb < 64) return "32–64 GB";
        return "64+ GB";
      };

      const memSizeMap: Record<string, number> = {};
      for (const a of allAssets) {
        const bucket = parseMemoryGB(a.totalPhysicalMemory || "");
        memSizeMap[bucket] = (memSizeMap[bucket] || 0) + 1;
      }
      const byMemorySize = Object.entries(memSizeMap).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);

      const parseProcessorFamily = (proc: string) => {
        if (!proc) return "Unknown";
        const p = proc.toLowerCase();
        if (p.includes("i9")) return "Intel Core i9";
        if (p.includes("i7")) return "Intel Core i7";
        if (p.includes("i5")) return "Intel Core i5";
        if (p.includes("i3")) return "Intel Core i3";
        if (p.includes("xeon")) return "Intel Xeon";
        if (p.includes("amd epyc")) return "AMD EPYC";
        if (p.includes("ryzen 9")) return "AMD Ryzen 9";
        if (p.includes("ryzen 7")) return "AMD Ryzen 7";
        if (p.includes("ryzen 5")) return "AMD Ryzen 5";
        if (p.includes("apple m")) return "Apple Silicon";
        if (p.includes("arm")) return "ARM";
        if (p.includes("intel")) return "Intel (Other)";
        if (p.includes("amd")) return "AMD (Other)";
        return "Unknown";
      };

      const procMap: Record<string, number> = {};
      for (const a of allAssets) {
        const fam = parseProcessorFamily(a.processor || "");
        procMap[fam] = (procMap[fam] || 0) + 1;
      }
      const byProcessorFamily = Object.entries(procMap).map(([name, count]) => ({ name, count })).sort((a, b) => b.count - a.count);

      const warrantyStats = { active: 0, expiring_soon: 0, expired: 0, unknown: 0 };
      for (const a of allAssets) {
        const s = (a.warrantyStatus || "unknown") as keyof typeof warrantyStats;
        warrantyStats[s] = (warrantyStats[s] || 0) + 1;
        if (!a.warrantyStatus) warrantyStats.unknown++;
      }

      res.json({
        total: allAssets.length,
        byOSFamily,
        byOS: countBy("operatingSystem"),
        byDeviceType: countBy("endpointType"),
        byManufacturer: countBy("systemManufacturer"),
        byModel: countBy("systemModel"),
        byMemoryType: countBy("memoryType"),
        byMemorySize,
        byProcessorFamily,
        byProcessor: countBy("processor"),
        byLocation: countBy("assetLocation"),
        byGroup: countBy("assetGroup").concat(countBy("endpointGroup")),
        byDeploymentType: countBy("deploymentType"),
        byCloudProvider: countBy("cloudProvider"),
        byStatus: countBy("status"),
        warrantyStats: Object.entries(warrantyStats).map(([name, count]) => ({ name, count })),
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // User-Asset correlation map
  app.get("/api/asset-inventory/:tenantId/user-asset-map", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const allAssets = await storage.getAssetsLight(tenantId);
      const userMap: Record<string, { user: string; email: string; assetCount: number; assets: { id: number; hostname: string; type: string; os: string; riskLevel: string }[] }> = {};

      for (const a of allAssets) {
        const userName = a.user || a.lastLoggedInUser || a.primaryUserId || null;
        const email = a.primaryUserEmail || (userName ? `${userName.replace(/\s+/g,'.')
          .toLowerCase()}@${tenantId}.internal` : null);
        if (!userName) continue;
        if (!userMap[userName]) {
          userMap[userName] = { user: userName, email: email || "", assetCount: 0, assets: [] };
        }
        userMap[userName].assetCount++;
        userMap[userName].assets.push({ id: a.id, hostname: a.hostname, type: a.endpointType || "Unknown", os: a.operatingSystem || "Unknown", riskLevel: a.riskLevel || "low" });
      }

      res.json({
        totalUsers: Object.keys(userMap).length,
        totalMapped: allAssets.filter(a => a.user || a.lastLoggedInUser || a.primaryUserId).length,
        totalUnmapped: allAssets.filter(a => !a.user && !a.lastLoggedInUser && !a.primaryUserId).length,
        users: Object.values(userMap).sort((a, b) => b.assetCount - a.assetCount),
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // Asset-Control coverage map
  app.get("/api/asset-inventory/:tenantId/control-coverage", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      const allAssets = await storage.getAssetsLight(tenantId);
      const integrations = await db.select().from(tenantSecurityTools).where(eq(tenantSecurityTools.tenantId, tenantId));

      // Coverage by security tool category
      const controlCategories = ["EDR/AV", "SIEM", "Vulnerability Scanner", "DLP", "PAM", "MDM", "Firewall", "WAF", "Email Security", "Cloud Security"];
      const coverage = controlCategories.map(cat => {
        const toolsInCat = integrations.filter(i => {
          const n = (i.toolName || "").toLowerCase();
          if (cat === "EDR/AV") return n.includes("defender") || n.includes("crowdstrike") || n.includes("sentinelone") || n.includes("carbon black") || n.includes("trend");
          if (cat === "SIEM") return n.includes("splunk") || n.includes("sentinel") || n.includes("qradar") || n.includes("elastic") || n.includes("siem");
          if (cat === "Vulnerability Scanner") return n.includes("qualys") || n.includes("nessus") || n.includes("rapid7") || n.includes("nexpose");
          if (cat === "DLP") return n.includes("dlp") || n.includes("symantec") || n.includes("forcepoint");
          if (cat === "MDM") return n.includes("intune") || n.includes("jamf") || n.includes("mdm") || n.includes("mobileiron");
          if (cat === "Firewall") return n.includes("palo alto") || n.includes("fortinet") || n.includes("checkpoint") || n.includes("cisco asa");
          return false;
        });
        const covered = toolsInCat.length > 0 ? allAssets.length : 0;
        const pct = allAssets.length > 0 ? Math.round((covered / allAssets.length) * 100) : 0;
        return { category: cat, covered, total: allAssets.length, percentage: pct, tools: toolsInCat.map(t => t.toolName) };
      });

      const assetsWithControls = allAssets.map(a => ({
        id: a.id,
        hostname: a.hostname,
        type: a.endpointType,
        os: a.operatingSystem,
        riskLevel: a.riskLevel,
        coverage: (a.controlsCoverage as any[] || []),
        coverageScore: Math.min(100, Math.max(0, Math.round(((a.controlsCoverage as any[] || []).length / Math.max(1, controlCategories.length)) * 100))),
      })).sort((a, b) => a.coverageScore - b.coverageScore).slice(0, 50);

      res.json({ coverage, assetsWithControls, integrationCount: integrations.length });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // ARIA AI SECURITY COPILOT
  // ─────────────────────────────────────────────────────────────────────────
  const copilotRateMap = new Map<string, { count: number; resetAt: number }>();
  const COPILOT_RATE_LIMIT = 20;
  const COPILOT_WINDOW_MS = 60_000;

  app.post("/api/copilot/query", isAuthenticated, async (req: any, res) => {
    try {
      const userId = String(req.user?.id || req.user?.claims?.sub || "anon");
      const now = Date.now();
      let bucket = copilotRateMap.get(userId);
      if (!bucket || now >= bucket.resetAt) {
        bucket = { count: 0, resetAt: now + COPILOT_WINDOW_MS };
        copilotRateMap.set(userId, bucket);
      }
      bucket.count++;
      if (bucket.count > COPILOT_RATE_LIMIT) {
        const retryAfter = Math.ceil((bucket.resetAt - now) / 1000);
        res.setHeader("Retry-After", retryAfter);
        return res.status(429).json({ message: `Rate limit exceeded. Try again in ${retryAfter}s.` });
      }

      const { question, tenantId } = req.body;
      if (!question || !tenantId) return res.status(400).json({ message: "question and tenantId required" });
      if (typeof question !== "string" || question.trim().length === 0) return res.status(400).json({ message: "question must be a non-empty string" });

      const result = await processARIAQuery(question.trim(), parseInt(tenantId));
      res.json(result);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // MITRE ATT&CK COVERAGE
  // ─────────────────────────────────────────────────────────────────────────
  app.get("/api/mitre/coverage", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.query.tenantId as string);
      const days = parseInt(req.query.days as string) || 90;
      if (!tenantId) return res.status(400).json({ message: "tenantId required" });

      const since = new Date(Date.now() - days * 86400000);

      // Sigma rule counts per technique (used by both PG and CH paths)
      const sigmaRows = await pool.query(
        `SELECT mitre_tags FROM sigma_rules WHERE is_enabled = true AND mitre_tags IS NOT NULL`
      );
      const ruleCounts: Record<string, number> = {};
      for (const sr of sigmaRows.rows) {
        const tags: string[] = Array.isArray(sr.mitre_tags) ? sr.mitre_tags : [];
        for (const tag of tags) {
          const m = String(tag).match(/T\d{4}(?:\.\d{3})?/i);
          if (m) {
            const tid = m[0].toUpperCase();
            ruleCounts[tid] = (ruleCounts[tid] || 0) + 1;
          }
        }
      }

      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // The PG coverage query groups the `incidents` table by mitre_technique_id.
      // Incidents are mirrored into CH via storage.chDualWriteIncidents on
      // create/update, so the fast-path now counts incidents from
      // `incidents_distributed` (a ReplacingMergeTree keyed on tenant_id+id),
      // keeping per-tile counts apples-to-apples with the PG path. FINAL is
      // used so duplicate versions emitted by the dual-write are collapsed
      // to the latest one before grouping.
      // Readiness guard: only use the CH fast-path once the startup backfill
      // has finished mirroring the historical PG incidents into CH. Until
      // then (especially right after the one-shot dedup-shard TRUNCATE
      // migration), CH would return systematically lower counts than PG, so
      // we fall through to the PG path to avoid a transient undercount.
      const { DatabaseStorage } = await import("./storage");
      const chCoverage = DatabaseStorage.isIncidentBackfillComplete()
        ? getClickHouseClient()
        : null;
      if (chCoverage) {
        try {
          const chStart = Date.now();
          const sinceIso = formatChDateTime64(since);
          // Mirror the PG fallback's filter set exactly so per-tile counts are
          // apples-to-apples between the two paths: tenant_id, time window,
          // and a non-null mitre_technique_id. The CH column is non-nullable
          // String (NULLs from PG land as ''), so `notEmpty()` is the
          // semantic equivalent of PG's `IS NOT NULL`. The PG path does NOT
          // apply INCIDENT_INTEGRATION_GUARD here, so neither do we — applying
          // it only on the fast-path would create systematic count drift
          // between the CH and PG responses for the same request.
          const sql = `
            SELECT
              mitre_technique_id AS tid,
              mitre_tactic       AS tactic,
              mitre_technique    AS technique,
              toUInt64(count())  AS cnt,
              toFloat64(avg(if(confidence_score > 0, confidence_score, 50))) AS avg_conf,
              max(created_at)    AS last_seen
            FROM incidents_distributed FINAL
            WHERE tenant_id = ${tenantId}
              AND created_at >= '${sinceIso}'
              AND notEmpty(mitre_technique_id)
            GROUP BY mitre_technique_id, mitre_tactic, mitre_technique
          `;
          const chRows = await chCoverage.queryRows<{
            tid: string; tactic: string; technique: string;
            cnt: string; avg_conf: number | string; last_seen: string;
          }>(sql);

          const covered: Record<string, { count: number; lastSeen: string; tactic: string; technique: string; confidence: number; ruleCount: number }> = {};
          for (const r of chRows) {
            const raw = String(r.tid || "").toUpperCase();
            const m = raw.match(/T\d{4}(?:\.\d{3})?/);
            const tid = m ? m[0] : raw;
            if (!tid) continue;
            const cnt = Number(r.cnt) || 0;
            const existing = covered[tid];
            if (!existing || existing.count < cnt) {
              covered[tid] = {
                count: cnt,
                lastSeen: String(r.last_seen ?? ""),
                tactic: r.tactic ?? "",
                technique: r.technique ?? "",
                confidence: Math.round(Number(r.avg_conf) || 50),
                ruleCount: ruleCounts[tid] || 0,
              };
            }
          }
          // Merge in sigma-only entries (have rules but no events)
          for (const [tid, ruleCount] of Object.entries(ruleCounts)) {
            if (!covered[tid] && ruleCount > 0) {
              covered[tid] = { count: 0, lastSeen: "", tactic: "", technique: "", confidence: 0, ruleCount };
            }
          }

          // Bail out to PG only if CH returned absolutely nothing usable —
          // a tenant with sigma rules but zero CH-derived techniques would
          // still show *some* covered set; prefer that over an empty board.
          if (Object.keys(covered).length > 0) {
            logChQuery("mitre.coverage", Date.now() - chStart, {
              tenant: tenantId, days, techniques: Object.keys(covered).length,
            });
            return res.json({ covered, days, ruleCounts, source: "clickhouse_olap", latencyMs: Date.now() - reqStart });
          }
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("mitre.coverage.failed", 0, { tenant: tenantId, error: chMsg });
        }
      }

      const rows = await pool.query(
        `SELECT mitre_technique_id, mitre_tactic, mitre_technique, COUNT(*) as count, MAX(created_at) as last_seen,
                AVG(CASE WHEN confidence_score IS NOT NULL THEN confidence_score ELSE 50 END)::int as avg_confidence
         FROM incidents
         WHERE tenant_id = $1 AND created_at >= $2 AND mitre_technique_id IS NOT NULL
         GROUP BY mitre_technique_id, mitre_tactic, mitre_technique`,
        [tenantId, since]
      );

      const covered: Record<string, { count: number; lastSeen: string; tactic: string; technique: string; confidence: number; ruleCount: number }> = {};
      for (const r of rows.rows) {
        const tid = r.mitre_technique_id;
        covered[tid] = {
          count: parseInt(r.count),
          lastSeen: r.last_seen,
          tactic: r.mitre_tactic,
          technique: r.mitre_technique,
          confidence: parseInt(r.avg_confidence) || 50,
          ruleCount: ruleCounts[tid] || 0,
        };
      }
      // Merge in sigma-only entries (have rules but no incidents)
      for (const [tid, ruleCount] of Object.entries(ruleCounts)) {
        if (!covered[tid] && ruleCount > 0) {
          covered[tid] = { count: 0, lastSeen: "", tactic: "", technique: "", confidence: 0, ruleCount };
        }
      }

      res.json({ covered, days, ruleCounts, source: "postgres", latencyMs: Date.now() - reqStart });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.get("/api/mitre/technique-incidents", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      const techniqueId = req.query.techniqueId as string;
      const days = parseInt(req.query.days as string) || 90;
      if (!tenantId || !techniqueId) return res.status(400).json({ message: "tenantId and techniqueId required" });
      await assertTenantAccess(req, tenantId);

      const since = new Date(Date.now() - days * 86400000);
      const rows = await pool.query(
        `SELECT id, title, severity, status, attacker, target, created_at, confidence_score
         FROM incidents
         WHERE tenant_id = $1 AND mitre_technique_id = $2 AND created_at >= $3
         ORDER BY created_at DESC LIMIT 20`,
        [tenantId, techniqueId, since]
      );

      const sigmaRows = await pool.query(
        `SELECT id, rule_id, title, level, match_count, last_matched_at
         FROM sigma_rules
         WHERE is_enabled = true AND mitre_tags IS NOT NULL
           AND mitre_tags::text ILIKE $1
         LIMIT 10`,
        [`%${techniqueId}%`]
      );

      res.json({ incidents: rows.rows, sigmaRules: sigmaRows.rows });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  app.post("/api/mitre/recommend", isAuthenticated, async (req: any, res) => {
    try {
      const { techniqueId, techniqueName, tactic, description, incidentCount } = req.body;
      if (!techniqueId) return res.status(400).json({ message: "techniqueId required" });

      const prompt = incidentCount > 0
        ? `You are a senior SOC detection engineer. Analyze detection coverage for MITRE ATT&CK technique ${techniqueId} (${techniqueName}) in the ${tactic} tactic.

We have ${incidentCount} incident(s) using this technique. Provide:
1. A brief assessment of detection quality (2-3 sentences)
2. Top 3 specific Sigma rule recommendations to improve coverage (rule concept, not full YAML)
3. Key log sources to ensure are ingested
Keep response concise, actionable, technical. Max 200 words.`
        : `You are a senior SOC detection engineer. Analyze detection gap for MITRE ATT&CK technique ${techniqueId} (${techniqueName}) in the ${tactic} tactic.

Technique description: ${description || "N/A"}

We have ZERO detections for this technique. Provide:
1. Why this technique is dangerous (1-2 sentences)
2. Top 3 specific Sigma/detection rule recommendations (describe what to detect, key fields/values)
3. Log sources required (e.g., Windows Security, Sysmon Event IDs, etc.)
Keep response concise, actionable, technical. Max 200 words.`;

      const aiCompletion = await openai.chat.completions.create({
        model: "gpt-4o-mini",
        messages: [{ role: "user", content: prompt }],
        max_completion_tokens: 400,
      });
      const recommendation = aiCompletion.choices[0]?.message?.content || "Unable to generate recommendation.";
      res.json({ recommendation });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // GLOBAL THREAT INTELLIGENCE MAP
  // ─────────────────────────────────────────────────────────────────────────
  const COUNTRY_NAME_TO_CODE: Record<string, string> = {
    "Afghanistan":"AF","Albania":"AL","Algeria":"DZ","Angola":"AO","Argentina":"AR",
    "Australia":"AU","Austria":"AT","Azerbaijan":"AZ","Bahrain":"BH","Bangladesh":"BD",
    "Belarus":"BY","Belgium":"BE","Brazil":"BR","Bulgaria":"BG","Canada":"CA",
    "Chile":"CL","China":"CN","Colombia":"CO","Congo":"CG","Croatia":"HR",
    "Cyprus":"CY","Czech Republic":"CZ","Denmark":"DK","Egypt":"EG","Ethiopia":"ET",
    "Finland":"FI","France":"FR","Germany":"DE","Ghana":"GH","Greece":"GR",
    "Hong Kong":"HK","Hungary":"HU","India":"IN","Indonesia":"ID","Iran":"IR",
    "Iraq":"IQ","Ireland":"IE","Israel":"IL","Italy":"IT","Japan":"JP","Jordan":"JO",
    "Kazakhstan":"KZ","Kenya":"KE","Kuwait":"KW","Laos":"LA","Lebanon":"LB",
    "Libya":"LY","Malaysia":"MY","Mexico":"MX","Morocco":"MA","Myanmar":"MM",
    "Netherlands":"NL","New Zealand":"NZ","Nigeria":"NG","North Korea":"KP",
    "Norway":"NO","Oman":"OM","Pakistan":"PK","Palestine":"PS","Panama":"PA",
    "Peru":"PE","Philippines":"PH","Poland":"PL","Portugal":"PT","Qatar":"QA",
    "Romania":"RO","Russia":"RU","Saudi Arabia":"SA","Senegal":"SN",
    "Singapore":"SG","South Africa":"ZA","South Korea":"KR","Spain":"ES",
    "Sudan":"SD","Sweden":"SE","Switzerland":"CH","Syria":"SY","Taiwan":"TW",
    "Thailand":"TH","Turkey":"TR","UAE":"AE","United Arab Emirates":"AE",
    "Uganda":"UG","Ukraine":"UA","United Kingdom":"GB","UK":"GB",
    "United States":"US","USA":"US","Venezuela":"VE","Vietnam":"VN",
    "Yemen":"YE","Zambia":"ZM","Zimbabwe":"ZW","Tanzania":"TZ","Tunisia":"TN",
  };
  function normalizeCountryToCode(raw: string): string {
    if (!raw) return "";
    const upper = raw.trim().toUpperCase();
    if (upper.length === 2) return upper; // Already ISO code
    return COUNTRY_NAME_TO_CODE[raw.trim()] || COUNTRY_NAME_TO_CODE[raw.trim().toLowerCase().replace(/\b\w/g, c => c.toUpperCase())] || "";
  }

  // ── IP Geolocation cache (in-memory, 24h TTL) ─────────────────────────────
  // countryCode is optional: cache entries written before the CH fast-path
  // shipped only stored {lat, lon}. The CH fast-path needs a country for the
  // arc `from` field (CH has no `country` column), so newer cache entries also
  // carry the ISO-2 code returned by ip-api.
  const _ipGeoCache = new Map<string, { lat: number; lon: number; countryCode?: string; expiresAt: number }>();
  const IP_GEO_TTL_MS = 24 * 60 * 60 * 1000;
  // Strict IPv4: each octet must be 0-255 with no leading zeros
  const PUBLIC_IP_RE = /^((25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)\.){3}(25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)$/;
  const PRIVATE_CIDRS: [number, number][] = [
    [0x0a000000, 0xff000000],   // 10.0.0.0/8
    [0xac100000, 0xfff00000],   // 172.16.0.0/12
    [0xc0a80000, 0xffff0000],   // 192.168.0.0/16
    [0x7f000000, 0xff000000],   // 127.0.0.0/8
    [0xa9fe0000, 0xffff0000],   // 169.254.0.0/16 (link-local)
    [0xe0000000, 0xf0000000],   // 224.0.0.0/4 (multicast)
    [0x00000000, 0xff000000],   // 0.0.0.0/8
  ];
  function isPublicIPv4(ip: string): boolean {
    if (!PUBLIC_IP_RE.test(ip)) return false;
    const parts = ip.split(".").map(Number);
    // Already validated by regex but guard against edge cases
    if (parts.length !== 4 || parts.some(p => p < 0 || p > 255)) return false;
    const n = ((parts[0] << 24) | (parts[1] << 16) | (parts[2] << 8) | parts[3]) >>> 0;
    return !PRIVATE_CIDRS.some(([net, mask]) => (n & mask) === net);
  }
  // Batch geolocation via ip-api.com (free, up to 100 IPs per batch POST, no API key required)
  async function geolocateIPs(ips: string[]): Promise<Map<string, { lat: number; lon: number }>> {
    const result = new Map<string, { lat: number; lon: number }>();
    const now = Date.now();
    const toFetch: string[] = [];
    for (const ip of ips) {
      const cached = _ipGeoCache.get(ip);
      if (cached && cached.expiresAt > now) {
        result.set(ip, { lat: cached.lat, lon: cached.lon });
      } else {
        toFetch.push(ip);
      }
    }
    if (!toFetch.length) return result;
    // ip-api.com batch endpoint: POST up to 100 IPs per request, no key required
    const BATCH_SIZE = 100;
    for (let i = 0; i < toFetch.length; i += BATCH_SIZE) {
      const batch = toFetch.slice(i, i + BATCH_SIZE);
      try {
        const resp = await fetch("http://ip-api.com/batch?fields=status,query,lat,lon,countryCode", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(batch.map(q => ({ query: q }))),
          signal: AbortSignal.timeout(8000),
        });
        if (resp.ok) {
          const rows: any[] = await resp.json();
          for (const row of rows) {
            if (row.status === "success" && row.lat != null && row.lon != null && row.query) {
              const cc = typeof row.countryCode === "string" ? row.countryCode : undefined;
              _ipGeoCache.set(row.query, { lat: row.lat, lon: row.lon, countryCode: cc, expiresAt: now + IP_GEO_TTL_MS });
              result.set(row.query, { lat: row.lat, lon: row.lon });
            }
          }
        }
      } catch (_) {
        // Non-fatal: falls back to country centroid on the frontend
      }
    }
    return result;
  }

  // Like geolocateIPs() but also returns the ISO-2 country code. Used by the
  // ClickHouse fast-path for /api/threat-map/arcs because CH events have no
  // `country` column — the arc `from` field must be derived from the source IP.
  async function geolocateIPsFull(ips: string[]): Promise<Map<string, { lat: number; lon: number; countryCode?: string }>> {
    // First make sure cache is warm (also writes countryCode for fresh rows)
    await geolocateIPs(ips);
    const out = new Map<string, { lat: number; lon: number; countryCode?: string }>();
    const now = Date.now();
    for (const ip of ips) {
      const c = _ipGeoCache.get(ip);
      if (c && c.expiresAt > now) {
        out.set(ip, { lat: c.lat, lon: c.lon, countryCode: c.countryCode });
      }
    }
    return out;
  }

  app.get("/api/threat-map/arcs", isAuthenticated, async (req: any, res) => {
    try {
      const reqStart = Date.now();
      const tenantId = parseInt(req.query.tenantId as string);
      const hours = parseInt(req.query.hours as string) || 24;
      if (!tenantId) return res.status(400).json({ message: "tenantId required" });

      // Enforce tenant-level access control
      await assertTenantAccess(req, tenantId);

      const since = new Date(Date.now() - hours * 3600000);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      // ── ClickHouse fast-path ────────────────────────────────────────────────
      // Threat globe arcs aggregate every event in the lookback window. On
      // PG that means scanning `security_events` plus several CIDR-subselect
      // joins per group, which dominates dashboard load on busy tenants. CH
      // has no `country` / `attacker` text columns, but we have `src_ip`,
      // `dst_ip`, `severity`, `mitre_tactic`, `ingested_at` — enough to
      // rebuild the same response shape:
      //   • from country: derived from `src_ip` via the same ip-api batch
      //     geo lookup the PG path uses for arc starting points
      //   • to office:    defaultOffice (CH lacks asset/target text needed
      //     for CIDR/keyword office matching — acceptable trade-off)
      // Falls back to PG on any CH error or when CH is not configured.
      const chArcsClient = getClickHouseClient();
      if (chArcsClient) {
        try {
          const chStart = Date.now();
          const sinceIso = formatChDateTime64(since);
          const tenantList = tenantIds.join(",");
          // Same integration-awareness guard the events fast-paths use, so
          // arcs only reflect log sources the tenant has actively connected.
          const guardMap = await getConnectedLogSourcesByTenant(tenantIds);
          const chGuard = buildChIntegrationGuard(guardMap);
          const guardSql = chGuard ? ` AND ${chGuard}` : "";
          // Public IPv4 only — exclude RFC1918 / loopback / link-local /
          // multicast / 0.0.0.0 ranges using CH's isIPAddressInRange.
          const publicIpFilter = `
              src_ip != toIPv4('0.0.0.0')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '10.0.0.0/8')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '172.16.0.0/12')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '192.168.0.0/16')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '127.0.0.0/8')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '169.254.0.0/16')
              AND NOT isIPAddressInRange(IPv4NumToString(src_ip), '224.0.0.0/4')`;
          // ── Office matching (parity with PG dual-signal logic) ───────────
          // PG path resolves each arc to an office via:
          //   Signal 1: hostname-keyword match against asset/target text
          //   Signal 2: CIDR match against attacker/asset/target IPs
          // Mirror that here so multi-office tenants don't see every arc
          // collapse to the default office. The CH `target` column is
          // populated by chDualWrite (storage.ts) and the CIDR / keyword
          // checks use ClickHouse re2 + isIPAddressInRange — no PG round-trip.
          const officeRowsForCase = await pool.query(
            `SELECT id, name, city, country_code, latitude, longitude, hostname_keywords, private_ip_ranges
             FROM infrastructure_locations
             WHERE tenant_id = ANY($1) AND is_active = true
               AND latitude IS NOT NULL AND longitude IS NOT NULL
             ORDER BY id ASC`,
            [tenantIds],
          );
          const tenantOfficesCh: any[] = officeRowsForCase.rows;
          const officeByIdCh = new Map<number, any>(tenantOfficesCh.map((o) => [o.id, o]));
          const defaultOfficeCh = tenantOfficesCh[0] ?? null;

          const KW_RE = /^[a-z0-9_-]+$/i;
          const CIDR_RE = /^\d{1,3}(\.\d{1,3}){3}\/\d{1,2}$/;
          const officeCaseFragments: string[] = [];
          // Signal 1 — hostname keyword match (host/target text). Same
          // word-boundary regex shape used by the PG path so behavior is
          // identical for tenants that already configured keywords there.
          for (const o of tenantOfficesCh) {
            const kws: string[] = (o.hostname_keywords ?? []).filter((k: string) => typeof k === "string" && KW_RE.test(k));
            if (!kws.length) continue;
            const conds = kws.map((k) => {
              const safe = k.toLowerCase();
              const re = `(^|[^a-z0-9_-])${safe}([^a-z0-9_-]|$)`;
              return `match(lower(host), '${re}') OR match(lower(target), '${re}')`;
            }).join(" OR ");
            officeCaseFragments.push(`WHEN (${conds}) THEN toUInt32(${o.id})`);
          }
          // Signal 2 — CIDR match. Try src_ip / dst_ip (IPv4-typed) first,
          // then fall back to text-typed host/target via isIPAddressInRange,
          // which returns 0 for non-IP strings so it's safe on hostnames.
          for (const o of tenantOfficesCh) {
            const ranges: string[] = Array.isArray(o.private_ip_ranges) ? o.private_ip_ranges : [];
            const validRanges = ranges.filter((r) => typeof r === "string" && CIDR_RE.test(r));
            if (!validRanges.length) continue;
            const conds = validRanges.map((r) => {
              return (
                `isIPAddressInRange(IPv4NumToString(src_ip), '${r}') ` +
                `OR isIPAddressInRange(IPv4NumToString(dst_ip), '${r}') ` +
                `OR isIPAddressInRange(host, '${r}') ` +
                `OR isIPAddressInRange(target, '${r}')`
              );
            }).join(" OR ");
            officeCaseFragments.push(`WHEN (${conds}) THEN toUInt32(${o.id})`);
          }
          const officeCaseExpr = officeCaseFragments.length > 0
            ? `CASE ${officeCaseFragments.join(" ")} ELSE toUInt32(0) END`
            : `toUInt32(0)`;

          const arcsSql = `
            SELECT
              IPv4NumToString(src_ip) AS sample_ip,
              if(empty(severity), 'medium', severity) AS severity,
              ${officeCaseExpr} AS office_id,
              toUInt64(count()) AS cnt
            FROM security_events_distributed
            WHERE tenant_id IN (${tenantList})
              AND ingested_at >= '${sinceIso}'
              AND ${publicIpFilter}
              ${guardSql}
            GROUP BY sample_ip, severity, office_id
            ORDER BY cnt DESC
            LIMIT 200
          `;
          const totalSql = `
            SELECT toUInt64(count()) AS total
            FROM security_events_distributed
            WHERE tenant_id IN (${tenantList})
              AND ingested_at >= '${sinceIso}'
              ${guardSql}
          `;
          const topTechSql = `
            SELECT mitre_tactic AS technique, toUInt64(count()) AS cnt
            FROM security_events_distributed
            WHERE tenant_id IN (${tenantList})
              AND ingested_at >= '${sinceIso}'
              AND mitre_tactic != ''
              ${guardSql}
            GROUP BY mitre_tactic
            ORDER BY cnt DESC
            LIMIT 1
          `;
          const topTargetsSql = `
            SELECT IPv4NumToString(dst_ip) AS target, toUInt64(count()) AS cnt
            FROM security_events_distributed
            WHERE tenant_id IN (${tenantList})
              AND ingested_at >= '${sinceIso}'
              AND dst_ip != toIPv4('0.0.0.0')
              ${guardSql}
            GROUP BY target
            ORDER BY cnt DESC
            LIMIT 10
          `;

          const [arcsRows, totalRows, techRows, dstRows] = await Promise.all([
            chArcsClient.queryRows<{ sample_ip: string; severity: string; office_id: string; cnt: string }>(arcsSql),
            chArcsClient.queryRows<{ total: string }>(totalSql),
            chArcsClient.queryRows<{ technique: string; cnt: string }>(topTechSql),
            chArcsClient.queryRows<{ target: string; cnt: string }>(topTargetsSql),
          ]);

          const uniqueIpsCh = [
            ...new Set(arcsRows.map((r) => r.sample_ip).filter((ip) => ip && isPublicIPv4(ip))),
          ] as string[];
          const ipGeoFull = uniqueIpsCh.length > 0 ? await geolocateIPsFull(uniqueIpsCh) : new Map();

          // Country counts derived from geo lookups (CH has no country column)
          const countryCounts = new Map<string, number>();
          const arcs: any[] = [];
          for (const r of arcsRows) {
            const cnt = Number(r.cnt) || 0;
            const ipGeo = ipGeoFull.get(r.sample_ip) as { lat: number; lon: number; countryCode?: string } | undefined;
            const from = ipGeo?.countryCode ? normalizeCountryToCode(ipGeo.countryCode) : "";
            if (!from) continue; // Drop rows we couldn't attribute to a country
            countryCounts.set(from, (countryCounts.get(from) || 0) + cnt);
            // Resolve the office matched by ClickHouse's per-row CASE
            // (0 = no match → fall back to the tenant's default office, same
            // behaviour as the PG path's COALESCE(..., default_office)).
            const matchedOfficeId = parseInt(r.office_id ?? "0", 10);
            const office = matchedOfficeId > 0 ? officeByIdCh.get(matchedOfficeId) ?? defaultOfficeCh : defaultOfficeCh;
            arcs.push({
              from,
              to: office?.country_code ?? "US",
              severity: r.severity,
              count: cnt,
              ...(office
                ? { toLat: office.latitude, toLon: office.longitude, toCity: office.city ?? office.name }
                : {}),
              fromLat: ipGeo!.lat,
              fromLon: ipGeo!.lon,
            });
          }

          const topSourcesCh = [...countryCounts.entries()]
            .sort((a, b) => b[1] - a[1])
            .slice(0, 10)
            .map(([country, count]) => ({ country, count }));

          // If geolocation produced no usable arcs (ip-api unreachable or
          // rate-limited), don't surface an empty globe — fall back to PG so
          // the widget keeps rendering meaningful data. We only short-circuit
          // to CH when there's at least one attributed arc OR there were no
          // matching CH rows to begin with (genuinely quiet tenant).
          if (arcs.length === 0 && arcsRows.length > 0) {
            logChQuery("dashboard.threat-map.arcs.no-geo", Date.now() - chStart, {
              tenant: tenantId, hours, ips: uniqueIpsCh.length,
            });
            throw new Error("threat-map: CH rows present but no country attributions resolved");
          }

          logChQuery("dashboard.threat-map.arcs", Date.now() - chStart, {
            tenant: tenantId, hours, arcs: arcs.length, ips: uniqueIpsCh.length,
          });

          return res.json({
            arcs,
            totalEvents: parseInt(totalRows[0]?.total ?? "0", 10),
            topSources: topSourcesCh,
            topTargets: dstRows.slice(0, 5).map((r) => ({
              country: (r.target?.slice(0, 2) || "US").toUpperCase(),
              count: parseInt(String(r.cnt), 10) || 0,
            })).filter((t) => t.country.length === 2),
            uniqueCountries: countryCounts.size,
            topTechnique: techRows[0]?.technique || "",
            hours,
            source: "clickhouse_olap",
            latencyMs: Date.now() - reqStart,
          });
        } catch (chErr: unknown) {
          const chMsg = chErr instanceof Error ? chErr.message : String(chErr);
          logChQuery("dashboard.threat-map.arcs.failed", 0, { tenant: tenantId, error: chMsg });
          // fall through to PG path
        }
      }

      // Step 1: Fetch tenant office locations from infrastructure_locations (DB-driven)
      const officeRes = await pool.query(
        `SELECT id, name, city, country_code, latitude, longitude, hostname_keywords, private_ip_ranges
         FROM infrastructure_locations
         WHERE tenant_id = ANY($1) AND is_active = true
           AND latitude IS NOT NULL AND longitude IS NOT NULL
         ORDER BY id ASC`,
        [tenantIds]
      );
      const tenantOffices: any[] = officeRes.rows;

      // Step 2: Build Signal 1 CASE clause — hostname keyword matching (safe: keywords are user-defined via Infrastructure UI)
      let kwCaseClause = "NULL::integer";
      if (tenantOffices.length > 0) {
        const kwCases: string[] = [];
        for (const office of tenantOffices) {
          const kws: string[] = (office.hostname_keywords || []).filter((kw: string) => /^[a-z0-9_\-]+$/i.test(kw));
          if (!kws.length) continue;
          // Use word-boundary regex matching to avoid false positives with short keywords
          const conds = kws.map((kw: string) => {
            const safe = kw.toLowerCase();
            const boundary = `(^|[^a-z0-9_-])${safe}([^a-z0-9_-]|$)`;
            return `(LOWER(COALESCE(asset,'')) ~ '${boundary}' OR LOWER(COALESCE(target,'')) ~ '${boundary}')`;
          }).join(" OR ");
          kwCases.push(`WHEN (${conds}) THEN ${office.id}`);
        }
        if (kwCases.length > 0) {
          kwCaseClause = `CASE ${kwCases.join(" ")} ELSE NULL END`;
        }
      }

      // Determine whether any offices have CIDR data (Signal 2 is only built when needed)
      const hasCIDR = tenantOffices.some(o => {
        const ranges = o.private_ip_ranges;
        return Array.isArray(ranges) ? ranges.length > 0 : (ranges && Object.keys(ranges).length > 0);
      });

      // Combined office_id: COALESCE(Signal1_keyword, Signal2_cidr_attacker, Signal2_cidr_asset, Signal2_cidr_target)
      // Signal 2 uses PostgreSQL inet operators — attacker/asset/target are validated as strict IPv4 first
      // Strict regex: each octet 0-255, no leading zeros, prevents malformed inet casts
      const ipRegex = `'^((25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])$'`;
      const cidrSubqAttacker = hasCIDR
        ? `(SELECT oc.id FROM infrastructure_locations oc, jsonb_array_elements_text(oc.private_ip_ranges) cidr
           WHERE oc.tenant_id = ANY($1) AND oc.is_active = true
             AND attacker ~ ${ipRegex} AND attacker::inet << cidr::inet
           LIMIT 1)`
        : "NULL::integer";
      const cidrSubqAsset = hasCIDR
        ? `(SELECT oc.id FROM infrastructure_locations oc, jsonb_array_elements_text(oc.private_ip_ranges) cidr
           WHERE oc.tenant_id = ANY($1) AND oc.is_active = true
             AND asset ~ ${ipRegex} AND asset::inet << cidr::inet
           LIMIT 1)`
        : "NULL::integer";
      const cidrSubqTarget = hasCIDR
        ? `(SELECT oc.id FROM infrastructure_locations oc, jsonb_array_elements_text(oc.private_ip_ranges) cidr
           WHERE oc.tenant_id = ANY($1) AND oc.is_active = true
             AND target ~ ${ipRegex} AND target::inet << cidr::inet
           LIMIT 1)`
        : "NULL::integer";

      const officeCaseExpr = `COALESCE(${kwCaseClause}, ${cidrSubqAttacker}, ${cidrSubqAsset}, ${cidrSubqTarget})`;

      // Step 3: Query events with dual-signal office detection (keyword + CIDR)
      const [eventsRes, totalRes, topSourcesRes, topTargetsRes, techniqueRes] = await Promise.all([
        pool.query(
          `SELECT country, severity, COUNT(*) as count, ${officeCaseExpr} as office_id,
                  MIN(CASE WHEN attacker ~ '^((25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])\\.){3}(25[0-5]|2[0-4][0-9]|1[0-9]{2}|[1-9][0-9]|[0-9])$'
                           AND NOT (attacker::inet << '10.0.0.0/8'::inet
                                    OR attacker::inet << '172.16.0.0/12'::inet
                                    OR attacker::inet << '192.168.0.0/16'::inet
                                    OR attacker::inet << '127.0.0.0/8'::inet
                                    OR attacker::inet << '169.254.0.0/16'::inet
                                    OR attacker::inet << '224.0.0.0/4'::inet)
                       THEN attacker END) as sample_ip
           FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND country IS NOT NULL AND country != ''
           GROUP BY country, severity, ${officeCaseExpr}
           ORDER BY count DESC
           LIMIT 200`,
          [tenantIds, since]
        ),
        pool.query(
          `SELECT COUNT(*) as total FROM security_events WHERE tenant_id = ANY($1) AND occurred_at >= $2`,
          [tenantIds, since]
        ),
        pool.query(
          `SELECT country, COUNT(*) as count FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND country IS NOT NULL AND country != ''
           GROUP BY country ORDER BY count DESC LIMIT 10`,
          [tenantIds, since]
        ),
        pool.query(
          `SELECT target, COUNT(*) as count FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND target IS NOT NULL AND target != ''
           GROUP BY target ORDER BY count DESC LIMIT 10`,
          [tenantIds, since]
        ),
        pool.query(
          `SELECT mitre_tactic as technique, COUNT(*) as count FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND mitre_tactic IS NOT NULL AND mitre_tactic != ''
           GROUP BY mitre_tactic ORDER BY count DESC LIMIT 1`,
          [tenantIds, since]
        ),
      ]);

      // Step 4: Build office lookup map and determine default/fallback office
      const officeById = new Map<number, any>(tenantOffices.map(o => [o.id, o]));
      const defaultOffice = tenantOffices[0] ?? null;

      // Step 5: Resolve attacker IPs to city-level lat/lon via ip-api.com
      const uniqueSampleIPs = [
        ...new Set(eventsRes.rows.map((r: any) => r.sample_ip).filter((ip: any) => ip && isPublicIPv4(ip)))
      ] as string[];
      const ipGeoMap = uniqueSampleIPs.length > 0 ? await geolocateIPs(uniqueSampleIPs) : new Map();

      const normalizedArcs = eventsRes.rows.map((r: any) => {
        const from = normalizeCountryToCode(r.country);
        if (!from) return null;
        const office = r.office_id ? officeById.get(r.office_id) : defaultOffice;
        const toLat  = office?.latitude   ?? null;
        const toLon  = office?.longitude  ?? null;
        const toCity = office?.city       ?? office?.name ?? null;
        const toCountry = office?.country_code ?? "US";
        // Apply IP-resolved geo position as arc source when available
        const ipGeo = r.sample_ip ? ipGeoMap.get(r.sample_ip) : undefined;
        return {
          from,
          to: toCountry,
          severity: r.severity,
          count: parseInt(r.count),
          ...(toLat !== null ? { toLat, toLon, toCity } : {}),
          ...(ipGeo ? { fromLat: ipGeo.lat, fromLon: ipGeo.lon } : {}),
        };
      }).filter(Boolean);

      res.json({
        arcs: normalizedArcs,
        totalEvents: parseInt(totalRes.rows[0]?.total ?? "0"),
        topSources: topSourcesRes.rows.map(r => ({ country: normalizeCountryToCode(r.country), count: parseInt(r.count) })).filter((s: any) => s.country),
        topTargets: topTargetsRes.rows.slice(0, 5).map(r => ({ country: r.target?.slice(0, 2)?.toUpperCase() || "US", count: parseInt(r.count) })).filter((t: any) => t.country.length === 2),
        uniqueCountries: new Set(normalizedArcs.map((a: any) => a.from)).size,
        topTechnique: techniqueRes.rows[0]?.technique || "",
        hours,
        source: "postgres",
        latencyMs: Date.now() - reqStart,
      });
    } catch (error: any) {
      const status = (error as any).status || 500;
      res.status(status).json({ message: error.message });
    }
  });

  app.get("/api/threat-map/country/:code", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      const { code } = req.params;
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const since = new Date(Date.now() - 30 * 86400000);

      const [eventsRes, incidentRes, techniqueRes, countRes] = await Promise.all([
        pool.query(
          `SELECT e.attacker as value, e.severity, e.occurred_at, e.event_type
           FROM security_events e
           WHERE e.tenant_id = ANY($1) AND e.occurred_at >= $2
             AND (UPPER(e.country) = UPPER($3) OR e.country ILIKE $3)
           ORDER BY e.occurred_at DESC LIMIT 10`,
          [tenantIds, since, code]
        ),
        pool.query(
          `SELECT i.id, i.title, i.severity, i.created_at
           FROM incidents i
           WHERE i.tenant_id = ANY($1) AND i.created_at >= $2
             AND (i.source_ip IS NOT NULL OR i.description ILIKE $3)
           ORDER BY i.severity DESC, i.created_at DESC LIMIT 5`,
          [tenantIds, since, `%${code}%`]
        ),
        pool.query(
          `SELECT mitre_tactic as technique, COUNT(*) as cnt
           FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2
             AND (UPPER(country) = UPPER($3) OR country ILIKE $3)
             AND mitre_tactic IS NOT NULL
           GROUP BY mitre_tactic ORDER BY cnt DESC LIMIT 1`,
          [tenantIds, since, code]
        ),
        pool.query(
          `SELECT COUNT(*) as total FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2
             AND (UPPER(country) = UPPER($3) OR country ILIKE $3)`,
          [tenantIds, since, code]
        ),
      ]);

      res.json({
        country: code,
        events: eventsRes.rows,
        incidents: incidentRes.rows,
        totalEvents: parseInt(countRes.rows[0]?.total ?? "0"),
        topTechnique: techniqueRes.rows[0]?.technique || null,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // THREAT RADAR — Attack vector distribution (10 sectors, last 30 days)
  // ─────────────────────────────────────────────────────────────────────────
  app.get("/api/threat-radar/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      // Enforce tenant access before any data access (prevents cross-tenant IDOR)
      await assertTenantAccess(req, tenantId);
      const tenantIds = await getAccessibleTenantIds(req, tenantId);
      const since = new Date(Date.now() - 30 * 86400000);

      // Query event_type distribution from security_events
      const [eventsRes, subTypeRes, aiRes] = await Promise.all([
        pool.query(
          `SELECT event_type,
                  COUNT(*) AS cnt,
                  MAX(CASE
                    WHEN severity = 'critical' THEN 4
                    WHEN severity = 'high'     THEN 3
                    WHEN severity = 'medium'   THEN 2
                    WHEN severity = 'low'      THEN 1
                    ELSE 0 END) AS max_sev
           FROM security_events
           WHERE tenant_id = ANY($1) AND occurred_at >= $2
             AND event_type IS NOT NULL
           GROUP BY event_type`,
          [tenantIds, since]
        ),

        // Sub-type fingerprinting: count keyword hits per event_type across threat_vector + threat + mitre_technique
        pool.query(
          `SELECT event_type,
                  SUM(CASE WHEN txt LIKE '%ransom%' THEN 1 ELSE 0 END)                                                 AS ransomware,
                  SUM(CASE WHEN txt LIKE '%malware%' OR txt LIKE '%trojan%' OR txt LIKE '%virus%' THEN 1 ELSE 0 END)   AS malware,
                  SUM(CASE WHEN txt LIKE '%ddos%' OR txt LIKE '%flood%' OR txt LIKE '%dos%' THEN 1 ELSE 0 END)         AS ddos,
                  SUM(CASE WHEN txt LIKE '%bot%' OR txt LIKE '%c2%' OR txt LIKE '%beacon%' OR txt LIKE '%command and control%' THEN 1 ELSE 0 END) AS botnet,
                  SUM(CASE WHEN txt LIKE '%lateral%' THEN 1 ELSE 0 END)                                                AS lateral,
                  SUM(CASE WHEN txt LIKE '%phish%' THEN 1 ELSE 0 END)                                                  AS phishing,
                  SUM(CASE WHEN txt LIKE '%spam%' THEN 1 ELSE 0 END)                                                   AS spam,
                  SUM(CASE WHEN txt LIKE '%bec%' THEN 1 ELSE 0 END)                                                    AS bec,
                  SUM(CASE WHEN txt LIKE '%exploit%' THEN 1 ELSE 0 END)                                                AS exploit,
                  SUM(CASE WHEN txt LIKE '%scan%' THEN 1 ELSE 0 END)                                                   AS scanning,
                  SUM(CASE WHEN txt LIKE '%exfil%' OR txt LIKE '%data leak%' THEN 1 ELSE 0 END)                        AS exfiltration,
                  SUM(CASE WHEN txt LIKE '%misconfig%' OR txt LIKE '%shadow it%' THEN 1 ELSE 0 END)                    AS misconfig,
                  SUM(CASE WHEN txt LIKE '%brute%' OR txt LIKE '%credential%' OR txt LIKE '%spray%' THEN 1 ELSE 0 END) AS bruteforce
           FROM (
             SELECT event_type,
               LOWER(
                 COALESCE(threat_vector,'') || ' ' ||
                 COALESCE(threat,'')        || ' ' ||
                 COALESCE(mitre_technique,'')
               ) AS txt
             FROM security_events
             WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND event_type IS NOT NULL
           ) t
           GROUP BY event_type`,
          [tenantIds, since]
        ),

        // AI-vector incidents
        pool.query(
          `SELECT COUNT(*) AS cnt,
                  MAX(CASE
                    WHEN severity = 'critical' THEN 4
                    WHEN severity = 'high'     THEN 3
                    WHEN severity = 'medium'   THEN 2
                    WHEN severity = 'low'      THEN 1
                    ELSE 0 END) AS max_sev
           FROM incidents
           WHERE tenant_id = ANY($1) AND created_at >= $2
             AND (
               LOWER(incident_type) LIKE '%prompt%'
               OR LOWER(incident_type) LIKE '%ai attack%'
               OR LOWER(incident_type) LIKE '%model poison%'
               OR LOWER(incident_type) LIKE '%adversarial%'
               OR LOWER(incident_type) LIKE '%deepfake%'
               OR LOWER(category)     LIKE '%ai%'
             )
             AND LOWER(COALESCE(incident_type,'')) NOT LIKE '%ai analysis%'`,
          [tenantIds, since]
        ),
      ]);

      const sevName = (score: number): string => {
        if (score >= 4) return "critical";
        if (score >= 3) return "high";
        if (score >= 2) return "medium";
        if (score >= 1) return "low";
        return "none";
      };

      // Build event-type → {count, sev} lookup
      const evMap = new Map<string, { count: number; sev: string }>();
      for (const row of eventsRes.rows) {
        evMap.set(row.event_type, { count: parseInt(row.cnt), sev: sevName(parseInt(row.max_sev)) });
      }

      // Build event-type → sub-type counts lookup
      const stMap = new Map<string, Record<string, number>>();
      for (const row of subTypeRes.rows) {
        stMap.set(row.event_type, {
          ransomware:  parseInt(row.ransomware  || 0),
          malware:     parseInt(row.malware     || 0),
          ddos:        parseInt(row.ddos        || 0),
          botnet:      parseInt(row.botnet      || 0),
          lateral:     parseInt(row.lateral     || 0),
          phishing:    parseInt(row.phishing    || 0),
          spam:        parseInt(row.spam        || 0),
          bec:         parseInt(row.bec         || 0),
          exploit:     parseInt(row.exploit     || 0),
          scanning:    parseInt(row.scanning    || 0),
          exfiltration:parseInt(row.exfiltration|| 0),
          misconfig:   parseInt(row.misconfig   || 0),
          bruteforce:  parseInt(row.bruteforce  || 0),
        });
      }

      // Pick dominant sub-type label given a radar vector and its underlying event_type(s)
      function topSubTypeFor(vector: string, eventTypes: string[]): string | null {
        const merged: Record<string, number> = {};
        for (const et of eventTypes) {
          const st = stMap.get(et);
          if (!st) continue;
          for (const [k, v] of Object.entries(st)) merged[k] = (merged[k] || 0) + v;
        }
        const pick = (keys: string[]): string | null => {
          let best: string | null = null;
          let bestN = 0;
          for (const k of keys) { if ((merged[k] || 0) > bestN) { bestN = merged[k]; best = k; } }
          return bestN > 0 ? best : null;
        };
        const LABELS: Record<string, string> = {
          ransomware: "ransomware", malware: "malware",
          ddos: "DDoS", botnet: "botnet/C2", lateral: "lateral mvmt",
          phishing: "phishing", spam: "spam", bec: "BEC",
          exploit: "exploitation", scanning: "scanning",
          exfiltration: "exfiltration", misconfig: "misconfig",
          bruteforce: "brute force",
        };
        if (vector === "endpoint")      { const k = pick(["ransomware","malware"]); return k ? LABELS[k] : null; }
        if (vector === "network")       { const k = pick(["ddos","botnet","lateral"]); return k ? LABELS[k] : null; }
        if (vector === "email")         { const k = pick(["phishing","spam","bec"]); return k ? LABELS[k] : null; }
        if (vector === "vulnerability") { const k = pick(["exploit","scanning"]); return k ? LABELS[k] : null; }
        if (vector === "data")          { const k = pick(["exfiltration"]); return k ? LABELS[k] : null; }
        if (vector === "cloud")         { const k = pick(["misconfig"]); return k ? LABELS[k] : null; }
        if (vector === "identity")      { const k = pick(["bruteforce"]); return k ? LABELS[k] : null; }
        return null;
      }

      // Cloud: casb + cloud combined
      const casbData  = evMap.get("casb")  || { count: 0, sev: "none" };
      const cloudData = evMap.get("cloud") || { count: 0, sev: "none" };
      const cloudCombined = {
        count: casbData.count + cloudData.count,
        sev:   casbData.count > cloudData.count ? casbData.sev : cloudData.sev,
      };

      const aiCount = parseInt(aiRes.rows[0]?.cnt || "0");
      const aiSev   = sevName(parseInt(aiRes.rows[0]?.max_sev || "0"));

      const SECTORS: Array<{ vector: string; label: string; data: { count: number; sev: string }; eventTypes: string[] }> = [
        { vector: "email",         label: "Email",         data: evMap.get("email")         || { count: 0, sev: "none" }, eventTypes: ["email"] },
        { vector: "endpoint",      label: "Endpoint",      data: evMap.get("endpoint")      || { count: 0, sev: "none" }, eventTypes: ["endpoint"] },
        { vector: "network",       label: "Network",       data: evMap.get("network")        || { count: 0, sev: "none" }, eventTypes: ["network"] },
        { vector: "web",           label: "Web",           data: evMap.get("sse")            || { count: 0, sev: "none" }, eventTypes: ["sse"] },
        { vector: "web_app",       label: "Web App",       data: evMap.get("waf")            || { count: 0, sev: "none" }, eventTypes: ["waf"] },
        { vector: "cloud",         label: "Cloud",         data: cloudCombined,                                            eventTypes: ["casb","cloud"] },
        { vector: "identity",      label: "Identity",      data: evMap.get("identity")       || { count: 0, sev: "none" }, eventTypes: ["identity"] },
        { vector: "data",          label: "Data",          data: evMap.get("dlp")            || { count: 0, sev: "none" }, eventTypes: ["dlp"] },
        { vector: "vulnerability", label: "Vulnerability", data: evMap.get("vulnerability")  || { count: 0, sev: "none" }, eventTypes: ["vulnerability"] },
        { vector: "ai",            label: "AI",            data: { count: aiCount, sev: aiSev },                          eventTypes: [] },
      ];

      const result = SECTORS.map(s => ({
        vector:           s.vector,
        label:            s.label,
        count:            s.data.count,
        dominantSeverity: s.data.sev,
        topSubType:       topSubTypeFor(s.vector, s.eventTypes),
      }));

      // Fallback: if 30-day window has zero data, retry with 90-day window
      const totalCount30 = result.reduce((acc, r) => acc + r.count, 0);
      if (totalCount30 === 0) {
        const since90 = new Date(Date.now() - 90 * 86400000);
        const [ev90, st90, ai90] = await Promise.all([
          pool.query(
            `SELECT event_type, COUNT(*) AS cnt,
                    MAX(CASE WHEN severity='critical' THEN 4 WHEN severity='high' THEN 3 WHEN severity='medium' THEN 2 WHEN severity='low' THEN 1 ELSE 0 END) AS max_sev
             FROM security_events WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND event_type IS NOT NULL GROUP BY event_type`,
            [tenantIds, since90]
          ),
          pool.query(
            `SELECT event_type,
               SUM(CASE WHEN txt LIKE '%ransom%' THEN 1 ELSE 0 END) AS ransomware,
               SUM(CASE WHEN txt LIKE '%malware%' OR txt LIKE '%trojan%' OR txt LIKE '%virus%' THEN 1 ELSE 0 END) AS malware,
               SUM(CASE WHEN txt LIKE '%ddos%' OR txt LIKE '%flood%' OR txt LIKE '%dos%' THEN 1 ELSE 0 END) AS ddos,
               SUM(CASE WHEN txt LIKE '%bot%' OR txt LIKE '%c2%' OR txt LIKE '%beacon%' THEN 1 ELSE 0 END) AS botnet,
               SUM(CASE WHEN txt LIKE '%lateral%' THEN 1 ELSE 0 END) AS lateral,
               SUM(CASE WHEN txt LIKE '%phish%' THEN 1 ELSE 0 END) AS phishing,
               SUM(CASE WHEN txt LIKE '%spam%' THEN 1 ELSE 0 END) AS spam,
               SUM(CASE WHEN txt LIKE '%bec%' THEN 1 ELSE 0 END) AS bec,
               SUM(CASE WHEN txt LIKE '%exploit%' THEN 1 ELSE 0 END) AS exploit,
               SUM(CASE WHEN txt LIKE '%scan%' THEN 1 ELSE 0 END) AS scanning,
               SUM(CASE WHEN txt LIKE '%exfil%' OR txt LIKE '%data leak%' THEN 1 ELSE 0 END) AS exfiltration,
               SUM(CASE WHEN txt LIKE '%misconfig%' THEN 1 ELSE 0 END) AS misconfig,
               SUM(CASE WHEN txt LIKE '%brute%' OR txt LIKE '%credential%' OR txt LIKE '%spray%' THEN 1 ELSE 0 END) AS bruteforce
             FROM (SELECT event_type, LOWER(COALESCE(threat_vector,'') || ' ' || COALESCE(threat,'') || ' ' || COALESCE(mitre_technique,'')) AS txt
                   FROM security_events WHERE tenant_id = ANY($1) AND occurred_at >= $2 AND event_type IS NOT NULL) t
             GROUP BY event_type`,
            [tenantIds, since90]
          ),
          pool.query(
            `SELECT COUNT(*) AS cnt,
                    MAX(CASE WHEN severity='critical' THEN 4 WHEN severity='high' THEN 3 WHEN severity='medium' THEN 2 WHEN severity='low' THEN 1 ELSE 0 END) AS max_sev
             FROM incidents WHERE tenant_id = ANY($1) AND created_at >= $2
               AND (LOWER(incident_type) LIKE '%prompt%' OR LOWER(incident_type) LIKE '%ai attack%' OR LOWER(category) LIKE '%ai%')
               AND LOWER(COALESCE(incident_type,'')) NOT LIKE '%ai analysis%'`,
            [tenantIds, since90]
          ),
        ]);
        const evMap90 = new Map<string, { count: number; sev: string }>();
        for (const row of ev90.rows) evMap90.set(row.event_type, { count: parseInt(row.cnt), sev: sevName(parseInt(row.max_sev)) });
        const stMap90 = new Map<string, Record<string, number>>();
        for (const row of st90.rows) stMap90.set(row.event_type, {
          ransomware: parseInt(row.ransomware||0), malware: parseInt(row.malware||0),
          ddos: parseInt(row.ddos||0), botnet: parseInt(row.botnet||0), lateral: parseInt(row.lateral||0),
          phishing: parseInt(row.phishing||0), spam: parseInt(row.spam||0), bec: parseInt(row.bec||0),
          exploit: parseInt(row.exploit||0), scanning: parseInt(row.scanning||0),
          exfiltration: parseInt(row.exfiltration||0), misconfig: parseInt(row.misconfig||0), bruteforce: parseInt(row.bruteforce||0),
        });
        const aiCount90 = parseInt(ai90.rows[0]?.cnt || "0");
        const aiSev90 = sevName(parseInt(ai90.rows[0]?.max_sev || "0"));
        const casbD90 = evMap90.get("casb") || { count: 0, sev: "none" };
        const cloudD90 = evMap90.get("cloud") || { count: 0, sev: "none" };
        const cloudC90 = { count: casbD90.count + cloudD90.count, sev: casbD90.count > cloudD90.count ? casbD90.sev : cloudD90.sev };
        const stMap90ref = stMap90;
        function topSubType90(vector: string, eventTypes: string[]): string | null {
          const merged: Record<string, number> = {};
          for (const et of eventTypes) { const st = stMap90ref.get(et); if (!st) continue; for (const [k, v] of Object.entries(st)) merged[k] = (merged[k] || 0) + v; }
          const pick = (keys: string[]) => { let best: string | null = null; let bestN = 0; for (const k of keys) { if ((merged[k]||0) > bestN) { bestN = merged[k]; best = k; } } return bestN > 0 ? best : null; };
          const LBL: Record<string, string> = { ransomware: "ransomware", malware: "malware", ddos: "DDoS", botnet: "botnet/C2", lateral: "lateral mvmt", phishing: "phishing", spam: "spam", bec: "BEC", exploit: "exploitation", scanning: "scanning", exfiltration: "exfiltration", misconfig: "misconfig", bruteforce: "brute force" };
          if (vector === "endpoint") { const k = pick(["ransomware","malware"]); return k ? LBL[k] : null; }
          if (vector === "network") { const k = pick(["ddos","botnet","lateral"]); return k ? LBL[k] : null; }
          if (vector === "email") { const k = pick(["phishing","spam","bec"]); return k ? LBL[k] : null; }
          if (vector === "vulnerability") { const k = pick(["exploit","scanning"]); return k ? LBL[k] : null; }
          if (vector === "data") { const k = pick(["exfiltration"]); return k ? LBL[k] : null; }
          if (vector === "cloud") { const k = pick(["misconfig"]); return k ? LBL[k] : null; }
          if (vector === "identity") { const k = pick(["bruteforce"]); return k ? LBL[k] : null; }
          return null;
        }
        const SECTORS90 = [
          { vector: "email", label: "Email", data: evMap90.get("email") || { count: 0, sev: "none" }, eventTypes: ["email"] },
          { vector: "endpoint", label: "Endpoint", data: evMap90.get("endpoint") || { count: 0, sev: "none" }, eventTypes: ["endpoint"] },
          { vector: "network", label: "Network", data: evMap90.get("network") || { count: 0, sev: "none" }, eventTypes: ["network"] },
          { vector: "web", label: "Web", data: evMap90.get("sse") || { count: 0, sev: "none" }, eventTypes: ["sse"] },
          { vector: "web_app", label: "Web App", data: evMap90.get("waf") || { count: 0, sev: "none" }, eventTypes: ["waf"] },
          { vector: "cloud", label: "Cloud", data: cloudC90, eventTypes: ["casb","cloud"] },
          { vector: "identity", label: "Identity", data: evMap90.get("identity") || { count: 0, sev: "none" }, eventTypes: ["identity"] },
          { vector: "data", label: "Data", data: evMap90.get("dlp") || { count: 0, sev: "none" }, eventTypes: ["dlp"] },
          { vector: "vulnerability", label: "Vulnerability", data: evMap90.get("vulnerability") || { count: 0, sev: "none" }, eventTypes: ["vulnerability"] },
          { vector: "ai", label: "AI", data: { count: aiCount90, sev: aiSev90 }, eventTypes: [] },
        ];
        res.json({ sectors: SECTORS90.map(s => ({ vector: s.vector, label: s.label, count: s.data.count, dominantSeverity: s.data.sev, topSubType: topSubType90(s.vector, s.eventTypes) })), windowDays: 90, fallbackUsed: true });
        return;
      }

      res.json({ sectors: result, windowDays: 30, fallbackUsed: false });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
  // THREAT MAP — Office locations (office-aware arc targeting)
  // ─────────────────────────────────────────────────────────────────────────
  app.get("/api/threat-map/offices", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.query.tenantId as string);
      if (!tenantId) return res.status(400).json({ message: "tenantId required" });

      // Enforce tenant access — prevents cross-tenant IDOR exposure
      await assertTenantAccess(req, tenantId);

      const tenantIds = await getAccessibleTenantIds(req, tenantId);

      // Read all geo-enabled office locations for this tenant from infrastructure_locations (DB-driven)
      const locRes = await pool.query(
        `SELECT id, name, city, country_code, latitude, longitude, hostname_keywords, metadata
         FROM infrastructure_locations
         WHERE tenant_id = ANY($1) AND is_active = true
           AND latitude IS NOT NULL AND longitude IS NOT NULL
         ORDER BY id ASC`,
        [tenantIds]
      );

      const offices = locRes.rows.map((r: any) => ({
        id:               r.id,
        name:             r.name,
        city:             r.city || r.metadata?.city || r.name,
        countryCode:      r.country_code || r.metadata?.countryCode || "US",
        lat:              r.latitude,
        lon:              r.longitude,
        hostnameKeywords: r.hostname_keywords || r.metadata?.hostnameKeywords || [],
        code:             (r.name || "HQ").replace(/^PKF\s+/i, "").substring(0, 4).toUpperCase(),
      }));

      return res.json(offices);
    } catch (error: any) {
      const status = (error as any).status || 500;
      res.status(status).json({ message: error.message });
    }
  });

  // INCIDENT INVESTIGATION CANVAS
  // ─────────────────────────────────────────────────────────────────────────
  app.get("/api/incidents/:id/graph", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);

      const incidentRes = await pool.query(
        `SELECT * FROM incidents WHERE id = $1 LIMIT 1`,
        [incidentId]
      );
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      const incident = incidentRes.rows[0];

      const access = await assertTenantAccess(req, incident.tenant_id);

      const eventsRes = await pool.query(
        `SELECT id, event_type, severity, threat, target, attacker, asset, description, 
                threat_vector, mitre_tactic, mitre_technique, action, source_type, occurred_at, country
         FROM security_events
         WHERE tenant_id = $1
         AND occurred_at BETWEEN $2 AND $3
         ORDER BY occurred_at ASC LIMIT 100`,
        [
          incident.tenant_id,
          new Date(new Date(incident.created_at).getTime() - 2 * 3600000),
          new Date(new Date(incident.created_at).getTime() + 24 * 3600000),
        ]
      );

      const nodes: any[] = [];
      const edges: any[] = [];
      const nodeSet = new Set<string>();

      function addNode(id: string, label: string, type: string, severity?: string) {
        if (!nodeSet.has(id)) {
          nodeSet.add(id);
          nodes.push({ id, label, type, severity: severity || "medium" });
        }
      }

      for (const e of eventsRes.rows) {
        if (e.attacker && e.attacker.length < 100) addNode(`ip:${e.attacker}`, e.attacker, "attacker", "high");
        if (e.target && e.target.length < 100) addNode(`asset:${e.target}`, e.target, "asset", e.severity);
        if (e.asset && e.asset.length < 100) addNode(`asset:${e.asset}`, e.asset, "asset", e.severity);
        if (e.attacker && e.target) {
          edges.push({ from: `ip:${e.attacker}`, to: `asset:${e.target}`, label: e.mitre_tactic || e.action || "attacked", eventId: e.id });
        }
        if (e.attacker && e.asset) {
          edges.push({ from: `ip:${e.attacker}`, to: `asset:${e.asset}`, label: e.action || "targeted", eventId: e.id });
        }
      }

      if (incident.source_ip) addNode(`ip:${incident.source_ip}`, incident.source_ip, "attacker", "critical");
      if (incident.destination_ip) addNode(`asset:${incident.destination_ip}`, incident.destination_ip, "asset", "high");

      const rawIocData = incident.ioc_data as any;
      const iocArr: any[] = Array.isArray(rawIocData)
        ? rawIocData
        : (rawIocData?.indicators && Array.isArray(rawIocData.indicators))
          ? rawIocData.indicators
          : [];
      for (const ioc of iocArr.slice(0, 10)) {
        addNode(`ioc:${ioc.value}`, ioc.value, "ioc", ioc.reputation === "malicious" ? "high" : "medium");
        if (incident.source_ip) edges.push({ from: `ip:${incident.source_ip}`, to: `ioc:${ioc.value}`, label: "used IOC" });
      }

      res.json({
        incident,
        nodes,
        edges: edges.slice(0, 100),
        timeline: eventsRes.rows,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ─────────────────────────────────────────────────────────────────────────
