  // Entity Graph Snapshot: POST to store, GET to retrieve (for PDF report embedding)
    app.post("/api/incidents/:id/entity-graph-snapshot", isAuthenticated, async (req: any, res) => {
      try {
        const incidentId = parseInt(req.params.id);
        const incidentRes = await pool.query(`SELECT tenant_id FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
        if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
        if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
        const { pngDataUrl } = req.body;
        if (!pngDataUrl || typeof pngDataUrl !== "string" || !pngDataUrl.startsWith("data:image/png")) {
          return res.status(400).json({ message: "Invalid PNG data URL" });
        }
        if (pngDataUrl.length > 5 * 1024 * 1024) return res.status(413).json({ message: "Image too large (max 5MB)" });
        setEntityGraphSnapshot(incidentId, pngDataUrl);
        res.json({ success: true, message: "Entity graph snapshot saved for report embedding" });
      } catch (error: any) {
        res.status(error.status || 500).json({ message: error.message });
      }
    });

    app.get("/api/incidents/:id/entity-graph-snapshot", isAuthenticated, async (req: any, res) => {
      try {
        const incidentId = parseInt(req.params.id);
        const incidentRes = await pool.query(`SELECT tenant_id FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
        if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
        if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
        const snapshot = entityGraphSnapshots.get(incidentId);
        res.json({ hasSnapshot: !!snapshot, savedAt: snapshot ? new Date().toISOString() : null });
      } catch (error: any) {
        res.status(error.status || 500).json({ message: error.message });
      }
    });

    app.get("/api/incidents/:id/evidence", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);
      const incidentRes = await pool.query(`SELECT tenant_id FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
      const evidence = await pool.query(`SELECT * FROM incident_evidence WHERE incident_id = $1 ORDER BY created_at ASC`, [incidentId]);
      res.json(evidence.rows);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  app.post("/api/incidents/:id/evidence", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);
      const incidentRes = await pool.query(`SELECT tenant_id FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      const { type, value, description } = req.body;
      if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
      const addedBy = req.session?.isSuperAdmin ? (req.session.superadminId || "superadmin") : (await getUserTenantAccess(req)).userId;
      const hash = crypto.createHash("sha256").update(`${incidentId}:${type}:${value}:${Date.now()}`).digest("hex");
      const result = await pool.query(`INSERT INTO incident_evidence (incident_id, tenant_id, type, value, description, added_by, chain_of_custody_hash) VALUES ($1, $2, $3, $4, $5, $6, $7) RETURNING *`,
        [incidentId, incidentRes.rows[0].tenant_id, type || "note", value, description, addedBy, hash]);
      res.json(result.rows[0]);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  app.delete("/api/incidents/:id/evidence/:evidenceId", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);
      const evidenceId = parseInt(req.params.evidenceId);
      const incidentRes = await pool.query(`SELECT tenant_id FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
      await pool.query(`DELETE FROM incident_evidence WHERE id = $1 AND incident_id = $2`, [evidenceId, incidentId]);
      res.json({ success: true });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // Quick Actions for War Room: escalate severity
  app.post("/api/incidents/:id/escalate", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);
      const incidentRes = await pool.query(`SELECT tenant_id, severity FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
      const severityLadder = ["low", "medium", "high", "critical"];
      const current = (incidentRes.rows[0].severity || "medium").toLowerCase();
      const idx = severityLadder.indexOf(current);
      const newSeverity = severityLadder[Math.min(idx + 1, severityLadder.length - 1)];
      await pool.query(`UPDATE incidents SET severity = $1, updated_at = NOW() WHERE id = $2`, [newSeverity, incidentId]);
      res.json({ success: true, severity: newSeverity });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // Quick Actions for War Room: classify as TP or FP
  app.post("/api/incidents/:id/classify", isAuthenticated, async (req: any, res) => {
    try {
      const incidentId = parseInt(req.params.id);
      const { classification } = req.body; // "true_positive" | "false_positive" | "inconclusive" | null
      if (classification && !["true_positive", "false_positive", "inconclusive"].includes(classification)) {
        return res.status(400).json({ message: "classification must be 'true_positive', 'false_positive', 'inconclusive', or null" });
      }
      const incidentRes = await pool.query(`SELECT tenant_id, severity, confidence_score, source_ip, destination_ip FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
      if (!incidentRes.rows.length) return res.status(404).json({ message: "Incident not found" });
      if (!req.session?.isSuperAdmin) await assertTenantAccess(req, incidentRes.rows[0].tenant_id);
      const newStatus = classification === "false_positive" ? "resolved" : (classification === "true_positive" ? "in_progress" : undefined);
      const updateQuery = newStatus
        ? `UPDATE incidents SET classification = $1, status = $2, updated_at = NOW() WHERE id = $3`
        : `UPDATE incidents SET classification = $1, updated_at = NOW() WHERE id = $2`;
      const params = newStatus ? [classification, newStatus, incidentId] : [classification, incidentId];
      await pool.query(updateQuery, params);

      // Auto-nominate IOCs when incident is classified as True Positive with confidence >= 80
      if (classification === "true_positive") {
        const inc = incidentRes.rows[0];
        try {
          await autoNominateIncidentIOCs(
            inc.tenant_id, incidentId,
            inc.source_ip, inc.destination_ip,
            inc.confidence_score ?? 80,
            req.user?.claims?.sub ?? "system"
          );
        } catch (_) { /* non-blocking */ }

        // Auto-draft a detection rule for confirmed True Positives (non-blocking background task)
        setImmediate(async () => {
          try {
            await generateRuleFromIncident(
              inc.tenant_id,
              incidentId,
              req.user?.claims?.sub ?? "system"
            );
          } catch (e: any) {
            console.warn(`[DetectionEngine] Auto-draft rule from incident ${incidentId} failed:`, e.message);
          }
        });

        // Auto-generate and persist response plan on TP confirmation (idempotent)
        setImmediate(async () => {
          try {
            const { isNew } = await generateAndPersistResponsePlan(incidentId);
            if (isNew) console.info(`[ResponseEngine] Auto-generated & persisted response plan for TP incident #${incidentId}`);
          } catch (e: any) {
            console.warn(`[ResponseEngine] Auto-plan generation failed for incident ${incidentId}:`, e.message);
          }
        });
      }

      // Capture analyst decision for adaptive learning (non-blocking)
      if (classification) {
        setImmediate(async () => {
          try {
            const incRow = incidentRes.rows[0];
            // Fetch triage info for the incident
            const triageRow = await pool.query(
              `SELECT triage_suggested_classification, triage_score, ioc_data, mitre_tactic, confidence_score,
                      source_type, log_source, asset, destination_ip, source_ip FROM incidents WHERE id = $1 LIMIT 1`,
              [incidentId]
            );
            const td = triageRow.rows[0] ?? {};
            const rawIocData: unknown = td.ioc_data;
            const iocArr: unknown[] = Array.isArray(rawIocData) ? rawIocData : ((rawIocData as { indicators?: unknown[] } | null)?.indicators ?? []);
            // Determine sourceType from the incident's source fields
            const sourceType = td.source_type || td.log_source || null;
            // Determine assetCriticality — look it up from the assets table
            let assetCriticality: string | null = null;
            if (td.asset) {
              try {
                const assetRow = await pool.query(`SELECT criticality FROM assets WHERE name = $1 AND tenant_id = $2 LIMIT 1`, [td.asset, incRow.tenant_id]);
                assetCriticality = assetRow.rows[0]?.criticality ?? null;
              } catch (_) {}
            }
            await captureAnalystDecision({
              tenantId: incRow.tenant_id,
              incidentId,
              analystId: req.user?.id ?? req.user?.claims?.sub ?? "unknown",
              analystVerdict: classification as "true_positive" | "false_positive" | "inconclusive",
              incidentSeverity: incRow.severity ?? null,
              mitreTactic: td.mitre_tactic ?? null,
              iocCount: iocArr.length,
              aiSuggestedClassification: td.triage_suggested_classification ?? null,
              aiConfidence: td.confidence_score ?? td.triage_score ?? null,
              sourceType,
              assetCriticality,
            });
          } catch (_) { /* non-blocking, never fail the main response */ }
        });
      }

      res.json({ success: true, classification });
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

  // ── Malware Analysis Routes (#119) ──────────────────────────────────────

  // Enforce a 5 MB request-size cap for malware analysis before body parsing is trusted
  app.post("/api/malware/analyze", isAuthenticated, (req, _res, next) => {
    const contentLength = parseInt(req.headers["content-length"] ?? "0", 10);
    if (contentLength > 5 * 1024 * 1024) {
      _res.status(413).json({ message: "Request too large (max 5MB)" });
      return;
    }
    next();
  }, async (req: any, res) => {
    try {
      const { content, language = "auto", fileType = "auto", incidentId } = req.body;
      if (!content || typeof content !== "string") {
        return res.status(400).json({ message: "content is required and must be a string" });
      }
      // Secondary guard: enforce content byte length ≤ 5 MB after body parsing (handles multibyte chars)
      if (Buffer.byteLength(content, "utf8") > 5 * 1024 * 1024) {
        return res.status(413).json({ message: "Script content too large (max 5MB)" });
      }
      const validLangs = ["powershell", "bash", "python", "vbscript", "javascript", "batch", "auto"];
      if (!validLangs.includes(language)) {
        return res.status(400).json({ message: `language must be one of: ${validLangs.join(", ")}` });
      }
      const validFileTypes = ["text_script", "text_other", "text_html", "binary_pe", "binary_elf", "binary_zip", "binary_pdf", "binary_other", "auto"];
      const resolvedFileType = validFileTypes.includes(fileType) ? fileType : "auto";
      const result = await analyzeScript(content, language, resolvedFileType);

      // Determine risk score from confidence and verdict
      const baseRisk = result.confidenceScore;
      const riskScore = result.verdict === "malicious" ? Math.max(60, baseRisk) : result.verdict === "suspicious" ? Math.min(59, Math.max(25, baseRisk)) : Math.min(24, baseRisk);

      // Normalize verdict to UI-expected values
      const verdictMap: Record<string, string> = { clean: "benign", suspicious: "suspicious", malicious: "malicious" };
      const normalizedVerdict = verdictMap[result.verdict] ?? "suspicious";

      // Normalize lineAnnotations → annotations (UI-expected shape)
      const annotations = result.lineAnnotations.map(a => ({
        line: a.lineNumber,
        code: a.code,
        severity: a.severity,
        description: a.behavior,
        category: a.technique,
      }));

      // Typed interface for IOCs enriched with reputation data
      interface EnrichedIoc {
        type: string;
        value: string;
        context?: string;
        confidence?: number;
        severity: string;
        reputation?: string;
        country?: string | null;
        intelConfidence?: number | null;
        malwareFamily?: string | null;
      }

      // Normalize IOCs — add severity field
      const normalizedIocs: EnrichedIoc[] = result.iocs.map(ioc => ({
        ...ioc,
        severity: (result.verdict === "malicious" ? "high" : result.verdict === "suspicious" ? "medium" : "low"),
        reputation: undefined,
        country: undefined,
        intelConfidence: undefined,
        malwareFamily: undefined,
      }));

      // Normalize mitreMappings — add tacticId/tacticName fields
      const normalizedMitre = result.mitreMappings.map(m => ({
        tacticId: m.tactic?.replace(/\s+/g, "-").toLowerCase() ?? "unknown",
        tacticName: m.tactic ?? "Unknown",
        techniqueId: m.techniqueId,
        techniqueName: m.techniqueName,
        confidence: m.confidence,
      }));

      // Use analysisSource from the engine itself — deterministic/ai/rule_based
      const analysisMethod: "ai" | "rule_based" =
        result.analysisSource === "ai" ? "ai" : "rule_based";

      const normalizedResult = {
        language: result.language,
        verdict: normalizedVerdict,
        confidence: result.confidenceScore,
        summary: result.summary,
        annotations,
        iocs: normalizedIocs,
        evasionTechniques: result.evasionTechniques,
        mitreMappings: normalizedMitre,
        riskScore,
        analysisMethod,
        analysisSource: result.analysisSource,
        fileType: result.fileType,
        analyzedAt: result.analyzedAt,
        lineCount: result.lineCount,
        malwareFamily: result.malwareFamily ?? null,
        threatCategory: result.threatCategory ?? null,
      };

      // ── IOC Reputation Lookup ─────────────────────────────────────────────
      // Async enrichment: look up each extracted IOC in the threat intel database
      // and attach reputation/country/malwareFamily data. For confirmed-malicious
      // hash IOCs, escalate the overall verdict/confidence/riskScore.
      {
        const tenantAccess = await getUserTenantAccess(req).catch(() => null);
        const tenantId = tenantAccess?.tenantId;
        if (tenantId && normalizedIocs.length > 0) {
          try {
            const iocValues = normalizedIocs.map(i => i.value).filter(Boolean);
            if (iocValues.length > 0) {
              const placeholders = iocValues.map((_, idx) => `$${idx + 2}`).join(", ");
              const repRows = await pool.query(
                `SELECT indicator_value, reputation, country, confidence, malware_family, tags, context FROM threat_intel_iocs
                 WHERE tenant_id = $1 AND LOWER(indicator_value) = ANY(ARRAY[${placeholders}]) LIMIT 100`,
                [tenantId, ...iocValues.map(v => v.toLowerCase())]
              );
              const repMap: Record<string, { reputation: string; country: string | null; confidence: number | null; malwareFamily: string | null }> = {};
              for (const row of repRows.rows) {
                // Use malware_family column directly; fall back to tags/context for legacy rows
                const directFamily = row.malware_family ? String(row.malware_family) : null;
                const tags: string[] = Array.isArray(row.tags) ? row.tags : [];
                const familyFromTags = tags.find((t: string) => !["malicious","suspicious","clean","hash","ip","domain","url"].includes(t.toLowerCase()));
                const familyFromContext = row.context ? String(row.context).split(/[,;.|]/)[0].trim().slice(0, 60) : null;
                const malwareFamily = directFamily ?? familyFromTags ?? familyFromContext ?? null;
                repMap[row.indicator_value.toLowerCase()] = {
                  reputation: row.reputation,
                  country: row.country,
                  confidence: Number(row.confidence) || null,
                  malwareFamily,
                };
              }
              // Merge reputation data back into normalizedResult.iocs (all elements are EnrichedIoc)
              let foundMaliciousHash = false;
              let bestIntelConfidence = 0;
              let bestMalwareFamily: string | null = null;
              for (const ioc of normalizedResult.iocs as EnrichedIoc[]) {
                const rep = repMap[ioc.value.toLowerCase()];
                if (rep) {
                  ioc.reputation = rep.reputation;
                  ioc.country = rep.country;
                  ioc.intelConfidence = rep.confidence;
                  ioc.malwareFamily = rep.malwareFamily;
                  // Escalate IOC severity for any confirmed-malicious IOC
                  if (rep.reputation === "malicious") {
                    ioc.severity = "high";
                    // Update context with malware family for hash IOCs
                    if (ioc.type === "hash") {
                      const familyLabel = rep.malwareFamily ? ` — ${rep.malwareFamily}` : "";
                      const hashType = ioc.value.length === 32 ? "MD5" : ioc.value.length === 40 ? "SHA-1" : "SHA-256";
                      ioc.context = `Known malicious ${hashType} hash${familyLabel} (threat intelligence confirmed)`;
                      foundMaliciousHash = true;
                      if ((rep.confidence ?? 0) > bestIntelConfidence) {
                        bestIntelConfidence = rep.confidence ?? 0;
                        bestMalwareFamily = rep.malwareFamily;
                      }
                    }
                  } else if (rep.reputation === "suspicious" && ioc.severity === "low") {
                    ioc.severity = "medium";
                  }
                }
              }
              // Escalate overall result when a hash IOC is confirmed malicious by threat intel
              if (foundMaliciousHash) {
                normalizedResult.verdict = "malicious";
                normalizedResult.confidence = Math.max(75, normalizedResult.confidence);
                normalizedResult.riskScore = Math.max(75, normalizedResult.riskScore);
                if (bestMalwareFamily && !normalizedResult.malwareFamily) {
                  normalizedResult.malwareFamily = bestMalwareFamily;
                }
                normalizedResult.summary = normalizedResult.summary.replace(
                  /awaiting threat intel reputation lookup/i,
                  `confirmed malicious by threat intelligence${bestMalwareFamily ? ` (${bestMalwareFamily})` : ""}`
                );
              }
            }
          } catch (_) { /* non-blocking IOC reputation enrichment */ }
        }
      }

      // ── Open-Source Threat Feed + Sandbox Enrichment (concurrent) ──────────────────────────────────────────────────────────────────────
      // Feed enrichment and sandbox enrichment run concurrently to minimize latency.
      // Each individual feed call has a 2s timeout; sandbox calls have 8s timeouts.
      try {
        const supportedTypes = ['hash', 'ip', 'domain', 'url', 'phishing_url'];
        const feedableIocs = normalizedIocs
          .filter(ioc => supportedTypes.includes(ioc.type))
          .map(ioc => ({ type: ioc.type === 'phishing_url' ? 'url' : ioc.type, value: ioc.value }));

        // Collect unique hash IOCs for sandbox enrichment
        const hashValues = [...new Set(
          normalizedIocs.filter(ioc => ioc.type === 'hash').map(ioc => ioc.value.toLowerCase())
        )].slice(0, 3); // top 3 distinct hashes

        // Run feed enrichment, sandbox enrichment, and Sigma rule matching concurrently
        const [feedResult, sandboxResults, sigmaMatches] = await Promise.all([
          feedableIocs.length > 0
            ? enrichIOCsFromPublicFeeds(feedableIocs)
            : Promise.resolve(null),
          hashValues.length > 0
            ? enrichHashWithSandboxes(hashValues[0]) // primary hash
            : Promise.resolve(null),
          // Sigma rule intelligence — synchronous but wrapped for consistent concurrent execution
          Promise.resolve().then(() => matchMalwareContent(content, normalizedIocs)).catch(() => [] as SigmaMatch[]),
        ]);

        if (feedResult) {
          // Key enrichment lookup by (type,value) to avoid collisions when different IOC types share the same literal value
          const enrichMap = new Map<string, typeof feedResult.iocResults[0]['enrichments']>();
          for (const r of feedResult.iocResults) {
            const mapKey = `${r.type}:${r.value.toLowerCase()}`;
            enrichMap.set(mapKey, r.enrichments);
          }

          // Merge feed enrichments into each IOC
          for (const ioc of normalizedIocs) {
            const iocType = ioc.type === 'phishing_url' ? 'url' : ioc.type;
            const enrichments = enrichMap.get(`${iocType}:${ioc.value.toLowerCase()}`);
            if (enrichments && enrichments.length > 0) {
              (ioc as Record<string, unknown>)['feedEnrichments'] = enrichments;
              // If any feed scored a hit and we haven't already found malware family, use feed data
              const hitEnr = enrichments.find(e => e.status === 'hit');
              if (hitEnr) {
                if (!ioc.malwareFamily && hitEnr.malwareFamily) {
                  ioc.malwareFamily = hitEnr.malwareFamily;
                }
                if (!ioc.country && hitEnr.country) {
                  ioc.country = hitEnr.country;
                }
                // Escalate severity for feed-confirmed malicious IOCs
                if (ioc.severity === 'low' || ioc.severity === 'medium') {
                  ioc.severity = 'high';
                }
                if (!ioc.reputation) {
                  ioc.reputation = 'malicious';
                }
                // Update context for hash IOCs so it reflects feed confirmation
                if (ioc.type === 'hash') {
                  const hashType = ioc.value.length === 64 ? 'SHA-256'
                    : ioc.value.length === 40 ? 'SHA-1'
                    : 'MD5';
                  const familyLabel = hitEnr.malwareFamily ? ` – ${hitEnr.malwareFamily}` : '';
                  ioc.context = `Known malicious ${hashType} hash${familyLabel} confirmed by ${hitEnr.feedName}`;
                }
              }
            }
          }

          // Verdict escalation from feeds
          if (feedResult.verdictEscalation) {
            normalizedResult.verdict = 'malicious';
            normalizedResult.confidence = Math.max(normalizedResult.confidence, 80);
            normalizedResult.riskScore = Math.max(normalizedResult.riskScore, 80);
          }

          (normalizedResult as Record<string, unknown>)['feedSources'] = feedResult.feedSources;
        } else {
          // No feedable IOCs — return feed availability metadata from DB
          try {
            const piRows = await pool.query('SELECT name, enabled, api_key, requires_key FROM platform_integrations');
            const piMap: Record<string, { enabled: boolean; hasKey: boolean; requiresKey: boolean }> = {};
            for (const r of piRows.rows) piMap[r.name] = { enabled: r.enabled, hasKey: !!r.api_key, requiresKey: r.requires_key };
            const pi = (slug: string) => piMap[slug] ?? { enabled: true, hasKey: false, requiresKey: false };
            (normalizedResult as Record<string, unknown>)['feedSources'] = [
              { name: 'MalwareBazaar', requiresKey: false, keyConfigured: true,                     status: pi('malwarebazaar').enabled   ? 'skipped' : 'disabled', hitCount: 0 },
              { name: 'URLhaus',       requiresKey: false, keyConfigured: true,                     status: pi('urlhaus').enabled         ? 'skipped' : 'disabled', hitCount: 0 },
              { name: 'Feodo Tracker', requiresKey: false, keyConfigured: true,                     status: pi('feodo_tracker').enabled   ? 'skipped' : 'disabled', hitCount: 0 },
              { name: 'AlienVault OTX', requiresKey: true, keyConfigured: pi('alienvault_otx').hasKey, status: !pi('alienvault_otx').enabled ? 'disabled' : pi('alienvault_otx').hasKey ? 'skipped' : 'no_key', hitCount: 0 },
              { name: 'VirusTotal',    requiresKey: true, keyConfigured: pi('virustotal').hasKey,   status: !pi('virustotal').enabled     ? 'disabled' : pi('virustotal').hasKey   ? 'skipped' : 'no_key', hitCount: 0 },
            ];
          } catch {
            (normalizedResult as Record<string, unknown>)['feedSources'] = [
              { name: 'MalwareBazaar', requiresKey: false, keyConfigured: true, status: 'skipped', hitCount: 0 },
              { name: 'URLhaus',       requiresKey: false, keyConfigured: true, status: 'skipped', hitCount: 0 },
              { name: 'Feodo Tracker', requiresKey: false, keyConfigured: true, status: 'skipped', hitCount: 0 },
              { name: 'AlienVault OTX', requiresKey: true, keyConfigured: false, status: 'no_key', hitCount: 0 },
              { name: 'VirusTotal',    requiresKey: true, keyConfigured: false, status: 'no_key', hitCount: 0 },
            ];
          }
        }

        // Attach sandbox enrichments to response if any hash IOCs were found
        if (sandboxResults) {
          (normalizedResult as Record<string, unknown>)['sandboxEnrichments'] = sandboxResults;
        }

        // Attach Sigma detection rule matches (always set — empty array = no matches)
        (normalizedResult as Record<string, unknown>)['sigmaMatches'] = sigmaMatches ?? [];
      } catch (_) {
        // Non-blocking — feed/sandbox enrichment should not crash the analysis
        (normalizedResult as Record<string, unknown>)['feedSources'] = [
          { name: 'MalwareBazaar', requiresKey: false, keyConfigured: true, status: 'unavailable', hitCount: 0 },
          { name: 'URLhaus',       requiresKey: false, keyConfigured: true, status: 'unavailable', hitCount: 0 },
          { name: 'Feodo Tracker', requiresKey: false, keyConfigured: true, status: 'unavailable', hitCount: 0 },
          { name: 'AlienVault OTX', requiresKey: true, keyConfigured: false, status: 'unavailable', hitCount: 0 },
          { name: 'VirusTotal',    requiresKey: true, keyConfigured: false, status: 'unavailable', hitCount: 0 },
        ];
        // Always set sigmaMatches even in enrichment error path so UI empty-state renders correctly
        if ((normalizedResult as Record<string, unknown>)['sigmaMatches'] === undefined) {
          (normalizedResult as Record<string, unknown>)['sigmaMatches'] = [];
        }
      }

            // If linked to an incident, auto-add IOCs to incident's ioc_data
      if (incidentId && result.iocs.length > 0) {
        try {
          const incRes = await pool.query(`SELECT tenant_id, ioc_data FROM incidents WHERE id = $1 LIMIT 1`, [incidentId]);
          if (incRes.rows.length) {
            await assertTenantAccess(req, incRes.rows[0].tenant_id);
            const rawExistingIoc: unknown = incRes.rows[0].ioc_data;
            const existing: unknown[] = Array.isArray(rawExistingIoc)
              ? rawExistingIoc
              : ((rawExistingIoc as { indicators?: unknown[] } | null)?.indicators ?? []);
            const newIocs = normalizedIocs.map(ioc => ({
              type: ioc.type,
              value: ioc.value,
              reputation: normalizedVerdict === "malicious" ? "malicious" : "suspicious",
              source: "malware_analysis",
              context: ioc.context,
            }));
            const merged = [...existing, ...newIocs];
            await pool.query(`UPDATE incidents SET ioc_data = $1, updated_at = NOW() WHERE id = $2`, [
              JSON.stringify(merged),
              incidentId,
            ]);
          }
        } catch (_) { /* non-blocking */ }
      }

      res.json(normalizedResult);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message || "Malware analysis failed" });
    }
  });

