  app.get("/api/ai-learning/trend/:tenantId", isAuthenticated, async (req: any, res) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      await assertTenantAccess(req, tenantId);
      // Return 30-day daily AI accuracy trend (% analyst decisions that agreed with AI suggestion)
      const rows = await pool.query(`
        SELECT
          DATE(created_at AT TIME ZONE 'UTC') as day,
          COUNT(*) as total,
          SUM(CASE WHEN ai_matched THEN 1 ELSE 0 END) as matched
        FROM ai_learning_feedback
        WHERE tenant_id = $1 AND created_at >= NOW() - INTERVAL '30 days'
        GROUP BY DATE(created_at AT TIME ZONE 'UTC')
        ORDER BY day
      `, [tenantId]);
      // Fill all 30 days — null accuracy for days with no data
      const trend: Array<{ day: string; total: number; matched: number; accuracy: number | null }> = [];
      for (let i = 29; i >= 0; i--) {
        const d = new Date();
        d.setUTCDate(d.getUTCDate() - i);
        const dayStr = d.toISOString().split("T")[0];
        interface TrendRow { day: string | Date; total: string | number; matched: string | number; }
        const found = (rows.rows as TrendRow[]).find(r => r.day === dayStr || (r.day instanceof Date && r.day.toISOString().startsWith(dayStr)));
        const total = found ? Number(found.total) : 0;
        const matched = found ? Number(found.matched) : 0;
        trend.push({ day: dayStr, total, matched, accuracy: total > 0 ? Math.round((matched / total) * 100) : null });
      }
      res.json(trend);
    } catch (error: any) {
      res.status(error.status || 500).json({ message: error.message });
    }
  });

