  // GET  /api/assets/:id/edr-assessments  — list past assessments (MSS only)
  app.get("/api/assets/:id/edr-assessments", isAuthenticated, async (req: any, res: any) => {
    try {
      const assetId = parseInt(req.params.id);
      if (isNaN(assetId)) return res.status(400).json({ message: "Invalid asset ID" });

      const access = await assertTenantAccess(req, req.user?.tenantId);
      assertMSSRole(access);
      const { tenantId } = access;

      const { edrCisAssessments, assets: assetsTable } = await import("@shared/schema");

      const [asset] = await db.select({ id: assetsTable.id }).from(assetsTable).where(
        and(eq(assetsTable.id, assetId), eq(assetsTable.tenantId, tenantId))
      );
      if (!asset) return res.status(404).json({ message: "Asset not found" });

      const rows = await db.select().from(edrCisAssessments)
        .where(and(eq(edrCisAssessments.assetId, assetId), eq(edrCisAssessments.tenantId, tenantId)))
        .orderBy(desc(edrCisAssessments.runAt))
        .limit(20);

      res.json(rows);
    } catch (e: any) {
      res.status(e.status ?? 500).json({ message: e.message });
    }
  });

