  // GET  /api/tenants/:tenantId/edr-schedule  — get tenant EDR schedule config (MSS only)
  app.get("/api/tenants/:tenantId/edr-schedule", isAuthenticated, async (req: any, res: any) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });

      const access = await assertTenantAccess(req, tenantId);
      assertMSSRole(access);

      const { securityIntegrations: si } = await import("@shared/schema");
      const integrations = await db
        .select({ id: si.id, platformKey: si.platformKey, configJson: si.configJson, isEnabled: si.isEnabled, status: si.status })
        .from(si)
        .where(
          and(
            eq(si.tenantId, tenantId),
            inArray(si.platformKey, ["cynet", "crowdstrike", "sentinelone", "ms_defender_endpoint"])
          )
        );

      const edrIntegration =
        integrations.find(i => i.status === 'connected') ??
        integrations.find(i => i.status == null && i.isEnabled === true) ??
        null;
      const configJson = (edrIntegration?.configJson as Record<string, any>) ?? {};
      const edrSchedule = configJson.edrSchedule ?? {
        enabled: false,
        dayOfWeek: 1,
        hourUtc: 2,
        platform: edrIntegration?.platformKey ?? null,
      };

      res.json({
        tenantId,
        edrSchedule,
        connectedPlatform: edrIntegration?.platformKey ?? null,
        hasEdrIntegration: !!edrIntegration,
      });
    } catch (e: any) {
      res.status(e.status ?? 500).json({ message: e.message });
    }
  });

  // PUT  /api/tenants/:tenantId/edr-schedule  — update tenant EDR schedule config (MSS admin only)
  app.put("/api/tenants/:tenantId/edr-schedule", isAuthenticated, async (req: any, res: any) => {
    try {
      const tenantId = parseInt(req.params.tenantId);
      if (isNaN(tenantId)) return res.status(400).json({ message: "Invalid tenant ID" });

      const access = await assertTenantAccess(req, tenantId);
      assertMSSRole(access);
      // Schedule writes require an elevated MSS admin or platform admin role
      const edrScheduleAdminRoles = ["platform_admin", "mss_admin", "soc_manager"];
      if (!edrScheduleAdminRoles.includes(access.role)) {
        return res.status(403).json({ message: "Forbidden: MSS admin role required to modify EDR schedule" });
      }

      const { enabled, dayOfWeek, hourUtc } = req.body ?? {};
      if (typeof enabled !== "boolean") return res.status(400).json({ message: "enabled (boolean) is required" });

      const { securityIntegrations: si } = await import("@shared/schema");
      const integrations = await db
        .select({ id: si.id, configJson: si.configJson })
        .from(si)
        .where(
          and(
            eq(si.tenantId, tenantId),
            inArray(si.platformKey, ["cynet", "crowdstrike", "sentinelone", "ms_defender_endpoint"]),
            eq(si.isEnabled, true)
          )
        )
        .limit(1);

      if (!integrations.length) return res.status(404).json({ message: "No active EDR integration found for this tenant" });

      const integration = integrations[0];
      const existing = (integration.configJson as Record<string, any>) ?? {};
      const updated = {
        ...existing,
        edrSchedule: {
          enabled,
          dayOfWeek: dayOfWeek ?? 1,
          hourUtc: hourUtc ?? 2,
        },
      };

      await db.update(si).set({ configJson: updated }).where(eq(si.id, integration.id));
      res.json({ success: true, edrSchedule: updated.edrSchedule });
    } catch (e: any) {
      res.status(e.status ?? 500).json({ message: e.message });
    }
  });

