  // ── ARIA Streaming Chat (SSE) ────────────────────────────────────────────────
  // POST /api/aria/stream
  // Accepts { question: string, tenantId: number } and streams token-by-token
  // AI responses using SSE (text/event-stream).  Works with any configured
  // AI provider: OpenAI-compatible providers use their native streaming, and
  // AWS Bedrock uses InvokeModelWithResponseStream via the Bedrock shim.
  //
  // Event format:
  //   data: {"type":"delta","content":"<token>"}
  //   data: {"type":"done"}
  //   data: {"type":"error","message":"<reason>"}
  app.post("/api/aria/stream", isAuthenticated, async (req: any, res) => {
    const { question, tenantId } = req.body;
    if (!question || typeof question !== "string") {
      return res.status(400).json({ error: "question required" });
    }
    const tid = parseInt(tenantId) || 0;

    res.setHeader("Content-Type", "text/event-stream");
    res.setHeader("Cache-Control", "no-cache");
    res.setHeader("Connection", "keep-alive");
    res.setHeader("X-Accel-Buffering", "no");
    res.flushHeaders();

    let closed = false;
    req.on("close", () => { closed = true; });

    try {
      const ai = createAIClient();
      const streamResult = await ai.chat.completions.create({
        model: getDefaultModel(),
        stream: true,
        max_tokens: 512,
        temperature: 0.3,
        messages: [
          {
            role: "system",
            content: `You are ARIA, an expert AI SOC analyst for Cyber Command Center — a multi-tenant MSSP platform. 
Answer concisely and professionally. Use **bold** for key numbers and important terms.
Tenant context: tenantId=${tid}, today=${new Date().toISOString().split("T")[0]}.`
          },
          { role: "user", content: question }
        ],
      });

      // Iterate the stream — works with both OpenAI AsyncIterable and BedrockStream
      for await (const chunk of streamResult as AsyncIterable<any>) {
        if (closed) break;
        const content = chunk.choices?.[0]?.delta?.content;
        if (content) {
          res.write(`data: ${JSON.stringify({ type: "delta", content })}\n\n`);
        }
      }

      if (!closed) {
        res.write(`data: ${JSON.stringify({ type: "done" })}\n\n`);
        res.end();
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : String(err);
      if (!closed) {
        res.write(`data: ${JSON.stringify({ type: "error", message })}\n\n`);
        res.end();
      }
    }
  });

  // ── AI Provider Settings ────────────────────────────────────────────────────
  // GET /api/admin/ai-provider-settings
