  // POST /api/admin/ai-provider-settings
  // Updates AI_PROVIDER and AI_REGION in the running process environment.
  // Changes take effect immediately for new requests (resetAIClient() clears the singleton).
  // For persistent changes across restarts, the environment variables must be
  // updated in the deployment configuration (Secrets Manager / ECS task definition).
  app.post("/api/admin/ai-provider-settings", isAuthenticated, isSuperAdminOrPlatformAdmin, async (req: any, res) => {
    try {
      const { provider, model, region, baseURL, apiKey } = req.body;
      const validProviders = ["openai", "anthropic", "ollama", "azure", "vertex", "huggingface", "custom", "bedrock", "grok", "deepseek", "kimi", "zai"];
      if (provider && !validProviders.includes(provider)) {
        return res.status(400).json({ message: `Invalid provider. Must be one of: ${validProviders.join(", ")}` });
      }

      if (provider) process.env.AI_PROVIDER = provider;
      if (model)    process.env.AI_MODEL    = model;
      if (region)   process.env.AI_REGION   = region;
      if (baseURL)  process.env.AI_BASE_URL  = baseURL;
      if (apiKey)   process.env.AI_API_KEY   = apiKey;

      // Reset singleton so next call uses new config
      resetAIClient();

      const info = getAIProviderInfo();
      res.json({ success: true, provider: info.provider, model: info.model, region: info.region });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // POST /api/admin/ai-provider-test
  // Tests the current (or specified) AI provider configuration.
  // For Bedrock: calls probeBedrockConnection() — no model inference charge (minimal prompt).
  // For OpenAI-compatible: sends a minimal chat completion request.
  app.post("/api/admin/ai-provider-test", isAuthenticated, isSuperAdminOrPlatformAdmin, async (req: any, res) => {
    try {
      const { provider: reqProvider, model: reqModel, region: reqRegion } = req.body;
      const effectiveProvider = reqProvider || process.env.AI_PROVIDER || "openai";

      if (effectiveProvider === "bedrock") {
        const result = await probeBedrockConnection(reqModel, reqRegion);
        return res.json(result);
      }

      // OpenAI-compatible test
      const ai = createAIClient();
      const start = Date.now();
      try {
        const resp = await ai.chat.completions.create({
          model: reqModel || process.env.AI_MODEL || "gpt-4o-mini",
          messages: [{ role: "user", content: "Reply with OK" }],
          max_tokens: 5,
        });
        const latencyMs = Date.now() - start;
        const text = resp?.choices?.[0]?.message?.content || "";
        return res.json({ ok: true, latencyMs, response: text, model: reqModel || process.env.AI_MODEL || "gpt-4o-mini" });
      } catch (aiErr: any) {
        return res.json({ ok: false, error: aiErr?.message ?? String(aiErr) });
      }
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // ── Platform Integrations (#135) ─────────────────────────────────────────────
  // Manage platform-wide third-party integrations. API keys stored in DB only.
  // Restricted to platform_admin / superadmin.

  // GET /api/admin/platform-integrations — list all integrations (keys masked)
  app.get("/api/admin/platform-integrations", isSuperAdminOrPlatformAdmin, async (_req, res) => {
    try {
      const result = await pool.query(
        "SELECT id, name, display_name, category, description, enabled, requires_key, api_key, last_tested_at, test_status, test_message, updated_at FROM platform_integrations ORDER BY category, display_name"
      );
      const rows = result.rows.map(row => ({
        id: row.id,
        name: row.name,
        displayName: row.display_name,
        category: row.category,
        description: row.description,
        enabled: row.enabled,
        requiresKey: row.requires_key,
        keyConfigured: !!row.api_key,
        maskedHint: row.api_key ? `…${String(row.api_key).slice(-4)}` : null,
        lastTestedAt: row.last_tested_at,
        testStatus: row.test_status,
        testMessage: row.test_message,
        updatedAt: row.updated_at,
      }));
      res.json(rows);
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // PATCH /api/admin/platform-integrations/:name — update enabled flag and/or API key
  app.patch("/api/admin/platform-integrations/:name", isSuperAdminOrPlatformAdmin, async (req: any, res) => {
    try {
      const { name } = req.params;
      const { enabled, apiKey } = req.body as { enabled?: boolean; apiKey?: string };

      // Check the integration exists
      const existing = await pool.query("SELECT id, requires_key FROM platform_integrations WHERE name = $1", [name]);
      if (existing.rows.length === 0) {
        return res.status(404).json({ message: `Integration '${name}' not found` });
      }

      const updates: string[] = ["updated_at = NOW()"];
      const params: unknown[] = [];

      if (typeof enabled === "boolean") {
        params.push(enabled);
        updates.push(`enabled = $${params.length}`);
      }

      if (typeof apiKey === "string" && apiKey.trim().length > 0) {
        // Only allow setting a key on key-requiring integrations
        if (!existing.rows[0].requires_key) {
          return res.status(400).json({ message: `Integration '${name}' does not require an API key` });
        }
        params.push(apiKey.trim());
        updates.push(`api_key = $${params.length}`);
        // Reset test status when key changes
        updates.push("test_status = 'untested'");
        updates.push("test_message = NULL");
        updates.push("last_tested_at = NULL");
      } else if (apiKey === "") {
        // Explicit empty string = clear the key
        params.push(null);
        updates.push(`api_key = $${params.length}`);
        updates.push("test_status = 'untested'");
        updates.push("test_message = NULL");
      }

      params.push(name);
      const sql = `UPDATE platform_integrations SET ${updates.join(", ")} WHERE name = $${params.length} RETURNING id, name, enabled, requires_key, api_key, test_status, updated_at`;
      const upd = await pool.query(sql, params);
      const row = upd.rows[0];
      res.json({
        name: row.name,
        enabled: row.enabled,
        requiresKey: row.requires_key,
        keyConfigured: !!row.api_key,
        maskedHint: row.api_key ? `…${String(row.api_key).slice(-4)}` : null,
        testStatus: row.test_status,
        updatedAt: row.updated_at,
      });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });

  // POST /api/admin/platform-integrations/:name/test — live probe per feed
  app.post("/api/admin/platform-integrations/:name/test", isSuperAdminOrPlatformAdmin, async (req: any, res) => {
    try {
      const { name } = req.params;
      const row = await pool.query("SELECT * FROM platform_integrations WHERE name = $1", [name]);
      if (row.rows.length === 0) {
        return res.status(404).json({ message: `Integration '${name}' not found` });
      }
      const integration = row.rows[0];
      if (!integration.enabled) {
        return res.status(400).json({ message: "Integration is disabled. Enable it before testing." });
      }
      if (integration.requires_key && !integration.api_key) {
        return res.status(400).json({ message: "API key not configured. Save a key first." });
      }

      const start = Date.now();
      let ok = false;
      let message = "";

      try {
        const TIMEOUT_MS = 5000;
        const controller = new AbortController();
        const timer = setTimeout(() => controller.abort(), TIMEOUT_MS);

        if (name === "malwarebazaar") {
          // Test with a known-safe hash lookup
          const r = await fetch("https://mb-api.abuse.ch/api/v1/", {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: "query=get_info&hash=44d88612fea8a8f36de82e1278abb02f",
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          message = ok ? `Reachable (HTTP ${r.status})` : `HTTP ${r.status}`;
        } else if (name === "urlhaus") {
          const r = await fetch("https://urlhaus-api.abuse.ch/v1/host/", {
            method: "POST",
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            body: "host=example.com",
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          message = ok ? `Reachable (HTTP ${r.status})` : `HTTP ${r.status}`;
        } else if (name === "feodo_tracker") {
          const r = await fetch("https://feodotracker.abuse.ch/downloads/ipblocklist_recommended.json", {
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          const blocklistCount = ok
            ? (() => { try { return r.headers.get("Content-Length") ? "available" : "available"; } catch { return "available"; } })()
            : "";
          message = ok ? `Blocklist ${blocklistCount} (HTTP ${r.status})` : `HTTP ${r.status}`;
        } else if (name === "alienvault_otx") {
          const r = await fetch("https://otx.alienvault.com/api/v1/user/me", {
            headers: { "X-OTX-API-KEY": integration.api_key },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json() as Record<string, unknown>;
            message = `Authenticated as ${d["username"] ?? "unknown user"}`;
          } else {
            message = r.status === 403 ? "Invalid API key" : `HTTP ${r.status}`;
          }
        } else if (name === "virustotal") {
          const r = await fetch("https://www.virustotal.com/api/v3/users/current", {
            headers: { "x-apikey": integration.api_key },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json() as Record<string, unknown>;
            const attrs = (d["data"] as Record<string, unknown>)?.["attributes"] as Record<string, unknown>;
            const quotas = attrs?.["quotas"] as Record<string, unknown> | null;
            const remaining = (quotas?.["api_requests_daily"] as Record<string, unknown>)?.["allowed"] ?? "?";
            message = `Authenticated. Daily quota: ${remaining} requests`;
          } else {
            message = r.status === 401 ? "Invalid API key" : `HTTP ${r.status}`;
          }
        } else if (name === 'threatfox') {
          const r = await fetch('https://threatfox-api.abuse.ch/api/v1/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ query: 'get_iocs', days: 1, limit: 1 }),
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          message = ok ? `Reachable (HTTP ${r.status})` : `HTTP ${r.status}`;
        } else if (name === 'greynoise') {
          const r = await fetch('https://api.greynoise.io/v3/community/8.8.8.8', {
            headers: { key: integration.api_key },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok || r.status === 429;
          message = ok ? `Reachable (HTTP ${r.status})` : r.status === 401 ? 'Invalid API key' : `HTTP ${r.status}`;
        } else if (name === 'shodan') {
          const r = await fetch(`https://api.shodan.io/api-info?key=${encodeURIComponent(integration.api_key)}`, {
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated. Credits: ${d.query_credits ?? '?'}`;
          } else {
            message = r.status === 401 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else if (name === 'urlscan_io') {
          const r = await fetch('https://urlscan.io/user/quotas', {
            headers: { 'API-Key': integration.api_key },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          message = ok ? `Authenticated (HTTP ${r.status})` : r.status === 401 ? 'Invalid API key' : `HTTP ${r.status}`;
        } else if (name === 'anyrun') {
          const r = await fetch('https://api.any.run/v1/user', {
            headers: { Authorization: `API-Key ${integration.api_key}` },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated as ${d.data?.login ?? 'user'}`;
          } else {
            message = r.status === 401 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else if (name === 'hybrid_analysis') {
          const r = await fetch('https://www.hybrid-analysis.com/api/v2/key/current', {
            headers: { 'api-key': integration.api_key, 'User-Agent': 'Falcon Sandbox' },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated. Tier: ${d.tier_name ?? 'unknown'}`;
          } else {
            message = r.status === 403 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else if (name === 'joe_sandbox') {
          const joeBody = new URLSearchParams({ apikey: integration.api_key, 'accept-tac': '1' });
          const r = await fetch('https://jbxcloud.joesecurity.org/api/v2/account/info', {
            method: 'POST',
            headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
            body: joeBody.toString(),
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated. Quota: ${d.data?.quota_remaining ?? '?'} remaining`;
          } else {
            message = r.status === 403 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else if (name === 'hatching_triage') {
          const r = await fetch('https://tria.ge/api/v0/me', {
            headers: { Authorization: `Bearer ${integration.api_key}` },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated as ${d.login ?? d.name ?? 'user'}`;
          } else {
            message = r.status === 403 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else if (name === 'intezer_analyze') {
          const tr = await fetch('https://analyze.intezer.com/api/v2-0/get-access-token', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ api_key: integration.api_key }),
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = tr.ok;
          message = ok ? 'API key valid — token obtained' : tr.status === 401 ? 'Invalid API key' : `HTTP ${tr.status}`;
        } else if (name === 'vmray') {
          const r = await fetch('https://eu.cloud.vmray.com/api/v1/system/info', {
            headers: { Authorization: `api_key ${integration.api_key}` },
            signal: controller.signal,
          });
          clearTimeout(timer);
          ok = r.ok;
          if (ok) {
            const d = await r.json();
            message = `Authenticated. Version: ${d.data?.version ?? 'unknown'}`;
          } else {
            message = r.status === 401 ? 'Invalid API key' : `HTTP ${r.status}`;
          }
        } else {
          clearTimeout(timer);
          ok = false;
          message = 'Unknown integration — no test probe defined';
        }
      } catch (probeErr: any) {
        ok = false;
        message = probeErr?.name === "AbortError" ? "Timed out after 5s" : (probeErr?.message ?? "Connection failed");
      }

      const latencyMs = Date.now() - start;
      const testStatus = ok ? "ok" : "error";

      // Persist result to DB
      await pool.query(
        "UPDATE platform_integrations SET last_tested_at = NOW(), test_status = $1, test_message = $2, updated_at = NOW() WHERE name = $3",
        [testStatus, message, name]
      );

      res.json({ ok, latencyMs, message });
    } catch (err: any) {
      res.status(500).json({ message: err.message });
    }
  });


